INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37429, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天気", "is_correct": false, "explanation": "天気は急いで変えられるものではないので、「急いで変えました」と合わない。"}, {"text": "戦術", "is_correct": true, "explanation": "状況に応じて行動や方法を変えるという意味で、「戦術を急いで変えました」と自然につながる。"}, {"text": "人柄", "is_correct": false, "explanation": "人柄は変えるものではなく、「人柄を急いで変えました」は意味が通らない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は急いで変えられないので、「年齢を急いで変えました」は文が成り立たない。"}], "explanations": {"天気": "天気は急いで変えられるものではないので、「急いで変えました」と合わない。", "戦術": "状況に応じて行動や方法を変えるという意味で、「戦術を急いで変えました」と自然につながる。", "人柄": "人柄は変えるものではなく、「人柄を急いで変えました」は意味が通らない。", "年齢": "年齢は急いで変えられないので、「年齢を急いで変えました」は文が成り立たない。"}, "sentence_index": 0, "correct_answer": "戦術"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は歴史の戦術が豊富で、クイズ大会で強い。", "explanation": "戦術は行動の方法を指し、覚えている情報の量には使わないので合わない。"}, {"text": "彼は重い戦術を背負って、山に登った。", "explanation": "戦術は計画や方法で、背負えるものではないので合わない。"}, {"text": "彼は戦術が大きく、相撲に向いている。", "explanation": "戦術は体の大きさを表さないので、体格の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37429, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教科書", "is_correct": false, "explanation": "教科書は戦い方ではないので、「逃げるのも一つの教科書です」は意味が通らない。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下は物事の方法ではないので、「一つの靴下です」は文として成り立たない。"}, {"text": "戦術", "is_correct": true, "explanation": "敵が多いときに逃げるのも戦い方の一つという意味で、「一つの戦術です」と自然に続く。"}, {"text": "寝室", "is_correct": false, "explanation": "寝室は戦い方を表さず、「一つの寝室です」は文脈に合わない。"}], "explanations": {"教科書": "教科書は戦い方ではないので、「逃げるのも一つの教科書です」は意味が通らない。", "靴下": "靴下は物事の方法ではないので、「一つの靴下です」は文として成り立たない。", "戦術": "敵が多いときに逃げるのも戦い方の一つという意味で、「一つの戦術です」と自然に続く。", "寝室": "寝室は戦い方を表さず、「一つの寝室です」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "戦術"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その選手は戦術の体重が重く、なかなか走れない。", "explanation": "戦術は計画や方法で、重さを量るものではないので、重い・軽いとは言えない。"}, {"text": "彼は怒りの戦術を抑えられず、大声を出した。", "explanation": "戦術は行動の方法で、怒りの気持ちは抑えるものなので合わない。"}, {"text": "今日は気温の戦術が高くて、汗が止まらない。", "explanation": "戦術は行動の方法で、温度の高さには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37429, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "相手の動きに合わせ、戦術を素早く変えるました。", "corrected_sentence": "相手の動きに合わせ、戦術を素早く変えました。", "error_description": "誤：「変えるました」、正：「変えました」。「ました」は動詞の連用形（変え）に続けるもので、辞書形の「変える」にはつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37429, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "監督は試合の途中で戦術の変えました。", "corrected_sentence": "監督は試合の途中で戦術を変えました。", "error_description": "誤：「戦術の」、正：「戦術を」。「変える」は他動詞で、変える対象である戦術を「を」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37430, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「勝つ」の対象を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「勝つ」は目的語を取らないので、「を」は合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語で、「勝てば」の対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属を示し、「勝つ」の対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "正解。「勝つ」の対象を示す「に」。", "を": "「勝つ」は目的語を取らないので、「を」は合わない。", "が": "「が」は主語で、「勝てば」の対象にならない。", "の": "「の」は所属を示し、「勝つ」の対象を示せない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "所属"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37430, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「始まる」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「始まる」は目的語を取らない自動詞なので、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や時点を示し、主語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属を示し、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "正解。「始まる」の主語を示す「が」。", "を": "「始まる」は目的語を取らない自動詞なので、「を」は合わない。", "に": "「に」は場所や時点を示し、主語にはならない。", "の": "「の」は所属を示し、主語を示せない。"}, "error_tags": {"を": "目的語", "に": "場所・時点", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37430, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "たたかうこと。ゲームなどで、相手と勝ち負けをきめること。", "primary_collocate": null, "pronunciation": "ばとる", "ipa": "batoɾɯ", "syllable_count": 3, "sentences": [{"text": "ゲームの中で、友だちとバトルをして勝った。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "ゲームの中[なか]で、友[とも]だちとバトルをして勝[か]った。", "sentence_source": "generated"}, {"text": "最後のバトルに勝てば、物語は終わる。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "最後[さいご]のバトルに勝[か]てば、物語[ものがたり]は終[お]わる。", "sentence_source": "generated"}, {"text": "二人のバトルは、一時間以上続いた。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "二人[ふたり]のバトルは、一時間[いちじかん]以上[いじょう]続[つづ]いた。", "sentence_source": "generated"}, {"text": "このカードゲームは、バトルで勝つと点がもらえる。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "このカードゲームは、バトルで勝[か]つと点[てん]がもらえる。", "sentence_source": "generated"}, {"text": "弟はバトルが好きで、毎日ゲームで戦っている。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "弟[おとうと]はバトルが好[す]きで、毎日[まいにち]ゲームで戦[たたか]っている。", "sentence_source": "generated"}, {"text": "ボスとのバトルに負けて、もう一度挑戦した。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "ボスとのバトルに負[ま]けて、もう一度[いちど]挑戦[ちょうせん]した。", "sentence_source": "generated"}, {"text": "強い相手とのバトルは、緊張する。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "強[つよ]い相手[あいて]とのバトルは、緊張[きんちょう]する。", "sentence_source": "generated"}, {"text": "バトルが始まると、画面が赤くなった。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "バトルが始[はじ]まると、画面[がめん]が赤[あか]くなった。", "sentence_source": "generated"}, {"text": "仲間と力を合わせて、バトルに勝った。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "仲間[なかま]と力[ちから]を合[あ]わせて、バトルに勝[か]った。", "sentence_source": "generated"}, {"text": "歌のバトルで優勝して、みんなに祝ってもらった。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "歌[うた]のバトルで優勝[ゆうしょう]して、みんなに祝[いわ]ってもらった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バトル", "label": "基本形"}], "register": "口語", "sense_fingerprint": "ゲームなどで相手と戦って勝ち負けを決めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ecbfbe-96fb-4154-838a-29e711cd0c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37430, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バトル", "is_correct": true, "explanation": "正解。ゲームで相手と勝ち負けを決める対戦を指す。"}, {"text": "買い物", "is_correct": false, "explanation": "勝ち負けを決める行為ではなく、「勝った」の形にならない。"}, {"text": "昼寝", "is_correct": false, "explanation": "勝ち負けを決める行為ではなく、「勝った」の形にならない。"}, {"text": "掃除", "is_correct": false, "explanation": "勝ち負けを決める行為ではなく、「勝った」の形にならない。"}], "explanations": {"バトル": "正解。ゲームで相手と勝ち負けを決める対戦を指す。", "買い物": "勝ち負けを決める行為ではなく、「勝った」の形にならない。", "昼寝": "勝ち負けを決める行為ではなく、「勝った」の形にならない。", "掃除": "勝ち負けを決める行為ではなく、「勝った」の形にならない。"}, "sentence_index": 0, "correct_answer": "バトル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スマホのバトルが切れて、充電した。", "explanation": "〈バッテリー〉との言い換え（音が似る）。切れるのは電池で、ゲームの対戦とは違う。"}, {"text": "最後までバトルがつかなかった。", "explanation": "〈勝負〉との言い換え。「勝負がつく」とは言うが、「バトルがつく」とは言わない。"}, {"text": "リレーの選手は、バトルを次の人に渡した。", "explanation": "〈バトン〉との言い換え（音が似る）。渡すのは棒状の道具で、バトルは渡せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37430, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バトル", "is_correct": true, "explanation": "正解。強い相手との対戦を指す。"}, {"text": "散歩", "is_correct": false, "explanation": "勝ち負けのない行為で、緊張する対象ではない。"}, {"text": "昼寝", "is_correct": false, "explanation": "休むための行為で、緊張する対象ではない。"}, {"text": "植木", "is_correct": false, "explanation": "植物で、緊張する対象ではない。"}], "explanations": {"バトル": "正解。強い相手との対戦を指す。", "散歩": "勝ち負けのない行為で、緊張する対象ではない。", "昼寝": "休むための行為で、緊張する対象ではない。", "植木": "植物で、緊張する対象ではない。"}, "sentence_index": 6, "correct_answer": "バトル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このゲームでは、バトルを倒すと宝箱が開く。", "explanation": "〈ボス〉との言い換え。倒すのは敵の対象で、バトルという出来事は倒せない。"}, {"text": "誕生日に、友だちのためにバトルを焼いた。", "explanation": "〈ケーキ〉との言い換え。焼くのは菓子や料理で、対戦は焼けない。"}, {"text": "みんなのために、バトルを作って出した。", "explanation": "〈ごちそう〉との言い換え。作って出すのは料理で、バトルは作って出すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37430, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゲームのバトルを勝って、アイテムをもらった。", "corrected_sentence": "ゲームのバトルで勝って、アイテムをもらった。", "error_description": "バトルで勝つ場面を示すのは「で」。「を」は目的語になるので誤り。正しくは「バトルで勝って」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37430, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強い敵とのバトルを負けて、悔しかった。", "corrected_sentence": "強い敵とのバトルに負けて、悔しかった。", "error_description": "「負ける」は相手を示す「に」を取る。「を」は誤り。正しくは「バトルに負けて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37431, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「バトルで」の場面を示す「で」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語で、場面を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語で、場面を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属を示し、場面は示せない。"}], "correct_answer": "で", "explanations": {"で": "正解。「バトルで」の場面を示す「で」。", "を": "「を」は目的語で、場面を示せない。", "が": "「が」は主語で、場面を示せない。", "の": "「の」は所属を示し、場面は示せない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "所属"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37431, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「バトルは」と主題を示す「は」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すが、「分からなかった」は状態を表すので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示し、主題にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、「バトルと最後まで分からなかった」は不自然。"}], "correct_answer": "は", "explanations": {"は": "正解。「バトルは」と主題を示す「は」。", "を": "「を」は動作の対象を示すが、「分からなかった」は状態を表すので合わない。", "に": "「に」は場所や相手を示し、主題にはならない。", "と": "「と」は並列や相手を示し、「バトルと最後まで分からなかった」は不自然。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37431, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "対戦。特に、ゲームや競技における敵対者との戦い。", "primary_collocate": null, "pronunciation": "ばとる", "ipa": "batoɾɯ", "syllable_count": 3, "sentences": [{"text": "来週、ゲームの大会で決勝のバトルがある。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "来週[らいしゅう]、ゲームの大会[たいかい]で決勝[けっしょう]のバトルがある。", "sentence_source": "generated"}, {"text": "ラップのバトルでは、相手より上手に言葉を返す。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "ラップのバトルでは、相手[あいて]より上手[じょうず]に言葉[ことば]を返[かえ]す。", "sentence_source": "generated"}, {"text": "二人の選手のバトルを、客席から見守った。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "二人[ふたり]の選手[せんしゅ]のバトルを、客席[きゃくせき]から見守[みまも]った。", "sentence_source": "generated"}, {"text": "ダンスのバトルで、彼は相手に勝った。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "ダンスのバトルで、彼[かれ]は相手[あいて]に勝[か]った。", "sentence_source": "generated"}, {"text": "勝ったほうが次に進む、一対一のバトルだ。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "勝[か]ったほうが次[つぎ]に進[すす]む、一対一[いちたいいち]のバトルだ。", "sentence_source": "generated"}, {"text": "世界の強い人が集まって、バトルをした。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "世界[せかい]の強[つよ]い人[ひと]が集[あつ]まって、バトルをした。", "sentence_source": "generated"}, {"text": "このゲームは、友だちとオンラインでバトルができる。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "このゲームは、友[とも]だちとオンラインでバトルができる。", "sentence_source": "generated"}, {"text": "相手が強くて、バトルは最後まで分からなかった。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "相手[あいて]が強[つよ]くて、バトルは最後[さいご]まで分[わ]からなかった。", "sentence_source": "generated"}, {"text": "料理のバトルでは、時間内に一品作る。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "料理[りょうり]のバトルでは、時間内[じかんない]に一品[いっぴん]作[つく]る。", "sentence_source": "generated"}, {"text": "新しいチームとのバトルに向けて、毎日練習した。", "target_word": "バトル", "complexity_tier": "T3", "furigana": "新[あたら]しいチームとのバトルに向[む]けて、毎日[まいにち]練習[れんしゅう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バトル", "label": "基本形"}], "register": "口語", "sense_fingerprint": "ゲームや競技での相手との対戦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ecbfbe-96fb-4154-838a-29e711cd0c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37431, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バトル", "is_correct": true, "explanation": "正解。ゲームや大会での対戦を指す。"}, {"text": "日焼け止め", "is_correct": false, "explanation": "肌を守る化粧品で、大会の試合にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "空の状態で、大会の試合にはならない。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除の道具で、大会の試合にはならない。"}], "explanations": {"バトル": "正解。ゲームや大会での対戦を指す。", "日焼け止め": "肌を守る化粧品で、大会の試合にはならない。", "天気": "空の状態で、大会の試合にはならない。", "掃除機": "掃除の道具で、大会の試合にはならない。"}, "sentence_index": 0, "correct_answer": "バトル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドローンのバトルが切れて、飛べなくなった。", "explanation": "〈バッテリー〉との言い換え（音が似る）。切れるのは電池で、対戦ではない。"}, {"text": "新しいチームのバトルに合格した。", "explanation": "〈試験〉との言い換え。合格するのは試験で、対戦は合格の対象にならない。"}, {"text": "バトルを並べて、お客さんを待った。", "explanation": "〈料理〉との言い換え。並べるのは料理で、バトルは並べられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37431, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バトル", "is_correct": true, "explanation": "正解。オンラインで友だちとできる対戦を指す。"}, {"text": "昼寝", "is_correct": false, "explanation": "オンラインでは行えない行為。"}, {"text": "植木", "is_correct": false, "explanation": "植物で、オンラインでできるものではない。"}, {"text": "散歩", "is_correct": false, "explanation": "外を歩く行為で、オンラインではできない。"}], "explanations": {"バトル": "正解。オンラインで友だちとできる対戦を指す。", "昼寝": "オンラインでは行えない行為。", "植木": "植物で、オンラインでできるものではない。", "散歩": "外を歩く行為で、オンラインではできない。"}, "sentence_index": 6, "correct_answer": "バトル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "リレーで、バトルを次の走者に渡した。", "explanation": "〈バトン〉との言い換え（音が似る）。渡すのは棒状の道具で、バトルは渡せない。"}, {"text": "夏休みの宿題で、ポスターを仕上げるかわりに、バトルを仕上げた。", "explanation": "〈作品〉との言い換え。仕上げるのは作品で、対戦は仕上げるものではない。"}, {"text": "新しいバトルを着て、パーティーに行った。", "explanation": "〈ドレス〉との言い換え。着るのは衣服で、バトルは着られない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37431, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "決勝のバトルを備えて、練習を続けた。", "corrected_sentence": "決勝のバトルに備えて、練習を続けた。", "error_description": "「備える」は「に」を取る。「を」は誤り。正しくは「決勝のバトルに備えて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37431, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "オンラインのバトルに、友だちに勝った。", "corrected_sentence": "オンラインのバトルで、友だちに勝った。", "error_description": "対戦の場面を示すのは「で」。「に」は誤り。正しくは「バトルで、友だちに勝った」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
