INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37432, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「分担を黒板に書きました」の「を」。「書く」の対象を示し、分担が目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "「分担が黒板に書きました」は分担が主語になり、「書く」の対象が消える。"}, {"text": "で", "is_correct": false, "explanation": "「分担で黒板に書きました」は手段の「で」になり、書く対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「分担より黒板に書きました」は比較の「より」になり、書く対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「分担を黒板に書きました」の「を」。「書く」の対象を示し、分担が目的語になる。", "が": "「分担が黒板に書きました」は分担が主語になり、「書く」の対象が消える。", "で": "「分担で黒板に書きました」は手段の「で」になり、書く対象を示せない。", "より": "「分担より黒板に書きました」は比較の「より」になり、書く対象にならない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37432, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "みんなで仕事を分けて、それぞれがやること。", "primary_collocate": null, "pronunciation": "ぶんたん", "ipa": "bɯɴtaɴ", "syllable_count": 4, "sentences": [{"text": "遠足の持ち物は、クラスで分担して用意しました。", "target_word": "分担して", "complexity_tier": "T3", "furigana": "遠足[えんそく]の持[も]ち物[もの]は、クラスで分担[ぶんたん]して用意[ようい]しました。", "sentence_source": "generated"}, {"text": "姉と私で、洗い物と洗濯を分担しています。", "target_word": "分担", "complexity_tier": "T3", "furigana": "姉[あね]と私[わたし]で、洗[あら]い物[もの]と洗濯[せんたく]を分担[ぶんたん]しています。", "sentence_source": "generated"}, {"text": "分担が決まっているので、迷わずに動けます。", "target_word": "分担", "complexity_tier": "T3", "furigana": "分担[ぶんたん]が決[き]まっているので、迷[まよ]わずに動[うご]けます。", "sentence_source": "generated"}, {"text": "発表の分担を決めるために、グループで集まりました。", "target_word": "分担", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の分担[ぶんたん]を決[き]めるために、グループで集[あつ]まりました。", "sentence_source": "generated"}, {"text": "一人では終わらないから、仕事を分担しよう。", "target_word": "分担", "complexity_tier": "T3", "furigana": "一人[ひとり]では終[お]わらないから、仕事[しごと]を分担[ぶんたん]しよう。", "sentence_source": "generated"}, {"text": "引っ越しの荷造りは、家族で分担することになりました。", "target_word": "分担する", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの荷造[にづく]りは、家族[かぞく]で分担[ぶんたん]することになりました。", "sentence_source": "generated"}, {"text": "文化祭の飾り作りと受付の分担は、紙に書いて教室に貼りました。", "target_word": "分担", "complexity_tier": "T3", "furigana": "文化祭[ぶんかさい]の飾[かざ]り作[づく]りと受付[うけつけ]の分担[ぶんたん]は、紙[かみ]に書[か]いて教室[きょうしつ]に貼[は]りました。", "sentence_source": "generated"}, {"text": "先生は、そうじの分担を黒板に書きました。", "target_word": "分担", "complexity_tier": "T3", "furigana": "先生[せんせい]は、そうじの分担[ぶんたん]を黒板[こくばん]に書[か]きました。", "sentence_source": "generated"}, {"text": "分担を変えたら、仕事が早く終わるようになりました。", "target_word": "分担", "complexity_tier": "T3", "furigana": "分担[ぶんたん]を変[か]えたら、仕事[しごと]が早[はや]く終[お]わるようになりました。", "sentence_source": "generated"}, {"text": "役目を分担すれば、だれか一人だけが疲れることもありません。", "target_word": "分担すれば", "complexity_tier": "T3", "furigana": "役目[やくめ]を分担[ぶんたん]すれば、だれか一人[ひとり]だけが疲[つか]れることもありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分担", "label": "基本形"}, {"form": "分担する", "label": "する動詞・辞書形"}, {"form": "分担して", "label": "て形"}, {"form": "分担した", "label": "た形"}, {"form": "分担すれば", "label": "仮定形"}], "register": "中立（日常的）", "sense_fingerprint": "みんなで仕事を分けて、それぞれが受け持つこと（する動詞化可）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b18bfd-21ad-4c83-b5d6-f22248d6b44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37432, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分担して", "is_correct": true, "explanation": "「クラスで分担して」は分けて行う意味で、「用意しました」の手段として合う。"}, {"text": "分担した", "is_correct": false, "explanation": "過去の終わった形では「用意しました」へ続けられず、文が成り立たない。"}, {"text": "分担すれば", "is_correct": false, "explanation": "仮定形は「分けたら」という条件になり、「用意しました」の手段としては文が成り立たない。"}, {"text": "分担しよう", "is_correct": false, "explanation": "意向形は呼びかけになり、過去の報告文の中に入らない。"}], "explanations": {"分担して": "「クラスで分担して」は分けて行う意味で、「用意しました」の手段として合う。", "分担した": "過去の終わった形では「用意しました」へ続けられず、文が成り立たない。", "分担すれば": "仮定形は「分けたら」という条件になり、「用意しました」の手段としては文が成り立たない。", "分担しよう": "意向形は呼びかけになり、過去の報告文の中に入らない。"}, "sentence_index": 0, "correct_answer": "分担して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この粉は分担を量ってから、ボウルに入れた。", "explanation": "ここは〈分量〉の意味。分担は役割を分け持つ語で、粉の量を量るなら〈分量〉を使う。"}, {"text": "この薬は、一回の分担を必ず守って飲んでください。", "explanation": "ここは〈用量〉の意味。分担は役割を分け持つ語で、薬の一回の量を指すなら〈用量〉を使う。"}, {"text": "この川は途中で二つに分担して流れている。", "explanation": "ここは〈分岐〉の意味。分担は人や役割を分け持つ語で、流れが分かれる場合は〈分岐〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37432, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分担", "is_correct": true, "explanation": "「受付の分担」は仕事の割り振りを指し、紙に書いて貼る内容として合う。"}, {"text": "分岐", "is_correct": false, "explanation": "「受付の分岐」は道の分かれのような意味になり、紙に書いて貼る内容として不自然。"}, {"text": "消費", "is_correct": false, "explanation": "「受付の消費」は物を使い尽くす意味で、教室に貼り出す内容にはならない。"}, {"text": "規模", "is_correct": false, "explanation": "「受付の規模」は大きさを表し、「飾り作り」と並ぶ仕事の区分にはならない。"}], "explanations": {"分担": "「受付の分担」は仕事の割り振りを指し、紙に書いて貼る内容として合う。", "分岐": "「受付の分岐」は道の分かれのような意味になり、紙に書いて貼る内容として不自然。", "消費": "「受付の消費」は物を使い尽くす意味で、教室に貼り出す内容にはならない。", "規模": "「受付の規模」は大きさを表し、「飾り作り」と並ぶ仕事の区分にはならない。"}, "sentence_index": 6, "correct_answer": "分担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋のパソコンは、分担が古くて動きが遅い。", "explanation": "ここは〈部品〉の意味。分担は役割を分け持つ語で、機械の部品を指すなら〈部品〉を使う。"}, {"text": "仕事は全部、後輩ひとりに分担させた。", "explanation": "ここは〈任せる〉の意味。分担は複数の人が分け合う語で、一人に全部を渡すなら〈任せる〉を使う。"}, {"text": "二人は力を分担して、試合に勝った。", "explanation": "ここは〈協力〉の意味。分担は役割を分ける語で、力を一つにまとめる場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37432, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄と私で、洗い物と洗濯を分担ています。", "corrected_sentence": "兄と私で、洗い物と洗濯を分担しています。", "error_description": "サ変動詞「する」の連用形「し」が抜けている。「分担しています」が正しく、「分担ています」は動詞として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37432, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "受付の分担を取ってから、紙に書きました。", "corrected_sentence": "受付の分担を決めてから、紙に書きました。", "error_description": "「分担を取る」は不自然な組み合わせ。割り振りを決める場合は「分担を決める」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37433, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「分担を決めた」の「を」。「決める」の対象を示し、分担が目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "「分担が決めた」では分担が主語になり、「決めた」の対象が消えてしまう。"}, {"text": "へ", "is_correct": false, "explanation": "「分担へ決めた」は方向を表す「へ」で、「決める」の対象には使わない。"}, {"text": "より", "is_correct": false, "explanation": "「分担より決めた」は比較の「より」で、「決める」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「分担を決めた」の「を」。「決める」の対象を示し、分担が目的語になる。", "が": "「分担が決めた」では分担が主語になり、「決めた」の対象が消えてしまう。", "へ": "「分担へ決めた」は方向を表す「へ」で、「決める」の対象には使わない。", "より": "「分担より決めた」は比較の「より」で、「決める」の対象にはならない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37433, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「分担に不満があり」の「に」。「不満」が向かう対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「分担が不満がある」は「が」が重なり、主語としても不自然になる。"}, {"text": "を", "is_correct": false, "explanation": "「分担を不満がある」は目的語にしても「不満がある」が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「分担で不満がある」は手段の「で」になり、不満の対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "「分担に不満があり」の「に」。「不満」が向かう対象を示す。", "が": "「分担が不満がある」は「が」が重なり、主語としても不自然になる。", "を": "「分担を不満がある」は目的語にしても「不満がある」が成り立たない。", "で": "「分担で不満がある」は手段の「で」になり、不満の対象を示せない。"}, "error_tags": {"が": "主語", "を": "対象", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37433, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "複数の人やグループが、それぞれの役割や責任を分け持つこと。また、その分け方。", "primary_collocate": null, "pronunciation": "ぶんたん", "ipa": "bɯɴtaɴ", "syllable_count": 4, "sentences": [{"text": "制作は、絵師、彫師、摺師の役割分担によって進められます。", "target_word": "分担", "complexity_tier": "T3", "furigana": "制作[せいさく]は、絵師[えし]、彫師[ほりし]、摺師[すりし]の役割分担[やくわりぶんたん]によって進[すす]められます。", "sentence_source": "mined"}, {"text": "家事の分担を決めたので、毎日の食事の準備が楽になりました。", "target_word": "分担", "complexity_tier": "T3", "furigana": "家事[かじ]の分担[ぶんたん]を決[き]めたので、毎日[まいにち]の食事[しょくじ]の準備[じゅんび]が楽[らく]になりました。", "sentence_source": "generated"}, {"text": "掃除は三人で分担して、三十分で終わらせました。", "target_word": "分担して", "complexity_tier": "T3", "furigana": "掃除[そうじ]は三人[さんにん]で分担[ぶんたん]して、三十分[さんじゅっぷん]で終[お]わらせました。", "sentence_source": "generated"}, {"text": "仕事の分担がはっきりしていないと、だれも責任を持ちません。", "target_word": "分担", "complexity_tier": "T3", "furigana": "仕事[しごと]の分担[ぶんたん]がはっきりしていないと、だれも責任[せきにん]を持[も]ちません。", "sentence_source": "generated"}, {"text": "兄と介護を分担して、母の世話をしています。", "target_word": "分担して", "complexity_tier": "T3", "furigana": "兄[あに]と介護[かいご]を分担[ぶんたん]して、母[はは]の世話[せわ]をしています。", "sentence_source": "generated"}, {"text": "班ごとに分担を決めてから、調べ学習を始めました。", "target_word": "分担", "complexity_tier": "T3", "furigana": "班[はん]ごとに分担[ぶんたん]を決[き]めてから、調[しら]べ学習[がくしゅう]を始[はじ]めました。", "sentence_source": "generated"}, {"text": "作業を分担すれば、一人あたりの負担は小さくなります。", "target_word": "分担すれば", "complexity_tier": "T3", "furigana": "作業[さぎょう]を分担[ぶんたん]すれば、一人[ひとり]あたりの負担[ふたん]は小[ちい]さくなります。", "sentence_source": "generated"}, {"text": "当番の分担に不満があり、会議で話し合いました。", "target_word": "分担", "complexity_tier": "T3", "furigana": "当番[とうばん]の分担[ぶんたん]に不満[ふまん]があり、会議[かいぎ]で話[はな]し合[あ]いました。", "sentence_source": "generated"}, {"text": "私のチームでは、料理と片づけを分担しています。", "target_word": "分担", "complexity_tier": "T3", "furigana": "私[わたし]のチームでは、料理[りょうり]と片[かた]づけを分担[ぶんたん]しています。", "sentence_source": "generated"}, {"text": "運動会の準備は、学年ごとに分担する予定です。", "target_word": "分担する", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の準備[じゅんび]は、学年[がくねん]ごとに分担[ぶんたん]する予定[よてい]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分担", "label": "基本形"}, {"form": "分担する", "label": "する動詞・辞書形"}, {"form": "分担して", "label": "て形"}, {"form": "分担した", "label": "た形"}, {"form": "分担すれば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "複数の人が役割や責任を分け持つこと、またはその分け方を表す名詞（する動詞化可）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b18bfd-21ad-4c83-b5d6-f22248d6b44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37433, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分担", "is_correct": true, "explanation": "「役割分担」は複数の人が役割を分け持つ意味で、「制作は…によって進められます」の手段として合う。"}, {"text": "消費", "is_correct": false, "explanation": "「役割消費」は役割を使い尽くす意味になり、制作の進め方を表す手段としては成り立たない。"}, {"text": "分岐", "is_correct": false, "explanation": "「分岐」は道や流れが分かれることを指し、役割の割り振りには使えない。"}, {"text": "解決", "is_correct": false, "explanation": "「役割解決」は役割の問題を解く意味になり、制作の進め方の手段としては合わない。"}], "explanations": {"分担": "「役割分担」は複数の人が役割を分け持つ意味で、「制作は…によって進められます」の手段として合う。", "消費": "「役割消費」は役割を使い尽くす意味になり、制作の進め方を表す手段としては成り立たない。", "分岐": "「分岐」は道や流れが分かれることを指し、役割の割り振りには使えない。", "解決": "「役割解決」は役割の問題を解く意味になり、制作の進め方の手段としては合わない。"}, "sentence_index": 0, "correct_answer": "分担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この土地は三つに分担して売り出された。", "explanation": "ここは〈分割〉の意味。分担は人が役割や責任を分け持つ語で、土地を区画に分けるなら〈分割〉を使う。"}, {"text": "この工事の費用は、市がひとりで分担している。", "explanation": "ここは〈負担〉の意味。分担は複数の人が分け持つ語なので、市が一人で全部背負う場合は〈負担〉を使う。"}, {"text": "大会の賞金は、成績に応じてチームに分担される決まりだ。", "explanation": "ここは〈配分〉の意味。賞金のように割り振る場合は〈配分〉を使い、〈分担〉は役割や責任を分け持つ場合に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37433, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分担すれば", "is_correct": true, "explanation": "仮定形で「分けたら」という条件を作り、「負担は小さくなる」という結果につながる。"}, {"text": "分担する", "is_correct": false, "explanation": "辞書形のままでは条件を作れず、「作業を分担する、負担は…」と文がつながらない。"}, {"text": "分担せず", "is_correct": false, "explanation": "「せず」は分けない状態を表し、負担が小さくなるという結果と意味が逆になる。"}, {"text": "分担しなければ", "is_correct": false, "explanation": "「しなければ」は分けない場合の条件になり、「負担は小さくなる」という結果と逆になる。"}], "explanations": {"分担すれば": "仮定形で「分けたら」という条件を作り、「負担は小さくなる」という結果につながる。", "分担する": "辞書形のままでは条件を作れず、「作業を分担する、負担は…」と文がつながらない。", "分担せず": "「せず」は分けない状態を表し、負担が小さくなるという結果と意味が逆になる。", "分担しなければ": "「しなければ」は分けない場合の条件になり、「負担は小さくなる」という結果と逆になる。"}, "sentence_index": 6, "correct_answer": "分担すれば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母のおはぎを、家族で分担して食べた。", "explanation": "ここは〈分け合う〉の意味。分担は仕事や責任を分け持つ語で、食べ物を分けて口にするなら〈分け合う〉を使う。"}, {"text": "この道は途中で二つに分担している。", "explanation": "ここは〈分岐〉の意味。分担は人や役割を分け持つ語で、道筋が分かれる場合は〈分岐〉を使う。"}, {"text": "二人は意見を分担して、結論を出した。", "explanation": "ここは〈出し合う〉の意味。分担は役割や仕事を割り振る語で、意見を出し合う場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37433, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "役割を分担で、資料を作りました。", "corrected_sentence": "役割を分担して、資料を作りました。", "error_description": "「分担して」の「して」が「で」になっている。「分担する」の て形は「分担して」が正しく、「分担で」は日本語として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37433, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "係の分担を決まってから、作業を始めました。", "corrected_sentence": "係の分担が決まってから、作業を始めました。", "error_description": "「決まる」は自動詞なので、対象は「が」で示す。「係の分担を決まって」は誤りで、「係の分担が決まってから」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37434, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "を", "is_correct": false, "explanation": "「基づく」に目的語は取らないため、「結果を基づいて」は成り立たない。"}, {"text": "に", "is_correct": true, "explanation": "「結果に基づいて」の形で、根拠を「に」で示す。「調査の結果に基づいて」は自然な形。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するため、「結果の基づいて」は文法的に続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「結果へ基づいて」は根拠の意味にならない。"}], "correct_answer": "に", "explanations": {"を": "「基づく」に目的語は取らないため、「結果を基づいて」は成り立たない。", "に": "「結果に基づいて」の形で、根拠を「に」で示す。「調査の結果に基づいて」は自然な形。", "の": "「の」は名詞を修飾するため、「結果の基づいて」は文法的に続かない。", "へ": "「へ」は方向を示すため、「結果へ基づいて」は根拠の意味にならない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37434, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「規則が基づいて」は規則が根拠になるという意味にならない。"}, {"text": "に", "is_correct": true, "explanation": "「規則に基づいて決めた」の形で、根拠を「に」で示す。自然な形。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すため、「規則と基づいて」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「規則より基づいて」は根拠の意味として通らない。"}], "correct_answer": "に", "explanations": {"が": "「が」は主語を示すため、「規則が基づいて」は規則が根拠になるという意味にならない。", "に": "「規則に基づいて決めた」の形で、根拠を「に」で示す。自然な形。", "と": "「と」は並列や引用を示すため、「規則と基づいて」は成り立たない。", "より": "「より」は比較を示すため、「規則より基づいて」は根拠の意味として通らない。"}, "error_tags": {"が": "主格", "と": "並列・引用", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37434, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "何かをもとにして、それにしたがうこと。", "primary_collocate": null, "pronunciation": "もとづく", "ipa": "motozɯkɯ", "syllable_count": 4, "sentences": [{"text": "この映画は実際にあった事件に基づいて作られました。", "target_word": "基づいて", "complexity_tier": "T3", "furigana": "この映画[えいが]は実際[じっさい]にあった事件[じけん]に基[もと]づいて作[つく]られました。", "sentence_source": "generated"}, {"text": "調査の結果に基づいて、新しい計画を立てた。", "target_word": "基づいて", "complexity_tier": "T3", "furigana": "調査[ちょうさ]の結果[けっか]に基[もと]づいて、新[あたら]しい計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "経験に基づく意見なので、とても説得力がある。", "target_word": "基づく", "complexity_tier": "T3", "furigana": "経験[けいけん]に基[もと]づく意見[いけん]なので、とても説得力[せっとくりょく]がある。", "sentence_source": "generated"}, {"text": "法律に基づいて、正しく手続きをしなければならない。", "target_word": "基づいて", "complexity_tier": "T3", "furigana": "法律[ほうりつ]に基[もと]づいて、正[ただ]しく手続[てつづ]きをしなければならない。", "sentence_source": "generated"}, {"text": "事実に基づかない噂を信じてはいけません。", "target_word": "基づかない", "complexity_tier": "T3", "furigana": "事実[じじつ]に基[もと]づかない噂[うわさ]を信[しん]じてはいけません。", "sentence_source": "generated"}, {"text": "このレポートはアンケートのデータに基づいて書かれています。", "target_word": "基づいて", "complexity_tier": "T3", "furigana": "このレポートはアンケートのデータに基[もと]づいて書[か]かれています。", "sentence_source": "generated"}, {"text": "先生は長年の研究に基づき、新しい方法を提案した。", "target_word": "基づき", "complexity_tier": "T3", "furigana": "先生[せんせい]は長年[ながねん]の研究[けんきゅう]に基[もと]づき、新[あたら]しい方法[ほうほう]を提案[ていあん]した。", "sentence_source": "generated"}, {"text": "規則に基づいて決めたので、誰にも文句は言えない。", "target_word": "基づいて", "complexity_tier": "T3", "furigana": "規則[きそく]に基[もと]づいて決[き]めたので、誰[だれ]にも文句[もんく]は言[い]えない。", "sentence_source": "generated"}, {"text": "彼の判断は感情ではなく、数字に基づいている。", "target_word": "基づいている", "complexity_tier": "T3", "furigana": "彼[かれ]の判断[はんだん]は感情[かんじょう]ではなく、数字[すうじ]に基[もと]づいている。", "sentence_source": "generated"}, {"text": "契約に基づく支払いは、来月の十日までに行われる。", "target_word": "基づく", "complexity_tier": "T3", "furigana": "契約[けいやく]に基[もと]づく支払[しはら]いは、来月[らいげつ]の十日[とおか]までに行[おこな]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "基づく", "label": "辞書形"}, {"form": "基づいて", "label": "て形"}, {"form": "基づいた", "label": "た形"}, {"form": "基づかない", "label": "ない形"}, {"form": "基づき", "label": "連用形"}, {"form": "基づけば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "事実・規則・経験などを土台や根拠にして、それに沿って判断や行動をすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe8a64e-398a-44c0-8fce-9cbeb83b8e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37434, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "離れて", "is_correct": false, "explanation": "「離れる」は「から」で起点を示すため、「事件に離れて」は意味が通らない。"}, {"text": "基づいて", "is_correct": true, "explanation": "事件を土台にして映画が作られたという意味で、「事件に基づいて作られました」と自然に続く。"}, {"text": "驚いて", "is_correct": false, "explanation": "「驚く」は感情を表し、「事件に驚いて作られた」は映画の成り立ちを表せない。"}, {"text": "眠って", "is_correct": false, "explanation": "「眠る」は動作の状態を示すだけで、「事件に眠って作られた」は文が成り立たない。"}], "explanations": {"離れて": "「離れる」は「から」で起点を示すため、「事件に離れて」は意味が通らない。", "基づいて": "事件を土台にして映画が作られたという意味で、「事件に基づいて作られました」と自然に続く。", "驚いて": "「驚く」は感情を表し、「事件に驚いて作られた」は映画の成り立ちを表せない。", "眠って": "「眠る」は動作の状態を示すだけで、「事件に眠って作られた」は文が成り立たない。"}, "sentence_index": 0, "correct_answer": "基づいて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ベッドに基づいて、昼寝した。", "explanation": "基づくは根拠にして従うことで、体を横たえる意味には使わないので合わない。"}, {"text": "川に基づいて、町が広がった。", "explanation": "基づくは根拠を土台にすることなので、川に沿って広がるという空間の意味には合わない。"}, {"text": "悩んでいる友人に基づいて、そっと話を聞いた。", "explanation": "基づくは根拠にすることなので、相手の気持ちに近づく意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37434, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌い", "is_correct": false, "explanation": "「歌う」は研究に続かず、「先生は長年の研究に歌い、提案した」は文が成り立たない。"}, {"text": "基づき", "is_correct": true, "explanation": "研究を根拠にしてという意味で、文を中止して後に続ける連用形「基づき」が入る。"}, {"text": "泳ぎ", "is_correct": false, "explanation": "「泳ぐ」は研究の根拠を示せず、「研究に泳ぎ」は意味が通らない。"}, {"text": "叫び", "is_correct": false, "explanation": "「叫ぶ」は根拠を表さず、「研究に叫び」は文に合わない。"}], "explanations": {"歌い": "「歌う」は研究に続かず、「先生は長年の研究に歌い、提案した」は文が成り立たない。", "基づき": "研究を根拠にしてという意味で、文を中止して後に続ける連用形「基づき」が入る。", "泳ぎ": "「泳ぐ」は研究の根拠を示せず、「研究に泳ぎ」は意味が通らない。", "叫び": "「叫ぶ」は根拠を表さず、「研究に叫び」は文に合わない。"}, "sentence_index": 6, "correct_answer": "基づき"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故に基づいて、交通が混んでいる。", "explanation": "基づくは根拠や土台を示すので、事故に付随して起きる結果を表す文には合わない。"}, {"text": "彼は電車に基づいて、郊外へ行った。", "explanation": "基づくは根拠にする意味なので、乗り物で移動する意味には使わない。"}, {"text": "ご飯に基づいて、会議を始めた。", "explanation": "基づくは根拠にする意味なので、食事をする意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37434, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新人の意見を基づいて、会議の時間を変えた。", "corrected_sentence": "新人の意見に基づいて、会議の時間を変えた。", "error_description": "誤：「意見を基づいて」、正：「意見に基づいて」。「基づく」は根拠を「に」で示すため、「を」は使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37434, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部長は市場の調べに基づくて、新しい商品を決めた。", "corrected_sentence": "部長は市場の調べに基づいて、新しい商品を決めた。", "error_description": "誤：「基づくて」、正：「基づいて」。五段動詞「基づく」のて形は「基づいて」（く→いて）になるため、「基づくて」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37436, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「新しいキャプテンのリーダーシップで、チームが一つになりました」の「で」は、手段や理由を示す。"}, {"text": "に", "is_correct": false, "explanation": "「リーダーシップに、チームが一つになりました」は手段の意味が出ず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「リーダーシップを、チームが一つになりました」は目的語として不自然で、結果の文にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「リーダーシップへ、チームが一つになる」は意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "「新しいキャプテンのリーダーシップで、チームが一つになりました」の「で」は、手段や理由を示す。", "に": "「リーダーシップに、チームが一つになりました」は手段の意味が出ず、文が成り立たない。", "を": "「リーダーシップを、チームが一つになりました」は目的語として不自然で、結果の文にならない。", "へ": "「へ」は方向を示すので、「リーダーシップへ、チームが一つになる」は意味が通らない。"}, "error_tags": {"に": "location_or_target", "を": "object", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37436, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37436, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の集まりで、みんなをまとめて引っぱっていく力のことです。", "primary_collocate": null, "pronunciation": "りーだーしっぷ", "ipa": "ɾiːdaːɕippɯ", "syllable_count": 7, "sentences": [{"text": "彼女はリーダーシップがあるので、みんなが安心してついていきます。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はリーダーシップがあるので、みんなが安心[あんしん]してついていきます。", "sentence_source": "generated"}, {"text": "新しいキャプテンのリーダーシップで、チームが一つになりました。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "新[あたら]しいキャプテンのリーダーシップで、チームが一[ひと]つになりました。", "sentence_source": "generated"}, {"text": "リーダーシップとは、ただ命令することではありません。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "リーダーシップとは、ただ命令[めいれい]することではありません。", "sentence_source": "generated"}, {"text": "兄は小さいころから、リーダーシップを発揮して遊びを決めていました。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "兄[あに]は小[ちい]さいころから、リーダーシップを発揮[はっき]して遊[あそ]びを決[き]めていました。", "sentence_source": "generated"}, {"text": "班長にはリーダーシップが必要なので、先生は田中さんを選びました。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "班長[はんちょう]にはリーダーシップが必要[ひつよう]なので、先生[せんせい]は田中[たなか]さんを選[えら]びました。", "sentence_source": "generated"}, {"text": "彼はリーダーシップが弱く、会議がいつもまとまりません。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "彼[かれ]はリーダーシップが弱[よわ]く、会議[かいぎ]がいつもまとまりません。", "sentence_source": "generated"}, {"text": "リーダーシップを身につけたくて、学級委員に立候補しました。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "リーダーシップを身[み]につけたくて、学級委員[がっきゅういいん]に立候補[りっこうほ]しました。", "sentence_source": "generated"}, {"text": "困ったときに声をかけてくれる、先輩のリーダーシップに助けられました。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "困[こま]ったときに声[こえ]をかけてくれる、先輩[せんぱい]のリーダーシップに助[たす]けられました。", "sentence_source": "generated"}, {"text": "リーダーシップのある人は、話を聞く力も持っています。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "リーダーシップのある人[ひと]は、話[はなし]を聞[き]く力[ちから]も持[も]っています。", "sentence_source": "generated"}, {"text": "山で道に迷ったとき、姉のリーダーシップのおかげで全員が無事に帰れました。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "山[やま]で道[みち]に迷[まよ]ったとき、姉[あね]のリーダーシップのおかげで全員[ぜんいん]が無事[ぶじ]に帰[かえ]れました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リーダーシップ", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "身近な集団(クラス・チーム・家族など)をまとめて引っぱる力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1bc596f-8b8d-4af6-bf10-97dcd2d33ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37436, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リーダーシップ", "is_correct": true, "explanation": "「彼女はリーダーシップがあるので、みんなが安心してついていく」の空所には、人をまとめて引っぱる力を表す語が入る。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気の状態を表す語で、人をまとめる力という文脈には入らない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさを表す語で、「彼女は〜があるので」の空所には意味が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は身体の重さを表す語で、人を引っぱる力の説明には合わない。"}], "explanations": {"リーダーシップ": "「彼女はリーダーシップがあるので、みんなが安心してついていく」の空所には、人をまとめて引っぱる力を表す語が入る。", "湿度": "湿度は空気の状態を表す語で、人をまとめる力という文脈には入らない。", "音量": "音量は音の大きさを表す語で、「彼女は〜があるので」の空所には意味が通らない。", "体重": "体重は身体の重さを表す語で、人を引っぱる力の説明には合わない。"}, "sentence_index": 0, "correct_answer": "リーダーシップ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "次のリーダーシップは田中さんに決まりました。", "explanation": "ここは〈リーダー（人）〉の意味。リーダーシップは能力や行動を指すので、人として選ばれる文には合わない。"}, {"text": "クラスのリーダーシップは、いつも遅刻してきます。", "explanation": "ここは〈ボス（人）〉の意味。リーダーシップは人ではないので、遅刻する主体にはならない。"}, {"text": "リーダーシップが三人集まりました。", "explanation": "ここは〈メンバー（人）〉の意味。リーダーシップは人を数える言葉ではないので、三人と数えられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37436, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リーダーシップ", "is_correct": true, "explanation": "「リーダーシップを身につけたくて、学級委員に立候補した」の空所には、人を導く力を表す語が入る。"}, {"text": "寝袋", "is_correct": false, "explanation": "寝袋は身につけるものではないので、「寝袋を身につけたくて」は成り立たない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は身につけて得る能力ではなく、「身につけたくて」の対象にならない。"}, {"text": "騒音", "is_correct": false, "explanation": "騒音は身につけて得る能力ではないので、「身につけたくて」と続かない。"}], "explanations": {"リーダーシップ": "「リーダーシップを身につけたくて、学級委員に立候補した」の空所には、人を導く力を表す語が入る。", "寝袋": "寝袋は身につけるものではないので、「寝袋を身につけたくて」は成り立たない。", "切手": "切手は身につけて得る能力ではなく、「身につけたくて」の対象にならない。", "騒音": "騒音は身につけて得る能力ではないので、「身につけたくて」と続かない。"}, "sentence_index": 6, "correct_answer": "リーダーシップ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このクラブのリーダーシップは、毎週金曜日の練習を休むことです。", "explanation": "ここは〈ルール（規則）〉の意味。リーダーシップは能力や行動で、守るべき決まりは表さないので合わない。"}, {"text": "クラブのリーダーシップは、毎週放課後に来てくれます。", "explanation": "ここは〈顧問（人）〉の意味。リーダーシップは人ではないので、来てくれる主体にはならない。"}, {"text": "班の集合場所は、リーダーシップの近くです。", "explanation": "ここは〈集合場所（場所）〉の意味。リーダーシップは能力や行動で、場所として存在しないので、近くにあるとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37436, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼はリーダーシップに発揮して、班をまとめました。", "corrected_sentence": "彼はリーダーシップを発揮して、班をまとめました。", "error_description": "「発揮する」の対象は「を」で示す。「に」にすると「リーダーシップに発揮する」となり、文が不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37436, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女はリーダーシップを身にあげました。", "corrected_sentence": "彼女はリーダーシップを身につけました。", "error_description": "「身につける」が正しい。「身にあげる」は能力を身につけるという意味にならず、誤った動詞になっている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37437, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「若い社員にもリーダーシップを求めています」の「を」は、「求める」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「求める」は目的語を「を」で示すので、「リーダーシップが求めています」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「リーダーシップに求める」は意味が通らず、目的語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「求める」の対象は表せない。"}], "correct_answer": "を", "explanations": {"を": "「若い社員にもリーダーシップを求めています」の「を」は、「求める」の目的語を示す。", "が": "「求める」は目的語を「を」で示すので、「リーダーシップが求めています」は不自然。", "に": "「リーダーシップに求める」は意味が通らず、目的語を示せない。", "で": "「で」は手段や場所を示すので、「求める」の対象は表せない。"}, "error_tags": {"が": "subject", "に": "target_or_direction", "で": "means_or_place"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37437, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「市長のリーダーシップにより、町の再開発が実現しました」の「により」の「に」は、原因や手段を示す。"}, {"text": "を", "is_correct": false, "explanation": "「リーダーシップをにより」は成り立たず、「により」の形を作れない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、原因を表す「により」の形には使えない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示すので、「リーダーシップの〜により」の形を作るには「に」が必要。"}], "correct_answer": "に", "explanations": {"に": "「市長のリーダーシップにより、町の再開発が実現しました」の「により」の「に」は、原因や手段を示す。", "を": "「リーダーシップをにより」は成り立たず、「により」の形を作れない。", "へ": "「へ」は方向を示すので、原因を表す「により」の形には使えない。", "の": "「の」は所属や修飾を示すので、「リーダーシップの〜により」の形を作るには「に」が必要。"}, "error_tags": {"を": "object", "へ": "direction", "の": "modifier"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37437, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "集団や組織において、目標を達成するために他のメンバーを導き、影響を与える能力や行動のこと。", "primary_collocate": null, "pronunciation": "りーだーしっぷ", "ipa": "ɾiːdaːɕippɯ", "syllable_count": 7, "sentences": [{"text": "部長のリーダーシップのおかげで、新しい計画が予定どおりに進みました。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "部長[ぶちょう]のリーダーシップのおかげで、新[あたら]しい計画[けいかく]が予定[よてい]どおりに進[すす]みました。", "sentence_source": "generated"}, {"text": "この会社では、若い社員にもリーダーシップを求めています。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]では、若[わか]い社員[しゃいん]にもリーダーシップを求[もと]めています。", "sentence_source": "generated"}, {"text": "目標を達成するには、チーム全体を導くリーダーシップが欠かせません。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "目標[もくひょう]を達成[たっせい]するには、チーム全体[ぜんたい]を導[みちび]くリーダーシップが欠[か]かせません。", "sentence_source": "generated"}, {"text": "研修では、メンバーに影響を与えるリーダーシップの方法を学びました。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "研修[けんしゅう]では、メンバーに影響[えいきょう]を与[あた]えるリーダーシップの方法[ほうほう]を学[まな]びました。", "sentence_source": "generated"}, {"text": "社長は強いリーダーシップで、会社の改革を進めました。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は強[つよ]いリーダーシップで、会社[かいしゃ]の改革[かいかく]を進[すす]めました。", "sentence_source": "generated"}, {"text": "リーダーシップを発揮できる人材を、管理職に選びます。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "リーダーシップを発揮[はっき]できる人材[じんざい]を、管理職[かんりしょく]に選[えら]びます。", "sentence_source": "generated"}, {"text": "プロジェクトが失敗したのは、リーダーシップが足りなかったからです。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "プロジェクトが失敗[しっぱい]したのは、リーダーシップが足[た]りなかったからです。", "sentence_source": "generated"}, {"text": "市長のリーダーシップにより、町の再開発が実現しました。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "市長[しちょう]のリーダーシップにより、町[まち]の再開発[さいかいはつ]が実現[じつげん]しました。", "sentence_source": "generated"}, {"text": "現場の声を聞くことも、大切なリーダーシップの一つです。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "現場[げんば]の声[こえ]を聞[き]くことも、大切[たいせつ]なリーダーシップの一[ひと]つです。", "sentence_source": "generated"}, {"text": "彼女は営業チームのリーダーとして、リーダーシップを学ぶ講座に通っています。", "target_word": "リーダーシップ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は営業[えいぎょう]チームのリーダーとして、リーダーシップを学[まな]ぶ講座[こうざ]に通[かよ]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リーダーシップ", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "会社・組織・行政で、目標達成のためにメンバーを導き影響を与える能力や行動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1bc596f-8b8d-4af6-bf10-97dcd2d33ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37437, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リーダーシップ", "is_correct": true, "explanation": "「部長のリーダーシップのおかげで、計画が予定どおりに進んだ」の空所には、組織をまとめる能力が入る。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気の状態を表す語で、部長の能力という文脈には入らない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさを表す語で、「部長の〜のおかげで」の空所には意味が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は身体の重さを表す語で、計画が進んだ理由としては成り立たない。"}], "explanations": {"リーダーシップ": "「部長のリーダーシップのおかげで、計画が予定どおりに進んだ」の空所には、組織をまとめる能力が入る。", "湿度": "湿度は空気の状態を表す語で、部長の能力という文脈には入らない。", "音量": "音量は音の大きさを表す語で、「部長の〜のおかげで」の空所には意味が通らない。", "体重": "体重は身体の重さを表す語で、計画が進んだ理由としては成り立たない。"}, "sentence_index": 0, "correct_answer": "リーダーシップ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "うちのリーダーシップは、毎朝私に声をかけてくれます。", "explanation": "ここは〈上司（人）〉の意味。リーダーシップは能力や行動を指すので、声をかける主体にはならない。"}, {"text": "リーダーシップが資料を確認します。", "explanation": "ここは〈担当者（人）〉の意味。リーダーシップは人ではないので、確認する主体にはならない。"}, {"text": "会議室のリーダーシップは、三階にあります。", "explanation": "ここは〈会議室（場所）〉の意味。リーダーシップは能力や行動で、場所としては存在しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37437, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リーダーシップ", "is_correct": true, "explanation": "「プロジェクトが失敗したのは、リーダーシップが足りなかったから」の空所には、導く力を表す語が入る。"}, {"text": "雲", "is_correct": false, "explanation": "雲は不足して失敗の理由になるものではなく、「足りなかった」と続かない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は失敗の理由として「足りなかった」とは言わないので、文の流れに合わない。"}, {"text": "夜空", "is_correct": false, "explanation": "夜空が足りないという状況は、プロジェクトの失敗の理由として成り立たない。"}], "explanations": {"リーダーシップ": "「プロジェクトが失敗したのは、リーダーシップが足りなかったから」の空所には、導く力を表す語が入る。", "雲": "雲は不足して失敗の理由になるものではなく、「足りなかった」と続かない。", "天気": "天気は失敗の理由として「足りなかった」とは言わないので、文の流れに合わない。", "夜空": "夜空が足りないという状況は、プロジェクトの失敗の理由として成り立たない。"}, "sentence_index": 6, "correct_answer": "リーダーシップ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研修会のリーダーシップは、三十人の参加者です。", "explanation": "ここは〈研修会（行事）〉の意味。リーダーシップは能力で、参加者として数えられない。"}, {"text": "事務所のリーダーシップは、駅の近くにあります。", "explanation": "ここは〈事務所（場所）〉の意味。リーダーシップは能力や行動で、場所としては存在しない。"}, {"text": "経理のリーダーシップが伝票を整理しました。", "explanation": "ここは〈経理（部署・人）〉の意味。リーダーシップは人ではないので、伝票を整理する主体にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37437, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社長はリーダーシップが発揮して、会社を変えました。", "corrected_sentence": "社長はリーダーシップを発揮して、会社を変えました。", "error_description": "「発揮する」の対象は「を」で示す。「が」にすると「リーダーシップが発揮する」となり、対象を誤って示している。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37437, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は強いリーダーシップを会社を導いています。", "corrected_sentence": "彼は強いリーダーシップで会社を導いています。", "error_description": "手段を示す「で」が正しい。「を」にすると目的語が二つ並んで文が不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37438, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37438, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「受付の者で案内いたします」は意味が通らない。"}, {"text": "が", "is_correct": true, "explanation": "「案内する」の主語として受付の者を示す。「受付の者がすぐにご案内いたします」は自然な形。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同や引用を示すため、「受付の者と案内いたします」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐため、「受付の者のすぐにご案内いたします」は文として続かない。"}], "correct_answer": "が", "explanations": {"で": "「で」は手段や場所を示すため、「受付の者で案内いたします」は意味が通らない。", "が": "「案内する」の主語として受付の者を示す。「受付の者がすぐにご案内いたします」は自然な形。", "と": "「と」は共同や引用を示すため、「受付の者と案内いたします」は不自然。", "の": "「の」は名詞どうしをつなぐため、「受付の者のすぐにご案内いたします」は文として続かない。"}, "error_tags": {"で": "手段・場所", "と": "共同・引用", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37438, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「者」は、何かをする人や、ある役割を持つ人のことを言います。", "primary_collocate": null, "pronunciation": "もの", "ipa": "mono", "syllable_count": 2, "sentences": [{"text": "参加を希望する者は、明日までに申し込んでください。", "target_word": "者", "complexity_tier": "T3", "furigana": "参加[さんか]を希望[きぼう]する者[もの]は、明日[あした]までに申[もう]し込[こ]んでください。", "sentence_source": "generated"}, {"text": "私は山田商事の者ですが、田中さんはいらっしゃいますか。", "target_word": "者", "complexity_tier": "T3", "furigana": "私[わたし]は山田商事[やまだしょうじ]の者[もの]ですが、田中[たなか]さんはいらっしゃいますか。", "sentence_source": "generated"}, {"text": "困っている者を見たら、助けるのが当たり前だ。", "target_word": "者", "complexity_tier": "T3", "furigana": "困[こま]っている者[もの]を見[み]たら、助[たす]けるのが当[あ]たり前[まえ]だ。", "sentence_source": "generated"}, {"text": "怪しい者ではありませんので、安心してください。", "target_word": "者", "complexity_tier": "T3", "furigana": "怪[あや]しい者[もの]ではありませんので、安心[あんしん]してください。", "sentence_source": "generated"}, {"text": "最後まで走りきった者だけが、この賞をもらえる。", "target_word": "者", "complexity_tier": "T3", "furigana": "最後[さいご]まで走[はし]りきった者[もの]だけが、この賞[しょう]をもらえる。", "sentence_source": "generated"}, {"text": "若い者に仕事を任せて、自分は少し休むことにした。", "target_word": "者", "complexity_tier": "T3", "furigana": "若[わか]い者[もの]に仕事[しごと]を任[まか]せて、自分[じぶん]は少[すこ]し休[やす]むことにした。", "sentence_source": "generated"}, {"text": "約束を守らない者は、信用されなくなる。", "target_word": "者", "complexity_tier": "T3", "furigana": "約束[やくそく]を守[まも]らない者[もの]は、信用[しんよう]されなくなる。", "sentence_source": "generated"}, {"text": "受付の者がすぐにご案内いたします。", "target_word": "者", "complexity_tier": "T3", "furigana": "受付[うけつけ]の者[もの]がすぐにご案内[あんない]いたします。", "sentence_source": "generated"}, {"text": "彼は何も持たない者だったが、努力で成功をつかんだ。", "target_word": "者", "complexity_tier": "T3", "furigana": "彼[かれ]は何[なに]も持[も]たない者[もの]だったが、努力[どりょく]で成功[せいこう]をつかんだ。", "sentence_source": "generated"}, {"text": "学校の規則を破った者には、罰が与えられる。", "target_word": "者", "complexity_tier": "T3", "furigana": "学校[がっこう]の規則[きそく]を破[やぶ]った者[もの]には、罰[ばつ]が与[あた]えられる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "者", "label": "基本形"}, {"form": "者たち", "label": "複数形"}], "register": "neutral", "sense_fingerprint": "ある行為をする人、ある立場や役割にある人を指す「もの」（単独で使う場合）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe8a64e-398a-44c0-8fce-9cbeb83b8e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37438, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会場", "is_correct": false, "explanation": "会場は人ではないので、「参加を希望する会場は、明日までに申し込んで」は意味が通らない。"}, {"text": "者", "is_correct": true, "explanation": "参加を希望する人を指し、「参加を希望する者は、明日までに申し込んでください」と自然に続く。"}, {"text": "時間", "is_correct": false, "explanation": "時間は申し込む対象の人にはならず、「参加を希望する時間は」は文が成り立たない。"}, {"text": "料金", "is_correct": false, "explanation": "料金は参加する人を指さず、「参加を希望する料金は、明日までに申し込んで」は合わない。"}], "explanations": {"会場": "会場は人ではないので、「参加を希望する会場は、明日までに申し込んで」は意味が通らない。", "者": "参加を希望する人を指し、「参加を希望する者は、明日までに申し込んでください」と自然に続く。", "時間": "時間は申し込む対象の人にはならず、「参加を希望する時間は」は文が成り立たない。", "料金": "料金は参加する人を指さず、「参加を希望する料金は、明日までに申し込んで」は合わない。"}, "sentence_index": 0, "correct_answer": "者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上にあった者を、誰かが持っていった。", "explanation": "者は人を指すので、机の上の品物には使えない。"}, {"text": "冷蔵庫に入れておいた者を、昨日みんなで食べた。", "explanation": "者は人を指すので、冷蔵庫に入れておく食品には使わない。"}, {"text": "駐車場に停めてあった者が、突然動いた。", "explanation": "者は人を指すので、駐車していた車には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37438, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電車", "is_correct": false, "explanation": "電車は約束を守る守らないの対象にならず、「約束を守らない電車は」は意味が通らない。"}, {"text": "者", "is_correct": true, "explanation": "約束を守らない人を指し、「約束を守らない者は、信用されなくなる」と自然に続く。"}, {"text": "時計", "is_correct": false, "explanation": "時計は約束を守る主体ではないので、「約束を守らない時計は信用されなくなる」は不自然。"}, {"text": "靴", "is_correct": false, "explanation": "靴は約束をする主体にならず、「約束を守らない靴は」は文が成り立たない。"}], "explanations": {"電車": "電車は約束を守る守らないの対象にならず、「約束を守らない電車は」は意味が通らない。", "者": "約束を守らない人を指し、「約束を守らない者は、信用されなくなる」と自然に続く。", "時計": "時計は約束を守る主体ではないので、「約束を守らない時計は信用されなくなる」は不自然。", "靴": "靴は約束をする主体にならず、「約束を守らない靴は」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この者は駅の近くにあって、とても便利だ。", "explanation": "者は人を指すので、建物や地点には使わない。"}, {"text": "古いセーターの者を、もう捨ててしまった。", "explanation": "者は人を指すので、セーターのような衣類には使わない。"}, {"text": "冷たい者を、夏に飲むと気持ちいい。", "explanation": "者は人を指すので、飲む物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37438, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "受付に来た者を、名前を書いてください。", "corrected_sentence": "受付に来た者は、名前を書いてください。", "error_description": "誤：「者を」、正：「者は」。文の話題として「者」を示すため「は」が必要。「を」だと後ろの「名前を」と目的語が重なり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37438, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "規則を守らなくて者は、信用されなくなる。", "corrected_sentence": "規則を守らない者は、信用されなくなる。", "error_description": "誤：「守らなくて者」、正：「守らない者」。名詞を修飾するときは「守らない」の普通形を使う。「なくて」の形は名詞に続けられない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37439, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「見る者によって」の「に」。「によって」の形で、作用する主体を表す。"}, {"text": "が", "is_correct": false, "explanation": "「者が」は主語になり、「によって」の形にならず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「者で」は手段を表す「で」だが、後ろの「よって」と結びつかない。"}, {"text": "を", "is_correct": false, "explanation": "「者を」は目的語になり、「よって」と合わず文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「見る者によって」の「に」。「によって」の形で、作用する主体を表す。", "が": "「者が」は主語になり、「によって」の形にならず文が成り立たない。", "で": "「者で」は手段を表す「で」だが、後ろの「よって」と結びつかない。", "を": "「者を」は目的語になり、「よって」と合わず文が成り立たない。"}, "error_tags": {"に": "「によって」の一部", "が": "主語", "で": "手段・場所", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37439, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37439, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「者」は、特定の動作や状態にある人を指す名詞です。多くの場合、漢語や連体修飾語と結びついて「〜する人」という意味を表します。", "primary_collocate": null, "pronunciation": "もの", "ipa": "mono", "syllable_count": 2, "sentences": [{"text": "この理論的基盤は、建物に込められた作者の意図や固定的な意味を脱構築し、その背後にある社会的な文脈や矛盾を浮き彫りにします。", "target_word": "者", "complexity_tier": "T5", "furigana": "この理論的基盤[りろんてききばん]は、建物[たてもの]に込[こ]められた作者[さくしゃ]の意図[いと]や固定的[こていてき]な意味[いみ]を脱構築[だつこうちく]し、その背後[はいご]にある社会的[しゃかいてき]な文脈[ぶんみゃく]や矛盾[むじゅん]を浮[う]き彫[ぼ]りにします。", "sentence_source": "mined"}, {"text": "結果として、建築は静的な物体ではなく、見る者によって絶えず意味が更新される開かれた場として再定義されるのです。", "target_word": "者", "complexity_tier": "T5", "furigana": "結果[けっか]として、建築[けんちく]は静的[せいてき]な物体[ぶったい]ではなく、見[み]る者[もの]によって絶[た]えず意味[いみ]が更新[こうしん]される開[ひら]かれた場[ば]として再定義[さいていぎ]されるのです。", "sentence_source": "mined"}, {"text": "それは、言葉を持たぬ者が自然と交わす、最も純粋な対話の形なのかもしれない。", "target_word": "者", "complexity_tier": "T5", "furigana": "それは、言葉[ことば]を持[も]たぬ者[もの]が自然[しぜん]と交[まじ]わす、最[もっと]も純粋[じゅんすい]な対話[たいわ]の形[かたち]なのかもしれない。", "sentence_source": "mined"}, {"text": "それこそが、静謐な自宅の工房において初学者が向き合う、ロボット製作の本質である。", "target_word": "者", "complexity_tier": "T5", "furigana": "それこそが、静謐[せいひつ]な自宅[じたく]の工房[こうぼう]において初学者[しょがくしゃ]が向[む]き合[あ]う、ロボット製作[せいさく]の本質[ほんしつ]である。", "sentence_source": "mined"}, {"text": "ロボット工学の深淵を志す者がまず体現すべきは、DIYの精神に根ざした泥臭い試行錯誤のプロセスに他ならない。", "target_word": "者", "complexity_tier": "T5", "furigana": "ロボット工学[こうがく]の深淵[しんえん]を志[こころざ]す者[もの]がまず体現[たいげん]すべきは、DIYの精神[せいしん]に根[ね]ざした泥臭[どろくさ]い試行錯誤[しこうさくご]のプロセスに他[ほか]ならない。", "sentence_source": "mined"}, {"text": "責任のある者が、最後まで話を聞くべきです。", "target_word": "者", "complexity_tier": "T3", "furigana": "責任[せきにん]のある者[もの]が、最後[さいご]まで話[はなし]を聞[き]くべきです。", "sentence_source": "generated"}, {"text": "若い者には負けないと、祖父は笑って言いました。", "target_word": "者", "complexity_tier": "T3", "furigana": "若[わか]い者[もの]には負[ま]けないと、祖父[そふ]は笑[わら]って言[い]いました。", "sentence_source": "generated"}, {"text": "関係のない者は、この部屋に入らないでください。", "target_word": "者", "complexity_tier": "T3", "furigana": "関係[かんけい]のない者[もの]は、この部屋[へや]に入[はい]らないでください。", "sentence_source": "generated"}, {"text": "努力を続けた者だけが、本当の喜びを味わえます。", "target_word": "者", "complexity_tier": "T3", "furigana": "努力[どりょく]を続[つづ]けた者[もの]だけが、本当[ほんとう]の喜[よろこ]びを味[あじ]わえます。", "sentence_source": "generated"}, {"text": "この会社で働く者として、お客様との約束は必ず守ります。", "target_word": "者", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]で働[はたら]く者[もの]として、お客様[きゃくさま]との約束[やくそく]は必[かなら]ず守[まも]ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "者", "label": "基本形"}, {"form": "者たち", "label": "複数形"}, {"form": "者が", "label": "が格"}], "register": "neutral", "sense_fingerprint": "連体修飾語を受けて「〜する人」を表す名詞「者」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 静的 (Zipf 3.04), 物体 (Zipf 3.86), 絶えず (Zipf 3.47)','sentence 3 above tier T1: 3 words above tier T1 (max 2): 静謐 (Zipf 2.66), 工房 (Zipf 3.99), 向き合う (Zipf 3.7)','sentence 4 above tier T1: 7 words above tier T1 (max 2): 深淵 (Zipf 3.16), 志す (Zipf 3.1), 体現 (Zipf 3.4), diy (Zipf 3.44), 根ざし (Zipf 2.82), 泥臭い (Zipf 2.6)']::text[], '08e7e9f6-0f05-455b-afc5-ee87762d7379') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37439, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "者", "is_correct": true, "explanation": "「責任のある者」の「者」。人を表し、「責任のある〇〇が」に入って文が成り立つ。"}, {"text": "色", "is_correct": false, "explanation": "「責任のある色が」は意味が通らず、人を表さない。"}, {"text": "波", "is_correct": false, "explanation": "「責任のある波が」は人に当てはまらず、文が成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "「責任のある窓が」は意味が通らず、文に合わない。"}], "explanations": {"者": "「責任のある者」の「者」。人を表し、「責任のある〇〇が」に入って文が成り立つ。", "色": "「責任のある色が」は意味が通らず、人を表さない。", "波": "「責任のある波が」は人に当てはまらず、文が成り立たない。", "窓": "「責任のある窓が」は意味が通らず、文に合わない。"}, "sentence_index": 0, "correct_answer": "者"}, "level_6": {"correct_sentence_index": 8, "wrong_sentences": [{"text": "この箱の中には、古い者がたくさん入っている。", "explanation": "〈物〉の意味。「者」は人を指すので、箱の中のものには使えない。「物」と言う。"}, {"text": "彼女は、いつも一番静かな者で本を読む。", "explanation": "〈場所〉の意味。読書をする場所は「場所」や「部屋」と言い、「者」は人を指すので使えない。"}, {"text": "庭の池には、めずらしい者が泳いでいる。", "explanation": "〈生き物〉の意味。「者」は人にだけ使うので、池にいる魚には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37439, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "者", "is_correct": true, "explanation": "「若い者」の「者」。人を表すので空欄に入り、「負けない」と自然につながる。"}, {"text": "花", "is_correct": false, "explanation": "「若い花には負けない」は人を表さず、意味が通らない。"}, {"text": "机", "is_correct": false, "explanation": "「若い机には負けない」は人を表さず、文として意味が通らない。"}, {"text": "石", "is_correct": false, "explanation": "「若い石には負けない」は人に当てはまらず、文として成り立たない。"}], "explanations": {"者": "「若い者」の「者」。人を表すので空欄に入り、「負けない」と自然につながる。", "花": "「若い花には負けない」は人を表さず、意味が通らない。", "机": "「若い机には負けない」は人を表さず、文として意味が通らない。", "石": "「若い石には負けない」は人に当てはまらず、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この案は、三日かけて作った者だ。", "explanation": "〈企画〉の意味。「者」は人を指すので、案のような物事には使えない。「企画」と言う。"}, {"text": "その絵は、三年かけて描いた者だ。", "explanation": "〈作品〉の意味。「者」は人を指すので、絵には使えない。「作品」と言う。"}, {"text": "その事件は、突然起きた者だ。", "explanation": "〈出来事〉の意味。「者」は人を指すので、事件には使えない。「出来事」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37439, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この製品を試した者に、使いやすさを評価している。", "corrected_sentence": "この製品を試した者が、使いやすさを評価している。", "error_description": "格助詞の誤り。「者に」は評価する主体（主語）を示せない。主語を示す「が」が正しい。", "correct_sentence_indices": [1, 2, 4]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37439, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若い者を、率先して掃除を手伝ってくれた。", "corrected_sentence": "若い者が、率先して掃除を手伝ってくれた。", "error_description": "格助詞の誤り。「若い者」は手伝う主体なので主語を示す「が」が正しく、「を」では目的語になって文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
