INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37440, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「支援を求める」の目的語。求める対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格。「支援が求める電話」は「求める」の主語として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「支援に求める」は対象を示す形として合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所。「支援で求める」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「支援を求める」の目的語。求める対象を示す。", "が": "主格。「支援が求める電話」は「求める」の主語として不自然。", "に": "「支援に求める」は対象を示す形として合わない。", "で": "手段・場所。「支援で求める」は成り立たない。"}, "error_tags": {"が": "主格", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37440, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ほかの人をたすけること。", "primary_collocate": null, "pronunciation": "しえん", "ipa": "ɕieɴ", "syllable_count": 3, "sentences": [{"text": "困っている友だちを支援したい。", "target_word": "支援", "complexity_tier": "T2", "furigana": "困[こま]っている友[とも]だちを支援[しえん]したい。", "sentence_source": "generated"}, {"text": "先生は生徒の勉強を支援してくれる。", "target_word": "支援", "complexity_tier": "T2", "furigana": "先生[せんせい]は生徒[せいと]の勉強[べんきょう]を支援[しえん]してくれる。", "sentence_source": "generated"}, {"text": "この町では、一人暮らしの高齢者への支援が行われている。", "target_word": "支援", "complexity_tier": "T4", "furigana": "この町[まち]では、一人暮[ひとりぐ]らしの高齢者[こうれいしゃ]への支援[しえん]が行[おこな]われている。", "sentence_source": "generated"}, {"text": "みんなの支援のおかげで、無事に大会を終えられた。", "target_word": "支援", "complexity_tier": "T3", "furigana": "みんなの支援[しえん]のおかげで、無事[ぶじ]に大会[たいかい]を終[お]えられた。", "sentence_source": "generated"}, {"text": "災害のとき、多くの国が日本を支援した。", "target_word": "支援", "complexity_tier": "T3", "furigana": "災害[さいがい]のとき、多[おお]くの国[くに]が日本[にほん]を支援[しえん]した。", "sentence_source": "generated"}, {"text": "母は私の夢をいつも支援してくれる。", "target_word": "支援", "complexity_tier": "T2", "furigana": "母[はは]は私[わたし]の夢[ゆめ]をいつも支援[しえん]してくれる。", "sentence_source": "generated"}, {"text": "彼は貧しい地域の学校を支援するために、毎月寄付をしている。", "target_word": "支援", "complexity_tier": "T4", "furigana": "彼[かれ]は貧[まず]しい地域[ちいき]の学校[がっこう]を支援[しえん]するために、毎月[まいつき]寄付[きふ]をしている。", "sentence_source": "generated"}, {"text": "支援を求める電話が、昼も夜も鳴り続けた。", "target_word": "支援", "complexity_tier": "T3", "furigana": "支援[しえん]を求[もと]める電話[でんわ]が、昼[ひる]も夜[よる]も鳴[な]り続[つづ]けた。", "sentence_source": "generated"}, {"text": "病気の家族を持つ人を支援する仕組みが必要だ。", "target_word": "支援", "complexity_tier": "T4", "furigana": "病気[びょうき]の家族[かぞく]を持[も]つ人[ひと]を支援[しえん]する仕組[しく]みが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "兄の仕事を支援しようと、週末は店を手伝った。", "target_word": "支援", "complexity_tier": "T3", "furigana": "兄[あに]の仕事[しごと]を支援[しえん]しようと、週末[しゅうまつ]は店[みせ]を手伝[てつだ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "支援", "label": "基本形"}, {"form": "支援する", "label": "サ変動詞"}], "register": "formal", "sense_fingerprint": "ほかの人をたすけること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b24d15-9ff0-4e3d-8f40-83d3e5a40e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37440, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "支援", "is_correct": true, "explanation": "「友だちを支援したい」。助けるという意味で文が成り立つ。"}, {"text": "修理", "is_correct": false, "explanation": "「友だちを修理したい」は意味が通らない。"}, {"text": "購入", "is_correct": false, "explanation": "「友だちを購入したい」は不自然。"}, {"text": "分解", "is_correct": false, "explanation": "「友だちを分解したい」は文脈に合わない。"}], "explanations": {"支援": "「友だちを支援したい」。助けるという意味で文が成り立つ。", "修理": "「友だちを修理したい」は意味が通らない。", "購入": "「友だちを購入したい」は不自然。", "分解": "「友だちを分解したい」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "支援"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店は、足りなくなった在庫を支援した。", "explanation": "ここは〈補充〉の意味。足りない在庫を補うことを指すので、人を助ける支援とは合わない。"}, {"text": "大雨が続き、練習の支援が出た。", "explanation": "ここは〈支障〉の意味。練習の妨げを指すので、助けるという支援は合わない。"}, {"text": "溺れた子の体重を支援した。", "explanation": "ここは〈支える〉の意味。体重を支えることを指すので、人を助ける支援とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37440, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支援", "is_correct": true, "explanation": "「学校を支援するために寄付をしている」。助けるという意味で寄付の目的と合う。"}, {"text": "睡眠", "is_correct": false, "explanation": "「学校を睡眠するために」は意味が通らない。"}, {"text": "停電", "is_correct": false, "explanation": "「学校を停電するために」は文脈に合わない。"}, {"text": "遠足", "is_correct": false, "explanation": "「学校を遠足するために」は不自然。"}], "explanations": {"支援": "「学校を支援するために寄付をしている」。助けるという意味で寄付の目的と合う。", "睡眠": "「学校を睡眠するために」は意味が通らない。", "停電": "「学校を停電するために」は文脈に合わない。", "遠足": "「学校を遠足するために」は不自然。"}, "sentence_index": 6, "correct_answer": "支援"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "兄の体を支援しようと、週末は店を手伝った。", "explanation": "ここは〈支える〉の意味。体を支えることを指すので、人の行動を助ける支援とは合わない。"}, {"text": "兄の機嫌を支援しようと、週末は店を手伝った。", "explanation": "ここは〈機嫌取り〉の意味。機嫌を取ることを指すので、人の活動を助ける支援とは合わない。"}, {"text": "兄の仕事の欠点を支援しようと、週末は店を手伝った。", "explanation": "ここは〈指摘〉の意味。欠点を示す行為を指すので、助ける支援とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37440, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は友人の挑戦を支援したがる。", "corrected_sentence": "私は友人の挑戦を支援したい。", "error_description": "「〜たい」は話し手自身の願望を表す。「〜たがる」は第三者の願望を表すので、「私は…支援したがる」は不自然。正しくは「支援したい」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37440, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地域の人々は、子どもたちの登下校を支援された。", "corrected_sentence": "地域の人々は、子どもたちの登下校を支援している。", "error_description": "「支援している」は支援する側の動作。「支援された」は受け身で、地域の人々が支援を受ける側になり文の意味が変わる。正しくは「支援している」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37441, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「支援を続けている」の目的語。続けられる対象として自然に入る。"}, {"text": "に", "is_correct": false, "explanation": "「支援に続けている」は「続ける」と合わず不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所。「支援で続けている」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「支援と続けている」は動詞と合わず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「支援を続けている」の目的語。続けられる対象として自然に入る。", "に": "「支援に続けている」は「続ける」と合わず不自然。", "で": "手段・場所。「支援で続けている」は成り立たない。", "と": "「支援と続けている」は動詞と合わず、文が成り立たない。"}, "error_tags": {"に": "方向・相手", "で": "手段・場所", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37441, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「届いた」の主語。食料や水の支援が届いたという文で主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語。「届く」は目的語を取らず、支援を届く対象にできない。"}, {"text": "に", "is_correct": false, "explanation": "「支援に届いた」は到着先として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「支援と届いた」は並列の形で、動作の主体にならない。"}], "correct_answer": "が", "explanations": {"が": "「届いた」の主語。食料や水の支援が届いたという文で主語を示す。", "を": "目的語。「届く」は目的語を取らず、支援を届く対象にできない。", "に": "「支援に届いた」は到着先として不自然。", "と": "「支援と届いた」は並列の形で、動作の主体にならない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37441, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分のことよりも、誰か他の人が何かをするのを助けること。", "primary_collocate": null, "pronunciation": "しえん", "ipa": "ɕieɴ", "syllable_count": 3, "sentences": [{"text": "ベンチャーキャピタルは、将来性のあるスタートアップへリスクを取って資金調達を行い、その成長を支援する重要な役割を担っている。", "target_word": "支援", "complexity_tier": "T5", "furigana": "ベンチャーキャピタルは、将来性[しょうらいせい]のあるスタートアップへリスクを取[と]って資金調達[しきんちょうたつ]を行[おこな]い、その成長[せいちょう]を支援[しえん]する重要[じゅうよう]な役割[やくわり]を担[にな]っている。", "sentence_source": "mined"}, {"text": "市は、被災した人々への支援を続けている。", "target_word": "支援", "complexity_tier": "T3", "furigana": "市[し]は、被災[ひさい]した人々[ひとびと]への支援[しえん]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "先輩が就職活動を支援してくれたおかげで、内定をもらえた。", "target_word": "支援", "complexity_tier": "T3", "furigana": "先輩[せんぱい]が就職活動[しゅうしょくかつどう]を支援[しえん]してくれたおかげで、内定[ないてい]をもらえた。", "sentence_source": "generated"}, {"text": "国は中小企業を支援するために、新しい制度を作った。", "target_word": "支援", "complexity_tier": "T4", "furigana": "国[くに]は中小企業[ちゅうしょうきぎょう]を支援[しえん]するために、新[あたら]しい制度[せいど]を作[つく]った。", "sentence_source": "generated"}, {"text": "留学生への支援が足りないと、学生たちは訴えた。", "target_word": "支援", "complexity_tier": "T4", "furigana": "留学生[りゅうがくせい]への支援[しえん]が足[た]りないと、学生[がくせい]たちは訴[うった]えた。", "sentence_source": "generated"}, {"text": "彼女は子どもの教育を支援する団体で働いている。", "target_word": "支援", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は子[こ]どもの教育[きょういく]を支援[しえん]する団体[だんたい]で働[はたら]いている。", "sentence_source": "generated"}, {"text": "友人の支援がなければ、この店は開けなかっただろう。", "target_word": "支援", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の支援[しえん]がなければ、この店[みせ]は開[ひら]けなかっただろう。", "sentence_source": "generated"}, {"text": "地震の後、各国から食料や水の支援が届いた。", "target_word": "支援", "complexity_tier": "T3", "furigana": "地震[じしん]の後[あと]、各国[かっこく]から食料[しょくりょう]や水[みず]の支援[しえん]が届[とど]いた。", "sentence_source": "generated"}, {"text": "会社は社員が資格を取ることを支援している。", "target_word": "支援", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は社員[しゃいん]が資格[しかく]を取[と]ることを支援[しえん]している。", "sentence_source": "generated"}, {"text": "ボランティアは、お年寄りの生活を支援する活動を行っている。", "target_word": "支援", "complexity_tier": "T4", "furigana": "ボランティアは、お年寄[としよ]りの生活[せいかつ]を支援[しえん]する活動[かつどう]を行[おこな]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "支援", "label": "基本形"}, {"form": "支援する", "label": "サ変動詞"}], "register": "formal", "sense_fingerprint": "他の人の活動を助けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): ベンチャー (Zipf 3.65), キャピタル (Zipf 3.3), 担っ (Zipf 3.73)']::text[], '13b24d15-9ff0-4e3d-8f40-83d3e5a40e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37441, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "支援", "is_correct": true, "explanation": "「成長を支援する」。他の人の成長を助ける意味で入る。"}, {"text": "散歩", "is_correct": false, "explanation": "「成長を散歩する」は成り立たず、助ける意味にならない。"}, {"text": "購入", "is_correct": false, "explanation": "「成長を購入する」は不自然で、助ける行為を表さない。"}, {"text": "修理", "is_correct": false, "explanation": "「成長を修理する」は意味が通らず、文の内容に合わない。"}], "explanations": {"支援": "「成長を支援する」。他の人の成長を助ける意味で入る。", "散歩": "「成長を散歩する」は成り立たず、助ける意味にならない。", "購入": "「成長を購入する」は不自然で、助ける行為を表さない。", "修理": "「成長を修理する」は意味が通らず、文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "支援"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は社員に給料を支援した。", "explanation": "ここは〈支給〉の意味。給料を渡す行為を表すので、助けるという支援は合わない。"}, {"text": "この保険は事故の損害を支援する。", "explanation": "ここは〈補填〉の意味。損害の穴埋めを指すので、人を助ける支援は合わない。"}, {"text": "請求書の代金を支援した。", "explanation": "ここは〈支払〉の意味。代金を払う行為を指すので、助けるという支援とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37441, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支援", "is_correct": true, "explanation": "「友人の支援がなければ」の名詞。助けるという意味で文が成り立つ。"}, {"text": "睡眠", "is_correct": false, "explanation": "「友人の睡眠がなければ」は店が開けなかった理由にならず、文脈に合わない。"}, {"text": "停電", "is_correct": false, "explanation": "「友人の停電がなければ」は意味が通らない。"}, {"text": "遠足", "is_correct": false, "explanation": "「友人の遠足がなければ」は店の開店と結びつかない。"}], "explanations": {"支援": "「友人の支援がなければ」の名詞。助けるという意味で文が成り立つ。", "睡眠": "「友人の睡眠がなければ」は店が開けなかった理由にならず、文脈に合わない。", "停電": "「友人の停電がなければ」は意味が通らない。", "遠足": "「友人の遠足がなければ」は店の開店と結びつかない。"}, "sentence_index": 6, "correct_answer": "支援"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボランティアは、お年寄りの足首を支援する活動を行っている。", "explanation": "ここは〈支える〉の意味。体を支えることを指すので、人の行動を助ける支援とは合わない。"}, {"text": "ボランティアは、お年寄りの意見を支援する活動を行っている。", "explanation": "ここは〈支持〉の意味。意見に賛成することを指すので、人の行動を助ける支援とは合わない。"}, {"text": "ボランティアは、お年寄りの欠点を支援する活動を行っている。", "explanation": "ここは〈指摘〉の意味。欠点を示す行為を指すので、助ける支援とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37441, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は被災地の人々で支援している。", "corrected_sentence": "市は被災地の人々を支援している。", "error_description": "「支援する」は助ける対象を「を」で示す。「で」は手段・場所を表すので、「人々で支援している」は不自然。正しくは「人々を支援している」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37441, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先輩は後輩の就職活動を支援されてくれた。", "corrected_sentence": "先輩は後輩の就職活動を支援してくれた。", "error_description": "「支援してくれた」は支援する側が主語。「支援されてくれた」は受け身で、先輩が支援を受ける側になり文の意味が逆になる。正しくは「支援してくれた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff3c1155-cac9-45f1-9a6b-c80ee2a650fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37442, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「裏方に徹して」の「に」。徹するが役割を取る形で、ここで正しい。"}, {"text": "を", "is_correct": false, "explanation": "「裏方を徹して」は徹するが目的語をとらず、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、役割を示す場面には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「裏方と徹して」は並列の意味になり、役割を示す文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "「裏方に徹して」の「に」。徹するが役割を取る形で、ここで正しい。", "を": "「裏方を徹して」は徹するが目的語をとらず、不自然になる。", "へ": "方向を表す「へ」は、役割を示す場面には合わない。", "と": "「裏方と徹して」は並列の意味になり、役割を示す文脈に合わない。"}, "error_tags": {"を": "object", "へ": "direction", "と": "companion"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37442, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「勉強に徹して」の「に」。対象を示し、徹するが取る形で正しい。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は対象の意味にならず、ここでは合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、対象を示す文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」は名詞をつなぐ働きで、動詞の前に対象を示すことはできない。"}], "correct_answer": "に", "explanations": {"に": "「勉強に徹して」の「に」。対象を示し、徹するが取る形で正しい。", "から": "起点を表す「から」は対象の意味にならず、ここでは合わない。", "より": "比較の「より」は、対象を示す文脈に合わない。", "の": "連体の「の」は名詞をつなぐ働きで、動詞の前に対象を示すことはできない。"}, "error_tags": {"から": "source", "より": "comparison", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37442, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "一つのことを最後までやり続ける。", "primary_collocate": null, "pronunciation": "てっする", "ipa": "tesːɯɾɯ", "syllable_count": 4, "sentences": [{"text": "チームは夜を徹して、橋の修理を続けた。", "target_word": "徹して", "complexity_tier": "T3", "furigana": "チームは夜[よる]を徹[てっ]して、橋[はし]の修理[しゅうり]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "彼は大会が終わるまで、裏方に徹して選手を支えた。", "target_word": "徹して", "complexity_tier": "T3", "furigana": "彼[かれ]は大会[たいかい]が終[お]わるまで、裏方[うらかた]に徹[てっ]して選手[せんしゅ]を支[ささ]えた。", "sentence_source": "generated"}, {"text": "最後まで節約に徹したおかげで、旅行の費用がたまった。", "target_word": "徹した", "complexity_tier": "T3", "furigana": "最後[さいご]まで節約[せつやく]に徹[てっ]したおかげで、旅行[りょこう]の費用[ひよう]がたまった。", "sentence_source": "generated"}, {"text": "看護師は夜を徹して、患者のそばについていた。", "target_word": "徹して", "complexity_tier": "T3", "furigana": "看護師[かんごし]は夜[よる]を徹[てっ]して、患者[かんじゃ]のそばについていた。", "sentence_source": "generated"}, {"text": "彼女は卒業するまで、ボランティアに徹した。", "target_word": "徹した", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は卒業[そつぎょう]するまで、ボランティアに徹[てっ]した。", "sentence_source": "generated"}, {"text": "彼は五十年間、同じ味を守ることに徹して店を続けた。", "target_word": "徹して", "complexity_tier": "T3", "furigana": "彼[かれ]は五十年[ごじゅうねん]間[かん]、同[おな]じ味[あじ]を守[まも]ることに徹[てっ]して店[みせ]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "会議が終わるまで、司会者は進行役に徹した。", "target_word": "徹した", "complexity_tier": "T3", "furigana": "会議[かいぎ]が終[お]わるまで、司会者[しかいしゃ]は進行役[しんこうやく]に徹[てっ]した。", "sentence_source": "generated"}, {"text": "試験の前は、毎晩勉強に徹して過ごした。", "target_word": "徹して", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]は、毎晩[まいばん]勉強[べんきょう]に徹[てっ]して過[す]ごした。", "sentence_source": "generated"}, {"text": "社長は引退するまで、現場の仕事に徹した。", "target_word": "徹した", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は引退[いんたい]するまで、現場[げんば]の仕事[しごと]に徹[てっ]した。", "sentence_source": "generated"}, {"text": "私は一年間、毎朝の練習に徹して、一日も休まなかった。", "target_word": "徹して", "complexity_tier": "T3", "furigana": "私[わたし]は一年間[いちねんかん]、毎朝[まいあさ]の練習[れんしゅう]に徹[てっ]して、一日[いちにち]も休[やす]まなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "徹する", "label": "辞書形"}, {"form": "徹して", "label": "て形"}, {"form": "徹した", "label": "た形"}, {"form": "徹しない", "label": "ない形"}, {"form": "徹すれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "ある行動や立場を途中でやめず、最後まで続けること（夜を徹してなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe8a64e-398a-44c0-8fce-9cbeb83b8e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37442, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "徹して", "is_correct": true, "explanation": "「夜を徹して」は夜通し休まず続ける意味で、修理を続けたという文に合う。"}, {"text": "諦めて", "is_correct": false, "explanation": "「夜を諦めて」は文として成り立たず、続けたという文脈とも逆になる。"}, {"text": "途切れて", "is_correct": false, "explanation": "「途切れる」は自動詞で「夜を」の後に続かず、続けたという文脈とも逆になる。"}, {"text": "引き返して", "is_correct": false, "explanation": "「引き返す」は途中で戻る意味で、修理を続けた文と矛盾する。"}], "explanations": {"徹して": "「夜を徹して」は夜通し休まず続ける意味で、修理を続けたという文に合う。", "諦めて": "「夜を諦めて」は文として成り立たず、続けたという文脈とも逆になる。", "途切れて": "「途切れる」は自動詞で「夜を」の後に続かず、続けたという文脈とも逆になる。", "引き返して": "「引き返す」は途中で戻る意味で、修理を続けた文と矛盾する。"}, "sentence_index": 0, "correct_answer": "徹して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その冷たさは骨の髄まで徹して、夜になっても体が温まらなかった。", "explanation": "ここは〈徹する〉の「しみ通る」の意味。寒さが体にしみ通る話で、最後まで続ける意味とは合わない。"}, {"text": "彼は三日目で仕事を投げ出し、夜を徹して寝ていた。", "explanation": "ここは〈徹夜〉（夜通し起きて続ける）の意味。寝ていた文には〈徹する〉は合わない。"}, {"text": "彼は周囲に何を言われても、自分の方針を徹して譲らなかった。", "explanation": "ここは〈貫く〉の意味。〈徹する〉は続ける意味で、方針を押し通す場面には〈貫く〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37442, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "徹した", "is_correct": true, "explanation": "「進行役に徹した」は役割に専念した意味で、空欄に合う。"}, {"text": "断った", "is_correct": false, "explanation": "「断る」は申し出を受けない意味で、役割を担った文と矛盾する。"}, {"text": "逃げた", "is_correct": false, "explanation": "「逃げる」は責任から離れる意味で、役割を務めた文とは逆になる。"}, {"text": "冷めた", "is_correct": false, "explanation": "「冷める」は熱や意欲が下がる意味で、進行役を務めた文には合わない。"}], "explanations": {"徹した": "「進行役に徹した」は役割に専念した意味で、空欄に合う。", "断った": "「断る」は申し出を受けない意味で、役割を担った文と矛盾する。", "逃げた": "「逃げる」は責任から離れる意味で、役割を務めた文とは逆になる。", "冷めた": "「冷める」は熱や意欲が下がる意味で、進行役を務めた文には合わない。"}, "sentence_index": 6, "correct_answer": "徹した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は突然、練習を途中で放り出すことに徹して、そのまま帰ってしまった。", "explanation": "ここは〈中断〉の意味。途中で手を止める中断とは逆で、〈徹する〉は最後まで続ける意味なので合わない。"}, {"text": "私は一年間、毎朝の練習をほとんど続けず、一日だけ休むことに徹した。", "explanation": "ここは〈休息〉の意味。〈徹する〉は続け切る意味で、休むことには使わない。"}, {"text": "安全確認を徹して、事故を防いだ。", "explanation": "ここは〈徹底する〉の意味。〈徹する〉は続ける意味で、安全確認を行き届かせる文には〈徹底する〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37442, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は一晩を徹しで、資料を整理した。", "corrected_sentence": "彼女は一晩を徹して、資料を整理した。", "error_description": "「徹して」（て形）が正しい。「徹しで」は接続の形として成り立たない誤った語形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "徹して", "is_correct": true, "explanation": "「裏方に徹して」のて形で、後ろの「支えた」へ続く形。"}, {"text": "徹しよう", "is_correct": false, "explanation": "意志の形で、「裏方に徹しよう選手を支えた」と続かず文が成り立たない。"}, {"text": "徹せよ", "is_correct": false, "explanation": "命令の形で、名詞を修飾したり後ろに続けたりできず文が成り立たない。"}, {"text": "徹しろ", "is_correct": false, "explanation": "命令の形で、「裏方に徹しろ選手を支えた」は文として続かない。"}], "correct_form": "徹して", "base_form": "徹する", "form_label": "て形", "sentence_index": 1, "explanations": {"徹して": "「裏方に徹して」のて形で、後ろの「支えた」へ続く形。", "徹しよう": "意志の形で、「裏方に徹しよう選手を支えた」と続かず文が成り立たない。", "徹せよ": "命令の形で、名詞を修飾したり後ろに続けたりできず文が成り立たない。", "徹しろ": "命令の形で、「裏方に徹しろ選手を支えた」は文として続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37442, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は夜間、運転手で徹して、お酒は飲まなかった。", "corrected_sentence": "彼は夜間、運転手に徹して、お酒は飲まなかった。", "error_description": "〈徹する〉は役割を表す「に」を取る。「で」は手段や場所を表すので、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "徹して", "is_correct": true, "explanation": "「勉強に徹して」のて形。後ろの「過ごした」へ続き、勉強に専念して過ごしたという意味になる。"}, {"text": "徹した", "is_correct": false, "explanation": "た形は完了を表し、「勉強に徹した過ごした」と後ろの動詞へ続かず、文が成り立たない。"}, {"text": "徹しない", "is_correct": false, "explanation": "ない形は否定の形で、「勉強に徹しない過ごした」と後ろの「過ごした」へ続かず、文が成り立たない。"}, {"text": "徹すれば", "is_correct": false, "explanation": "仮定形で、「勉強に徹すれば過ごした」と後ろの「過ごした」へ続かず、文が成り立たない。"}], "correct_form": "徹して", "base_form": "徹する", "form_label": "て形", "sentence_index": 7, "explanations": {"徹して": "「勉強に徹して」のて形。後ろの「過ごした」へ続き、勉強に専念して過ごしたという意味になる。", "徹した": "た形は完了を表し、「勉強に徹した過ごした」と後ろの動詞へ続かず、文が成り立たない。", "徹しない": "ない形は否定の形で、「勉強に徹しない過ごした」と後ろの「過ごした」へ続かず、文が成り立たない。", "徹すれば": "仮定形で、「勉強に徹すれば過ごした」と後ろの「過ごした」へ続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37443, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「聞き役に徹し」の「に」。役割を示し、徹するが取る形で正しい。"}, {"text": "を", "is_correct": false, "explanation": "「聞き役を徹し」は徹するが目的語をとらず、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、役割を示す場面には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「聞き役と徹し」は並列の意味になり、役割を示す文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "「聞き役に徹し」の「に」。役割を示し、徹するが取る形で正しい。", "を": "「聞き役を徹し」は徹するが目的語をとらず、不自然になる。", "へ": "方向を表す「へ」は、役割を示す場面には合わない。", "と": "「聞き役と徹し」は並列の意味になり、役割を示す文脈に合わない。"}, "error_tags": {"を": "object", "へ": "direction", "と": "companion"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37443, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「運転手に徹して」の「に」。役割を示し、徹するが取る形で正しい。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は役割の意味にならず、ここでは合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、役割を示す文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」は名詞をつなぐ働きで、ここでは役割を示せない。"}], "correct_answer": "に", "explanations": {"に": "「運転手に徹して」の「に」。役割を示し、徹するが取る形で正しい。", "から": "起点を表す「から」は役割の意味にならず、ここでは合わない。", "より": "比較の「より」は、役割を示す文脈に合わない。", "の": "連体の「の」は名詞をつなぐ働きで、ここでは役割を示せない。"}, "error_tags": {"から": "source", "より": "comparison", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37443, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "一つのことに集中し、他のことを考えずにそれだけを行うこと。", "primary_collocate": null, "pronunciation": "てっする", "ipa": "tesːɯɾɯ", "syllable_count": 4, "sentences": [{"text": "試合の後半、チームは守りに徹して勝ちを守った。", "target_word": "徹して", "complexity_tier": "T3", "furigana": "試合[しあい]の後半[こうはん]、チームは守[まも]りに徹[てっ]して勝[か]ちを守[まも]った。", "sentence_source": "generated"}, {"text": "彼は会議で聞き役に徹し、ほとんど話さなかった。", "target_word": "徹し", "complexity_tier": "T3", "furigana": "彼[かれ]は会議[かいぎ]で聞[き]き役[やく]に徹[てっ]し、ほとんど話[はな]さなかった。", "sentence_source": "generated"}, {"text": "彼女は仕事に徹するあまり、休みの日も連絡がつかない。", "target_word": "徹する", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は仕事[しごと]に徹[てっ]するあまり、休[やす]みの日[ひ]も連絡[れんらく]がつかない。", "sentence_source": "generated"}, {"text": "私は今日、案内役に徹するので、写真は撮りません。", "target_word": "徹する", "complexity_tier": "T3", "furigana": "私[わたし]は今日[きょう]、案内役[あんないやく]に徹[てっ]するので、写真[しゃしん]は撮[と]りません。", "sentence_source": "generated"}, {"text": "彼は悪役に徹した演技で、観客を驚かせた。", "target_word": "徹した", "complexity_tier": "T3", "furigana": "彼[かれ]は悪役[あくやく]に徹[てっ]した演技[えんぎ]で、観客[かんきゃく]を驚[おどろ]かせた。", "sentence_source": "generated"}, {"text": "プロに徹する人は、感情を表に出さない。", "target_word": "徹する", "complexity_tier": "T3", "furigana": "プロに徹[てっ]する人[ひと]は、感情[かんじょう]を表[おもて]に出[だ]さない。", "sentence_source": "generated"}, {"text": "彼は研究に徹して、友達との約束も忘れてしまった。", "target_word": "徹して", "complexity_tier": "T3", "furigana": "彼[かれ]は研究[けんきゅう]に徹[てっ]して、友達[ともだち]との約束[やくそく]も忘[わす]れてしまった。", "sentence_source": "generated"}, {"text": "今日は運転手に徹して、お酒は飲まないことにした。", "target_word": "徹して", "complexity_tier": "T3", "furigana": "今日[きょう]は運転手[うんてんしゅ]に徹[てっ]して、お酒[さけ]は飲[の]まないことにした。", "sentence_source": "generated"}, {"text": "彼女はコーチとして指導に徹し、自分の成績は気にしなかった。", "target_word": "徹し", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はコーチとして指導[しどう]に徹[てっ]し、自分[じぶん]の成績[せいせき]は気[き]にしなかった。", "sentence_source": "generated"}, {"text": "受験の前は、勉強に徹して、ゲームもやめた。", "target_word": "徹して", "complexity_tier": "T3", "furigana": "受験[じゅけん]の前[まえ]は、勉強[べんきょう]に徹[てっ]して、ゲームもやめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "徹する", "label": "辞書形"}, {"form": "徹して", "label": "て形"}, {"form": "徹した", "label": "た形"}, {"form": "徹しない", "label": "ない形"}, {"form": "徹すれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "ある役割や立場に専念し、ほかのことをせずそれだけに集中すること（聞き役に徹するなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe8a64e-398a-44c0-8fce-9cbeb83b8e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37443, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "徹して", "is_correct": true, "explanation": "「守りに徹して」は守りに専念して、の意味で、勝ちを守った文に合う。"}, {"text": "攻めて", "is_correct": false, "explanation": "「攻める」は攻撃する意味で、守りに対する文脈では空欄に入らない。"}, {"text": "崩して", "is_correct": false, "explanation": "「守りを崩す」は目的語に「を」を取り、「守りに」の空欄には入らない。"}, {"text": "見送って", "is_correct": false, "explanation": "「見送る」は見届けたり先送りにしたりする意味で、「守りに」の後には続かない。"}], "explanations": {"徹して": "「守りに徹して」は守りに専念して、の意味で、勝ちを守った文に合う。", "攻めて": "「攻める」は攻撃する意味で、守りに対する文脈では空欄に入らない。", "崩して": "「守りを崩す」は目的語に「を」を取り、「守りに」の空欄には入らない。", "見送って": "「見送る」は見届けたり先送りにしたりする意味で、「守りに」の後には続かない。"}, "sentence_index": 0, "correct_answer": "徹して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "真冬の風が骨まで徹して、ストーブの前から動けなかった。", "explanation": "ここは〈徹する〉の「しみ通る」の意味。寒風が骨にしみる話で、一つのことに集中する意味とは合わない。"}, {"text": "彼女はすべての仕事に徹して、一つのことにはまったく力を入れなかった。", "explanation": "ここは〈分散〉の意味。〈徹する〉は一つに集中する意味なので、すべての仕事に広く手を出す文とは合わない。"}, {"text": "駅の点検を徹して、一日で全部終わらせた。", "explanation": "ここは〈徹底する〉の意味。〈徹する〉は一つに集中する意味で、点検を隅々まで行き届かせる文には〈徹底する〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37443, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "徹して", "is_correct": true, "explanation": "「研究に徹して」は研究に専念して、の意味で、約束を忘れた文に合う。"}, {"text": "断って", "is_correct": false, "explanation": "「断る」は申し出を受けない意味で、研究に専念する文脈とは合わない。"}, {"text": "冷めて", "is_correct": false, "explanation": "「冷める」は意欲が下がる意味で、研究に打ち込む文とは逆になる。"}, {"text": "怠って", "is_correct": false, "explanation": "「怠る」は務めを果たさない意味で、「研究に」の後には続かない。"}], "explanations": {"徹して": "「研究に徹して」は研究に専念して、の意味で、約束を忘れた文に合う。", "断って": "「断る」は申し出を受けない意味で、研究に専念する文脈とは合わない。", "冷めて": "「冷める」は意欲が下がる意味で、研究に打ち込む文とは逆になる。", "怠って": "「怠る」は務めを果たさない意味で、「研究に」の後には続かない。"}, "sentence_index": 6, "correct_answer": "徹して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は仕事を途中で断念することに徹して、結局何も残らなかった。", "explanation": "ここは〈断念〉ではなく〈集中〉の場面。〈徹する〉は一つのことに集中して続ける意味で、途中で断念する文とは合わない。"}, {"text": "冷え込みが骨の髄まで徹して、勉強どころではなかった。", "explanation": "ここは〈徹する〉の「しみ通る」の意味。寒さが骨にしみる話で、一つのことに集中する意味とは合わない。"}, {"text": "受験生の私は、家事にも勉強にも徹して、どちらも中途半端に終わった。", "explanation": "ここは〈両立〉の意味。〈徹する〉は一つに絞る意味なので、二つに同時に力を注ぐ文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37443, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は日曜日、台所の掃除が徹して、料理はしなかった。", "corrected_sentence": "彼は日曜日、台所の掃除に徹して、料理はしなかった。", "error_description": "〈徹する〉は対象を「に」で示す。「が」は主語を示すので、ここでは「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "徹し", "is_correct": true, "explanation": "「聞き役に徹し」の連用形で、後ろの「話さなかった」へ続く形。"}, {"text": "徹する", "is_correct": false, "explanation": "辞書形は文を続けて接続する形としては使えない。"}, {"text": "徹しない", "is_correct": false, "explanation": "ない形は否定の意味になり、ほとんど話さなかったという文と意味が逆になる。"}, {"text": "徹しよう", "is_correct": false, "explanation": "意志の形で、後ろの過去の文と続かず文が成り立たない。"}], "correct_form": "徹し", "base_form": "徹する", "form_label": "連用形", "sentence_index": 1, "explanations": {"徹し": "「聞き役に徹し」の連用形で、後ろの「話さなかった」へ続く形。", "徹する": "辞書形は文を続けて接続する形としては使えない。", "徹しない": "ない形は否定の意味になり、ほとんど話さなかったという文と意味が逆になる。", "徹しよう": "意志の形で、後ろの過去の文と続かず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37443, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は今夜、受験の勉強に徹しで、ゲームはしなかった。", "corrected_sentence": "彼女は今夜、受験の勉強に徹して、ゲームはしなかった。", "error_description": "「徹して」（て形）が正しい。「徹しで」は接続の形として成り立たない誤った語形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "徹して", "is_correct": true, "explanation": "「運転手に徹して」のて形。後ろの「飲まないことにした」へ続く形。"}, {"text": "徹した", "is_correct": false, "explanation": "た形は完了を表し、後ろの接続が合わない。"}, {"text": "徹しよう", "is_correct": false, "explanation": "意志の形で、「運転手に徹しよう、お酒は飲まないことにした」とは続かない。"}, {"text": "徹せよ", "is_correct": false, "explanation": "命令の形で、文の途中では続けられず文が成り立たない。"}], "correct_form": "徹して", "base_form": "徹する", "form_label": "て形", "sentence_index": 7, "explanations": {"徹して": "「運転手に徹して」のて形。後ろの「飲まないことにした」へ続く形。", "徹した": "た形は完了を表し、後ろの接続が合わない。", "徹しよう": "意志の形で、「運転手に徹しよう、お酒は飲まないことにした」とは続かない。", "徹せよ": "命令の形で、文の途中では続けられず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37444, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「戦闘」が「した」の対象になるので、「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「戦闘が」が主語になると「した」の対象にならず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は戦闘の対象を示さないので、「した」と結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、戦闘の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「戦闘」が「した」の対象になるので、「を」が正しい。", "が": "「戦闘が」が主語になると「した」の対象にならず、文が成り立たない。", "に": "「に」は戦闘の対象を示さないので、「した」と結びつかない。", "へ": "「へ」は方向を示すので、戦闘の対象にはならない。"}, "error_tags": {"が": "主語", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
