INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37444, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "武力を用いて戦うこと。", "primary_collocate": null, "pronunciation": "せんとう", "ipa": "sentoː", "syllable_count": 4, "sentences": [{"text": "昨日の夜、町の近くで激しい戦闘が起こった。", "target_word": "戦闘", "complexity_tier": "T3", "furigana": "昨日[きのう]の夜[よる]、町[まち]の近[ちか]くで激[はげ]しい戦闘[せんとう]が起[お]こった。", "sentence_source": "generated"}, {"text": "ゲームの中で、主人公は何度も戦闘をした。", "target_word": "戦闘", "complexity_tier": "T3", "furigana": "ゲームの中[なか]で、主人公[しゅじんこう]は何度[なんど]も戦闘[せんとう]をした。", "sentence_source": "generated"}, {"text": "戦闘が終わると、兵士たちは静かに休んだ。", "target_word": "戦闘", "complexity_tier": "T3", "furigana": "戦闘[せんとう]が終[お]わると、兵士[へいし]たちは静[しず]かに休[やす]んだ。", "sentence_source": "generated"}, {"text": "この映画は、長い戦闘の場面が見どころだ。", "target_word": "戦闘", "complexity_tier": "T3", "furigana": "この映画[えいが]は、長[なが]い戦闘[せんとう]の場面[ばめん]が見[み]どころだ。", "sentence_source": "generated"}, {"text": "山の中の戦闘で、多くの人がけがをした。", "target_word": "戦闘", "complexity_tier": "T3", "furigana": "山[やま]の中[なか]の戦闘[せんとう]で、多[おお]くの人[ひと]がけがをした。", "sentence_source": "generated"}, {"text": "両国の軍は、三日間も戦闘を続けた。", "target_word": "戦闘", "complexity_tier": "T3", "furigana": "両国[りょうこく]の軍[ぐん]は、三日間[みっかかん]も戦闘[せんとう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "戦闘に入る前に、隊長が作戦を説明した。", "target_word": "戦闘", "complexity_tier": "T3", "furigana": "戦闘[せんとう]に入[はい]る前[まえ]に、隊長[たいちょう]が作戦[さくせん]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "戦闘は朝まで続いたが、夜明けに静かになった。", "target_word": "戦闘", "complexity_tier": "T3", "furigana": "戦闘[せんとう]は朝[あさ]まで続[つづ]いたが、夜明[よあ]けに静[しず]かになった。", "sentence_source": "generated"}, {"text": "祖父は戦争中、遠い島で戦闘を経験したそうだ。", "target_word": "戦闘", "complexity_tier": "T4", "furigana": "祖父[そふ]は戦争中[せんそうちゅう]、遠[とお]い島[しま]で戦闘[せんとう]を経験[けいけん]したそうだ。", "sentence_source": "generated"}, {"text": "戦闘が始まったという知らせに、町の人は驚いた。", "target_word": "戦闘", "complexity_tier": "T3", "furigana": "戦闘[せんとう]が始[はじ]まったという知[し]らせに、町[まち]の人[ひと]は驚[おどろ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戦闘", "label": "dictionary"}, {"form": "戦闘が", "label": "subject"}, {"form": "戦闘を", "label": "object"}, {"form": "戦闘中", "label": "compound"}], "register": "neutral", "sense_fingerprint": "たたかうこと（戦い）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7bfaf5f-7601-4049-bf95-765962747195') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37444, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戦闘", "is_correct": true, "explanation": "町の近くで激しい戦いが起きたという文脈に合う。"}, {"text": "休憩", "is_correct": false, "explanation": "休憩は休むこと。激しく起きた出来事の文脈に合わない。"}, {"text": "配達", "is_correct": false, "explanation": "配達は品物を届けること。激しく起きた出来事の文脈に合わない。"}, {"text": "試食", "is_correct": false, "explanation": "試食は味を確かめること。激しく起きた出来事の文脈に合わない。"}], "explanations": {"戦闘": "町の近くで激しい戦いが起きたという文脈に合う。", "休憩": "休憩は休むこと。激しく起きた出来事の文脈に合わない。", "配達": "配達は品物を届けること。激しく起きた出来事の文脈に合わない。", "試食": "試食は味を確かめること。激しく起きた出来事の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "戦闘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄弟は遺産をめぐって、三年も戦闘を続けた。", "explanation": "家族間の争いは〈争い〉。戦闘は武力で戦うことを指すので、家庭内の争いには使わない。"}, {"text": "国会では、政党同士が激しく戦闘を続けた。", "explanation": "議論での戦いは〈論戦〉。戦闘は武力の戦いに使うので、政治の論争には合わない。"}, {"text": "決勝戦では、両チームが激しく戦闘をした。", "explanation": "試合の勝負は〈試合〉。戦闘は武力の戦いを指し、スポーツには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37444, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戦闘", "is_correct": true, "explanation": "作戦を説明してから戦いに入るという文脈に合う。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除は部屋などをきれいにすること。作戦説明の流れと合わない。"}, {"text": "買い物", "is_correct": false, "explanation": "買い物は品物を買うこと。戦いに入る前の作戦説明とは合わない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は食べ物を作ること。戦いに入る前の作戦説明とは合わない。"}], "explanations": {"戦闘": "作戦を説明してから戦いに入るという文脈に合う。", "掃除": "掃除は部屋などをきれいにすること。作戦説明の流れと合わない。", "買い物": "買い物は品物を買うこと。戦いに入る前の作戦説明とは合わない。", "料理": "料理は食べ物を作ること。戦いに入る前の作戦説明とは合わない。"}, "sentence_index": 6, "correct_answer": "戦闘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夫婦げんかで、二人は夜まで戦闘を続けた。", "explanation": "口げんかは〈口論〉。戦闘は武力の戦いを指すので、夫婦げんかには使わない。"}, {"text": "会社と組合は、賃金をめぐって戦闘を続けた。", "explanation": "労使の争いは〈争議〉。戦闘は武力の戦いを指すので、労使交渉には合わない。"}, {"text": "締め切りに追われ、彼は夜まで作業と戦闘した。", "explanation": "仕事を進めるのは〈作業〉。戦闘は武力の戦いで、仕事には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
