INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37445, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「戦闘」が「避ける」の対象になるので、「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「戦闘が」が主語になると、「避ける」の対象にならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は避ける対象を示さないので、この文脈に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、避ける対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「戦闘」が「避ける」の対象になるので、「を」が正しい。", "が": "「戦闘が」が主語になると、「避ける」の対象にならない。", "に": "「に」は避ける対象を示さないので、この文脈に合わない。", "へ": "「へ」は方向を示すので、避ける対象にはならない。"}, "error_tags": {"が": "主語", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
