INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37445, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "敵や相手と戦うこと。また、その行動。", "primary_collocate": null, "pronunciation": "せんとう", "ipa": "sentoː", "syllable_count": 4, "sentences": [{"text": "敵との戦闘に備えて、兵士たちは武器を点検した。", "target_word": "戦闘", "complexity_tier": "T4", "furigana": "敵[てき]との戦闘[せんとう]に備[そな]えて、兵士[へいし]たちは武器[ぶき]を点検[てんけん]した。", "sentence_source": "generated"}, {"text": "戦闘を避けるため、使者は話し合いを求めた。", "target_word": "戦闘", "complexity_tier": "T4", "furigana": "戦闘[せんとう]を避[さ]けるため、使者[ししゃ]は話[はな]し合[あ]いを求[もと]めた。", "sentence_source": "generated"}, {"text": "このゲームでは、敵との戦闘に勝つと経験値がもらえる。", "target_word": "戦闘", "complexity_tier": "T3", "furigana": "このゲームでは、敵[てき]との戦闘[せんとう]に勝[か]つと経験値[けいけんち]がもらえる。", "sentence_source": "generated"}, {"text": "戦闘で傷ついた兵士を、医者が手当てした。", "target_word": "戦闘", "complexity_tier": "T4", "furigana": "戦闘[せんとう]で傷[きず]ついた兵士[へいし]を、医者[いしゃ]が手当[てあ]てした。", "sentence_source": "generated"}, {"text": "彼は戦闘の経験が少ないので、緊張していた。", "target_word": "戦闘", "complexity_tier": "T4", "furigana": "彼[かれ]は戦闘[せんとう]の経験[けいけん]が少[すく]ないので、緊張[きんちょう]していた。", "sentence_source": "generated"}, {"text": "戦闘が長引いて、食べ物も水も足りなくなった。", "target_word": "戦闘", "complexity_tier": "T4", "furigana": "戦闘[せんとう]が長引[ながび]いて、食[た]べ物[もの]も水[みず]も足[た]りなくなった。", "sentence_source": "generated"}, {"text": "リーダーの合図で、全員がいっせいに戦闘を始めた。", "target_word": "戦闘", "complexity_tier": "T3", "furigana": "リーダーの合図[あいず]で、全員[ぜんいん]がいっせいに戦闘[せんとう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "戦闘の音が聞こえて、村の人たちは家に隠れた。", "target_word": "戦闘", "complexity_tier": "T3", "furigana": "戦闘[せんとう]の音[おと]が聞[き]こえて、村[むら]の人[ひと]たちは家[いえ]に隠[かく]れた。", "sentence_source": "generated"}, {"text": "両軍の戦闘は、雪の降る日にも休まず続いた。", "target_word": "戦闘", "complexity_tier": "T4", "furigana": "両軍[りょうぐん]の戦闘[せんとう]は、雪[ゆき]の降[ふ]る日[ひ]にも休[やす]まず続[つづ]いた。", "sentence_source": "generated"}, {"text": "戦闘に勝っても、多くのものを失ってしまった。", "target_word": "戦闘", "complexity_tier": "T4", "furigana": "戦闘[せんとう]に勝[か]っても、多[おお]くのものを失[うしな]ってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戦闘", "label": "dictionary"}, {"form": "戦闘が", "label": "subject"}, {"form": "戦闘を", "label": "object"}, {"form": "戦闘で", "label": "de-marked"}], "register": "neutral", "sense_fingerprint": "敵や相手と戦う行動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7bfaf5f-7601-4049-bf95-765962747195') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37445, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戦闘", "is_correct": true, "explanation": "敵との戦いに備えて武器を点検するという文脈に合う。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏は楽器などで音楽を奏でること。敵に備える文脈に合わない。"}, {"text": "試験", "is_correct": false, "explanation": "試験は能力を確かめること。敵との戦いに備える文脈に合わない。"}, {"text": "取材", "is_correct": false, "explanation": "取材は情報を集めること。敵との戦いに備える文脈に合わない。"}], "explanations": {"戦闘": "敵との戦いに備えて武器を点検するという文脈に合う。", "演奏": "演奏は楽器などで音楽を奏でること。敵に備える文脈に合わない。", "試験": "試験は能力を確かめること。敵との戦いに備える文脈に合わない。", "取材": "取材は情報を集めること。敵との戦いに備える文脈に合わない。"}, "sentence_index": 0, "correct_answer": "戦闘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月の会議に向けて、報告書を戦闘した。", "explanation": "文書を作るのは〈作成〉。戦闘は敵や相手と戦う行動を指すので、報告書には使わない。"}, {"text": "夫婦の口論で、二人は戦闘を始めた。", "explanation": "口げんかは〈口論〉。戦闘は敵との武力の戦いを指すので、家庭内の言い争いには使わない。"}, {"text": "締め切りとの戦闘に、夜中まで取り組んだ。", "explanation": "仕事を進めるのは〈作業〉。戦闘は敵と戦う行動を指すので、仕事には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37445, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戦闘", "is_correct": true, "explanation": "合図で全員がいっせいに敵と戦う行動を始めたという文脈に合う。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空が赤く染まる自然現象で、人が始める行動ではない。"}, {"text": "地震", "is_correct": false, "explanation": "地震は地面が揺れる現象で、人が合図で始めるものではない。"}, {"text": "開花", "is_correct": false, "explanation": "開花は花が咲くこと。人が合図で一斉に始める行動ではない。"}], "explanations": {"戦闘": "合図で全員がいっせいに敵と戦う行動を始めたという文脈に合う。", "夕焼け": "夕焼けは空が赤く染まる自然現象で、人が始める行動ではない。", "地震": "地震は地面が揺れる現象で、人が合図で始めるものではない。", "開花": "開花は花が咲くこと。人が合図で一斉に始める行動ではない。"}, "sentence_index": 6, "correct_answer": "戦闘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい曲を戦闘して、コンサートで披露した。", "explanation": "曲を作るのは〈作曲〉。戦闘は敵や相手と戦う行動を指すので、音楽には使わない。"}, {"text": "夏休みの作文を戦闘した。", "explanation": "文章を書くのは〈作文〉。戦闘は敵や相手と戦う行動を指すので、文章には使わない。"}, {"text": "料理の戦闘に勝って、おいしい食事を作った。", "explanation": "料理は〈調理〉する。戦闘は敵と武力で戦うことを指すので、料理には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37445, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兵士は戦闘が避けようと、夜に移動した。", "corrected_sentence": "兵士は戦闘を避けようと、夜に移動した。", "error_description": "誤りは「が」。「避ける」は他動詞で、対象は「を」で示す。「戦闘が避ける」は文として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37445, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "敵が夜明けに戦闘が仕掛けてきた。", "corrected_sentence": "敵が夜明けに戦闘を仕掛けてきた。", "error_description": "誤りは「が」。「仕掛ける」は他動詞で、対象は「を」で示す。「戦闘が仕掛ける」は文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37446, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「勉強に特化した」の「に」。特化の対象を示し、特化が取る形で正しい。"}, {"text": "を", "is_correct": false, "explanation": "「勉強を特化した」は特化が目的語をとらず、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、特化の対象を示す文脈には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「勉強と特化した」は並列の意味になり、対象を示す文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "「勉強に特化した」の「に」。特化の対象を示し、特化が取る形で正しい。", "を": "「勉強を特化した」は特化が目的語をとらず、不自然になる。", "へ": "方向を表す「へ」は、特化の対象を示す文脈には合わない。", "と": "「勉強と特化した」は並列の意味になり、対象を示す文脈に合わない。"}, "error_tags": {"を": "object", "へ": "direction", "と": "companion"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37446, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「見た目に特化して」の「に」。特化の対象を示し、特化が取る形で正しい。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は特化の対象を示せず、ここでは合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、特化の対象を示す文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」は名詞をつなぐ働きで、特化の対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "「見た目に特化して」の「に」。特化の対象を示し、特化が取る形で正しい。", "から": "起点を表す「から」は特化の対象を示せず、ここでは合わない。", "より": "比較の「より」は、特化の対象を示す文脈に合わない。", "の": "連体の「の」は名詞をつなぐ働きで、特化の対象を示せない。"}, "error_tags": {"から": "source", "より": "comparison", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37446, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あることに特に力を入れて、ほかのことはあまり考えないこと。", "primary_collocate": null, "pronunciation": "とっか", "ipa": "tokːa", "syllable_count": 3, "sentences": [{"text": "この店は味に特化して、サービスはあまり気にしていない。", "target_word": "特化して", "complexity_tier": "T3", "furigana": "この店[みせ]は味[あじ]に特化[とっか]して、サービスはあまり気[き]にしていない。", "sentence_source": "generated"}, {"text": "兄は英語の勉強に特化した結果、数学の成績が下がった。", "target_word": "特化した", "complexity_tier": "T3", "furigana": "兄[あに]は英語[えいご]の勉強[べんきょう]に特化[とっか]した結果[けっか]、数学[すうがく]の成績[せいせき]が下[さ]がった。", "sentence_source": "generated"}, {"text": "今年は守りに特化して、攻めはほとんど考えないことにした。", "target_word": "特化して", "complexity_tier": "T3", "furigana": "今年[ことし]は守[まも]りに特化[とっか]して、攻[せ]めはほとんど考[かんが]えないことにした。", "sentence_source": "generated"}, {"text": "彼女は料理の腕を磨くことに特化して、掃除はいつも後回しだ。", "target_word": "特化して", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は料理[りょうり]の腕[うで]を磨[みが]くことに特化[とっか]して、掃除[そうじ]はいつも後回[あとまわ]しだ。", "sentence_source": "generated"}, {"text": "私は短い期間だけ、試験対策に特化して勉強した。", "target_word": "特化して", "complexity_tier": "T3", "furigana": "私[わたし]は短[みじか]い期間[きかん]だけ、試験対策[しけんたいさく]に特化[とっか]して勉強[べんきょう]した。", "sentence_source": "generated"}, {"text": "会社は新製品の開発に特化した分、宣伝にお金を使わなかった。", "target_word": "特化した", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新製品[しんせいひん]の開発[かいはつ]に特化[とっか]した分[ぶん]、宣伝[せんでん]にお金[かね]を使[つか]わなかった。", "sentence_source": "generated"}, {"text": "このクラブは大会で勝つことに特化していて、楽しむ余裕はない。", "target_word": "特化していて", "complexity_tier": "T3", "furigana": "このクラブは大会[たいかい]で勝[か]つことに特化[とっか]していて、楽[たの]しむ余裕[よゆう]はない。", "sentence_source": "generated"}, {"text": "彼は見た目に特化して服を選ぶので、着心地は二の次だ。", "target_word": "特化して", "complexity_tier": "T3", "furigana": "彼[かれ]は見[み]た目[め]に特化[とっか]して服[ふく]を選[えら]ぶので、着心地[きごこち]は二[に]の次[つぎ]だ。", "sentence_source": "generated"}, {"text": "今月は節約に特化して、遊びの予定は全部やめた。", "target_word": "特化して", "complexity_tier": "T3", "furigana": "今月[こんげつ]は節約[せつやく]に特化[とっか]して、遊[あそ]びの予定[よてい]は全部[ぜんぶ]やめた。", "sentence_source": "generated"}, {"text": "この授業は点数を上げることに特化して、理解は求めない。", "target_word": "特化して", "complexity_tier": "T3", "furigana": "この授業[じゅぎょう]は点数[てんすう]を上[あ]げることに特化[とっか]して、理解[りかい]は求[もと]めない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "特化", "label": "名詞形"}, {"form": "特化する", "label": "辞書形"}, {"form": "特化して", "label": "て形"}, {"form": "特化した", "label": "た形"}, {"form": "特化しない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "一つの点に力を集中し、ほかの点を後回しにすること（する動詞として使う）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe8a64e-398a-44c0-8fce-9cbeb83b8e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37446, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特化して", "is_correct": true, "explanation": "「味に特化して」は味だけに力を絞る意味で、サービスを気にしない文に合う。"}, {"text": "値引いて", "is_correct": false, "explanation": "「値引く」は「味を」の形で使い、「味に」の空欄には入らない。"}, {"text": "失って", "is_correct": false, "explanation": "「味を失う」は味がなくなる意味で、力を絞る文脈には合わない。"}, {"text": "偽って", "is_correct": false, "explanation": "「味を偽る」は味を偽る意味で、ここでは文が成り立たない。"}], "explanations": {"特化して": "「味に特化して」は味だけに力を絞る意味で、サービスを気にしない文に合う。", "値引いて": "「値引く」は「味を」の形で使い、「味に」の空欄には入らない。", "失って": "「味を失う」は味がなくなる意味で、力を絞る文脈には合わない。", "偽って": "「味を偽る」は味を偽る意味で、ここでは文が成り立たない。"}, "sentence_index": 0, "correct_answer": "特化して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はあらゆる分野に特化して、どれも深く学んだ。", "explanation": "ここは〈万能〉の意味。〈特化〉は一つの分野に絞る意味なので、あらゆる分野を深く学ぶ文とは合わない。"}, {"text": "兄は英語も数学も理科も、すべて特化して勉強した。", "explanation": "ここは〈分散〉の意味。〈特化〉は一つに絞る意味なので、複数の科目を同時に深く学んだ文とは合わない。"}, {"text": "この店は味にも値段にも特化して、ほかの点は後回しにしていない。", "explanation": "ここは〈万能〉の意味。〈特化〉は一つの点に絞る意味なので、味と値段の両方に絞った文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37446, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特化していて", "is_correct": true, "explanation": "「勝つことに特化していて」は勝つことに力を絞っている意味で、楽しむ余裕がない文に合う。"}, {"text": "隠れて", "is_correct": false, "explanation": "「勝つことに隠れて」は成り立たず、勝つことに力を注ぐ文脈とも合わない。"}, {"text": "拒んで", "is_correct": false, "explanation": "「勝つことを拒んで」は勝つことを避ける意味で、勝つことに力を入れている文と逆になる。"}, {"text": "眠って", "is_correct": false, "explanation": "「勝つことに眠って」は意味が通らず、空欄には入らない。"}], "explanations": {"特化していて": "「勝つことに特化していて」は勝つことに力を絞っている意味で、楽しむ余裕がない文に合う。", "隠れて": "「勝つことに隠れて」は成り立たず、勝つことに力を注ぐ文脈とも合わない。", "拒んで": "「勝つことを拒んで」は勝つことを避ける意味で、勝つことに力を入れている文と逆になる。", "眠って": "「勝つことに眠って」は意味が通らず、空欄には入らない。"}, "sentence_index": 6, "correct_answer": "特化していて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は家族全員のために、すべての仕事に特化して取り組んだ。", "explanation": "ここは〈全般〉の意味。〈特化〉は一つの分野に絞る意味で、すべての仕事を対象にする文とは合わない。"}, {"text": "この授業は宿題を全部特化して出すので、生徒は迷わない。", "explanation": "ここは〈一括〉の意味。〈特化〉は一つの目的に絞る意味で、宿題を全部まとめて出す文とは合わない。"}, {"text": "この授業は点数も理解も同時に特化して、どちらも中途半端だ。", "explanation": "ここは〈両立〉の意味。〈特化〉は一つの点に絞る意味で、二つを同時に対象にする文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37446, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は手作りの菓子を特化して、店を続けた。", "corrected_sentence": "祖父は手作りの菓子に特化して、店を続けた。", "error_description": "〈特化〉は対象を「に」で示す。「を」は目的語を示すので、ここでは「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37446, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は色使いに特化て、絵の教室を開いた。", "corrected_sentence": "妹は色使いに特化して、絵の教室を開いた。", "error_description": "「特化して」のて形の「して」が必要。「特化て」は誤った語形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
