INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37447, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "特定の分野や用途に集中していること。", "primary_collocate": null, "pronunciation": "とっか", "ipa": "tokːa", "syllable_count": 3, "sentences": [{"text": "この会社は、子ども向けの教材に特化している。", "target_word": "特化している", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、子[こ]ども向[む]けの教材[きょうざい]に特化[とっか]している。", "sentence_source": "generated"}, {"text": "医療に特化したアプリが、病院で使われ始めた。", "target_word": "特化した", "complexity_tier": "T3", "furigana": "医療[いりょう]に特化[とっか]したアプリが、病院[びょういん]で使[つか]われ始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼女は古い着物の修理に特化した店を開いた。", "target_word": "特化した", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は古[ふる]い着物[きもの]の修理[しゅうり]に特化[とっか]した店[みせ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "このカメラは、水中の撮影に特化して作られている。", "target_word": "特化して", "complexity_tier": "T3", "furigana": "このカメラは、水中[すいちゅう]の撮影[さつえい]に特化[とっか]して作[つく]られている。", "sentence_source": "generated"}, {"text": "私たちの学校は、音楽教育に特化しています。", "target_word": "特化しています", "complexity_tier": "T3", "furigana": "私[わたし]たちの学校[がっこう]は、音楽教育[おんがくきょういく]に特化[とっか]しています。", "sentence_source": "generated"}, {"text": "翻訳の仕事の中でも、彼は法律の文書に特化している。", "target_word": "特化している", "complexity_tier": "T3", "furigana": "翻訳[ほんやく]の仕事[しごと]の中[なか]でも、彼[かれ]は法律[ほうりつ]の文書[ぶんしょ]に特化[とっか]している。", "sentence_source": "generated"}, {"text": "山道を走ることに特化した靴は、街では歩きにくい。", "target_word": "特化した", "complexity_tier": "T3", "furigana": "山道[やまみち]を走[はし]ることに特化[とっか]した靴[くつ]は、街[まち]では歩[ある]きにくい。", "sentence_source": "generated"}, {"text": "この辞書は、料理の用語に特化している。", "target_word": "特化している", "complexity_tier": "T3", "furigana": "この辞書[じしょ]は、料理[りょうり]の用語[ようご]に特化[とっか]している。", "sentence_source": "generated"}, {"text": "農業に特化した大学が、町に新しくできた。", "target_word": "特化した", "complexity_tier": "T3", "furigana": "農業[のうぎょう]に特化[とっか]した大学[だいがく]が、町[まち]に新[あたら]しくできた。", "sentence_source": "generated"}, {"text": "その工場は、小さな部品の製造に特化している。", "target_word": "特化している", "complexity_tier": "T3", "furigana": "その工場[こうじょう]は、小[ちい]さな部品[ぶひん]の製造[せいぞう]に特化[とっか]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "特化", "label": "名詞形"}, {"form": "特化する", "label": "辞書形"}, {"form": "特化して", "label": "て形"}, {"form": "特化した", "label": "た形"}, {"form": "特化している", "label": "状態形"}], "register": "neutral", "sense_fingerprint": "製品・店・組織などが、特定の分野や用途に絞って作られている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe8a64e-398a-44c0-8fce-9cbeb83b8e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37447, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特化している", "is_correct": true, "explanation": "「子ども向けの教材に特化している」は特定の用途に絞っている意味で、文に合う。"}, {"text": "反している", "is_correct": false, "explanation": "「教材に反している」は逆らう意味で、教材を対象にする文脈には合わない。"}, {"text": "眠っている", "is_correct": false, "explanation": "「教材に眠っている」は意味が通らず、空欄に入らない。"}, {"text": "欠けている", "is_correct": false, "explanation": "「教材に欠けている」は教材が足りない意味になり、用途に絞る文とは合わない。"}], "explanations": {"特化している": "「子ども向けの教材に特化している」は特定の用途に絞っている意味で、文に合う。", "反している": "「教材に反している」は逆らう意味で、教材を対象にする文脈には合わない。", "眠っている": "「教材に眠っている」は意味が通らず、空欄に入らない。", "欠けている": "「教材に欠けている」は教材が足りない意味になり、用途に絞る文とは合わない。"}, "sentence_index": 0, "correct_answer": "特化している"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このカメラは、ほかの撮影を全部こなすように特化して作られている。", "explanation": "ここは〈万能〉の意味。〈特化〉は特定の用途に絞る意味なので、ほかの撮影を全部こなす文とは合わない。"}, {"text": "このアプリは、文字の入力も写真の加工も同じ力で特化して作られている。", "explanation": "ここは〈両立〉の意味。〈特化〉は一つの対象に絞る意味で、二つに同じ力を注ぐ文とは合わない。"}, {"text": "この辞書は、旅行の会話に特化していて、料理の用語も全部載っている。", "explanation": "ここは〈網羅〉の意味。〈特化〉は一つの分野に絞る意味なので、旅行も料理も全部載せる文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37447, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特化した", "is_correct": true, "explanation": "「山道を走ることに特化した靴」は山道の用途に絞った靴の意味で、空欄に合う。"}, {"text": "隠れた", "is_correct": false, "explanation": "「走ることに隠れた靴」は意味が通らず、空欄には入らない。"}, {"text": "拒んだ", "is_correct": false, "explanation": "「走ることを拒んだ靴」は意味が逆になり、用途を表す文脈に合わない。"}, {"text": "失った", "is_correct": false, "explanation": "「走ることに失った靴」は意味が通らず、空欄には入らない。"}], "explanations": {"特化した": "「山道を走ることに特化した靴」は山道の用途に絞った靴の意味で、空欄に合う。", "隠れた": "「走ることに隠れた靴」は意味が通らず、空欄には入らない。", "拒んだ": "「走ることを拒んだ靴」は意味が逆になり、用途を表す文脈に合わない。", "失った": "「走ることに失った靴」は意味が通らず、空欄には入らない。"}, "sentence_index": 6, "correct_answer": "特化した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その工場は、特化した製品を次々と作り、種類をどんどん広げている。", "explanation": "ここは〈多角化〉の意味。〈特化〉は一つに絞る意味なので、種類を次々広げる文とは合わない。"}, {"text": "その家族は、料理の全般に特化していて、一つの料理に絞ったことは一度もない。", "explanation": "ここは〈万能〉の意味。〈特化〉は一つに絞る意味で、全般を扱う文とは合わない。"}, {"text": "その工場は、部品にも機械にも特化していて、どちらも同じ力で作っている。", "explanation": "ここは〈両立〉の意味。〈特化〉は一つの対象に絞る意味で、二つに同じ力を注ぐ文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37447, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このお店は、古い着物の修理に特化しいる。", "corrected_sentence": "このお店は、古い着物の修理に特化している。", "error_description": "「特化している」の「て」が必要。「特化しいる」は誤った形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37447, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は、焼き菓子の製造で特化している。", "corrected_sentence": "この店は、焼き菓子の製造に特化している。", "error_description": "〈特化〉は対象を「に」で示す。「で」は手段や場所を示すので、ここでは「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37448, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「次の世代を担う」で、世代が「担う」の目的語になるため「を」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「次の世代に担う」では「担う」の目的語を示せず、文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「次の世代で担う」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「担う」は方向に向かう動詞ではないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「次の世代を担う」で、世代が「担う」の目的語になるため「を」が正しい。", "に": "「次の世代に担う」では「担う」の目的語を示せず、文として成り立たない。", "で": "手段や場所を示すが、「次の世代で担う」では意味が通らない。", "へ": "方向を示すが、「担う」は方向に向かう動詞ではないので合わない。"}, "error_tags": {"に": "位置・相手", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37448, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「役目を担って」で、役目が「担って」の目的語になるため「を」が正しい。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を表すが、「役目と担って」は目的語を示せず成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、「役目から担って」は目的語を示せず合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、「役目より担って」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「役目を担って」で、役目が「担って」の目的語になるため「を」が正しい。", "と": "並列や共同を表すが、「役目と担って」は目的語を示せず成り立たない。", "から": "起点を表すが、「役目から担って」は目的語を示せず合わない。", "より": "比較を表すが、「役目より担って」は文として成り立たない。"}, "error_tags": {"と": "並列・共同", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37448, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "自分でやると決めたことを、しっかりと引き受けること。", "primary_collocate": null, "pronunciation": "になう", "ipa": "ninaɯ", "syllable_count": 3, "sentences": [{"text": "彼女は新しい計画の責任を担うことになった。", "target_word": "担う", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は新(あたら)しい計画(けいかく)の責任(せきにん)を担(にな)うことになった。", "sentence_source": "generated"}, {"text": "次の世代を担う若者を育てたい。", "target_word": "担う", "complexity_tier": "T3", "furigana": "次(つぎ)の世代(せだい)を担(にな)う若者(わかもの)を育(そだ)てたい。", "sentence_source": "generated"}, {"text": "兄は家族を養う役割を担っている。", "target_word": "担って", "complexity_tier": "T3", "furigana": "兄(あに)は家族(かぞく)を養(やしな)う役割(やくわり)を担(にな)っている。", "sentence_source": "generated"}, {"text": "委員長として、会の運営を担います。", "target_word": "担い", "complexity_tier": "T3", "furigana": "委員長(いいんちょう)として、会(かい)の運営(うんえい)を担(にな)います。", "sentence_source": "generated"}, {"text": "大事な仕事を担う以上、途中で投げ出せない。", "target_word": "担う", "complexity_tier": "T3", "furigana": "大事(だいじ)な仕事(しごと)を担(にな)う以上(いじょう)、途中(とちゅう)で投(な)げ出(だ)せない。", "sentence_source": "generated"}, {"text": "この町の未来を担うのは、君たちだ。", "target_word": "担う", "complexity_tier": "T3", "furigana": "この町(まち)の未来(みらい)を担(にな)うのは、君(きみ)たちだ。", "sentence_source": "generated"}, {"text": "だれもやりたがらなかった司会を、彼は自分から担った。", "target_word": "担った", "complexity_tier": "T3", "furigana": "だれもやりたがらなかった司会(しかい)を、彼(かれ)は自分(じぶん)から担(にな)った。", "sentence_source": "generated"}, {"text": "彼は一人でチームの重い役目を担ってきた。", "target_word": "担って", "complexity_tier": "T3", "furigana": "彼(かれ)は一人(ひとり)でチームの重(おも)い役目(やくめ)を担(にな)ってきた。", "sentence_source": "generated"}, {"text": "誰にも頼まれていないのに、彼は困難な調査の役目を自ら担った。", "target_word": "担った", "complexity_tier": "T3", "furigana": "誰にも頼まれていないのに、彼は困難な調査の役目を自ら担(にな)った。", "sentence_source": "generated"}, {"text": "地域の安全を担う消防団に入った。", "target_word": "担う", "complexity_tier": "T3", "furigana": "地域(ちいき)の安全(あんぜん)を担(にな)う消防団(しょうぼうだん)に入(はい)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "担う", "label": "辞書形"}, {"form": "担わない", "label": "否定形"}, {"form": "担い", "label": "連用形"}, {"form": "担った", "label": "過去形"}, {"form": "担って", "label": "て形"}, {"form": "担えば", "label": "仮定形"}], "register": "文章語", "sense_fingerprint": "役目や責任を自分のものとして引き受ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: 投げ出せ (Zipf 1.5)']::text[], 'c0767258-83b5-4171-bcae-53bbc15f4a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37448, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担う", "is_correct": true, "explanation": "文中の形。「責任を担うことになった」で、役目を引き受ける意味として自然に成り立つ。"}, {"text": "眠る", "is_correct": false, "explanation": "「責任を眠る」は動詞と目的語が結びつかず、文として成り立たない。"}, {"text": "溶ける", "is_correct": false, "explanation": "「責任を溶ける」は意味をなさず、責任を引き受ける話の流れにも合わない。"}, {"text": "散る", "is_correct": false, "explanation": "「責任を散る」は動詞の組み合わせが不自然で、文の内容と合わない。"}], "explanations": {"担う": "文中の形。「責任を担うことになった」で、役目を引き受ける意味として自然に成り立つ。", "眠る": "「責任を眠る」は動詞と目的語が結びつかず、文として成り立たない。", "溶ける": "「責任を溶ける」は意味をなさず、責任を引き受ける話の流れにも合わない。", "散る": "「責任を散る」は動詞の組み合わせが不自然で、文の内容と合わない。"}, "sentence_index": 0, "correct_answer": "担う"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は一台の車を担っていて、毎日通勤に使っている。", "explanation": "ここは〈持つ〉の場面。車を所有する意味は「持つ」で、〈担う〉の役割・責任の意味とは合わない。"}, {"text": "彼は転んで大けがを担って、一週間入院した。", "explanation": "ここは〈負う〉の場面。けがは「負う」が自然で、〈担う〉は役割や責任を引き受ける意味なので合わない。"}, {"text": "彼は昨夜、風邪を担って寝込んだ。", "explanation": "ここは〈引く〉の場面。風邪は「引く」が自然で、〈担う〉の役割・責任の意味とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37448, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担った", "is_correct": true, "explanation": "文中の形。「司会を自分から担った」で、引き受けた出来事の過去として自然。"}, {"text": "咲いた", "is_correct": false, "explanation": "「司会を咲いた」は動詞と目的語が結びつかず、文として成り立たない。"}, {"text": "凍った", "is_correct": false, "explanation": "「司会を凍った」は意味が通らず、司会を引き受ける話の流れに合わない。"}, {"text": "煮えた", "is_correct": false, "explanation": "「司会を煮えた」は意味をなさず、文の内容と合わない。"}], "explanations": {"担った": "文中の形。「司会を自分から担った」で、引き受けた出来事の過去として自然。", "咲いた": "「司会を咲いた」は動詞と目的語が結びつかず、文として成り立たない。", "凍った": "「司会を凍った」は意味が通らず、司会を引き受ける話の流れに合わない。", "煮えた": "「司会を煮えた」は意味をなさず、文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "担った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は持病を担って、毎日薬を飲んでいる。", "explanation": "ここは〈抱える〉の場面。持病は「抱える」が自然で、〈担う〉は役割や責任を引き受ける意味なので合わない。"}, {"text": "大事な鍵を担って、帰りを待った。", "explanation": "ここは〈預かる〉の場面。大切な物を預かる内容で、〈担う〉の役割・責任の意味とは合わない。"}, {"text": "窓辺で景色を担っていた。", "explanation": "ここは〈眺める〉の場面。景色は「眺める」の対象で、〈担う〉は役割を引き受けることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37448, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社の将来に担う若手が今年入社した。", "corrected_sentence": "会社の将来を担う若手が今年入社した。", "error_description": "「担う」は「〜を担う」の形で目的語に「を」を取る。「将来に」は助詞の誤りで、正しくは「将来を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "担う", "is_correct": true, "explanation": "文中の辞書形。「担う若者」の形で名詞を修飾している。"}, {"text": "担って", "is_correct": false, "explanation": "て形。名詞を修飾できず、「担って若者」は文として成り立たない。"}, {"text": "担い", "is_correct": false, "explanation": "連用形。名詞を直接修飾できず、「担い若者」は文法的に成り立たない。"}, {"text": "担えば", "is_correct": false, "explanation": "仮定形。名詞を修飾できず、「担えば若者」は文として成り立たない。"}], "correct_form": "担う", "base_form": "担う", "form_label": "辞書形", "sentence_index": 1, "explanations": {"担う": "文中の辞書形。「担う若者」の形で名詞を修飾している。", "担って": "て形。名詞を修飾できず、「担って若者」は文として成り立たない。", "担い": "連用形。名詞を直接修飾できず、「担い若者」は文法的に成り立たない。", "担えば": "仮定形。名詞を修飾できず、「担えば若者」は文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37448, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は一人で店の重い役目を担いてきた。", "corrected_sentence": "彼女は一人で店の重い役目を担ってきた。", "error_description": "「担いて」は誤ったて形。「担う」のて形は「担って」で、「担ってきた」の形にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "担って", "is_correct": true, "explanation": "文中のて形。「担ってきた」で、経過を表す動詞の続き方として正しい。"}, {"text": "担う", "is_correct": false, "explanation": "辞書形。「担う、きた」と続かず、文の流れが合わない。"}, {"text": "担えば", "is_correct": false, "explanation": "仮定形。条件の意味になり、ずっと役目を続けてきたという経過の意味と合わない。"}, {"text": "担わず", "is_correct": false, "explanation": "連用形（ず）の否定。「担わずにきた」は役目を担わなかった意味になり、文と反対になる。"}], "correct_form": "担って", "base_form": "担う", "form_label": "て形", "sentence_index": 7, "explanations": {"担って": "文中のて形。「担ってきた」で、経過を表す動詞の続き方として正しい。", "担う": "辞書形。「担う、きた」と続かず、文の流れが合わない。", "担えば": "仮定形。条件の意味になり、ずっと役目を続けてきたという経過の意味と合わない。", "担わず": "連用形（ず）の否定。「担わずにきた」は役目を担わなかった意味になり、文と反対になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37450, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「能力を試す」で、試す対象を示す格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「能力へ試す」は方向を示すが、試す対象にはならず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「能力に試す」は相手や方向を示すが、試す対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「自分の能力の試したい」は連体修飾になり、「試したい」の目的語が立たない。"}], "correct_answer": "を", "explanations": {"を": "「能力を試す」で、試す対象を示す格助詞。", "へ": "「能力へ試す」は方向を示すが、試す対象にはならず文が成り立たない。", "に": "「能力に試す」は相手や方向を示すが、試す対象にはならない。", "の": "「自分の能力の試したい」は連体修飾になり、「試したい」の目的語が立たない。"}, "error_tags": {"へ": "方向", "に": "相手・方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37450, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「能力で社員を評価する」で、評価の手段や基準を示す格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「能力へ社員を評価する」は方向を示すが、評価の基準にはならず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「能力を社員を評価する」は目的語が二つ並び、文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「能力に社員を評価する」は評価の基準を表せず、不自然。"}], "correct_answer": "で", "explanations": {"で": "「能力で社員を評価する」で、評価の手段や基準を示す格助詞。", "へ": "「能力へ社員を評価する」は方向を示すが、評価の基準にはならず不自然。", "を": "「能力を社員を評価する」は目的語が二つ並び、文が崩れる。", "に": "「能力に社員を評価する」は評価の基準を表せず、不自然。"}, "error_tags": {"へ": "方向", "を": "目的語", "に": "評価の基準"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37450, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするための力や才能のこと。", "primary_collocate": null, "pronunciation": "のうりょく", "ipa": "noːɾʲokɯ", "syllable_count": 5, "sentences": [{"text": "彼女は三か国語を話す能力があるので、通訳の仕事に選ばれた。", "target_word": "能力", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は三[さん]か国語[こくご]を話[はな]す能力[のうりょく]があるので、通訳[つうやく]の仕事[しごと]に選[えら]ばれた。", "sentence_source": "generated"}, {"text": "新しい仕事では、自分の能力を試したいと思っている。", "target_word": "能力", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]では、自分[じぶん]の能力[のうりょく]を試[ため]したいと思[おも]っている。", "sentence_source": "generated"}, {"text": "能力が高くても、努力をやめれば成長は止まってしまう。", "target_word": "能力", "complexity_tier": "T3", "furigana": "能力[のうりょく]が高[たか]くても、努力[どりょく]をやめれば成長[せいちょう]は止[と]まってしまう。", "sentence_source": "generated"}, {"text": "この試験では、日本語を読む能力だけでなく、聞く力も調べる。", "target_word": "能力", "complexity_tier": "T3", "furigana": "この試験[しけん]では、日本語[にほんご]を読[よ]む能力[のうりょく]だけでなく、聞[き]く力[ちから]も調[しら]べる。", "sentence_source": "generated"}, {"text": "犬は人間よりにおいを感じ取る能力が高い。", "target_word": "能力", "complexity_tier": "T3", "furigana": "犬[いぬ]は人間[にんげん]よりにおいを感[かん]じ取[と]る能力[のうりょく]が高[たか]い。", "sentence_source": "generated"}, {"text": "先生は生徒一人ひとりの能力に合わせて宿題を出した。", "target_word": "能力", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]一人[ひとり]ひとりの能力[のうりょく]に合[あ]わせて宿題[しゅくだい]を出[だ]した。", "sentence_source": "generated"}, {"text": "彼は能力を認められて、若くして部長になった。", "target_word": "能力", "complexity_tier": "T3", "furigana": "彼[かれ]は能力[のうりょく]を認[みと]められて、若[わか]くして部長[ぶちょう]になった。", "sentence_source": "generated"}, {"text": "年齢ではなく能力で社員を評価する会社が増えている。", "target_word": "能力", "complexity_tier": "T3", "furigana": "年齢[ねんれい]ではなく能力[のうりょく]で社員[しゃいん]を評価[ひょうか]する会社[かいしゃ]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "赤ちゃんは、言葉を覚える能力を生まれつき持っている。", "target_word": "能力", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは、言葉[ことば]を覚[おぼ]える能力[のうりょく]を生[う]まれつき持[も]っている。", "sentence_source": "generated"}, {"text": "自分の能力以上の仕事を引き受けて、結局間に合わなかった。", "target_word": "能力", "complexity_tier": "T3", "furigana": "自分[じぶん]の能力[のうりょく]以上[いじょう]の仕事[しごと]を引[ひ]き受[う]けて、結局[けっきょく]間[ま]に合[あ]わなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "能力", "label": "基本形"}, {"form": "能力の", "label": "連体形"}, {"form": "能力を", "label": "目的語形"}], "register": "neutral", "sense_fingerprint": "人が何かをなしとげるために持っている力や才能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aaf6791-139f-41e3-8c71-ba48b836c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37450, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能力", "is_correct": true, "explanation": "「話す能力」は、〜する力のこと。文脈に合う。"}, {"text": "年齢", "is_correct": false, "explanation": "「話す年齢」とは言わず、文が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "「話す体重」は意味をなさず、通訳の仕事の理由にもならない。"}, {"text": "天気", "is_correct": false, "explanation": "「話す天気」とは言えず、空所に入らない。"}], "explanations": {"能力": "「話す能力」は、〜する力のこと。文脈に合う。", "年齢": "「話す年齢」とは言わず、文が通らない。", "体重": "「話す体重」は意味をなさず、通訳の仕事の理由にもならない。", "天気": "「話す天気」とは言えず、空所に入らない。"}, "sentence_index": 0, "correct_answer": "能力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この本の能力は三百ページだ。", "explanation": "ここは〈分量〉の意味。能力は人や機械ができる力を指し、本の大きさには使わない。"}, {"text": "彼女は能力が明るく、誰とでもすぐ打ち解ける。", "explanation": "ここは〈性格〉の意味。能力は「できる力」なので、人柄の明るさには使わない。"}, {"text": "台風の能力で、街の屋根が次々に飛ばされた。", "explanation": "ここは〈威力〉の意味。台風のような自然の破壊力は威力と言い、能力とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37450, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能力", "is_correct": true, "explanation": "「能力を認められる」で、できる力を評価されたという意味になる。"}, {"text": "寿命", "is_correct": false, "explanation": "「寿命を認められる」とは言わず、文が成り立たない。"}, {"text": "手紙", "is_correct": false, "explanation": "「手紙を認められる」は意味をなさず、昇進の理由にもならない。"}, {"text": "天井", "is_correct": false, "explanation": "「天井を認められる」は不自然で、空所に入らない。"}], "explanations": {"能力": "「能力を認められる」で、できる力を評価されたという意味になる。", "寿命": "「寿命を認められる」とは言わず、文が成り立たない。", "手紙": "「手紙を認められる」は意味をなさず、昇進の理由にもならない。", "天井": "「天井を認められる」は不自然で、空所に入らない。"}, "sentence_index": 6, "correct_answer": "能力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店の能力は、毎朝六時から夜十時までだ。", "explanation": "ここは〈営業時間〉の意味。能力は人や物ができる力で、時間の長さには使わない。"}, {"text": "このペンの能力は青色だ。", "explanation": "ここは〈色彩〉の意味。能力は人や物ができる力を指すので、色彩の性質には使わない。"}, {"text": "このテーブルの能力は、長さが二メートルだ。", "explanation": "ここは〈寸法〉の意味。能力は人や物ができる力を指すので、物の長さは指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37450, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この仕事には語学の能力を必要だ。", "corrected_sentence": "この仕事には語学の能力が必要だ。", "error_description": "「必要だ」は「〜が必要だ」の形で、必要とされるものは「が」で示す。ここで「を」を使うのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37450, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社員の能力を高いため、研修を増やした。", "corrected_sentence": "社員の能力を高めるため、研修を増やした。", "error_description": "「能力を」の後には他動詞「高める」が続く。形容詞「高い」は目的語に続けられないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37452, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37452, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「補完がうまくいく」で、「うまくいく」の主語を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「補完をうまくいけば」は目的語を示すが、「うまくいく」は主語を取る動詞なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「補完へうまくいけば」は方向を示すが、「うまくいく」と結びつかない。"}, {"text": "から", "is_correct": false, "explanation": "「補完からうまくいけば」は起点を示すが、ここでは主語を示す必要がある。"}], "correct_answer": "が", "explanations": {"が": "「補完がうまくいく」で、「うまくいく」の主語を示す格助詞。", "を": "「補完をうまくいけば」は目的語を示すが、「うまくいく」は主語を取る動詞なので合わない。", "へ": "「補完へうまくいけば」は方向を示すが、「うまくいく」と結びつかない。", "から": "「補完からうまくいけば」は起点を示すが、ここでは主語を示す必要がある。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37452, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "足りないところを、おたがいに助けて、そろえること。", "primary_collocate": null, "pronunciation": "ほかん", "ipa": "hokaɴ", "syllable_count": 3, "sentences": [{"text": "二人は足りないところを補完し合って、よいチームになった。", "target_word": "補完", "complexity_tier": "T3", "furigana": "二人[ふたり]は足[た]りないところを補完[ほかん]し合[あ]って、よいチームになった。", "sentence_source": "generated"}, {"text": "私は計算が得意で、彼女は文章が得意なので、お互いを補完できる。", "target_word": "補完", "complexity_tier": "T3", "furigana": "私[わたし]は計算[けいさん]が得意[とくい]で、彼女[かのじょ]は文章[ぶんしょう]が得意[とくい]なので、お互[たが]いを補完[ほかん]できる。", "sentence_source": "generated"}, {"text": "弱点を補完する相手を見つけたことが、共同経営の成功につながった。", "target_word": "補完", "complexity_tier": "T3", "furigana": "弱点[じゃくてん]を補完[ほかん]する相手[あいて]を見[み]つけたことが、共同[きょうどう]経営[けいえい]の成功[せいこう]につながった。", "sentence_source": "generated"}, {"text": "営業と開発が補完の関係にあるため、会社は安定している。", "target_word": "補完", "complexity_tier": "T3", "furigana": "営業[えいぎょう]と開発[かいはつ]が補完[ほかん]の関係[かんけい]にあるため、会社[かいしゃ]は安定[あんてい]している。", "sentence_source": "generated"}, {"text": "この二つの店は商品が重ならず、互いに補完している。", "target_word": "補完", "complexity_tier": "T3", "furigana": "この二[ふた]つの店[みせ]は商品[しょうひん]が重[かさ]ならず、互[たが]いに補完[ほかん]している。", "sentence_source": "generated"}, {"text": "兄は体力があり、弟は頭がよいので、兄弟は補完し合って家業を支えた。", "target_word": "補完", "complexity_tier": "T3", "furigana": "兄[あに]は体力[たいりょく]があり、弟[おとうと]は頭[あたま]がよいので、兄弟[きょうだい]は補完[ほかん]し合[あ]って家業[かぎょう]を支[ささ]えた。", "sentence_source": "generated"}, {"text": "地図と説明書は互いに補完する役割を持っている。", "target_word": "補完", "complexity_tier": "T3", "furigana": "地図[ちず]と説明書[せつめいしょ]は互[たが]いに補完[ほかん]する役割[やくわり]を持[も]っている。", "sentence_source": "generated"}, {"text": "補完がうまくいけば、一人ずつの欠点は目立たなくなる。", "target_word": "補完", "complexity_tier": "T3", "furigana": "補完[ほかん]がうまくいけば、一人[ひとり]ずつの欠点[けってん]は目立[めだ]たなくなる。", "sentence_source": "generated"}, {"text": "夫婦で足りない部分を補完し合うことが、長続きの秘訣だという。", "target_word": "補完", "complexity_tier": "T3", "furigana": "夫婦[ふうふ]で足[た]りない部分[ぶぶん]を補完[ほかん]し合[あ]うことが、長続[ながつづ]きの秘訣[ひけつ]だという。", "sentence_source": "generated"}, {"text": "苦手な分野を友達と補完しながら、試験勉強を進めた。", "target_word": "補完", "complexity_tier": "T3", "furigana": "苦手[にがて]な分野[ぶんや]を友達[ともだち]と補完[ほかん]しながら、試験[しけん]勉強[べんきょう]を進[すす]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "補完する", "label": "終止形"}, {"form": "補完した", "label": "過去形"}, {"form": "補完して", "label": "て形"}, {"form": "補完し合う", "label": "相互形"}], "register": "neutral", "sense_fingerprint": "互いの足りない部分を補い合って完全な形にすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aaf6791-139f-41e3-8c71-ba48b836c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37452, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "補完", "is_correct": true, "explanation": "「補完し合う」で、互いの足りない部分を補い合う意味になり文に合う。"}, {"text": "測量", "is_correct": false, "explanation": "土地の寸法を測ることで、「足りないところを測量し合う」は意味をなさない。"}, {"text": "配送", "is_correct": false, "explanation": "荷物を届けることで、足りない部分を配送し合うとは言わない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつけることで、足りないところに点火しても文が通らない。"}], "explanations": {"補完": "「補完し合う」で、互いの足りない部分を補い合う意味になり文に合う。", "測量": "土地の寸法を測ることで、「足りないところを測量し合う」は意味をなさない。", "配送": "荷物を届けることで、足りない部分を配送し合うとは言わない。", "点火": "火をつけることで、足りないところに点火しても文が通らない。"}, "sentence_index": 0, "correct_answer": "補完"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在庫が減ったので、棚の商品を補完した。", "explanation": "ここは〈補充〉の意味。商品を補って並べ直すことは補充と言い、補完は互いの欠けを補い合うこと。"}, {"text": "事故の損害を補完してもらった。", "explanation": "ここは〈補償〉の意味。損害を金銭などで償うことは補償と言い、補完とは言わない。"}, {"text": "古くなった橋の構造を補完した。", "explanation": "ここは〈補強〉の意味。弱い部分を強くすることは補強と言い、補完とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37452, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "補完", "is_correct": true, "explanation": "「互いに補完する役割」で、足りない部分を補い合う意味になり文に合う。"}, {"text": "解散", "is_correct": false, "explanation": "団体などを解くことで、「互いに解散する役割」は文が通らない。"}, {"text": "点滅", "is_correct": false, "explanation": "明かりがついたり消えたりすることで、役割の説明にはならない。"}, {"text": "購入", "is_correct": false, "explanation": "買うことで、「互いに購入する役割」は意味をなさない。"}], "explanations": {"補完": "「互いに補完する役割」で、足りない部分を補い合う意味になり文に合う。", "解散": "団体などを解くことで、「互いに解散する役割」は文が通らない。", "点滅": "明かりがついたり消えたりすることで、役割の説明にはならない。", "購入": "買うことで、「互いに購入する役割」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "補完"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "英語が苦手なので、放課後に補完を受けている。", "explanation": "ここは〈補習〉の意味。授業の遅れを取り戻す勉強は補習と言い、補完とは言わない。"}, {"text": "雨で壊れた道路の穴を、補完した。", "explanation": "ここは〈補修〉の意味。壊れた所を直すことは補修で、補完は不足を互いに補うこと。"}, {"text": "船が港で燃料を補完した。", "explanation": "ここは〈補給〉の意味。燃料などを供給することは補給と言い、補完とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37452, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この二人は補完を関係にあり、仕事がよくまわる。", "corrected_sentence": "この二人は補完の関係にあり、仕事がよくまわる。", "error_description": "「補完の関係」は「補完」に「の」が続いて名詞を修飾する形。「を」は目的語を示すため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37452, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仕事の手順を先輩と補完ながら覚えた。", "corrected_sentence": "仕事の手順を先輩と補完しながら覚えた。", "error_description": "「補完」は「補完する」として動詞になるので、「しながら」と続ける。「し」を落とした「補完ながら」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
