INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37454, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「部品が合う」の主語を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "合うは目的語を取らないので、「を」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表すので、主語の位置には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、合う相手を示す用法にはならない。"}], "correct_answer": "が", "explanations": {"が": "「部品が合う」の主語を示す格助詞。", "を": "合うは目的語を取らないので、「を」は文として成り立たない。", "で": "場所や手段を表すので、主語の位置には入らない。", "へ": "方向を表し、合う相手を示す用法にはならない。"}, "error_tags": {"を": "対象の格", "で": "場所・手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37454, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ふたつのものが、ぴったりとくっつく。", "primary_collocate": null, "pronunciation": "あう", "ipa": "aɯ", "syllable_count": 2, "sentences": [{"text": "このふたは瓶にぴったり合います。", "target_word": "合います", "complexity_tier": "T2", "furigana": "このふたは瓶[びん]にぴったり合[あ]います。", "sentence_source": "generated"}, {"text": "二枚の板がきれいに合って、すき間がありません。", "target_word": "合って", "complexity_tier": "T3", "furigana": "二枚[にまい]の板[いた]がきれいに合[あ]って、すき間[ま]がありません。", "sentence_source": "generated"}, {"text": "割れた皿のかけらが合うかどうか、試してみました。", "target_word": "合う", "complexity_tier": "T3", "furigana": "割[わ]れた皿[さら]のかけらが合[あ]うかどうか、試[ため]してみました。", "sentence_source": "generated"}, {"text": "ねじが穴に合わなくて、水がもれてしまいました。", "target_word": "合わなくて", "complexity_tier": "T3", "furigana": "ねじが穴[あな]に合[あ]わなくて、水[みず]がもれてしまいました。", "sentence_source": "generated"}, {"text": "パズルのピースが合うと、気持ちがいいです。", "target_word": "合う", "complexity_tier": "T2", "furigana": "パズルのピースが合[あ]うと、気持[きも]ちがいいです。", "sentence_source": "generated"}, {"text": "戸がしっかり合っていないので、風が入ります。", "target_word": "合っていない", "complexity_tier": "T3", "furigana": "戸[と]がしっかり合[あ]っていないので、風[かぜ]が入[はい]ります。", "sentence_source": "generated"}, {"text": "古い窓は枠に合わなくなって、すき間ができました。", "target_word": "合わなくなって", "complexity_tier": "T4", "furigana": "古[ふる]い窓[まど]は枠[わく]に合[あ]わなくなって、すき間[ま]ができました。", "sentence_source": "generated"}, {"text": "二つの部品が合うように、ゆっくり押してください。", "target_word": "合う", "complexity_tier": "T3", "furigana": "二[ふた]つの部品[ぶひん]が合[あ]うように、ゆっくり押[お]してください。", "sentence_source": "generated"}, {"text": "切った布の端が合って、きれいにつながりました。", "target_word": "合って", "complexity_tier": "T3", "furigana": "切[き]った布[ぬの]の端[はし]が合[あ]って、きれいにつながりました。", "sentence_source": "generated"}, {"text": "二つの部品は、形が合うと、ぴったりくっつきます。", "target_word": "合う", "complexity_tier": "T3", "furigana": "二(ふた)つの部品(ぶひん)は、形(かたち)が合(あ)うと、ぴったりくっつきます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "合う", "label": "辞書形"}, {"form": "合います", "label": "丁寧形"}, {"form": "合わない", "label": "否定形"}, {"form": "合った", "label": "過去形"}, {"form": "合って", "label": "て形"}, {"form": "合えば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "二つの物が隙間なくぴったり重なり合う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4be6f74-22e6-41bf-9393-a52cbcefdc01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37454, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合います", "is_correct": true, "explanation": "「ふたが瓶にぴったりくっつく」意味に合い、丁寧形で文を結べる。"}, {"text": "割れます", "is_correct": false, "explanation": "ふたが瓶に割れて密着するとは言えず、「ぴったり」と合わない。"}, {"text": "転がります", "is_correct": false, "explanation": "ふたが瓶の上を転がる動きで、ぴったり接する状態を表せない。"}, {"text": "外れます", "is_correct": false, "explanation": "「ぴったり」と反対に、ふたが瓶から離れる意味になり文脈に合わない。"}], "explanations": {"合います": "「ふたが瓶にぴったりくっつく」意味に合い、丁寧形で文を結べる。", "割れます": "ふたが瓶に割れて密着するとは言えず、「ぴったり」と合わない。", "転がります": "ふたが瓶の上を転がる動きで、ぴったり接する状態を表せない。", "外れます": "「ぴったり」と反対に、ふたが瓶から離れる意味になり文脈に合わない。"}, "sentence_index": 0, "correct_answer": "合います"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボールが壁に合った。", "explanation": "ここは〈当たる〉の意味。ぶつかる意味は当たるで表し、ぴったりくっつく意味の合うは使わない。"}, {"text": "ガムが靴の底に合って、取れません。", "explanation": "ここは〈付く〉の意味。ガムが靴に付着する場合は付くを使い、形がぴったり合う意味の合うは使わない。"}, {"text": "手紙が家に合って、うれしかった。", "explanation": "ここは〈届く〉の意味。相手の所へ着く意味は届くで表し、くっつく意味の合うは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37454, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合わなくなって", "is_correct": true, "explanation": "「枠に合わなくなって」の形で、窓が枠に合わなくなった状態を表す。"}, {"text": "転がって", "is_correct": false, "explanation": "窓が枠の中で転がるとは言えず、すき間の原因の説明にならない。"}, {"text": "割れて", "is_correct": false, "explanation": "窓が割れてすき間ができる意味になり、枠との関係が合わない。"}, {"text": "焦げて", "is_correct": false, "explanation": "窓が焦げるのは枠との接合とは無関係で、文脈に合わない。"}], "explanations": {"合わなくなって": "「枠に合わなくなって」の形で、窓が枠に合わなくなった状態を表す。", "転がって": "窓が枠の中で転がるとは言えず、すき間の原因の説明にならない。", "割れて": "窓が割れてすき間ができる意味になり、枠との関係が合わない。", "焦げて": "窓が焦げるのは枠との接合とは無関係で、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "合わなくなって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ようやく電話が合って、ほっとした。", "explanation": "ここは〈つながる〉の意味。電話や回線がつながることには合うを使わない。"}, {"text": "バスに合って、駅へ行った。", "explanation": "ここは〈乗る〉の意味。乗り物に乗る場合は乗るを使い、合うでは表せない。"}, {"text": "雷が木に合って、倒れた。", "explanation": "ここは〈当たる〉の意味。物が当たる意味は当たるで表し、ぴったり合う意味の合うは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37454, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この鍵は錠を合います。", "corrected_sentence": "この鍵は錠に合います。", "error_description": "「合う」は「〜に合う」の形をとるため、相手には「に」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "合って", "is_correct": true, "explanation": "て形で、後ろの「すき間がありません」へ続けられる。"}, {"text": "合う", "is_correct": false, "explanation": "辞書形で文を終えると「、」で続ける文の流れが切れ、て形の接続にならない。"}, {"text": "合わない", "is_correct": false, "explanation": "否定形にすると「板が合わない」意味になり、文の内容が逆転する。"}, {"text": "合います", "is_correct": false, "explanation": "丁寧形は文末用で、後ろに続ける文の接続には使えない。"}], "correct_form": "合って", "base_form": "合う", "form_label": "て形", "sentence_index": 1, "explanations": {"合って": "て形で、後ろの「すき間がありません」へ続けられる。", "合う": "辞書形で文を終えると「、」で続ける文の流れが切れ、て形の接続にならない。", "合わない": "否定形にすると「板が合わない」意味になり、文の内容が逆転する。", "合います": "丁寧形は文末用で、後ろに続ける文の接続には使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37454, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ねじが穴に合うれば、水がもれません。", "corrected_sentence": "ねじが穴に合えば、水がもれません。", "error_description": "「合う」の仮定形は「合えば」。「合うれば」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "合う", "is_correct": true, "explanation": "辞書形で「ように」に続き、部品がくっつくよう求める文になる。"}, {"text": "合います", "is_correct": false, "explanation": "丁寧形は「ように」に直接続けられず、文が成立しない。"}, {"text": "合って", "is_correct": false, "explanation": "て形は「ように」に続けられず、目的を表す文にならない。"}, {"text": "合えば", "is_correct": false, "explanation": "仮定形は条件を表し、「ように」の目的の意味と合わない。"}], "correct_form": "合う", "base_form": "合う", "form_label": "辞書形", "sentence_index": 7, "explanations": {"合う": "辞書形で「ように」に続き、部品がくっつくよう求める文になる。", "合います": "丁寧形は「ように」に直接続けられず、文が成立しない。", "合って": "て形は「ように」に続けられず、目的を表す文にならない。", "合えば": "仮定形は条件を表し、「ように」の目的の意味と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37455, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
