INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37455, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "条件や状況にぴったりと当てはまる。", "primary_collocate": null, "pronunciation": "あう", "ipa": "aɯ", "syllable_count": 2, "sentences": [{"text": "今は一人一人の体に合う薬です。", "target_word": "合う", "complexity_tier": "T3", "furigana": "今[いま]は一人一人[ひとりひとり]の体[からだ]に合[あ]う薬[くすり]です。", "sentence_source": "mined"}, {"text": "私たちの希望条件に合う物件が、やっと見つかりました。", "target_word": "合う", "complexity_tier": "T3", "furigana": "私たちの希望[きぼう]条件[じょうけん]に合[あ]う物件[ぶっけん]が、やっと見つかりました。", "sentence_source": "generated"}, {"text": "色が服に合うかどうか、店で確かめました。", "target_word": "合う", "complexity_tier": "T3", "furigana": "色[いろ]が服[ふく]に合[あ]うかどうか、店[みせ]で確[たし]かめました。", "sentence_source": "generated"}, {"text": "私は辛い料理が口に合わなくて、残してしまいました。", "target_word": "合わなくて", "complexity_tier": "T3", "furigana": "私[わたし]は辛[から]い料理[りょうり]が口[くち]に合[あ]わなくて、残[のこ]してしまいました。", "sentence_source": "generated"}, {"text": "このデザインは私の好みに合うので、迷わず買いました。", "target_word": "合う", "complexity_tier": "T3", "furigana": "このデザインは私の好み[このみ]に合[あ]うので、迷[まよ]わず買[か]いました。", "sentence_source": "generated"}, {"text": "新しい仕事は自分に合っていると思います。", "target_word": "合っている", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]は自分[じぶん]に合[あ]っていると思[おも]います。", "sentence_source": "generated"}, {"text": "予算に合う部屋を探しています。", "target_word": "合う", "complexity_tier": "T3", "furigana": "予算[よさん]に合[あ]う部屋[へや]を探[さが]しています。", "sentence_source": "generated"}, {"text": "結婚式には場所に合う服を着ていきます。", "target_word": "合う", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]には場所[ばしょ]に合[あ]う服[ふく]を着[き]ていきます。", "sentence_source": "generated"}, {"text": "サイズが合わない靴は、足が痛くなります。", "target_word": "合わない", "complexity_tier": "T3", "furigana": "サイズが合[あ]わない靴[くつ]は、足[あし]が痛[いた]くなります。", "sentence_source": "generated"}, {"text": "この上着は季節に合わないので、あまり着ていません。", "target_word": "合わない", "complexity_tier": "T3", "furigana": "この上着[うわぎ]は季節[きせつ]に合[あ]わないので、あまり着[き]ていません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "合う", "label": "辞書形"}, {"form": "合います", "label": "丁寧形"}, {"form": "合わない", "label": "否定形"}, {"form": "合った", "label": "過去形"}, {"form": "合って", "label": "て形"}, {"form": "合えば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "条件・好み・状況にふさわしく当てはまる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4be6f74-22e6-41bf-9393-a52cbcefdc01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37455, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合う", "is_correct": true, "explanation": "「体に合う薬」の「合う」。体にぴったり当てはまる薬という意味になり、文が自然。"}, {"text": "行く", "is_correct": false, "explanation": "「体に行く薬」は意味が通らない。行くは移動を表し、薬の性質を示せない。"}, {"text": "話す", "is_correct": false, "explanation": "「体に話す薬」は成り立たない。話すは会話を表し、薬を修飾できない。"}, {"text": "降る", "is_correct": false, "explanation": "「体に降る薬」は不自然。降るは雨などが落ちる動きで、薬には使えない。"}], "explanations": {"合う": "「体に合う薬」の「合う」。体にぴったり当てはまる薬という意味になり、文が自然。", "行く": "「体に行く薬」は意味が通らない。行くは移動を表し、薬の性質を示せない。", "話す": "「体に話す薬」は成り立たない。話すは会話を表し、薬を修飾できない。", "降る": "「体に降る薬」は不自然。降るは雨などが落ちる動きで、薬には使えない。"}, "sentence_index": 0, "correct_answer": "合う"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友だちと駅で合いました。", "explanation": "ここは〈会う〉の意味。〈合う〉は条件や状態がぴったり当てはまるという意味で、人と会うことには使えない。"}, {"text": "今から出かけても、電車に合いません。", "explanation": "ここは〈間に合う〉の意味。〈合う〉だけでは時間に間に合うという意味にならない。〈間に合う〉を使う。"}, {"text": "この箱に、大きなケーキが合います。", "explanation": "ここは〈入る〉の意味。〈合う〉は中に収まるという意味ではない。箱に入る場合は〈入る〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37455, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合う", "is_correct": true, "explanation": "「予算に合う部屋」の「合う」。予算に当てはまる部屋という意味になり、自然に成り立つ。"}, {"text": "戻る", "is_correct": false, "explanation": "「予算に戻る部屋」は意味が通らない。戻るは元の場所に帰ることで、条件を表さない。"}, {"text": "聞く", "is_correct": false, "explanation": "「予算に聞く部屋」は成り立たない。聞くは音や話を受け取る動作で、部屋を修飾できない。"}, {"text": "続く", "is_correct": false, "explanation": "「予算に続く部屋」は不自然。続くは継続を表し、条件を示せない。"}], "explanations": {"合う": "「予算に合う部屋」の「合う」。予算に当てはまる部屋という意味になり、自然に成り立つ。", "戻る": "「予算に戻る部屋」は意味が通らない。戻るは元の場所に帰ることで、条件を表さない。", "聞く": "「予算に聞く部屋」は成り立たない。聞くは音や話を受け取る動作で、部屋を修飾できない。", "続く": "「予算に続く部屋」は不自然。続くは継続を表し、条件を示せない。"}, "sentence_index": 6, "correct_answer": "合う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来月の試験に合いたいので、毎日勉強しています。", "explanation": "ここは〈合格〉の意味。〈合う〉は条件に当てはまる意味で、試験に受かるという意味にはならない。"}, {"text": "明日、社長に合ってから会社へ行きます。", "explanation": "ここは〈会う〉の意味。〈合う〉は人と会うことを表さない。人と会うには〈会う〉を使う。"}, {"text": "このポケットに、大きな財布が合います。", "explanation": "ここは〈入る〉の意味。〈合う〉は条件に当てはまる意味で、物が中に収まる意味ではない。収まる場合は〈入る〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37455, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このスーツは私の体形で合います。", "corrected_sentence": "このスーツは私の体形に合います。", "error_description": "「体形で合います」の「で」が誤り。〈合う〉は合わせる対象を「に」で示すので、正しくは「体形に合います」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "合う", "is_correct": true, "explanation": "「条件に合う物件」のように名詞を修飾する形。辞書形が正しい。"}, {"text": "合います", "is_correct": false, "explanation": "丁寧形。名詞を直接修飾できず、「合います物件」になってしまうので不可。"}, {"text": "合おう", "is_correct": false, "explanation": "意志形。名詞を直接修飾できず、「合おう物件」は不自然なので不可。"}, {"text": "合って", "is_correct": false, "explanation": "て形。名詞を修飾できず、「合って物件」となるので不可。"}], "correct_form": "合う", "base_form": "合う", "form_label": "辞書形", "sentence_index": 1, "explanations": {"合う": "「条件に合う物件」のように名詞を修飾する形。辞書形が正しい。", "合います": "丁寧形。名詞を直接修飾できず、「合います物件」になってしまうので不可。", "合おう": "意志形。名詞を直接修飾できず、「合おう物件」は不自然なので不可。", "合って": "て形。名詞を修飾できず、「合って物件」となるので不可。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37455, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この靴は足のサイズによく合わます。", "corrected_sentence": "この靴は足のサイズによく合います。", "error_description": "「合わます」は誤った活用。丁寧形は「合います」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "合う", "is_correct": true, "explanation": "「場所に合う服」のように名詞を修飾する形。辞書形が正しい。"}, {"text": "合おう", "is_correct": false, "explanation": "意志形。名詞を直接修飾できず、「合おう服」は不自然なので不可。"}, {"text": "合え", "is_correct": false, "explanation": "命令形。名詞を直接修飾できず、「合え服」は不自然なので不可。"}, {"text": "合えば", "is_correct": false, "explanation": "仮定形。名詞を直接修飾できず、「合えば服」となり不自然。"}], "correct_form": "合う", "base_form": "合う", "form_label": "辞書形", "sentence_index": 7, "explanations": {"合う": "「場所に合う服」のように名詞を修飾する形。辞書形が正しい。", "合おう": "意志形。名詞を直接修飾できず、「合おう服」は不自然なので不可。", "合え": "命令形。名詞を直接修飾できず、「合え服」は不自然なので不可。", "合えば": "仮定形。名詞を直接修飾できず、「合えば服」となり不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
