INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37456, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなで同じことを目指すこと。", "primary_collocate": null, "pronunciation": "きょうつう", "ipa": "kʲoːtsɯː", "syllable_count": 4, "sentences": [{"text": "選手たちは、優勝という共通の目標に向かって毎日練習した。", "target_word": "共通", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは、優勝[ゆうしょう]という共通[きょうつう]の目標[もくひょう]に向[む]かって毎日[まいにち]練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "町の人々は、川をきれいにするという共通の願いを持っている。", "target_word": "共通", "complexity_tier": "T3", "furigana": "町[まち]の人々[ひとびと]は、川[かわ]をきれいにするという共通[きょうつう]の願[ねが]いを持[も]っている。", "sentence_source": "generated"}, {"text": "共通の目的があれば、年齢が違っても協力できる。", "target_word": "共通", "complexity_tier": "T3", "furigana": "共通[きょうつう]の目的[もくてき]があれば、年齢[ねんれい]が違[ちが]っても協力[きょうりょく]できる。", "sentence_source": "generated"}, {"text": "全員が共通の夢を見ているからこそ、このチームは強い。", "target_word": "共通", "complexity_tier": "T3", "furigana": "全員[ぜんいん]が共通[きょうつう]の夢[ゆめ]を見[み]ているからこそ、このチームは強[つよ]い。", "sentence_source": "generated"}, {"text": "クラスの共通の目標は、文化祭を成功させることだ。", "target_word": "共通", "complexity_tier": "T3", "furigana": "クラスの共通[きょうつう]の目標[もくひょう]は、文化祭[ぶんかさい]を成功[せいこう]させることだ。", "sentence_source": "generated"}, {"text": "国どうしが共通の課題に取り組むため、会議が開かれた。", "target_word": "共通", "complexity_tier": "T3", "furigana": "国[くに]どうしが共通[きょうつう]の課題[かだい]に取[と]り組[く]むため、会議[かいぎ]が開[ひら]かれた。", "sentence_source": "generated"}, {"text": "社員が共通の目的を理解していないと、仕事はばらばらになる。", "target_word": "共通", "complexity_tier": "T3", "furigana": "社員[しゃいん]が共通[きょうつう]の目的[もくてき]を理解[りかい]していないと、仕事[しごと]はばらばらになる。", "sentence_source": "generated"}, {"text": "二つの学校は、地域を守るという共通の思いで手を組んだ。", "target_word": "共通", "complexity_tier": "T3", "furigana": "二[ふた]つの学校[がっこう]は、地域[ちいき]を守[まも]るという共通[きょうつう]の思[おも]いで手[て]を組[く]んだ。", "sentence_source": "generated"}, {"text": "家族みんなで共通の目標を決めて、貯金を始めた。", "target_word": "共通", "complexity_tier": "T3", "furigana": "家族[かぞく]みんなで共通[きょうつう]の目標[もくひょう]を決[き]めて、貯金[ちょきん]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "共通の願いに向かって、みんなが少しずつ力を出し合った。", "target_word": "共通", "complexity_tier": "T3", "furigana": "共通[きょうつう]の願[ねが]いに向[む]かって、みんなが少[すこ]しずつ力[ちから]を出[だ]し合[あ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "共通する", "label": "終止形"}, {"form": "共通した", "label": "過去形"}, {"form": "共通して", "label": "て形"}, {"form": "共通の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "全員が同じ目標や願いを持って一緒に目指していること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aaf6791-139f-41e3-8c71-ba48b836c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37456, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共通", "is_correct": true, "explanation": "「共通の目標」で、みんなが同じものを目指す意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の目標」は目指す対象にならず、文が通らない。"}, {"text": "寒さ", "is_correct": false, "explanation": "「寒さの目標」は目指す対象にならず、文が成り立たない。"}, {"text": "味", "is_correct": false, "explanation": "「味の目標」は意味をなさず、練習の目的にもならない。"}], "explanations": {"共通": "「共通の目標」で、みんなが同じものを目指す意味に合う。", "天気": "「天気の目標」は目指す対象にならず、文が通らない。", "寒さ": "「寒さの目標」は目指す対象にならず、文が成り立たない。", "味": "「味の目標」は意味をなさず、練習の目的にもならない。"}, "sentence_index": 0, "correct_answer": "共通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私一人だけの共通の目標を、毎晩ノートに書いている。", "explanation": "ここは〈個人の目標〉の意味。共通は複数の人が同じものを分け持つことを指すので、個人的な目標には使わない。"}, {"text": "この部屋の共通は十畳だ。", "explanation": "ここは〈広さ〉の意味。共通は複数の人や物に同じ点があることで、部屋の広さは指さない。"}, {"text": "今朝の共通は雨だった。", "explanation": "ここは〈天気〉の意味。共通は人が目指す目標や性質を指し、天気には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37456, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共通", "is_correct": true, "explanation": "「共通の目的」で、社員全員が同じ目的を理解するという意味に合う。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気の目的」は意味をなさず、理解の対象にならない。"}, {"text": "天然", "is_correct": false, "explanation": "「天然の目的」は意味をなさず、文の空所に入らない。"}, {"text": "雨音", "is_correct": false, "explanation": "「雨音の目的」は意味をなさず、理解の対象にならない。"}], "explanations": {"共通": "「共通の目的」で、社員全員が同じ目的を理解するという意味に合う。", "眠気": "「眠気の目的」は意味をなさず、理解の対象にならない。", "天然": "「天然の目的」は意味をなさず、文の空所に入らない。", "雨音": "「雨音の目的」は意味をなさず、理解の対象にならない。"}, "sentence_index": 6, "correct_answer": "共通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は共通の性格で、すぐに怒る。", "explanation": "ここは〈一人だけの特徴〉の意味。共通は複数の人や物に同じ点があることを指すので、一人の性質には使わない。"}, {"text": "私の共通の体温は、三十七度だ。", "explanation": "ここは〈一人だけの体の状態〉の意味。共通は複数の人に当てはまる性質を指すので、自分一人の体温には使わない。"}, {"text": "私だけに共通の眠気が襲ってきた。", "explanation": "ここは〈自分だけの感覚〉の意味。共通は複数の人に当てはまることを指すので、私だけに起きる眠気とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37456, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "全員が共通を目的を持って働いている。", "corrected_sentence": "全員が共通の目的を持って働いている。", "error_description": "「共通」は名詞として「の目的」と続けて修飾する。「を」では目的語になってしまい、「目的」の修飾が崩れるので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37456, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "みんなが共通くて目指している目標がある。", "corrected_sentence": "みんなが共通して目指している目標がある。", "error_description": "「共通する」のて形は「共通して」。「共通くて」は形容詞の活用で、動詞の「共通する」には使えないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
