INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37457, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "複数の人や物事の間で、同じであること。また、みんなに当てはまること。", "primary_collocate": null, "pronunciation": "きょうつう", "ipa": "kʲoːtsɯː", "syllable_count": 4, "sentences": [{"text": "兄と私には、音楽が好きだという共通した趣味がある。", "target_word": "共通", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]には、音楽[おんがく]が好[す]きだという共通[きょうつう]した趣味[しゅみ]がある。", "sentence_source": "generated"}, {"text": "この二つの言葉には、意味に共通するところがある。", "target_word": "共通", "complexity_tier": "T3", "furigana": "この二[ふた]つの言葉[ことば]には、意味[いみ]に共通[きょうつう]するところがある。", "sentence_source": "generated"}, {"text": "この学校では、全員に共通の制服を着せている。", "target_word": "共通", "complexity_tier": "T3", "furigana": "この学校[がっこう]では、全員[ぜんいん]に共通[きょうつう]の制服[せいふく]を着[き]せている。", "sentence_source": "generated"}, {"text": "犬も猫も、人に飼われるという点で共通している。", "target_word": "共通", "complexity_tier": "T3", "furigana": "犬[いぬ]も猫[ねこ]も、人[ひと]に飼[か]われるという点[てん]で共通[きょうつう]している。", "sentence_source": "generated"}, {"text": "世界の子どもたちに共通する願いは、平和に暮らすことだ。", "target_word": "共通", "complexity_tier": "T3", "furigana": "世界[せかい]の子[こ]どもたちに共通[きょうつう]する願[ねが]いは、平和[へいわ]に暮[く]らすことだ。", "sentence_source": "generated"}, {"text": "二人は出身地が共通していたので、すぐに仲良くなった。", "target_word": "共通", "complexity_tier": "T3", "furigana": "二人[ふたり]は出身地[しゅっしんち]が共通[きょうつう]していたので、すぐに仲良[なかよ]くなった。", "sentence_source": "generated"}, {"text": "この問題は、どの会社にも共通して起こっている。", "target_word": "共通", "complexity_tier": "T3", "furigana": "この問題[もんだい]は、どの会社[かいしゃ]にも共通[きょうつう]して起[お]こっている。", "sentence_source": "generated"}, {"text": "私たちの家族には、背が高いという共通の特徴がある。", "target_word": "共通", "complexity_tier": "T3", "furigana": "私[わたし]たちの家族[かぞく]には、背[せ]が高[たか]いという共通[きょうつう]の特徴[とくちょう]がある。", "sentence_source": "generated"}, {"text": "料金表は、すべての店で共通になっている。", "target_word": "共通", "complexity_tier": "T3", "furigana": "料金表[りょうきんひょう]は、すべての店[みせ]で共通[きょうつう]になっている。", "sentence_source": "generated"}, {"text": "友達とは好きな食べ物が共通なので、店選びで困らない。", "target_word": "共通", "complexity_tier": "T3", "furigana": "友達[ともだち]とは好[す]きな食[た]べ物[もの]が共通[きょうつう]なので、店選[みせえら]びで困[こま]らない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "共通する", "label": "終止形"}, {"form": "共通した", "label": "過去形"}, {"form": "共通して", "label": "て形"}, {"form": "共通の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "複数の人や物の間で同じである性質、またすべてに当てはまること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aaf6791-139f-41e3-8c71-ba48b836c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37457, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共通", "is_correct": true, "explanation": "「共通した趣味」で、二人に同じ趣味があるという意味に合う。"}, {"text": "完成", "is_correct": false, "explanation": "「完成した」は作業などが仕上がった意味で、趣味の説明にならない。"}, {"text": "誤解", "is_correct": false, "explanation": "「誤解した趣味」は趣味を取り違えたことになり、文が通らない。"}, {"text": "予習", "is_correct": false, "explanation": "「予習した趣味」は授業前の学習の意味で、趣味には当てはまらない。"}], "explanations": {"共通": "「共通した趣味」で、二人に同じ趣味があるという意味に合う。", "完成": "「完成した」は作業などが仕上がった意味で、趣味の説明にならない。", "誤解": "「誤解した趣味」は趣味を取り違えたことになり、文が通らない。", "予習": "「予習した趣味」は授業前の学習の意味で、趣味には当てはまらない。"}, "sentence_index": 0, "correct_answer": "共通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この机は一つだけなのに、共通の色をしている。", "explanation": "ここは〈単独の特徴〉の意味。共通は複数に同じ点があることなので、単独の物の色には使わない。"}, {"text": "この部屋の共通は十畳だ。", "explanation": "ここは〈広さ〉の意味。共通は複数のものに同じ性質があることで、部屋の広さは指さない。"}, {"text": "今朝の共通は雨だった。", "explanation": "ここは〈天気〉の意味。共通は性質が複数に当てはまることで、天候には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37457, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共通", "is_correct": true, "explanation": "「共通して起こっている」で、どの会社にも同じように起こるという意味に合う。"}, {"text": "解消", "is_correct": false, "explanation": "問題を取り除くことで、「解消して起こっている」は文が通らない。"}, {"text": "予告", "is_correct": false, "explanation": "前もって知らせることで、「予告して起こっている」は意味をなさない。"}, {"text": "放置", "is_correct": false, "explanation": "そのままにしておくことで、「放置して起こっている」は文が成り立たない。"}], "explanations": {"共通": "「共通して起こっている」で、どの会社にも同じように起こるという意味に合う。", "解消": "問題を取り除くことで、「解消して起こっている」は文が通らない。", "予告": "前もって知らせることで、「予告して起こっている」は意味をなさない。", "放置": "そのままにしておくことで、「放置して起こっている」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "共通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は共通の性格で、すぐに怒る。", "explanation": "ここは〈一人だけの特徴〉の意味。共通は複数の人や物に同じ点があることを指すので、一人の気質には使わない。"}, {"text": "私の共通の身長は、百七十センチだ。", "explanation": "ここは〈一人だけの体の特徴〉の意味。共通は複数に当てはまる点を指すので、自分一人の体格には使わない。"}, {"text": "私だけに共通の眠気が襲ってきた。", "explanation": "ここは〈自分だけの感覚〉の意味。共通は複数の人に当てはまることを指すので、私だけに起きる眠気とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37457, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この二人には、同じ学校に通ったという共通で経験がある。", "corrected_sentence": "この二人には、同じ学校に通ったという共通の経験がある。", "error_description": "「共通」は名詞として「の経験」と続けて修飾する。「で」では修飾関係が成り立たず、文が通らないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37457, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この二つの店は、どちらも共通くて営業時間が短い。", "corrected_sentence": "この二つの店は、どちらも共通して営業時間が短い。", "error_description": "「共通する」のて形は「共通して」。「共通くて」は形容詞の活用で、動詞の「共通する」には使えないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
