INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37458, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「目標を大きく書いた」の「を」は、書く対象として「目標」に直接付く。"}, {"text": "が", "is_correct": false, "explanation": "「目標が大きく書いた」では、目標が主語になり、「書いた」の対象がなくなって文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「書いた」の対象を表す文脈には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「目標より大きく書いた」は比較の「より」になり、書く対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「目標を大きく書いた」の「を」は、書く対象として「目標」に直接付く。", "が": "「目標が大きく書いた」では、目標が主語になり、「書いた」の対象がなくなって文が成り立たない。", "へ": "「へ」は方向を示すので、「書いた」の対象を表す文脈には合わない。", "より": "「目標より大きく書いた」は比較の「より」になり、書く対象を示せない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37458, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "めざすところ。みんながんばるほうこう。", "primary_collocate": null, "pronunciation": "もくひょう", "ipa": "mokɯçoː", "syllable_count": 4, "sentences": [{"text": "今年のクラスの目標は、全員で合唱コンクールに出ることだ。", "target_word": "目標", "complexity_tier": "T3", "furigana": "今年[ことし]のクラスの目標[もくひょう]は、全員[ぜんいん]で合唱[がっしょう]コンクールに出[で]ることだ。", "sentence_source": "generated"}, {"text": "私たちは「ごみを減らす」という目標を決めて活動している。", "target_word": "目標", "complexity_tier": "T3", "furigana": "私[わたし]たちは「ごみを減[へ]らす」という目標[もくひょう]を決[き]めて活動[かつどう]している。", "sentence_source": "generated"}, {"text": "チームの目標がはっきりしていると、練習にも気持ちが入る。", "target_word": "目標", "complexity_tier": "T3", "furigana": "チームの目標[もくひょう]がはっきりしていると、練習[れんしゅう]にも気持[きも]ちが入[はい]る。", "sentence_source": "generated"}, {"text": "会社は、来年の売り上げを二倍にする目標を発表した。", "target_word": "目標", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、来年[らいねん]の売[う]り上[あ]げを二倍[にばい]にする目標[もくひょう]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "みんなで目標を立てて、運動会に向けて練習を始めた。", "target_word": "目標", "complexity_tier": "T3", "furigana": "みんなで目標[もくひょう]を立[た]てて、運動会[うんどうかい]に向[む]けて練習[れんしゅう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "目標を達成したとき、全員で喜び合った。", "target_word": "目標", "complexity_tier": "T3", "furigana": "目標[もくひょう]を達成[たっせい]したとき、全員[ぜんいん]で喜[よろこ]び合[あ]った。", "sentence_source": "generated"}, {"text": "町の目標は、十年後に人口を増やすことだ。", "target_word": "目標", "complexity_tier": "T3", "furigana": "町[まち]の目標[もくひょう]は、十年後[じゅうねんご]に人口[じんこう]を増[ふ]やすことだ。", "sentence_source": "generated"}, {"text": "先生は黒板に学期の目標を大きく書いた。", "target_word": "目標", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に学期[がっき]の目標[もくひょう]を大[おお]きく書[か]いた。", "sentence_source": "generated"}, {"text": "目標が高すぎて、メンバーのやる気が下がってしまった。", "target_word": "目標", "complexity_tier": "T3", "furigana": "目標[もくひょう]が高[たか]すぎて、メンバーのやる気[き]が下[さ]がってしまった。", "sentence_source": "generated"}, {"text": "私たちの部の目標は、県大会で一勝することだ。", "target_word": "目標", "complexity_tier": "T3", "furigana": "私[わたし]たちの部[ぶ]の目標[もくひょう]は、県大会[けんたいかい]で一勝[いっしょう]することだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "目標", "label": "基本形"}, {"form": "目標の", "label": "連体形"}, {"form": "目標を", "label": "目的語形"}], "register": "neutral", "sense_fingerprint": "集団や自分が達成しようと決めた、がんばって向かう先", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aaf6791-139f-41e3-8c71-ba48b836c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37458, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目標", "is_correct": true, "explanation": "正解。「今年のクラスの目標は〜ことだ」で、めざす先を示す語として自然に入る。"}, {"text": "感想", "is_correct": false, "explanation": "「感想は〜ことだ」では、文の主語が感想になり、全員で出場することを感想とは言えないので合わない。"}, {"text": "失敗", "is_correct": false, "explanation": "「失敗は〜ことだ」は意味が通らない。合唱コンクールに出ることは、達成すべき先であって失敗ではない。"}, {"text": "記憶", "is_correct": false, "explanation": "「記憶は〜ことだ」は、過去の出来事を思い出す内容でなければ成り立たず、今年の計画とは合わない。"}], "explanations": {"目標": "正解。「今年のクラスの目標は〜ことだ」で、めざす先を示す語として自然に入る。", "感想": "「感想は〜ことだ」では、文の主語が感想になり、全員で出場することを感想とは言えないので合わない。", "失敗": "「失敗は〜ことだ」は意味が通らない。合唱コンクールに出ることは、達成すべき先であって失敗ではない。", "記憶": "「記憶は〜ことだ」は、過去の出来事を思い出す内容でなければ成り立たず、今年の計画とは合わない。"}, "sentence_index": 0, "correct_answer": "目標"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "努力の目標が実って、ついに賞をもらった。", "explanation": "ここは〈成果〉の意味。目標は到達すべき先で、実るものではない。実るのは努力の成果や夢のほうなので、目標には合わない。"}, {"text": "後半、彼が見事な目標を入れて、チームは勝った。", "explanation": "ここは〈得点〉の意味。ゴールを入れるという点の取り方は得点やゴールと言い、目標は目指す先なので合わない。"}, {"text": "山道では、木に目標を付けて迷わないようにした。", "explanation": "ここは〈目印〉の意味。道しるべとして木に付ける印は目印で、目標は目指す先なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37458, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目標", "is_correct": true, "explanation": "正解。「町の目標は〜ことだ」で、人口を増やすという到達すべき先を示す。"}, {"text": "勘違い", "is_correct": false, "explanation": "「勘違いは〜ことだ」では、誤解の内容を述べる文になり、人口を増やすことの説明にならない。"}, {"text": "感動", "is_correct": false, "explanation": "「感動は〜ことだ」は、感じた気持ちを述べる文になり、町の計画としては意味が通らない。"}, {"text": "手応え", "is_correct": false, "explanation": "「手応えは〜ことだ」は、ある行動による感触の話になり、将来の人口計画とは合わない。"}], "explanations": {"目標": "正解。「町の目標は〜ことだ」で、人口を増やすという到達すべき先を示す。", "勘違い": "「勘違いは〜ことだ」では、誤解の内容を述べる文になり、人口を増やすことの説明にならない。", "感動": "「感動は〜ことだ」は、感じた気持ちを述べる文になり、町の計画としては意味が通らない。", "手応え": "「手応えは〜ことだ」は、ある行動による感触の話になり、将来の人口計画とは合わない。"}, "sentence_index": 6, "correct_answer": "目標"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この機械の目標は、まず電源を入れることだ。", "explanation": "ここは〈手順〉の意味。目標は到達すべき先で、順番に行う作業の段階を指す語ではない。"}, {"text": "試合に負けた目標は、足のけがだった。", "explanation": "ここは〈原因〉の意味。目標は目指すもので、負けた理由を示す語ではないので合わない。"}, {"text": "交差点の目標が赤になった。", "explanation": "ここは〈信号〉の意味。色で合図を示すのは信号で、目標は目指す先なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37458, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私たちのクラスの目標を、来月までに教室をきれいにすることだ。", "corrected_sentence": "私たちのクラスの目標は、来月までに教室をきれいにすることだ。", "error_description": "目標を主題として示すには「は」が必要。「を」にすると、目標を対象にする文になり、後半の「〜ことだ」と文の形が合わなくなる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37458, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来月の大会で優勝するという目標を向けて、毎日練習している。", "corrected_sentence": "来月の大会で優勝するという目標に向けて、毎日練習している。", "error_description": "「目標に向けて」の「に」が正しい。「を」を付けると、目標を向ける対象のように読まれ、「向ける」の使い方が誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37459, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "正解。「目標からそれる」で、目当てを外れる起点を示す。"}, {"text": "の", "is_correct": false, "explanation": "「矢は目標のそれて」は、「の」で名詞を続ける形になり、「それる」の述語として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「目標がそれて」は、目標を主語にする文になり、矢がそれるという意味にならない。"}, {"text": "で", "is_correct": false, "explanation": "「目標でそれて」は、手段や場所の「で」になり、「それる」と結びつかない。"}], "correct_answer": "から", "explanations": {"から": "正解。「目標からそれる」で、目当てを外れる起点を示す。", "の": "「矢は目標のそれて」は、「の」で名詞を続ける形になり、「それる」の述語として成り立たない。", "が": "「目標がそれて」は、目標を主語にする文になり、矢がそれるという意味にならない。", "で": "「目標でそれて」は、手段や場所の「で」になり、「それる」と結びつかない。"}, "error_tags": {"から": "起点", "の": "連体（述語にならない）", "が": "主格（主語）", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37459, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「目標に道を選んだ」で、道を選ぶ目当て（目指す先）を示す。"}, {"text": "を", "is_correct": false, "explanation": "「目標を道を選んだ」は、「を」が二つ続いて文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「目標が道を選んだ」は、目標が選ぶ主体になり、お寺を目指す文脈と合わない。"}, {"text": "から", "is_correct": false, "explanation": "「目標から道を選んだ」は起点の意味になり、目当てとして選ぶ意味を表せない。"}], "correct_answer": "に", "explanations": {"に": "正解。「目標に道を選んだ」で、道を選ぶ目当て（目指す先）を示す。", "を": "「目標を道を選んだ」は、「を」が二つ続いて文が成り立たない。", "が": "「目標が道を選んだ」は、目標が選ぶ主体になり、お寺を目指す文脈と合わない。", "から": "「目標から道を選んだ」は起点の意味になり、目当てとして選ぶ意味を表せない。"}, "error_tags": {"に": "目当て・到達点", "を": "対象（二重の「を」）", "が": "主格（主語）", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37459, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "めざすこと。目的。目当て。", "primary_collocate": null, "pronunciation": "もくひょう", "ipa": "mokɯçoː", "syllable_count": 4, "sentences": [{"text": "船は遠くの灯台を目標にして、夜の海を進んだ。", "target_word": "目標", "complexity_tier": "T3", "furigana": "船[ふね]は遠[とお]くの灯台[とうだい]を目標[もくひょう]にして、夜[よる]の海[うみ]を進[すす]んだ。", "sentence_source": "generated"}, {"text": "矢は目標からそれて、後ろの木に刺さった。", "target_word": "目標", "complexity_tier": "T3", "furigana": "矢[や]は目標[もくひょう]からそれて、後[うし]ろの木[き]に刺[さ]さった。", "sentence_source": "generated"}, {"text": "山で道に迷い、目標にしていた赤い屋根を見失った。", "target_word": "目標", "complexity_tier": "T3", "furigana": "山[やま]で道[みち]に迷[まよ]い、目標[もくひょう]にしていた赤[あか]い屋根[やね]を見失[みうしな]った。", "sentence_source": "generated"}, {"text": "駅前のビルを目標に歩けば、店はすぐ見つかる。", "target_word": "目標", "complexity_tier": "T3", "furigana": "駅前[えきまえ]のビルを目標[もくひょう]に歩[ある]けば、店[みせ]はすぐ見[み]つかる。", "sentence_source": "generated"}, {"text": "選手は百メートル先の目標をねらって弓を引いた。", "target_word": "目標", "complexity_tier": "T3", "furigana": "選手[せんしゅ]は百[ひゃく]メートル先[さき]の目標[もくひょう]をねらって弓[ゆみ]を引[ひ]いた。", "sentence_source": "generated"}, {"text": "彼は日本一の料理人を目標に、毎日修業している。", "target_word": "目標", "complexity_tier": "T3", "furigana": "彼[かれ]は日本一[にほんいち]の料理人[りょうりにん]を目標[もくひょう]に、毎日[まいにち]修業[しゅぎょう]している。", "sentence_source": "generated"}, {"text": "探査機は小さな目標の近くに正確に着陸した。", "target_word": "目標", "complexity_tier": "T3", "furigana": "探査機[たんさき]は小[ちい]さな目標[もくひょう]の近[ちか]くに正確[せいかく]に着陸[ちゃくりく]した。", "sentence_source": "generated"}, {"text": "初めての旅行なので、有名なお寺を目標に道を選んだ。", "target_word": "目標", "complexity_tier": "T3", "furigana": "初[はじ]めての旅行[りょこう]なので、有名[ゆうめい]なお寺[てら]を目標[もくひょう]に道[みち]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "毎月本を三冊読むことを目標にしている。", "target_word": "目標", "complexity_tier": "T3", "furigana": "毎月[まいつき]本[ほん]を三冊[さんさつ]読[よ]むことを目標[もくひょう]にしている。", "sentence_source": "generated"}, {"text": "目標が決まらないまま、一年がむだに過ぎてしまった。", "target_word": "目標", "complexity_tier": "T3", "furigana": "目標[もくひょう]が決[き]まらないまま、一年[いちねん]がむだに過[す]ぎてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "目標", "label": "基本形"}, {"form": "目標の", "label": "連体形"}, {"form": "目標に", "label": "目当て形"}], "register": "neutral", "sense_fingerprint": "行動や視線の目当てとなる、めざす対象や印", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aaf6791-139f-41e3-8c71-ba48b836c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37459, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目標", "is_correct": true, "explanation": "正解。「灯台を目標にして」で、船が進む際のめあてとなる対象を示す。"}, {"text": "汽笛", "is_correct": false, "explanation": "「灯台を汽笛にして」は、灯台を音を出す道具にする意味になり、進む先の目当てとして合わない。"}, {"text": "甲板", "is_correct": false, "explanation": "「灯台を甲板にして」は、灯台を船の床にする意味になり、文として通らない。"}, {"text": "錨", "is_correct": false, "explanation": "「灯台を錨にして」は、灯台を船を止める道具にする意味になり、進むめあての文脈に合わない。"}], "explanations": {"目標": "正解。「灯台を目標にして」で、船が進む際のめあてとなる対象を示す。", "汽笛": "「灯台を汽笛にして」は、灯台を音を出す道具にする意味になり、進む先の目当てとして合わない。", "甲板": "「灯台を甲板にして」は、灯台を船の床にする意味になり、文として通らない。", "錨": "「灯台を錨にして」は、灯台を船を止める道具にする意味になり、進むめあての文脈に合わない。"}, "sentence_index": 0, "correct_answer": "目標"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "交差点の目標に従って、右へ曲がった。", "explanation": "ここは〈標識〉の意味。道を示す札や看板を指す語で、目標は目指す対象なので、従うものとしては使わない。"}, {"text": "海岸に目標が立っていて、風にはためいている。", "explanation": "ここは〈旗〉の意味。風にはためくものは旗であり、目標は目当てとなる対象で、はためく物を指さない。"}, {"text": "船長は目標を広げて、航路を確かめた。", "explanation": "ここは〈地図〉の意味。広げて確かめるのは地図であり、目標は広げて見る物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37459, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目標", "is_correct": true, "explanation": "正解。「小さな目標の近くに着陸した」で、着陸のめあてとなる地点を示す。"}, {"text": "電波", "is_correct": false, "explanation": "「小さな電波の近くに着陸した」は、電波の近くに降りる意味になり、着陸の地点としては合わない。"}, {"text": "大気", "is_correct": false, "explanation": "「小さな大気の近くに着陸した」は、空気の近くに降りる意味になり、着陸地点の説明として通らない。"}, {"text": "重力", "is_correct": false, "explanation": "「小さな重力の近くに着陸した」は、力の近くに降りる意味になり、地点を示す文として成り立たない。"}], "explanations": {"目標": "正解。「小さな目標の近くに着陸した」で、着陸のめあてとなる地点を示す。", "電波": "「小さな電波の近くに着陸した」は、電波の近くに降りる意味になり、着陸の地点としては合わない。", "大気": "「小さな大気の近くに着陸した」は、空気の近くに降りる意味になり、着陸地点の説明として通らない。", "重力": "「小さな重力の近くに着陸した」は、力の近くに降りる意味になり、地点を示す文として成り立たない。"}, "sentence_index": 6, "correct_answer": "目標"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "船は目標を東にとって、ここから沖へ出た。", "explanation": "ここは〈方位〉の意味。東にとるのは方位で、目標は目指す先を表す語なので合わない。"}, {"text": "船の目標が重すぎて、港まで運べなかった。", "explanation": "ここは〈荷物〉の意味。重さのある物を指す語で、目当ての対象である目標には重さの話をしない。"}, {"text": "目標が晴れて、海が穏やかになった。", "explanation": "ここは〈空模様〉の意味。晴れるのは空の様子で、目標は目指す先を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37459, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "漁師は夜明けに、港の灯りを目標で船を出す。", "corrected_sentence": "漁師は夜明けに、港の灯りを目標にして船を出す。", "error_description": "「目標にして」の「に」が正しい。「で」にすると、目標を手段として使う意味になり、「にして」の形が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37459, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ボールの落ちた地点を目標が、矢を放った。", "corrected_sentence": "ボールの落ちた地点を目標にして、矢を放った。", "error_description": "「目標にして」の「に」が正しい。「が」にすると、目標が主語になり、「放った」の主語の関係が崩れて文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37460, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「会社に向かった」で、向かう先を示す。文中の「会社」に直接付く。"}, {"text": "を", "is_correct": false, "explanation": "「会社を向かった」は、会社を目的語にする形になり、向かうの使い方として不自然。"}, {"text": "が", "is_correct": false, "explanation": "「会社が向かった」は、会社が主語になり、人が向かうという意味にならない。"}, {"text": "の", "is_correct": false, "explanation": "「会社の向かった」は連体の形になり、文の中で動詞の述語として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "正解。「会社に向かった」で、向かう先を示す。文中の「会社」に直接付く。", "を": "「会社を向かった」は、会社を目的語にする形になり、向かうの使い方として不自然。", "が": "「会社が向かった」は、会社が主語になり、人が向かうという意味にならない。", "の": "「会社の向かった」は連体の形になり、文の中で動詞の述語として成り立たない。"}, "error_tags": {"に": "方向・到達点", "を": "対象（目的語）", "が": "主格（主語）", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37460, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「飼い主に向かって」で、向かう相手を示す。文中の「飼い主」に直接付く。"}, {"text": "と", "is_correct": false, "explanation": "「飼い主と向かって」は、一緒に向かう意味になり、相手を目指す動きを表せない。"}, {"text": "から", "is_correct": false, "explanation": "「飼い主から向かって」は起点の意味になり、飼い主へ走る動きと逆になる。"}, {"text": "より", "is_correct": false, "explanation": "「飼い主より向かって」は比較の意味になり、向かう先を示す文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "正解。「飼い主に向かって」で、向かう相手を示す。文中の「飼い主」に直接付く。", "と": "「飼い主と向かって」は、一緒に向かう意味になり、相手を目指す動きを表せない。", "から": "「飼い主から向かって」は起点の意味になり、飼い主へ走る動きと逆になる。", "より": "「飼い主より向かって」は比較の意味になり、向かう先を示す文として成り立たない。"}, "error_tags": {"に": "方向・相手", "と": "共同", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37460, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所や人に向けて進むこと。", "primary_collocate": null, "pronunciation": "むかう", "ipa": "mɯkaɯ", "syllable_count": 3, "sentences": [{"text": "朝八時に家を出て、駅に向かいます。", "target_word": "向かいます", "complexity_tier": "T2", "furigana": "朝[あさ]八時[はちじ]に家[いえ]を出[で]て、駅[えき]に向[む]かいます。", "sentence_source": "generated"}, {"text": "電車が遅れたので、急いで会社に向かった。", "target_word": "向かった", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が遅[おく]れたので、急[いそ]いで会社[かいしゃ]に向[む]かった。", "sentence_source": "generated"}, {"text": "先生に呼ばれたので、職員室に向かいました。", "target_word": "向かいました", "complexity_tier": "T3", "furigana": "先生[せんせい]に呼[よ]ばれたので、職員室[しょくいんしつ]に向[む]かいました。", "sentence_source": "generated"}, {"text": "雨が降ってきたので、近くのコンビニに向かって走った。", "target_word": "向かって", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ってきたので、近[ちか]くのコンビニに向[む]かって走[はし]った。", "sentence_source": "generated"}, {"text": "彼は財布を忘れたことに気づき、すぐ家に向かった。", "target_word": "向かった", "complexity_tier": "T3", "furigana": "彼[かれ]は財布[さいふ]を忘[わす]れたことに気[き]づき、すぐ家[いえ]に向[む]かった。", "sentence_source": "generated"}, {"text": "母は病院に向かう途中で、友だちに会った。", "target_word": "向かう", "complexity_tier": "T3", "furigana": "母[はは]は病院[びょういん]に向[む]かう途中[とちゅう]で、友[とも]だちに会[あ]った。", "sentence_source": "generated"}, {"text": "空港に向かうバスは、十分おきに出ています。", "target_word": "向かう", "complexity_tier": "T3", "furigana": "空港[くうこう]に向[む]かうバスは、十分[じゅっぷん]おきに出[で]ています。", "sentence_source": "generated"}, {"text": "犬は飼い主に向かって、うれしそうに走ってきた。", "target_word": "向かって", "complexity_tier": "T3", "furigana": "犬[いぬ]は飼[か]い主[ぬし]に向[む]かって、うれしそうに走[はし]ってきた。", "sentence_source": "generated"}, {"text": "道に迷ったが、地図を見て約束の店に向かうことができた。", "target_word": "向かう", "complexity_tier": "T4", "furigana": "道[みち]に迷[まよ]ったが、地図[ちず]を見[み]て約束[やくそく]の店[みせ]に向[む]かうことができた。", "sentence_source": "generated"}, {"text": "私が部屋に入ると、彼女は私のほうに向かって歩いてきた。", "target_word": "向かって", "complexity_tier": "T4", "furigana": "私[わたし]が部屋[へや]に入[はい]ると、彼女[かのじょ]は私[わたし]のほうに向[む]かって歩[ある]いてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "向かう", "label": "辞書形"}, {"form": "向かいます", "label": "丁寧形"}, {"form": "向かわない", "label": "否定形"}, {"form": "向かって", "label": "て形"}, {"form": "向かった", "label": "た形"}, {"form": "向かえば", "label": "仮定形"}, {"form": "向かおう", "label": "意志形"}], "register": "標準・中立", "sense_fingerprint": "ある場所や人のほうへ体を動かして進む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aaf6791-139f-41e3-8c71-ba48b836c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37460, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "向かいます", "is_correct": true, "explanation": "正解。「家を出て、駅に向かいます」で、丁寧な文末として自然に入る。"}, {"text": "向かって", "is_correct": false, "explanation": "「駅に向かって。」で文が終わると、文として不完全になる。"}, {"text": "向かえ", "is_correct": false, "explanation": "命令形なので、丁寧に出発を述べる文には入らない。"}, {"text": "向かえば", "is_correct": false, "explanation": "条件の形なので、文末に置くと続きがなく、文として成り立たない。"}], "explanations": {"向かいます": "正解。「家を出て、駅に向かいます」で、丁寧な文末として自然に入る。", "向かって": "「駅に向かって。」で文が終わると、文として不完全になる。", "向かえ": "命令形なので、丁寧に出発を述べる文には入らない。", "向かえば": "条件の形なので、文末に置くと続きがなく、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "向かいます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "犬は窓の光に向かって、後ろへ下がった。", "explanation": "ここは〈後退〉の意味。退くのは後退で、向かうは前へ進むことなので合わない。"}, {"text": "犬は怖がって、飼い主から離れるように向かった。", "explanation": "ここは〈逃げる〉の意味。怖がって遠ざかるのは逃げるで、向かうは進む先へ近づく語なので合わない。"}, {"text": "電車は駅から遠ざかって、ゆっくり走った。", "explanation": "ここは〈遠ざかる〉の意味。遠ざかるのは離れていく動きで、向かうは近づいていく動きなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37460, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向かう", "is_correct": true, "explanation": "正解。「空港に向かうバス」で、空港へ行くバスを修飾する形として自然。"}, {"text": "向かおう", "is_correct": false, "explanation": "意志の形なので、名詞を修飾する形として入らない。"}, {"text": "向かいます", "is_correct": false, "explanation": "丁寧形は名詞を直接修飾できず、「空港に向かいますバス」は不自然。"}, {"text": "向かわせ", "is_correct": false, "explanation": "使役の形なので、バスが空港へ向かう意味にならず、文として成り立たない。"}], "explanations": {"向かう": "正解。「空港に向かうバス」で、空港へ行くバスを修飾する形として自然。", "向かおう": "意志の形なので、名詞を修飾する形として入らない。", "向かいます": "丁寧形は名詞を直接修飾できず、「空港に向かいますバス」は不自然。", "向かわせ": "使役の形なので、バスが空港へ向かう意味にならず、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "向かう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私が部屋に入ると、彼女は私のほうを避けるように向かって歩いてきた。", "explanation": "ここは〈離れていく〉の意味。近づく方向を指す向かうは、離れていく動きとは逆なので合わない。"}, {"text": "私が部屋に入ると、彼女は私のほうに向かって目をそらした。", "explanation": "ここは〈背を向ける〉の意味。背を向ける動きは相手へ近づく向かうとは逆なので合わない。"}, {"text": "私が部屋に入ると、彼女は私のほうに向かって歩き去った。", "explanation": "ここは〈遠ざかる〉の意味。近づく動きを表す向かうは、遠ざかって離れる動きとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37460, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は、大学の受験を向かって毎日勉強している。", "corrected_sentence": "妹は、大学の受験に向かって毎日勉強している。", "error_description": "「向かって」の前には「に」が必要。「を」にすると、受験を目的語にする形になり、「向かって」と結びつかない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "向かった", "is_correct": true, "explanation": "正解。「会社に向かった」で、過去の出来事として文末に入る。"}, {"text": "向かって", "is_correct": false, "explanation": "「会社に向かって」で止まると、文が完結しない。"}, {"text": "向かえば", "is_correct": false, "explanation": "条件の形なので、文末に置くと意味が成り立たない。"}, {"text": "向かおう", "is_correct": false, "explanation": "意志の形なので、過去の出来事を述べる文には合わない。"}], "correct_form": "向かった", "base_form": "向かう", "form_label": "た形", "sentence_index": 1, "explanations": {"向かった": "正解。「会社に向かった」で、過去の出来事として文末に入る。", "向かって": "「会社に向かって」で止まると、文が完結しない。", "向かえば": "条件の形なので、文末に置くと意味が成り立たない。", "向かおう": "意志の形なので、過去の出来事を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37460, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日の大会に向かう、毎朝走る練習をしている。", "corrected_sentence": "明日の大会に向かって、毎朝走る練習をしている。", "error_description": "「向かって」が正しい連用形。「向かう、」と辞書形で止めると、後ろの文と正しく続かず、文の接続が崩れる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "向かって", "is_correct": true, "explanation": "正解。「飼い主に向かって、走ってきた」で、相手の方へ進む動作を述べる連用形。"}, {"text": "向かいます", "is_correct": false, "explanation": "丁寧形なので、「〜て、走ってきた」と続けると文として不自然。"}, {"text": "向かわない", "is_correct": false, "explanation": "否定形なので、飼い主へ向かったという内容と反対になり、文の流れに合わない。"}, {"text": "向かえ", "is_correct": false, "explanation": "命令形なので、犬の動作を述べる文には入らない。"}], "correct_form": "向かって", "base_form": "向かう", "form_label": "て形", "sentence_index": 7, "explanations": {"向かって": "正解。「飼い主に向かって、走ってきた」で、相手の方へ進む動作を述べる連用形。", "向かいます": "丁寧形なので、「〜て、走ってきた」と続けると文として不自然。", "向かわない": "否定形なので、飼い主へ向かったという内容と反対になり、文の流れに合わない。", "向かえ": "命令形なので、犬の動作を述べる文には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37461, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「北に向かって」で、進む方向を示す。文中の「北」に直接付く。"}, {"text": "を", "is_correct": false, "explanation": "「北を向かって」は、北を目的語にする形になり、方向を示す文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「北が向かって」は、北が主語になり、台風が進む文として意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「北で向かって」は、場所や手段の「で」になり、進む方向を示す形として合わない。"}], "correct_answer": "に", "explanations": {"に": "正解。「北に向かって」で、進む方向を示す。文中の「北」に直接付く。", "を": "「北を向かって」は、北を目的語にする形になり、方向を示す文として成り立たない。", "が": "「北が向かって」は、北が主語になり、台風が進む文として意味が通らない。", "で": "「北で向かって」は、場所や手段の「で」になり、進む方向を示す形として合わない。"}, "error_tags": {"に": "方向", "を": "対象（目的語）", "が": "主格（主語）", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37461, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「目的地に向かって」で、向かう先を示す。文中の「目的地」に直接付く。"}, {"text": "と", "is_correct": false, "explanation": "「目的地と向かって」は、目的地と一緒に進む意味になり、行き先を示す文として合わない。"}, {"text": "から", "is_correct": false, "explanation": "「目的地から向かって」は起点の意味になり、目的地へ向かう動きと逆になる。"}, {"text": "より", "is_correct": false, "explanation": "「目的地より向かって」は比較の意味になり、行き先を示す文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "正解。「目的地に向かって」で、向かう先を示す。文中の「目的地」に直接付く。", "と": "「目的地と向かって」は、目的地と一緒に進む意味になり、行き先を示す文として合わない。", "から": "「目的地から向かって」は起点の意味になり、目的地へ向かう動きと逆になる。", "より": "「目的地より向かって」は比較の意味になり、行き先を示す文として成り立たない。"}, "error_tags": {"に": "方向・到達点", "と": "共同", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37461, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "目標や目的地に向けて進むこと。また、ある方向へ動くこと。", "primary_collocate": null, "pronunciation": "むかう", "ipa": "mɯkaɯ", "syllable_count": 3, "sentences": [{"text": "選手たちは優勝に向かって、毎日練習している。", "target_word": "向かって", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは優勝[ゆうしょう]に向[む]かって、毎日[まいにち]練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "台風は北に向かって、ゆっくり進んでいる。", "target_word": "向かって", "complexity_tier": "T3", "furigana": "台風[たいふう]は北[きた]に向[む]かって、ゆっくり進[すす]んでいる。", "sentence_source": "generated"}, {"text": "登山者は頂上に向かって、一歩ずつ登った。", "target_word": "向かって", "complexity_tier": "T3", "furigana": "登山者[とざんしゃ]は頂上[ちょうじょう]に向[む]かって、一歩[いっぽ]ずつ登[のぼ]った。", "sentence_source": "generated"}, {"text": "病気は少しずつ快方に向かっている。", "target_word": "向かっている", "complexity_tier": "T3", "furigana": "病気[びょうき]は少[すこ]しずつ快方[かいほう]に向[む]かっている。", "sentence_source": "generated"}, {"text": "来月の試験に向かって、毎晩勉強しています。", "target_word": "向かって", "complexity_tier": "T3", "furigana": "来月[らいげつ]の試験[しけん]に向[む]かって、毎晩[まいばん]勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "鳥の群れが南に向かって飛んでいった。", "target_word": "向かって", "complexity_tier": "T2", "furigana": "鳥[とり]の群[む]れが南[みなみ]に向[む]かって飛[と]んでいった。", "sentence_source": "generated"}, {"text": "会議は、結論に向かって進み始めた。", "target_word": "向かって", "complexity_tier": "T3", "furigana": "会議[かいぎ]は、結論[けつろん]に向[む]かって進[すす]み始[はじ]めた。", "sentence_source": "generated"}, {"text": "船は目的地に向かって、静かに港を出た。", "target_word": "向かって", "complexity_tier": "T3", "furigana": "船[ふね]は目的地[もくてきち]に向[む]かって、静[しず]かに港[みなと]を出[で]た。", "sentence_source": "generated"}, {"text": "彼は大きな目標に向かう力を持っている。", "target_word": "向かう", "complexity_tier": "T3", "furigana": "彼[かれ]は大[おお]きな目標[もくひょう]に向[む]かう力[ちから]を持[も]っている。", "sentence_source": "generated"}, {"text": "景気は回復に向かうと言われている。", "target_word": "向かう", "complexity_tier": "T4", "furigana": "景気[けいき]は回復[かいふく]に向[む]かうと言[い]われている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "向かう", "label": "辞書形"}, {"form": "向かいます", "label": "丁寧形"}, {"form": "向かわない", "label": "否定形"}, {"form": "向かって", "label": "て形"}, {"form": "向かった", "label": "た形"}, {"form": "向かえば", "label": "仮定形"}, {"form": "向かおう", "label": "意志形"}], "register": "標準・中立", "sense_fingerprint": "目標や目的地、ある方向や状態へ進んでいく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aaf6791-139f-41e3-8c71-ba48b836c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37461, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "向かって", "is_correct": true, "explanation": "正解。「優勝に向かって、毎日練習している」で、目標へ進む努力を表す連用形。"}, {"text": "向かえ", "is_correct": false, "explanation": "命令形なので、「毎日練習している」と続く説明文には入らない。"}, {"text": "向かおう", "is_correct": false, "explanation": "意志の形なので、現在続けている練習の説明とは合わない。"}, {"text": "向かいます", "is_correct": false, "explanation": "丁寧形は「〜います」と続かず、「優勝に向かいます、毎日練習している」は不自然。"}], "explanations": {"向かって": "正解。「優勝に向かって、毎日練習している」で、目標へ進む努力を表す連用形。", "向かえ": "命令形なので、「毎日練習している」と続く説明文には入らない。", "向かおう": "意志の形なので、現在続けている練習の説明とは合わない。", "向かいます": "丁寧形は「〜います」と続かず、「優勝に向かいます、毎日練習している」は不自然。"}, "sentence_index": 0, "correct_answer": "向かって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風は北に向かって、いったん後ろへ下がった。", "explanation": "ここは〈後退〉の意味。退くのは後退で、向かうは前へ進む動きなので合わない。"}, {"text": "会議は結論に向かって、すぐ引き返した。", "explanation": "ここは〈引き返す〉の意味。元へ戻るのは引き返すで、向かうは先へ進む動きなので合わない。"}, {"text": "その話は笑いに向かって、みんなが静かに後ずさりした。", "explanation": "ここは〈後ずさり〉の意味。後ろへ下がるのは後ずさりで、向かうは進む先へ動く語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37461, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向かって", "is_correct": true, "explanation": "正解。「結論に向かって、進み始めた」で、会議が目指す先へ進む様子を表す。"}, {"text": "向かえる", "is_correct": false, "explanation": "可能の形なので、「結論に向かえる、進み始めた」は文として続かず不自然。"}, {"text": "向かわせ", "is_correct": false, "explanation": "使役の形なので、会議を向かわせる意味になり、会議自身が進む文と合わない。"}, {"text": "向かいそう", "is_correct": false, "explanation": "様態の形なので、「向かいそう、進み始めた」と続けると、意味が成り立たない。"}], "explanations": {"向かって": "正解。「結論に向かって、進み始めた」で、会議が目指す先へ進む様子を表す。", "向かえる": "可能の形なので、「結論に向かえる、進み始めた」は文として続かず不自然。", "向かわせ": "使役の形なので、会議を向かわせる意味になり、会議自身が進む文と合わない。", "向かいそう": "様態の形なので、「向かいそう、進み始めた」と続けると、意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "向かって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "景気は回復に向かって、一晩で消えたと言われている。", "explanation": "ここは〈消滅〉の意味。消えるのは消滅で、向かうは進む先を指す語なので、回復の方向とは合わない。"}, {"text": "景気は回復に向かって、真っ逆さまに落ちている。", "explanation": "ここは〈下降〉の意味。落ちるのは下降で、向かうは進む先へ動く語なので、回復の方向とは矛盾する。"}, {"text": "景気は回復に向かって、会議室の鍵を閉めた。", "explanation": "ここは〈施錠〉の意味。鍵を閉めるのは施錠で、向かうは進む先を指す語なので、景気の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37461, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新製品の発売を向かって、準備を進めている。", "corrected_sentence": "新製品の発売に向かって、準備を進めている。", "error_description": "「向かって」の前には「に」が必要。「を」にすると、発売を目的語にする形になり、向かう先を示せない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "向かって", "is_correct": true, "explanation": "正解。「北に向かって、ゆっくり進んでいる」で、台風の進む方向を示す連用形。"}, {"text": "向かいます", "is_correct": false, "explanation": "丁寧形なので、「北に向かいます、ゆっくり進んでいる」と続けると不自然。"}, {"text": "向かえ", "is_correct": false, "explanation": "命令形なので、台風の動きを説明する文には入らない。"}, {"text": "向かわない", "is_correct": false, "explanation": "否定形なので、北へ進んでいるという文の内容と反対になる。"}], "correct_form": "向かって", "base_form": "向かう", "form_label": "て形", "sentence_index": 1, "explanations": {"向かって": "正解。「北に向かって、ゆっくり進んでいる」で、台風の進む方向を示す連用形。", "向かいます": "丁寧形なので、「北に向かいます、ゆっくり進んでいる」と続けると不自然。", "向かえ": "命令形なので、台風の動きを説明する文には入らない。", "向かわない": "否定形なので、北へ進んでいるという文の内容と反対になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37461, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来春の開店に向かう、店の準備を進めている。", "corrected_sentence": "来春の開店に向かって、店の準備を進めている。", "error_description": "「向かって」が正しい連用形。「向かう、」と辞書形で止めると、後ろの文と正しく続かず、文の接続が崩れる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "向かって", "is_correct": true, "explanation": "正解。「目的地に向かって、静かに港を出た」で、目的地へ進む動きを表す連用形。"}, {"text": "向かえば", "is_correct": false, "explanation": "条件の形なので、「目的地に向かえば、静かに港を出た」と続けると意味が合わない。"}, {"text": "向かわず", "is_correct": false, "explanation": "否定の連用形なので、目的地へ向かわないという意味になり、船の動きと矛盾する。"}, {"text": "向かえる", "is_correct": false, "explanation": "可能の形なので、船の動きの説明としては不自然で、文の流れに合わない。"}], "correct_form": "向かって", "base_form": "向かう", "form_label": "て形", "sentence_index": 7, "explanations": {"向かって": "正解。「目的地に向かって、静かに港を出た」で、目的地へ進む動きを表す連用形。", "向かえば": "条件の形なので、「目的地に向かえば、静かに港を出た」と続けると意味が合わない。", "向かわず": "否定の連用形なので、目的地へ向かわないという意味になり、船の動きと矛盾する。", "向かえる": "可能の形なので、船の動きの説明としては不自然で、文の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37462, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「大きな組織で、広報の仕事をしている」の「で」は、仕事をする場所を示す。ここに入るのが正しい。"}, {"text": "を", "is_correct": false, "explanation": "「大きな組織を、広報の仕事をしている」は不自然。「を」は目的語を示すが、ここは場所を述べる文。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、働く場所を表す文脈には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「働く場所」の意味にはならず合わない。"}], "correct_answer": "で", "explanations": {"で": "「大きな組織で、広報の仕事をしている」の「で」は、仕事をする場所を示す。ここに入るのが正しい。", "を": "「大きな組織を、広報の仕事をしている」は不自然。「を」は目的語を示すが、ここは場所を述べる文。", "へ": "「へ」は方向を示すので、働く場所を表す文脈には合わない。", "から": "「から」は起点を示すので、「働く場所」の意味にはならず合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37462, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「その組織は」の「は」は主題を示す。文の主語を示すので、ここに入るのが正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、作られたものの動作主を表す文脈には合わない。"}, {"text": "を", "is_correct": false, "explanation": "「組織を作られた」は不自然。「作られた」の目的語にはならないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、ここでは比べる文脈がなく合わない。"}], "correct_answer": "は", "explanations": {"は": "「その組織は」の「は」は主題を示す。文の主語を示すので、ここに入るのが正しい。", "へ": "「へ」は方向を示すので、作られたものの動作主を表す文脈には合わない。", "を": "「組織を作られた」は不自然。「作られた」の目的語にはならないので合わない。", "より": "「より」は比較を示すので、ここでは比べる文脈がなく合わない。"}, "error_tags": {"へ": "方向", "を": "目的語", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37462, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が集まって、一緒に何かをするまとまりのことです。", "primary_collocate": null, "pronunciation": "そしき", "ipa": "soɕiki", "syllable_count": 3, "sentences": [{"text": "この組織には、百人の人が働いています。", "target_word": "組織", "complexity_tier": "T2", "furigana": "この組織[そしき]には、百人[ひゃくにん]の人[ひと]が働[はたら]いています。", "sentence_source": "generated"}, {"text": "彼は大きな組織で、広報の仕事をしています。", "target_word": "組織", "complexity_tier": "T3", "furigana": "彼[かれ]は大[おお]きな組織[そしき]で、広報[こうほう]の仕事[しごと]をしています。", "sentence_source": "generated"}, {"text": "地域の人たちが集まって、新しい組織を作った。", "target_word": "組織", "complexity_tier": "T3", "furigana": "地域[ちいき]の人[ひと]たちが集[あつ]まって、新[あたら]しい組織[そしき]を作[つく]った。", "sentence_source": "generated"}, {"text": "組織のみんなで協力して、イベントを成功させた。", "target_word": "組織", "complexity_tier": "T3", "furigana": "組織[そしき]のみんなで協力[きょうりょく]して、イベントを成功[せいこう]させた。", "sentence_source": "generated"}, {"text": "小さな組織だが、メンバーの仲はとてもいい。", "target_word": "組織", "complexity_tier": "T3", "furigana": "小[ちい]さな組織[そしき]だが、メンバーの仲[なか]はとてもいい。", "sentence_source": "generated"}, {"text": "兄は環境を守る組織に入っている。", "target_word": "組織", "complexity_tier": "T3", "furigana": "兄[あに]は環境[かんきょう]を守[まも]る組織[そしき]に入[はい]っている。", "sentence_source": "generated"}, {"text": "組織の中では、ルールを守ることが大切だ。", "target_word": "組織", "complexity_tier": "T3", "furigana": "組織[そしき]の中[なか]では、ルールを守[まも]ることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "その組織は、困っている人を助けるために作られた。", "target_word": "組織", "complexity_tier": "T3", "furigana": "その組織[そしき]は、困[こま]っている人[ひと]を助[たす]けるために作[つく]られた。", "sentence_source": "generated"}, {"text": "大きな組織ほど、意見をまとめるのに時間がかかる。", "target_word": "組織", "complexity_tier": "T4", "furigana": "大[おお]きな組織[そしき]ほど、意見[いけん]をまとめるのに時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "町の清掃をする組織に、私も参加したい。", "target_word": "組織", "complexity_tier": "T3", "furigana": "町[まち]の清掃[せいそう]をする組織[そしき]に、私[わたし]も参加[さんか]したい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組織", "label": "基本形"}], "register": "標準・中立", "sense_fingerprint": "一緒に活動する人たちのまとまり、グループ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aaf6791-139f-41e3-8c71-ba48b836c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37462, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組織", "is_correct": true, "explanation": "「この組織には百人の人が働く」の〈組織〉は、人が集まって活動する団体を指し、「には」で働く場所を示す。ここに入るのが正しい。"}, {"text": "制度", "is_correct": false, "explanation": "〈制度〉は決まりごとの仕組みで、そこに人が働くとは言わないので合わない。"}, {"text": "方針", "is_correct": false, "explanation": "〈方針〉は進め方の考えを表し、働く人が所属する場所にはならないので合わない。"}, {"text": "目的", "is_correct": false, "explanation": "〈目的〉は到達したいことで、人が働く場所ではないので合わない。"}], "explanations": {"組織": "「この組織には百人の人が働く」の〈組織〉は、人が集まって活動する団体を指し、「には」で働く場所を示す。ここに入るのが正しい。", "制度": "〈制度〉は決まりごとの仕組みで、そこに人が働くとは言わないので合わない。", "方針": "〈方針〉は進め方の考えを表し、働く人が所属する場所にはならないので合わない。", "目的": "〈目的〉は到達したいことで、人が働く場所ではないので合わない。"}, "sentence_index": 0, "correct_answer": "組織"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅前は組織があふれて、なかなか前に進めなかった。", "explanation": "ここは〈人混み〉の意味。組織は目的をもつ団体を指すので、大勢の人がいる混雑には使わず、〈人混み〉と言う。"}, {"text": "この筋肉の組織が、けがで傷ついた。", "explanation": "ここは〈体の組織〉の意味。人が集まってできた団体の意味ではないので、教える義項とは合わない。"}, {"text": "この機械の組織が壊れて、動かなくなった。", "explanation": "ここは〈機構〉の意味。組織は人の集まりを指すので、機械の内部の仕組みには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37462, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組織", "is_correct": true, "explanation": "「組織の中ではルールを守る」の〈組織〉は、そこで決まりに従う団体のこと。ここに入るのが正しい。"}, {"text": "日程", "is_correct": false, "explanation": "〈日程〉は予定の順序で、ルールを守る場所にはならないので合わない。"}, {"text": "規模", "is_correct": false, "explanation": "〈規模〉は大きさを表し、ルールを守る場の意味にはならないので合わない。"}, {"text": "予算", "is_correct": false, "explanation": "〈予算〉は使えるお金の計画で、「中でルールを守る」とは言わないので合わない。"}], "explanations": {"組織": "「組織の中ではルールを守る」の〈組織〉は、そこで決まりに従う団体のこと。ここに入るのが正しい。", "日程": "〈日程〉は予定の順序で、ルールを守る場所にはならないので合わない。", "規模": "〈規模〉は大きさを表し、ルールを守る場の意味にはならないので合わない。", "予算": "〈予算〉は使えるお金の計画で、「中でルールを守る」とは言わないので合わない。"}, "sentence_index": 6, "correct_answer": "組織"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この論文は、読者の組織が多くて、読みやすい。", "explanation": "ここは〈読者の団体〉の意味。組織は論文の組み立てや目的をもつ団体を指すので、読者の集まりを表す使い方には合わない。"}, {"text": "子どもの頃からの友達の組織が、今も続いている。", "explanation": "ここは〈つながり・輪〉の意味。組織は目的をもつ団体なので、気の合う友達どうしの関係には合わない。"}, {"text": "この鉄の組織を顕微鏡で調べた。", "explanation": "ここは〈材料の内部構造〉の意味。人が集まる団体の意味ではないので、この義項とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37462, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その組織を入って、三年になります。", "corrected_sentence": "その組織に入って、三年になります。", "error_description": "「組織に入る」は「に」で入る先を示す。「を」にすると「入る」の目的語になり、不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37462, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この組織入ると、毎月会費を払う必要がある。", "corrected_sentence": "この組織に入ると、毎月会費を払う必要がある。", "error_description": "「入る」は入る先を「に」で示すが、「に」が抜けた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37463, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「組織を変える」の「を」は変える対象を示す。ここに入るのが正しい。"}, {"text": "が", "is_correct": false, "explanation": "「組織が変えて」は不自然。「変える」は対象を「を」で受ける動詞なので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「組織より変えて」は比較の「より」となり、変える対象を示せず成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「組織で変える」は手段・場所を示すが、変える対象を示す文脈には合わない。"}], "correct_answer": "を", "explanations": {"を": "「組織を変える」の「を」は変える対象を示す。ここに入るのが正しい。", "が": "「組織が変えて」は不自然。「変える」は対象を「を」で受ける動詞なので合わない。", "より": "「組織より変えて」は比較の「より」となり、変える対象を示せず成り立たない。", "で": "「組織で変える」は手段・場所を示すが、変える対象を示す文脈には合わない。"}, "error_tags": {"が": "主語", "より": "比較", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37463, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「学校の組織は」の「は」は主題を示す。文の主語を示すので、ここに入るのが正しい。"}, {"text": "を", "is_correct": false, "explanation": "「組織を分かれている」は不自然。「分かれる」は目的語をとらないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「組織の、」は名詞が続かず、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「分かれている」の文脈には合わない。"}], "correct_answer": "は", "explanations": {"は": "「学校の組織は」の「は」は主題を示す。文の主語を示すので、ここに入るのが正しい。", "を": "「組織を分かれている」は不自然。「分かれる」は目的語をとらないので合わない。", "の": "「組織の、」は名詞が続かず、文として成り立たない。", "へ": "「へ」は方向を示すので、「分かれている」の文脈には合わない。"}, "error_tags": {"を": "目的語", "の": "連体", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37463, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "共通の目的や活動のために人々が集まってできた集団、またはその仕組み。", "primary_collocate": null, "pronunciation": "そしき", "ipa": "soɕiki", "syllable_count": 3, "sentences": [{"text": "国際的な組織が、災害の被害を調べている。", "target_word": "組織", "complexity_tier": "T4", "furigana": "国際的[こくさいてき]な組織[そしき]が、災害[さいがい]の被害[ひがい]を調[しら]べている。", "sentence_source": "generated"}, {"text": "会社の組織を変えて、新しい部署を作った。", "target_word": "組織", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の組織[そしき]を変[か]えて、新[あたら]しい部署[ぶしょ]を作[つく]った。", "sentence_source": "generated"}, {"text": "この組織は、研究を進めるために設立された。", "target_word": "組織", "complexity_tier": "T4", "furigana": "この組織[そしき]は、研究[けんきゅう]を進[すす]めるために設立[せつりつ]された。", "sentence_source": "generated"}, {"text": "組織の仕組みが複雑で、決定が遅れている。", "target_word": "組織", "complexity_tier": "T4", "furigana": "組織[そしき]の仕組[しく]みが複雑[ふくざつ]で、決定[けってい]が遅[おく]れている。", "sentence_source": "generated"}, {"text": "警察は、その組織の活動を調べている。", "target_word": "組織", "complexity_tier": "T3", "furigana": "警察[けいさつ]は、その組織[そしき]の活動[かつどう]を調[しら]べている。", "sentence_source": "generated"}, {"text": "非営利の組織として、地域の教育を支えている。", "target_word": "組織", "complexity_tier": "T4", "furigana": "非営利[ひえいり]の組織[そしき]として、地域[ちいき]の教育[きょういく]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "組織の目的をはっきりさせてから、活動を始めよう。", "target_word": "組織", "complexity_tier": "T4", "furigana": "組織[そしき]の目的[もくてき]をはっきりさせてから、活動[かつどう]を始[はじ]めよう。", "sentence_source": "generated"}, {"text": "学校の組織は、校長、教師、事務員などに分かれている。", "target_word": "組織", "complexity_tier": "T4", "furigana": "学校[がっこう]の組織[そしき]は、校長[こうちょう]、教師[きょうし]、事務員[じむいん]などに分[わ]かれている。", "sentence_source": "generated"}, {"text": "世界各地の組織が協力して、森を守っている。", "target_word": "組織", "complexity_tier": "T3", "furigana": "世界[せかい]各地[かくち]の組織[そしき]が協力[きょうりょく]して、森[もり]を守[まも]っている。", "sentence_source": "generated"}, {"text": "組織の運営には、お金も人も必要だ。", "target_word": "組織", "complexity_tier": "T3", "furigana": "組織[そしき]の運営[うんえい]には、お金[かね]も人[ひと]も必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組織", "label": "基本形"}], "register": "標準・やや硬い", "sense_fingerprint": "目的を持つ団体、およびその内部の構成や仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aaf6791-139f-41e3-8c71-ba48b836c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37463, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組織", "is_correct": true, "explanation": "「国際的な組織が調べている」の主語は、目的をもつ団体を指す〈組織〉。ここに入るのが正しい。"}, {"text": "制度", "is_correct": false, "explanation": "〈制度〉は決まりの仕組みで、被害を調べる主体にはならないので合わない。"}, {"text": "方針", "is_correct": false, "explanation": "〈方針〉は考えや進め方で、調べるという動作の主体にはならないので合わない。"}, {"text": "目的", "is_correct": false, "explanation": "〈目的〉は到達したいことで、被害を調べる主語にはならないので合わない。"}], "explanations": {"組織": "「国際的な組織が調べている」の主語は、目的をもつ団体を指す〈組織〉。ここに入るのが正しい。", "制度": "〈制度〉は決まりの仕組みで、被害を調べる主体にはならないので合わない。", "方針": "〈方針〉は考えや進め方で、調べるという動作の主体にはならないので合わない。", "目的": "〈目的〉は到達したいことで、被害を調べる主語にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "組織"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車の組織が三十分遅れた。", "explanation": "ここは〈電車・乗り物〉の意味。組織は人の団体や仕組みを指すので、乗り物には使わない。"}, {"text": "駅前に人の組織ができていた。", "explanation": "ここは〈集団〉の意味。組織は目的をもつ団体で、偶然集まった人の群れは指さない。"}, {"text": "子どもの頃からの友達の組織が、今も続いている。", "explanation": "ここは〈つながり〉の意味。組織は目的をもつ団体で、友達どうしの関係には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37463, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組織", "is_correct": true, "explanation": "「組織の目的をはっきりさせる」の〈組織〉は、目的をもつ団体を指す。ここに入るのが正しい。"}, {"text": "感情", "is_correct": false, "explanation": "〈感情〉には「目的をはっきりさせる」とは言わないので合わない。"}, {"text": "期限", "is_correct": false, "explanation": "〈期限〉は締め切りの日で、目的をはっきりさせる対象にはならないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "〈天気〉には目的をはっきりさせるという文脈が成り立たないので合わない。"}], "explanations": {"組織": "「組織の目的をはっきりさせる」の〈組織〉は、目的をもつ団体を指す。ここに入るのが正しい。", "感情": "〈感情〉には「目的をはっきりさせる」とは言わないので合わない。", "期限": "〈期限〉は締め切りの日で、目的をはっきりさせる対象にはならないので合わない。", "天気": "〈天気〉には目的をはっきりさせるという文脈が成り立たないので合わない。"}, "sentence_index": 6, "correct_answer": "組織"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "放課後、組織を誘って、公園へ遊びに行った。", "explanation": "ここは〈仲間〉の意味。組織は目的をもつ団体で、遊びに誘う仲間の意味では使わない。"}, {"text": "この部屋は、組織が散らかっていて、片付けにくい。", "explanation": "ここは〈物の散らかり〉の意味。組織は人の団体や仕組みを指すので、物には使わない。"}, {"text": "夕立で、組織が遅れて、家に着くのが遅くなった。", "explanation": "ここは〈人・乗り物の移動〉の意味。組織は団体を指すので、移動して遅れるものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37463, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい組織を参加するには、申込書が必要です。", "corrected_sentence": "新しい組織に参加するには、申込書が必要です。", "error_description": "「参加する」は「に」で参加先を示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37463, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この組織入ると、毎月会費がかかる。", "corrected_sentence": "この組織に入ると、毎月会費がかかる。", "error_description": "「入る」は入る先を「に」で示すが、「に」が抜けた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37464, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「自己を知る」の目的語を示す「を」で、文が自然に成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「知る」は「に」で帰着先を取らず、「自己に知る」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「知る」の対象にならず、「自己へ知る」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同の「と」は「自己と知る」と続かず、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「自己を知る」の目的語を示す「を」で、文が自然に成り立つ。", "に": "「知る」は「に」で帰着先を取らず、「自己に知る」は意味が通らない。", "へ": "方向の「へ」は「知る」の対象にならず、「自己へ知る」は成り立たない。", "と": "共同の「と」は「自己と知る」と続かず、意味が通らない。"}, "error_tags": {"に": "帰着・相手", "へ": "方向", "と": "共同"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "他者", "is_correct": true, "explanation": "自分以外の人を指し、「自己」の対義語として辞書に並ぶ。"}, {"text": "社会", "is_correct": false, "explanation": "人々の集まりを指し、「自己」の対義語ではない。"}, {"text": "環境", "is_correct": false, "explanation": "周囲の状況を指し、自分自身の反対語ではない。"}, {"text": "感情", "is_correct": false, "explanation": "心の働きを指し、「自己」の対義語ではない。"}], "correct_answer": "他者", "explanations": {"他者": "自分以外の人を指し、「自己」の対義語として辞書に並ぶ。", "社会": "人々の集まりを指し、「自己」の対義語ではない。", "環境": "周囲の状況を指し、自分自身の反対語ではない。", "感情": "心の働きを指し、「自己」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37464, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「自己が変われば」の主語を示す「が」で、文が自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「変わる」は自動詞なので目的語の「を」は取らず、「自己を変われば」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "所属の「の」は動詞の前に来ず、「自己の変われば」は文が崩れる。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、「自己より変われば」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「自己が変われば」の主語を示す「が」で、文が自然に成り立つ。", "を": "「変わる」は自動詞なので目的語の「を」は取らず、「自己を変われば」は不自然。", "の": "所属の「の」は動詞の前に来ず、「自己の変われば」は文が崩れる。", "より": "比較の「より」で、「自己より変われば」は意味が通らない。"}, "error_tags": {"を": "対象", "の": "所属", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "他者", "is_correct": true, "explanation": "自分以外の人を指し、「自己」の対義語として辞書に並ぶ。"}, {"text": "家族", "is_correct": false, "explanation": "血縁や同居の人々を指し、「自己」の対義語ではない。"}, {"text": "世間", "is_correct": false, "explanation": "社会一般の人々を指すが、「自己」の対義語ではない。"}, {"text": "組織", "is_correct": false, "explanation": "団体を指し、自分自身の反対語ではない。"}], "correct_answer": "他者", "explanations": {"他者": "自分以外の人を指し、「自己」の対義語として辞書に並ぶ。", "家族": "血縁や同居の人々を指し、「自己」の対義語ではない。", "世間": "社会一般の人々を指すが、「自己」の対義語ではない。", "組織": "団体を指し、自分自身の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37464, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分自身のこと。", "primary_collocate": null, "pronunciation": "じこ", "ipa": "dʑiko", "syllable_count": 2, "sentences": [{"text": "面接では、まず自己の長所を具体的に述べてください。", "target_word": "自己", "complexity_tier": "T3", "furigana": "面接[めんせつ]では、まず自己[じこ]の長所[ちょうしょ]を具体的[ぐたいてき]に述[の]べてください。", "sentence_source": "generated"}, {"text": "自己を知ることは、成長の第一歩だ。", "target_word": "自己", "complexity_tier": "T4", "furigana": "自己[じこ]を知[し]ることは、成長[せいちょう]の第一歩[だいいっぽ]だ。", "sentence_source": "generated"}, {"text": "彼は他人の意見に流されず、自己の信念を貫いた。", "target_word": "自己", "complexity_tier": "T3", "furigana": "彼[かれ]は他人[たにん]の意見[いけん]に流[なが]されず、自己[じこ]の信念[しんねん]を貫[つらぬ]いた。", "sentence_source": "generated"}, {"text": "日記を書くと、自己を見つめ直すことができる。", "target_word": "自己", "complexity_tier": "T3", "furigana": "日記[にっき]を書[か]くと、自己[じこ]を見[み]つめ直[なお]すことができる。", "sentence_source": "generated"}, {"text": "自己の中にある不安と、ゆっくり向き合った。", "target_word": "自己", "complexity_tier": "T4", "furigana": "自己[じこ]の中[なか]にある不安[ふあん]と、ゆっくり向[む]き合[あ]った。", "sentence_source": "generated"}, {"text": "この授業では、自己について深く考える。", "target_word": "自己", "complexity_tier": "T3", "furigana": "この授業[じゅぎょう]では、自己[じこ]について深[ふか]く考[かんが]える。", "sentence_source": "generated"}, {"text": "他人と比べるより、自己の変化に目を向けよう。", "target_word": "自己", "complexity_tier": "T4", "furigana": "他人[たにん]と比[くら]べるより、自己[じこ]の変化[へんか]に目[め]を向[む]けよう。", "sentence_source": "generated"}, {"text": "自己が変われば、周りの見え方も変わる。", "target_word": "自己", "complexity_tier": "T4", "furigana": "自己[じこ]が変[か]われば、周[まわ]りの見[み]え方[かた]も変[か]わる。", "sentence_source": "generated"}, {"text": "哲学者は、自己とは何かを問い続けた。", "target_word": "自己", "complexity_tier": "T4", "furigana": "哲学者[てつがくしゃ]は、自己[じこ]とは何[なに]かを問[と]い続[つづ]けた。", "sentence_source": "generated"}, {"text": "自己を大切にできる人は、他人にもやさしい。", "target_word": "自己", "complexity_tier": "T3", "furigana": "自己[じこ]を大切[たいせつ]にできる人[ひと]は、他人[たにん]にもやさしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自己", "label": "dictionary"}, {"form": "自己を", "label": "object"}, {"form": "自己の", "label": "genitive"}, {"form": "自己が", "label": "subject"}], "register": "formal", "sense_fingerprint": "自分自身（自分というもの）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7bfaf5f-7601-4049-bf95-765962747195') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37464, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自己", "is_correct": true, "explanation": "「自己の長所」として、面接で自分自身の強みを指すのに合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の長所」は面接の文脈で意味が通らない。"}, {"text": "洗剤", "is_correct": false, "explanation": "「洗剤の長所」は面接で自分を述べる文脈に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「季節の長所」は面接で自分の強みを述べる文脈に合わない。"}], "explanations": {"自己": "「自己の長所」として、面接で自分自身の強みを指すのに合う。", "天気": "「天気の長所」は面接の文脈で意味が通らない。", "洗剤": "「洗剤の長所」は面接で自分を述べる文脈に合わない。", "季節": "「季節の長所」は面接で自分の強みを述べる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "自己"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は自己が足りず、遅刻を繰り返している。", "explanation": "ここは〈自覚〉の意味。足りないのは自分への気づきなので〈自覚〉で表し、自己は『自分自身』を指すので合わない。"}, {"text": "彼は自己を誇って話すので、周りに嫌われた。", "explanation": "ここは〈自慢〉の意味。得意げに語ることは〈自慢〉で言い、自己は『自分自身』を指すので『自己を誇る』とは言わない。"}, {"text": "彼は実力もないのに、自己の専門家を名乗って講演している。", "explanation": "ここは〈自称〉の意味。自分でそう名乗ることは〈自称〉で言い、自己は『自分自身』なので『自己の専門家』とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37464, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自己", "is_correct": true, "explanation": "「自己の変化」として、自分自身が変わることを指すのに合う。"}, {"text": "足音", "is_correct": false, "explanation": "「足音の変化に目を向けよう」は意味が通らない。"}, {"text": "包丁", "is_correct": false, "explanation": "「包丁の変化に目を向けよう」は比べる文脈に合わない。"}, {"text": "天井", "is_correct": false, "explanation": "「天井の変化に目を向けよう」は人の比較の文脈に合わない。"}], "explanations": {"自己": "「自己の変化」として、自分自身が変わることを指すのに合う。", "足音": "「足音の変化に目を向けよう」は意味が通らない。", "包丁": "「包丁の変化に目を向けよう」は比べる文脈に合わない。", "天井": "「天井の変化に目を向けよう」は人の比較の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "自己"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は自己がなくて、発表の前はいつも緊張する。", "explanation": "ここは〈自信〉の意味。発表前の不安は〈自信〉がないことで表し、自己は『自分自身』を指すので緊張の話には合わない。"}, {"text": "このイベントの費用は、すべて自己だ。", "explanation": "ここは〈自前〉の意味。費用を自分たちで用意することは〈自前〉で表し、自己は『自分自身』を指すので費用の話には合わない。"}, {"text": "友人に自己製のジャムを配った。", "explanation": "ここは〈自家製〉の意味。家で作ったものは〈自家製〉で言い、自己は『自分自身』なので『自己製』とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37464, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は自己を弱さを認めて、前に進んだ。", "corrected_sentence": "彼女は自己の弱さを認めて、前に進んだ。", "error_description": "誤りは「自己を」。「自己の弱さ」の所有を表す「の」が正しく、「を」を入れると二重の「を」になって不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37464, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "自己を成長すると、周りの見方も変わる。", "corrected_sentence": "自己が成長すると、周りの見方も変わる。", "error_description": "誤りは「自己を」。「成長する」は自動詞なので目的語の「を」は取らず、主語を示す「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
