INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37466, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「和食の典型」で、和食に属する典型を示す連体修飾になり、正しい。"}, {"text": "と", "is_correct": false, "explanation": "「和食と典型だ」は並列の形にならず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「和食から典型だ」は起点の意味にならず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "「和食より典型だ」は比較の文にならず、言ってもいい内容と合わない。"}], "correct_answer": "の", "explanations": {"の": "「和食の典型」で、和食に属する典型を示す連体修飾になり、正しい。", "と": "「和食と典型だ」は並列の形にならず、文が成り立たない。", "から": "「和食から典型だ」は起点の意味にならず、不自然。", "より": "「和食より典型だ」は比較の文にならず、言ってもいい内容と合わない。"}, "error_tags": {"の": "連体修飾", "と": "並列", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37466, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるものの特徴をよく表している、代表的な例。", "primary_collocate": null, "pronunciation": "てんけい", "ipa": "teŋkeː", "syllable_count": 4, "sentences": [{"text": "この町の古い家は、日本の田舎の典型です。", "target_word": "典型", "complexity_tier": "T3", "furigana": "この町[まち]の古[ふる]い家[いえ]は、日本[にほん]の田舎[いなか]の典型[てんけい]です。", "sentence_source": "generated"}, {"text": "彼の話し方は、頭のいい人の典型だと思います。", "target_word": "典型", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はな]し方[かた]は、頭[あたま]のいい人[ひと]の典型[てんけい]だと思[おも]います。", "sentence_source": "generated"}, {"text": "この絵は、江戸時代の絵の典型として知られています。", "target_word": "典型", "complexity_tier": "T3", "furigana": "この絵[え]は、江戸時代[えどじだい]の絵[え]の典型[てんけい]として知[し]られています。", "sentence_source": "generated"}, {"text": "朝ごはんがパンとコーヒーだけなのは、忙しい会社員の典型です。", "target_word": "典型", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんがパンとコーヒーだけなのは、忙[いそが]しい会社員[かいしゃいん]の典型[てんけい]です。", "sentence_source": "generated"}, {"text": "その事件は、お金のトラブルの典型でした。", "target_word": "典型", "complexity_tier": "T3", "furigana": "その事件[じけん]は、お金[かね]のトラブルの典型[てんけい]でした。", "sentence_source": "generated"}, {"text": "日本の夏を表す典型は、花火と風鈴です。", "target_word": "典型", "complexity_tier": "T3", "furigana": "日本[にほん]の夏[なつ]を表[あらわ]す典型[てんけい]は、花火[はなび]と風鈴[ふうりん]です。", "sentence_source": "generated"}, {"text": "彼女はがんばり屋の典型で、休みの日も勉強しています。", "target_word": "典型", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はがんばり屋[や]の典型[てんけい]で、休[やす]みの日[ひ]も勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "この料理は、和食の典型だと言ってもいいでしょう。", "target_word": "典型", "complexity_tier": "T3", "furigana": "この料理[りょうり]は、和食[わしょく]の典型[てんけい]だと言[い]ってもいいでしょう。", "sentence_source": "generated"}, {"text": "先生は、よくある間違いの典型を黒板に書きました。", "target_word": "典型", "complexity_tier": "T3", "furigana": "先生[せんせい]は、よくある間違[まちが]いの典型[てんけい]を黒板[こくばん]に書[か]きました。", "sentence_source": "generated"}, {"text": "失敗の典型を知っておくと、同じ間違いを防げます。", "target_word": "典型", "complexity_tier": "T3", "furigana": "失敗[しっぱい]の典型[てんけい]を知[し]っておくと、同[おな]じ間違[まちが]いを防[ふせ]げます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "典型", "label": "基本形"}], "register": "標準", "sense_fingerprint": "特徴をよく表す代表的な例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b906860-ce3e-49f4-97db-f10691e443cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37466, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "典型", "is_correct": true, "explanation": "「田舎の典型」で、古い家が田舎らしさをよく示す例だと述べる文に合う。"}, {"text": "自由", "is_correct": false, "explanation": "「田舎の自由」は家の性質を表す言い方にならず、文が成り立たない。"}, {"text": "原則", "is_correct": false, "explanation": "「田舎の原則」は家の特徴の例として不自然で、文の意味が通らない。"}, {"text": "期限", "is_correct": false, "explanation": "「田舎の期限」は意味をなさず、古い家の説明として成り立たない。"}], "explanations": {"典型": "「田舎の典型」で、古い家が田舎らしさをよく示す例だと述べる文に合う。", "自由": "「田舎の自由」は家の性質を表す言い方にならず、文が成り立たない。", "原則": "「田舎の原則」は家の特徴の例として不自然で、文の意味が通らない。", "期限": "「田舎の期限」は意味をなさず、古い家の説明として成り立たない。"}, "sentence_index": 0, "correct_answer": "典型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この事件は、めったに起きない典型でした。", "explanation": "〈例外〉の意味。めったにないものを指す語で、多くの例に共通する代表例を表す典型とは逆になる。"}, {"text": "今回だけ、典型として出場を認められました。", "explanation": "〈特例〉の意味。特別に認められた扱いを指す語で、代表的な例を表す典型とは合わない。"}, {"text": "彼のデザインは典型で、だれも真似できません。", "explanation": "〈独創〉の意味。独自で他に真似のできない性質を指す語で、ありふれた型を表す典型とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37466, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "典型", "is_correct": true, "explanation": "「がんばり屋の典型」で、人の特徴をよく示す例だと述べる文に合う。"}, {"text": "安定", "is_correct": false, "explanation": "「がんばり屋の安定」は人を表す言い方にならず、文が成り立たない。"}, {"text": "比較", "is_correct": false, "explanation": "「がんばり屋の比較」は意味をなさず、彼女の様子を説明する文に合わない。"}, {"text": "誤解", "is_correct": false, "explanation": "「がんばり屋の誤解」は意味が通らず、勉強している様子の説明として成り立たない。"}], "explanations": {"典型": "「がんばり屋の典型」で、人の特徴をよく示す例だと述べる文に合う。", "安定": "「がんばり屋の安定」は人を表す言い方にならず、文が成り立たない。", "比較": "「がんばり屋の比較」は意味をなさず、彼女の様子を説明する文に合わない。", "誤解": "「がんばり屋の誤解」は意味が通らず、勉強している様子の説明として成り立たない。"}, "sentence_index": 6, "correct_answer": "典型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この骨董品は、世界に一つしかない典型です。", "explanation": "〈珍品〉の意味。世界に一つだけの品は、多くの例に共通する型とは言えず、この語とは合わない。"}, {"text": "この寺は、だれにも見せたことのない典型を大切にしています。", "explanation": "〈秘蔵品〉の意味。だれにも見せない品は、多くの例に共通する代表例とは言えず、この語とは合わない。"}, {"text": "彼は、クラスの典型として大会に出ます。", "explanation": "〈代表〉の意味。選ばれて出場する人を指す語で、特徴をよく示す例を表す典型とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
