INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37467, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある種類のものの中で、その特徴を最もよく示している代表的な例。", "primary_collocate": null, "pronunciation": "てんけい", "ipa": "teŋkeː", "syllable_count": 4, "sentences": [{"text": "このアパートは、都会の狭い部屋の典型で、台所と寝室が続いています。", "target_word": "典型", "complexity_tier": "T3", "furigana": "このアパートは、都会[とかい]の狭[せま]い部屋[へや]の典型[てんけい]で、台所[だいどころ]と寝室[しんしつ]が続[つづ]いています。", "sentence_source": "generated"}, {"text": "その小説の主人公は、昔の日本の父親の典型です。", "target_word": "典型", "complexity_tier": "T3", "furigana": "その小説[しょうせつ]の主人公[しゅじんこう]は、昔[むかし]の日本[にほん]の父親[ちちおや]の典型[てんけい]です。", "sentence_source": "generated"}, {"text": "梅雨は、日本の気候の特徴をよく表す典型です。", "target_word": "典型", "complexity_tier": "T3", "furigana": "梅雨[つゆ]は、日本[にほん]の気候[きこう]の特徴[とくちょう]をよく表[あらわ]す典型[てんけい]です。", "sentence_source": "generated"}, {"text": "この病気は、子どもがかかりやすい病気の典型です。", "target_word": "典型", "complexity_tier": "T3", "furigana": "この病気[びょうき]は、子[こ]どもがかかりやすい病気[びょうき]の典型[てんけい]です。", "sentence_source": "generated"}, {"text": "先生は、成功した会社の典型を一つ取り上げて説明しました。", "target_word": "典型", "complexity_tier": "T3", "furigana": "先生[せんせい]は、成功[せいこう]した会社[かいしゃ]の典型[てんけい]を一つ取[と]り上[あ]げて説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "彼の失敗は、準備不足が原因の典型でした。", "target_word": "典型", "complexity_tier": "T3", "furigana": "彼[かれ]の失敗[しっぱい]は、準備不足[じゅんびぶそく]が原因[げんいん]の典型[てんけい]でした。", "sentence_source": "generated"}, {"text": "この建物は、明治時代の洋風建築の典型として残されています。", "target_word": "典型", "complexity_tier": "T3", "furigana": "この建物[たてもの]は、明治時代[めいじじだい]の洋風建築[ようふうけんちく]の典型[てんけい]として残[のこ]されています。", "sentence_source": "generated"}, {"text": "山に囲まれた小さな村は、静かな田舎の典型です。", "target_word": "典型", "complexity_tier": "T3", "furigana": "山[やま]に囲[かこ]まれた小[ちい]さな村[むら]は、静[しず]かな田舎[いなか]の典型[てんけい]です。", "sentence_source": "generated"}, {"text": "彼女の服装は、真面目な学生の典型で、いつも白いシャツです。", "target_word": "典型", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の服装[ふくそう]は、真面目[まじめ]な学生[がくせい]の典型[てんけい]で、いつも白[しろ]いシャツです。", "sentence_source": "generated"}, {"text": "典型を一つ見れば、その種類の特徴がよくわかります。", "target_word": "典型", "complexity_tier": "T3", "furigana": "典型[てんけい]を一[ひと]つ見[み]れば、その種類[しゅるい]の特徴[とくちょう]がよくわかります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "典型", "label": "基本形"}], "register": "標準", "sense_fingerprint": "ある種類の中で特徴を最もよく示す代表例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b906860-ce3e-49f4-97db-f10691e443cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37467, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "典型", "is_correct": true, "explanation": "「狭い部屋の典型」で、台所と寝室が続く間取りの代表例だと述べる文に合う。"}, {"text": "信頼", "is_correct": false, "explanation": "「狭い部屋の信頼」は意味をなさず、間取りの説明として成り立たない。"}, {"text": "流行", "is_correct": false, "explanation": "「狭い部屋の流行」は間取りの説明にならず、文が通らない。"}, {"text": "根拠", "is_correct": false, "explanation": "「狭い部屋の根拠」は意味が通らず、台所と寝室の説明に合わない。"}], "explanations": {"典型": "「狭い部屋の典型」で、台所と寝室が続く間取りの代表例だと述べる文に合う。", "信頼": "「狭い部屋の信頼」は意味をなさず、間取りの説明として成り立たない。", "流行": "「狭い部屋の流行」は間取りの説明にならず、文が通らない。", "根拠": "「狭い部屋の根拠」は意味が通らず、台所と寝室の説明に合わない。"}, "sentence_index": 0, "correct_answer": "典型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この病気は、子どもにはめったに見られない典型です。", "explanation": "〈例外〉の意味。子どもにまれな例外を言う語で、子どもに多い代表例を表す典型とは逆になる。"}, {"text": "この薬は、典型として子どもにも使えます。", "explanation": "〈特例〉の意味。特別に認められた扱いを指す語で、代表的な例を表す典型とは合わない。"}, {"text": "店は、どこにも売っていない典型を一つ店頭に飾っています。", "explanation": "〈珍品〉の意味。どこにも売っていない品は、多くの例に共通する代表例とは言えず、この語とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37467, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "典型", "is_correct": true, "explanation": "「洋風建築の典型」として残されているという文に合い、その時代の代表例を示す。"}, {"text": "自由", "is_correct": false, "explanation": "「洋風建築の自由」は建物を表す言い方にならず、文が成り立たない。"}, {"text": "原則", "is_correct": false, "explanation": "「洋風建築の原則」は建物の例を示す言い方にならず、不自然。"}, {"text": "期限", "is_correct": false, "explanation": "「洋風建築の期限」は意味をなさず、残されているという文と合わない。"}], "explanations": {"典型": "「洋風建築の典型」として残されているという文に合い、その時代の代表例を示す。", "自由": "「洋風建築の自由」は建物を表す言い方にならず、文が成り立たない。", "原則": "「洋風建築の原則」は建物の例を示す言い方にならず、不自然。", "期限": "「洋風建築の期限」は意味をなさず、残されているという文と合わない。"}, "sentence_index": 6, "correct_answer": "典型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この宝石は、世界にひとつしかない典型です。", "explanation": "〈珍品〉の意味。世界に一つだけの品は、多くの例に共通する型とは言えず、この語とは合わない。"}, {"text": "この遺跡は、だれも知らない典型を一つだけ残しています。", "explanation": "〈未発見〉の意味。だれも知らない品は、多くの例に共通する代表例とは言えず、この語とは合わない。"}, {"text": "彼女は、チームの典型として大会に出ます。", "explanation": "〈代表〉の意味。選ばれて出場する人を指す語で、特徴をよく示す例を表す典型とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37467, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は、昔ながらの商店街の典型に知られています。", "corrected_sentence": "この店は、昔ながらの商店街の典型として知られています。", "error_description": "助詞の誤り。「典型として知られる」は「として」で受けるので、「典型に」は成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37467, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この料理は、和食の典型な組み合わせです。", "corrected_sentence": "この料理は、和食の典型的な組み合わせです。", "error_description": "形の誤り。「典型」を形容動詞のように使うには「典型的な」が必要で、「典型な」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37468, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「例として」の「と」は資格・見立てを示す。「例として挙げる」の意味になるので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「例を、りんごやバナナがある」は不自然。「を」は目的語を示すので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、例を挙げる文脈には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「例として」の意味にはならず合わない。"}], "correct_answer": "と", "explanations": {"と": "「例として」の「と」は資格・見立てを示す。「例として挙げる」の意味になるので正しい。", "を": "「例を、りんごやバナナがある」は不自然。「を」は目的語を示すので合わない。", "へ": "「へ」は方向を示すので、例を挙げる文脈には合わない。", "から": "「から」は起点を示すので、「例として」の意味にはならず合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37468, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「同じような例が、他の国にもある」の「が」は主語を示す。ここに入るのが正しい。"}, {"text": "を", "is_correct": false, "explanation": "「例を、他の国にもある」は不自然。「ある」は目的語をとらないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、存在を表す文脈には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、ここでは比べる文脈がなく合わない。"}], "correct_answer": "が", "explanations": {"が": "「同じような例が、他の国にもある」の「が」は主語を示す。ここに入るのが正しい。", "を": "「例を、他の国にもある」は不自然。「ある」は目的語をとらないので合わない。", "へ": "「へ」は方向を示すので、存在を表す文脈には合わない。", "より": "「より」は比較を示すので、ここでは比べる文脈がなく合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37468, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ほかのものと似ているところを見せるために出された、一つのもの。", "primary_collocate": null, "pronunciation": "れい", "ipa": "ɾeː", "syllable_count": 2, "sentences": [{"text": "先生は、わかりやすい例を一つ出してくれた。", "target_word": "例", "complexity_tier": "T2", "furigana": "先生[せんせい]は、わかりやすい例[れい]を一[ひと]つ出[だ]してくれた。", "sentence_source": "generated"}, {"text": "「果物」の例として、りんごやバナナがある。", "target_word": "例", "complexity_tier": "T3", "furigana": "「果物[くだもの]」の例[れい]として、りんごやバナナがある。", "sentence_source": "generated"}, {"text": "例を見れば、このきまりが理解しやすい。", "target_word": "例", "complexity_tier": "T3", "furigana": "例[れい]を見[み]れば、このきまりが理解[りかい]しやすい。", "sentence_source": "generated"}, {"text": "彼の成功は、努力が実を結んだ良い例だ。", "target_word": "例", "complexity_tier": "T3", "furigana": "彼[かれ]の成功[せいこう]は、努力[どりょく]が実[み]を結[むす]んだ良[よ]い例[れい]だ。", "sentence_source": "generated"}, {"text": "例をあげて話すと、相手に伝わりやすい。", "target_word": "例", "complexity_tier": "T3", "furigana": "例[れい]をあげて話[はな]すと、相手[あいて]に伝[つた]わりやすい。", "sentence_source": "generated"}, {"text": "動物の例として、犬とねこを挙げた。", "target_word": "例", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の例[れい]として、犬[いぬ]とねこを挙[あ]げた。", "sentence_source": "generated"}, {"text": "失敗した例から、私たちは多くを学べる。", "target_word": "例", "complexity_tier": "T3", "furigana": "失敗[しっぱい]した例[れい]から、私[わたし]たちは多[おお]くを学[まな]べる。", "sentence_source": "generated"}, {"text": "同じような例が、他の国にもある。", "target_word": "例", "complexity_tier": "T3", "furigana": "同[おな]じような例[れい]が、他[ほか]の国[くに]にもある。", "sentence_source": "generated"}, {"text": "悪い例を見せて、気をつけるところを教えた。", "target_word": "例", "complexity_tier": "T3", "furigana": "悪[わる]い例[れい]を見[み]せて、気[き]をつけるところを教[おし]えた。", "sentence_source": "generated"}, {"text": "例を一つ考えてから、自分の意見を書きましょう。", "target_word": "例", "complexity_tier": "T3", "furigana": "例[れい]を一[ひと]つ考[かんが]えてから、自分[じぶん]の意見[いけん]を書[か]きましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "例", "label": "基本形"}], "register": "標準・中立", "sense_fingerprint": "説明や比較のために取り上げる、似た物事の一つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aaf6791-139f-41e3-8c71-ba48b836c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37468, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "例", "is_correct": true, "explanation": "「わかりやすい例を一つ出す」の〈例〉は、説明のために示す一つの事柄。ここに入るのが正しい。"}, {"text": "色", "is_correct": false, "explanation": "〈色〉は見た目の性質で、説明のために出すものではないので合わない。"}, {"text": "影", "is_correct": false, "explanation": "〈影〉は光によって生じる暗い部分で、説明として出すものではないので合わない。"}, {"text": "熱", "is_correct": false, "explanation": "〈熱〉は温度の状態で、説明のために一つ出すとは言わないので合わない。"}], "explanations": {"例": "「わかりやすい例を一つ出す」の〈例〉は、説明のために示す一つの事柄。ここに入るのが正しい。", "色": "〈色〉は見た目の性質で、説明のために出すものではないので合わない。", "影": "〈影〉は光によって生じる暗い部分で、説明として出すものではないので合わない。", "熱": "〈熱〉は温度の状態で、説明のために一つ出すとは言わないので合わない。"}, "sentence_index": 0, "correct_answer": "例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今朝、例を一つ買って、とても甘かった。", "explanation": "ここは〈食べ物〉の意味。例は説明のために示す事柄で、買って食べられるものではないので合わない。"}, {"text": "新製品の例を店頭で配った。", "explanation": "ここは〈見本・実物〉の意味。例は説明のために示すもので、配る商品には使わない。"}, {"text": "例の件で、明日、先生に相談します。", "explanation": "ここは〈例の〉（前に話題にした、あの）の意味。一つの事例を示す意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37468, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "例", "is_correct": true, "explanation": "「失敗した例から、多くを学べる」の〈例〉は、示された一つの出来事。ここに入るのが正しい。"}, {"text": "味", "is_correct": false, "explanation": "〈味〉は食べ物の感覚で、失敗から学ぶ対象にはならないので合わない。"}, {"text": "音", "is_correct": false, "explanation": "〈音〉は聞こえるもので、失敗から学ぶ対象にはならないので合わない。"}, {"text": "温度", "is_correct": false, "explanation": "〈温度〉は測る数値で、失敗から学ぶ対象にはならないので合わない。"}], "explanations": {"例": "「失敗した例から、多くを学べる」の〈例〉は、示された一つの出来事。ここに入るのが正しい。", "味": "〈味〉は食べ物の感覚で、失敗から学ぶ対象にはならないので合わない。", "音": "〈音〉は聞こえるもので、失敗から学ぶ対象にはならないので合わない。", "温度": "〈温度〉は測る数値で、失敗から学ぶ対象にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "例を三つ買ってきてください。", "explanation": "ここは〈例〉を物として買う意味。例は説明のために示す事柄で、買える品物ではないので合わない。"}, {"text": "例を一つ食べてから、料理を作りましょう。", "explanation": "ここは〈食べ物〉の意味。例は食べられるものではないので、料理の前に食べるという使い方は合わない。"}, {"text": "例を一つ洗ってから、料理を作りましょう。", "explanation": "ここは〈洗える物〉の意味。例は物ではなく示す事柄なので、洗うものとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37468, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この説明には、わかりやすい例で必要だ。", "corrected_sentence": "この説明には、わかりやすい例が必要だ。", "error_description": "「例が必要だ」の「が」を「で」にした誤り。「必要だ」は主語を「が」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37468, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "例挙げてもらうと、理解しやすくなる。", "corrected_sentence": "例を挙げてもらうと、理解しやすくなる。", "error_description": "「挙げる」は対象を「を」で示すが、「を」が抜けた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37469, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「例にならって」の「に」は手本とする先を示す。ここに入るのが正しい。"}, {"text": "を", "is_correct": false, "explanation": "「例をならって」は不自然。「ならう」は「に」で手本を示すので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を示すので、「ならう」の対象を表す文脈には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「ならう」の対象を表す文脈には合わない。"}], "correct_answer": "に", "explanations": {"に": "「例にならって」の「に」は手本とする先を示す。ここに入るのが正しい。", "を": "「例をならって」は不自然。「ならう」は「に」で手本を示すので合わない。", "で": "「で」は手段・場所を示すので、「ならう」の対象を表す文脈には合わない。", "へ": "「へ」は方向を示すので、「ならう」の対象を表す文脈には合わない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37469, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「例が付いている」の「が」は主語を示す。ここに入るのが正しい。"}, {"text": "と", "is_correct": false, "explanation": "「例と付いている」は並列の「と」になり、「付いている」の主語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「例より付いている」は比較の「より」になり、主語にならず文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「例から付いている」は起点の「から」になり、「付いている」の主語を示す文にはならない。"}], "correct_answer": "が", "explanations": {"が": "「例が付いている」の「が」は主語を示す。ここに入るのが正しい。", "と": "「例と付いている」は並列の「と」になり、「付いている」の主語を示せない。", "より": "「例より付いている」は比較の「より」になり、主語にならず文が成り立たない。", "から": "「例から付いている」は起点の「から」になり、「付いている」の主語を示す文にはならない。"}, "error_tags": {"と": "並列・引用", "より": "比較・基準", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37469, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他と比較したり、使い方を示したりするために示される、具体的な物事や文。", "primary_collocate": null, "pronunciation": "れい", "ipa": "ɾeː", "syllable_count": 2, "sentences": [{"text": "辞書の例を読んで、この言葉の使い方を覚えた。", "target_word": "例", "complexity_tier": "T3", "furigana": "辞書[じしょ]の例[れい]を読[よ]んで、この言葉[ことば]の使[つか]い方[かた]を覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "教科書の例にならって、自分で文を作ってみよう。", "target_word": "例", "complexity_tier": "T3", "furigana": "教科書[きょうかしょ]の例[れい]にならって、自分[じぶん]で文[ぶん]を作[つく]ってみよう。", "sentence_source": "generated"}, {"text": "数学の問題は、まず例を見てから解くとよい。", "target_word": "例", "complexity_tier": "T3", "furigana": "数学[すうがく]の問題[もんだい]は、まず例[れい]を見[み]てから解[と]くとよい。", "sentence_source": "generated"}, {"text": "次の例のように、動詞の形を変えてください。", "target_word": "例", "complexity_tier": "T3", "furigana": "次[つぎ]の例[れい]のように、動詞[どうし]の形[かたち]を変[か]えてください。", "sentence_source": "generated"}, {"text": "他の会社の例と比べて、料金の違いを調べた。", "target_word": "例", "complexity_tier": "T4", "furigana": "他[ほか]の会社[かいしゃ]の例[れい]と比[くら]べて、料金[りょうきん]の違[ちが]いを調[しら]べた。", "sentence_source": "generated"}, {"text": "この文法の例は、日常の会話でよく使われる。", "target_word": "例", "complexity_tier": "T3", "furigana": "この文法[ぶんぽう]の例[れい]は、日常[にちじょう]の会話[かいわ]でよく使[つか]われる。", "sentence_source": "generated"}, {"text": "先生は黒板に例を書いて、使い方を説明した。", "target_word": "例", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に例[れい]を書[か]いて、使[つか]い方[かた]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "書き方の例が付いているので、申込書は簡単に書ける。", "target_word": "例", "complexity_tier": "T4", "furigana": "書[か]き方[かた]の例[れい]が付[つ]いているので、申込書[もうしこみしょ]は簡単[かんたん]に書[か]ける。", "sentence_source": "generated"}, {"text": "過去の例と比べると、今年は参加者が多い。", "target_word": "例", "complexity_tier": "T3", "furigana": "過去[かこ]の例[れい]と比べると、今年は参加者が多い。", "sentence_source": "generated"}, {"text": "例にあるとおりに、名前と住所を書いてください。", "target_word": "例", "complexity_tier": "T3", "furigana": "例[れい]にあるとおりに、名前[なまえ]と住所[じゅうしょ]を書[か]いてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "例", "label": "基本形"}], "register": "標準・中立", "sense_fingerprint": "比較や使い方の手本として示される具体的な事柄や文", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aaf6791-139f-41e3-8c71-ba48b836c05b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37469, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "例", "is_correct": true, "explanation": "「辞書の例を読んで使い方を覚えた」の〈例〉は、使い方を示す文。ここに入るのが正しい。"}, {"text": "切符", "is_correct": false, "explanation": "〈切符〉は乗車などに使うもので、使い方を覚える文脈には合わない。"}, {"text": "音", "is_correct": false, "explanation": "〈音〉は聞くもので、辞書の中で読むものではないので合わない。"}, {"text": "湯気", "is_correct": false, "explanation": "〈湯気〉は立ちのぼる蒸気で、辞書の中で読むものではないので合わない。"}], "explanations": {"例": "「辞書の例を読んで使い方を覚えた」の〈例〉は、使い方を示す文。ここに入るのが正しい。", "切符": "〈切符〉は乗車などに使うもので、使い方を覚える文脈には合わない。", "音": "〈音〉は聞くもので、辞書の中で読むものではないので合わない。", "湯気": "〈湯気〉は立ちのぼる蒸気で、辞書の中で読むものではないので合わない。"}, "sentence_index": 0, "correct_answer": "例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "例を一つ洗ってから、薬を飲みましょう。", "explanation": "ここは〈使い方を示す文例〉の意味。例は洗える物ではないので、薬の前に洗う相手としては合わない。"}, {"text": "例を一つ乗って、駅まで行った。", "explanation": "ここは〈乗り物〉の意味。例は乗れるものではなく、示す事柄なので合わない。"}, {"text": "例を二つ買って、お風呂に入った。", "explanation": "ここは〈物〉の意味。例は説明のための事柄で、買う品物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37469, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "例", "is_correct": true, "explanation": "「黒板に例を書いて、使い方を説明した」の〈例〉は、説明のために書く文。ここに入るのが正しい。"}, {"text": "音楽", "is_correct": false, "explanation": "〈音楽〉は黒板に書くものではないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "〈天気〉は黒板に書いて使い方を説明するものではないので合わない。"}, {"text": "切符", "is_correct": false, "explanation": "〈切符〉は黒板に書いて使い方を説明するものではないので合わない。"}], "explanations": {"例": "「黒板に例を書いて、使い方を説明した」の〈例〉は、説明のために書く文。ここに入るのが正しい。", "音楽": "〈音楽〉は黒板に書くものではないので合わない。", "天気": "〈天気〉は黒板に書いて使い方を説明するものではないので合わない。", "切符": "〈切符〉は黒板に書いて使い方を説明するものではないので合わない。"}, "sentence_index": 6, "correct_answer": "例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "例を三つ飲んで、お礼を言った。", "explanation": "ここは〈例〉を飲み物のように扱う意味。例は示す事柄で、飲めるものではないので合わない。"}, {"text": "例の件で、明日、先生に相談します。", "explanation": "ここは〈例の〉（前に話題にした、あの）の意味。手本として示す事例の意味とは別なので合わない。"}, {"text": "雨が降ると、例の川が増水する。", "explanation": "ここは〈例の〉（前に話題にした、あの）の意味。事例を示す意味とは別なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37469, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この例を合わせて、文を書いてください。", "corrected_sentence": "この例に合わせて、文を書いてください。", "error_description": "「例に合わせる」の「に」を「を」にした誤り。「合わせる」は合わせる先を「に」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37469, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "例挙げて、理由を説明してください。", "corrected_sentence": "例を挙げて、理由を説明してください。", "error_description": "「挙げる」は対象を「を」で示すが、「を」が抜けた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3a90e9-9b68-422f-939e-adeb52d8b6a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
