INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37470, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「サークルに参加して」の「に」で、参加する先を示す。"}, {"text": "が", "is_correct": false, "explanation": "「サークルが参加して」ではサークルが主語になり、姉の話の流れに合わない。"}, {"text": "を", "is_correct": false, "explanation": "「大学のサークルを参加して」は「参加する」が「を」を取らないため文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すが、「サークルから参加した」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「サークルに参加して」の「に」で、参加する先を示す。", "が": "「サークルが参加して」ではサークルが主語になり、姉の話の流れに合わない。", "を": "「大学のサークルを参加して」は「参加する」が「を」を取らないため文が成り立たない。", "から": "「から」は起点を表すが、「サークルから参加した」では意味が通らない。"}, "error_tags": {"を": "目的語の誤り", "より": "比較の誤り", "から": "起点の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37470, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何人かの人が一つのことをするとき、その人たちの中にいること。", "primary_collocate": null, "pronunciation": "さんか", "ipa": "saŋka", "syllable_count": 3, "sentences": [{"text": "毎年、町のマラソン大会に参加する。", "target_word": "参加", "complexity_tier": "T2", "furigana": "毎年[まいとし]、町[まち]のマラソン大会[たいかい]に参加[さんか]する。", "sentence_source": "generated"}, {"text": "友だちに誘われて、ボランティア活動に参加した。", "target_word": "参加", "complexity_tier": "T3", "furigana": "友[とも]だちに誘[さそ]われて、ボランティア活動[かつどう]に参加[さんか]した。", "sentence_source": "generated"}, {"text": "このイベントは無料で、誰でも参加できる。", "target_word": "参加", "complexity_tier": "T3", "furigana": "このイベントは無料[むりょう]で、誰[だれ]でも参加[さんか]できる。", "sentence_source": "generated"}, {"text": "熱があったので、遠足への参加をやめた。", "target_word": "参加", "complexity_tier": "T3", "furigana": "熱[ねつ]があったので、遠足[えんそく]への参加[さんか]をやめた。", "sentence_source": "generated"}, {"text": "授業では、みんなが話し合いに参加することが大切だ。", "target_word": "参加", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]では、みんなが話[はな]し合[あ]いに参加[さんか]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "申し込みをしないと、大会に参加できない。", "target_word": "参加", "complexity_tier": "T3", "furigana": "申[もう]し込[こ]みをしないと、大会[たいかい]に参加[さんか]できない。", "sentence_source": "generated"}, {"text": "参加する人が多くて、会場はとてもにぎやかだった。", "target_word": "参加", "complexity_tier": "T4", "furigana": "参加[さんか]する人[ひと]が多[おお]くて、会場[かいじょう]はとてもにぎやかだった。", "sentence_source": "generated"}, {"text": "姉は大学のサークルに参加して、新しい友だちができた。", "target_word": "参加", "complexity_tier": "T3", "furigana": "姉[あね]は大学[だいがく]のサークルに参加[さんか]して、新[あたら]しい友[とも]だちができた。", "sentence_source": "generated"}, {"text": "今年の祭りには、外国からの観光客も参加した。", "target_word": "参加", "complexity_tier": "T3", "furigana": "今年[ことし]の祭[まつ]りには、外国[がいこく]からの観光客[かんこうきゃく]も参加[さんか]した。", "sentence_source": "generated"}, {"text": "試合に参加するためには、まず登録が必要だ。", "target_word": "参加", "complexity_tier": "T4", "furigana": "試合[しあい]に参加[さんか]するためには、まず登録[とうろく]が必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "参加する", "label": "辞書形"}, {"form": "参加します", "label": "丁寧形"}, {"form": "参加した", "label": "過去形"}, {"form": "参加して", "label": "て形"}, {"form": "参加しない", "label": "否定形"}, {"form": "参加できる", "label": "可能形"}], "register": "中立（普通体）", "sense_fingerprint": "大会・活動・会などに仲間として加わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18652b11-0c76-4c07-b9a2-da1d1612a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37470, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参加", "is_correct": true, "explanation": "「大会の一員として加わる」の意味で、空欄に入る唯一の語。"}, {"text": "解約", "is_correct": false, "explanation": "契約を終わらせる意味で、大会に加わることとは合わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "文章を別の言語に直す意味で、マラソン大会とは結びつかない。"}, {"text": "製造", "is_correct": false, "explanation": "物を作る意味で、大会に対して使うと意味が通らない。"}], "explanations": {"参加": "「大会の一員として加わる」の意味で、空欄に入る唯一の語。", "解約": "契約を終わらせる意味で、大会に加わることとは合わない。", "翻訳": "文章を別の言語に直す意味で、マラソン大会とは結びつかない。", "製造": "物を作る意味で、大会に対して使うと意味が通らない。"}, "sentence_index": 0, "correct_answer": "参加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この資料は論文の参加として役立った。", "explanation": "ここは〈参考〉の意味。資料を役立てることは参加ではなく参考と言うので合わない。"}, {"text": "分からない言葉は、辞書に参加して意味を確かめた。", "explanation": "ここは〈参照〉の意味。辞書を見て調べることは、催しや集まりに加わる参加とは言わないので合わない。"}, {"text": "週末、祖父の家に参加して、昼ご飯をごちそうになった。", "explanation": "ここは〈訪ねる〉の意味。家を訪問して食事をもらうことは、集まりや催しに加わる参加とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37470, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参加", "is_correct": true, "explanation": "「参加する人」の形で、大勢が加わる意味に合う。"}, {"text": "節約", "is_correct": false, "explanation": "お金や物を惜しんで使う意味で、人の集まりには合わない。"}, {"text": "点検", "is_correct": false, "explanation": "調べて確かめる意味で、会場のにぎわいとは結びつかない。"}, {"text": "測量", "is_correct": false, "explanation": "土地の広さなどを測る意味で、空欄には入らない。"}], "explanations": {"参加": "「参加する人」の形で、大勢が加わる意味に合う。", "節約": "お金や物を惜しんで使う意味で、人の集まりには合わない。", "点検": "調べて確かめる意味で、会場のにぎわいとは結びつかない。", "測量": "土地の広さなどを測る意味で、空欄には入らない。"}, "sentence_index": 6, "correct_answer": "参加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験官の許可を得て、彼は部屋に参加した。", "explanation": "ここは〈入室〉の意味。部屋に入ることは参加ではなく入室と言うので合わない。"}, {"text": "駅で電車に参加して、家まで帰った。", "explanation": "ここは〈乗る〉の意味。乗り物に乗ることは、催しに加わる参加とは言わないので合わない。"}, {"text": "神社に参加して、お守りを買った。", "explanation": "ここは〈参拝〉の意味。神社にお参りすることは参加ではなく参拝と言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37470, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週、学校の球技大会を参加する。", "corrected_sentence": "来週、学校の球技大会に参加する。", "error_description": "助詞の誤り。参加は「大会に参加する」のように「に」を取るので、「を」は誤り。正しくは「大会に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37470, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来月の音楽会に参加られる人は、申し込んでください。", "corrected_sentence": "来月の音楽会に参加できる人は、申し込んでください。", "error_description": "活用の誤り。「参加する」の可能形は「参加できる」で、「参加られる」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37472, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「生徒の自発」の「の」で、自発の持ち主を示す。"}, {"text": "に", "is_correct": false, "explanation": "「生徒に自発を待った」では、待つ相手として意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「生徒を自発を待った」は「を」が二つ重なり、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の助詞で、ここでは比べる対象がないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「生徒の自発」の「の」で、自発の持ち主を示す。", "に": "「生徒に自発を待った」では、待つ相手として意味が通らない。", "を": "「生徒を自発を待った」は「を」が二つ重なり、文が成り立たない。", "より": "「より」は比較の助詞で、ここでは比べる対象がないので合わない。"}, "error_tags": {"に": "相手の誤り", "を": "目的語の重複", "より": "比較の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37472, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「子どもの自発」の「の」で、自発の持ち主を示す。"}, {"text": "を", "is_correct": false, "explanation": "「子どもを自発が育たない」では「子どもを」が目的語になり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「子どもへ自発が育たない」は方向の「へ」で、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「子どもで自発が育たない」は、手段や場所を示す「で」として意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「子どもの自発」の「の」で、自発の持ち主を示す。", "を": "「子どもを自発が育たない」では「子どもを」が目的語になり、文が成り立たない。", "へ": "「子どもへ自発が育たない」は方向の「へ」で、文が成り立たない。", "で": "「子どもで自発が育たない」は、手段や場所を示す「で」として意味が通らない。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "で": "手段・場所の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37472, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分から進んで何かをすること。", "primary_collocate": null, "pronunciation": "じはつ", "ipa": "dʑihatsɯ", "syllable_count": 3, "sentences": [{"text": "子どもの自発を大切にする教育が広まっている。", "target_word": "自発", "complexity_tier": "T3", "furigana": "子[こ]どもの自発[じはつ]を大切[たいせつ]にする教育[きょういく]が広[ひろ]まっている。", "sentence_source": "generated"}, {"text": "先生は命令せず、生徒の自発を待った。", "target_word": "自発", "complexity_tier": "T3", "furigana": "先生[せんせい]は命令[めいれい]せず、生徒[せいと]の自発[じはつ]を待[ま]った。", "sentence_source": "generated"}, {"text": "この清掃活動は、住民の自発によって始まった。", "target_word": "自発", "complexity_tier": "T3", "furigana": "この清掃[せいそう]活動[かつどう]は、住民[じゅうみん]の自発[じはつ]によって始[はじ]まった。", "sentence_source": "generated"}, {"text": "強制された仕事より、自発の行動のほうが長く続く。", "target_word": "自発", "complexity_tier": "T3", "furigana": "強制[きょうせい]された仕事[しごと]より、自発[じはつ]の行動[こうどう]のほうが長[なが]く続[つづ]く。", "sentence_source": "generated"}, {"text": "会社は社員の自発を引き出すために、自由な時間を作った。", "target_word": "自発", "complexity_tier": "T4", "furigana": "会社[かいしゃ]は社員[しゃいん]の自発[じはつ]を引[ひ]き出[だ]すために、自由[じゆう]な時間[じかん]を作[つく]った。", "sentence_source": "generated"}, {"text": "無理に勧めず、本人の自発に任せることにした。", "target_word": "自発", "complexity_tier": "T3", "furigana": "無理[むり]に勧[すす]めず、本人[ほんにん]の自発[じはつ]に任[まか]せることにした。", "sentence_source": "generated"}, {"text": "ごみ拾いは自発によるもので、参加しなくても責められない。", "target_word": "自発", "complexity_tier": "T4", "furigana": "ごみ拾[ひろ]いは自発[じはつ]によるもので、参加[さんか]しなくても責[せ]められない。", "sentence_source": "generated"}, {"text": "親が口を出しすぎると、子どもの自発が育たない。", "target_word": "自発", "complexity_tier": "T3", "furigana": "親[おや]が口[くち]を出[だ]しすぎると、子[こ]どもの自発[じはつ]が育[そだ]たない。", "sentence_source": "generated"}, {"text": "自発を促すには、小さな成功を経験させるとよい。", "target_word": "自発", "complexity_tier": "T4", "furigana": "自発[じはつ]を促[うなが]すには、小[ちい]さな成功[せいこう]を経験[けいけん]させるとよい。", "sentence_source": "generated"}, {"text": "自発を尊重する先生のもとで、生徒たちは進んで研究を始めた。", "target_word": "自発", "complexity_tier": "T4", "furigana": "自発[じはつ]を尊重[そんちょう]する先生[せんせい]のもとで、生徒[せいと]たちは進[すす]んで研究[けんきゅう]を始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自発", "label": "基本形"}, {"form": "自発の", "label": "連体形（の）"}, {"form": "自発を", "label": "目的語形（を）"}, {"form": "自発に", "label": "に格形"}], "register": "やや硬い（普通体）", "sense_fingerprint": "人に強制されず、自分から進んで行うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18652b11-0c76-4c07-b9a2-da1d1612a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37472, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自発", "is_correct": true, "explanation": "「子どもの自発」で、自分から進んで行う意味に合う。"}, {"text": "栄養", "is_correct": false, "explanation": "体に必要な養分の意味で、大切にする対象としては合わない。"}, {"text": "命令", "is_correct": false, "explanation": "指図する意味で、大切にする対象とは合わない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さの意味で、教育の対象としては合わない。"}], "explanations": {"自発": "「子どもの自発」で、自分から進んで行う意味に合う。", "栄養": "体に必要な養分の意味で、大切にする対象としては合わない。", "命令": "指図する意味で、大切にする対象とは合わない。", "体重": "体の重さの意味で、教育の対象としては合わない。"}, "sentence_index": 0, "correct_answer": "自発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "親に反対されても、彼は親から自発して家を出た。", "explanation": "ここは〈独立〉の意味。親の元を離れて自分の生活を持つことは自発ではなく独立と言うので合わない。"}, {"text": "彼は自分の欠点を自発していたので、すぐに直せた。", "explanation": "ここは〈自覚〉の意味。欠点に気づいていることは自発ではなく自覚と言うので合わない。"}, {"text": "子どもが自発して生活できるように、家事を任せている。", "explanation": "ここは〈自立〉の意味。ひとりで生活できるようになることは自発ではなく自立と言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37472, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自発", "is_correct": true, "explanation": "「自発によるもの」で、自分から行う意味に合う。"}, {"text": "年齢", "is_correct": false, "explanation": "年の数の意味で、ごみ拾いの理由としては合わない。"}, {"text": "天候", "is_correct": false, "explanation": "空模様の意味で、ごみ拾いの動機としては合わない。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちの意味で、ごみ拾いの理由にはならない。"}], "explanations": {"自発": "「自発によるもの」で、自分から行う意味に合う。", "年齢": "年の数の意味で、ごみ拾いの理由としては合わない。", "天候": "空模様の意味で、ごみ拾いの動機としては合わない。", "食欲": "食べたい気持ちの意味で、ごみ拾いの理由にはならない。"}, "sentence_index": 6, "correct_answer": "自発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その新しい薬は、重い副作用を自発することがある。", "explanation": "ここは〈誘発〉の意味。薬などが別の症状を引き起こすことは自発ではなく誘発と言うので合わない。"}, {"text": "彼は新しい腕時計を、みんなの前で自発していた。", "explanation": "ここは〈自慢〉の意味。得意げに見せることは自発ではなく自慢と言うので合わない。"}, {"text": "感染が広がり、市は外出を自発するよう呼びかけた。", "explanation": "ここは〈自粛〉の意味。進んで控えることは自発ではなく自粛と言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37472, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、孫の自発な行動を見守ることにした。", "corrected_sentence": "祖母は、孫の自発的な行動を見守ることにした。", "error_description": "形の誤り。「自発」は名詞なので「な」を直接つけて「自発な」とするのは誤り。正しくは「自発的な」（または「自発の」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37472, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生の指示ではなく、生徒は自発から研究を始めた。", "corrected_sentence": "先生の指示ではなく、生徒は自発的に研究を始めた。", "error_description": "助詞の誤り。「自発から」は起点を表し、研究を始める理由として意味が通らない。正しくは「自発的に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
