INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37473, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "他の人に言われなくても、自分の意志で行動すること。", "primary_collocate": null, "pronunciation": "じはつ", "ipa": "dʑihatsɯ", "syllable_count": 3, "sentences": [{"text": "弟は親に言われなくても部屋の掃除を始めた。その自発に、母は大いに感心した。", "target_word": "自発", "complexity_tier": "T3", "furigana": "弟[おとうと]は親[おや]に言[い]われなくても部屋[へや]の掃除[そうじ]を始[はじ]めた。その自発[じはつ]に、母[はは]は大[おお]いに感心[かんしん]した。", "sentence_source": "generated"}, {"text": "母に頼まれる前に皿を洗ったのは、私の自発だ。", "target_word": "自発", "complexity_tier": "T3", "furigana": "母[はは]に頼[たの]まれる前[まえ]に皿[さら]を洗[あら]ったのは、私[わたし]の自発[じはつ]だ。", "sentence_source": "generated"}, {"text": "新人の自発を評価して、課長は彼に大きな仕事を任せた。", "target_word": "自発", "complexity_tier": "T4", "furigana": "新人[しんじん]の自発[じはつ]を評価[ひょうか]して、課長[かちょう]は彼[かれ]に大[おお]きな仕事[しごと]を任[まか]せた。", "sentence_source": "generated"}, {"text": "先輩に言われたからではなく、この練習はあくまで私の自発によるものだ。", "target_word": "自発", "complexity_tier": "T3", "furigana": "先輩[せんぱい]に言[い]われたからではなく、この練習[れんしゅう]はあくまで私[わたし]の自発[じはつ]によるものだ。", "sentence_source": "generated"}, {"text": "指示がなくても、自発の行動ができる人が求められる。", "target_word": "自発", "complexity_tier": "T4", "furigana": "指示[しじ]がなくても、自発[じはつ]の行動[こうどう]ができる人[ひと]が求[もと]められる。", "sentence_source": "generated"}, {"text": "彼女が夜まで残って片付けたのは、誰かの命令ではなく自発だった。", "target_word": "自発", "complexity_tier": "T4", "furigana": "彼女[かのじょ]が夜[よる]まで残[のこ]って片付[かたづ]けたのは、誰[だれ]かの命令[めいれい]ではなく自発[じはつ]だった。", "sentence_source": "generated"}, {"text": "親に見張られて覚える勉強より、子どもの自発から生まれた勉強のほうが身につく。", "target_word": "自発", "complexity_tier": "T3", "furigana": "親[おや]に見張[みは]られて覚[おぼ]える勉強[べんきょう]より、子[こ]どもの自発[じはつ]から生[う]まれた勉強[べんきょう]のほうが身[み]につく。", "sentence_source": "generated"}, {"text": "誰も頼んでいないので、この手伝いは完全に自発だ。", "target_word": "自発", "complexity_tier": "T3", "furigana": "誰[だれ]も頼[たの]んでいないので、この手伝[てつだ]いは完全[かんぜん]に自発[じはつ]だ。", "sentence_source": "generated"}, {"text": "頼まれた仕事ではなく自発によるものなので、お金はもらわない。", "target_word": "自発", "complexity_tier": "T3", "furigana": "頼[たの]まれた仕事[しごと]ではなく自発[じはつ]によるものなので、お金[かね]はもらわない。", "sentence_source": "generated"}, {"text": "部員の自発によって、毎朝のグラウンド整備が続いている。", "target_word": "自発", "complexity_tier": "T4", "furigana": "部員[ぶいん]の自発[じはつ]によって、毎朝[まいあさ]のグラウンド整備[せいび]が続[つづ]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自発", "label": "基本形"}, {"form": "自発の", "label": "連体形（の）"}, {"form": "自発で", "label": "で格形"}, {"form": "自発だ", "label": "断定形"}], "register": "やや硬い（普通体）", "sense_fingerprint": "指示や依頼がなくても、自分の意志で動くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18652b11-0c76-4c07-b9a2-da1d1612a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37473, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自発", "is_correct": true, "explanation": "「その自発に感心した」で、自分から動いたことを指す。"}, {"text": "寝坊", "is_correct": false, "explanation": "朝に起きられない意味で、感心する対象にはならない。"}, {"text": "出費", "is_correct": false, "explanation": "お金を使うことの意味で、感心する理由にはならない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さの意味で、感心する対象としては合わない。"}], "explanations": {"自発": "「その自発に感心した」で、自分から動いたことを指す。", "寝坊": "朝に起きられない意味で、感心する対象にはならない。", "出費": "お金を使うことの意味で、感心する理由にはならない。", "体重": "体の重さの意味で、感心する対象としては合わない。"}, "sentence_index": 0, "correct_answer": "自発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は隠していた借金を、ついに自発した。", "explanation": "ここは〈白状〉の意味。隠していたことを打ち明けるのは自発ではなく白状と言うので合わない。"}, {"text": "昨日勝った試合の話を、彼は得意げに自発していた。", "explanation": "ここは〈自慢〉の意味。得意げに話すことは自発ではなく自慢と言うので合わない。"}, {"text": "先生に自発で指名されて、みんなの前で発表した。", "explanation": "ここは〈指名〉の意味。先生が人を選ぶことは自発ではなく指名と言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37473, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自発", "is_correct": true, "explanation": "「子どもの自発から生まれた」で、自分から動いたことを指す。"}, {"text": "栄養", "is_correct": false, "explanation": "体の養分の意味で、勉強が生まれる起点としては合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度の意味で、勉強の起点としては合わない。"}, {"text": "寝癖", "is_correct": false, "explanation": "寝ている間にできる髪の乱れで、勉強とは結びつかない。"}], "explanations": {"自発": "「子どもの自発から生まれた」で、自分から動いたことを指す。", "栄養": "体の養分の意味で、勉強が生まれる起点としては合わない。", "体温": "体の温度の意味で、勉強の起点としては合わない。", "寝癖": "寝ている間にできる髪の乱れで、勉強とは結びつかない。"}, "sentence_index": 6, "correct_answer": "自発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新人が会議を自発して、議題を次々に決めた。", "explanation": "ここは〈主導〉の意味。会議を引っ張って進めることは自発ではなく主導と言うので合わない。"}, {"text": "配達の遅れを自発したので、客は安心した。", "explanation": "ここは〈解決〉の意味。問題を片付けることは自発ではなく解決と言うので合わない。"}, {"text": "彼は失礼な態度を、取引先に自発した。", "explanation": "ここは〈謝罪〉の意味。詫びることは自発ではなく謝罪と言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37473, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "誰にも言われず、彼女は自発な行動として部屋を片付けた。", "corrected_sentence": "誰にも言われず、彼女は自発の行動として部屋を片付けた。", "error_description": "形の誤り。「自発」は名詞なので「な」ではなく「の」でつなぐ。「自発な」は誤りで、正しくは「自発の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37473, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "命令されなくても、彼は自発が掃除を始めた。", "corrected_sentence": "命令されなくても、彼は自発的に掃除を始めた。", "error_description": "助詞の誤り。「自発が」は自発を主語にしてしまう誤り。正しくは「自発的に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
