INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37474, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「変化に適応できず」の「に」で、適応する対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「変化が適応できず」では、変化が主語になり文の流れが合わない。"}, {"text": "の", "is_correct": false, "explanation": "「変化の適応できず」では、適応の対象がつながらず文が合わない。"}, {"text": "から", "is_correct": false, "explanation": "「変化から適応できず」では、起点を示す「から」が合わない。"}], "correct_answer": "に", "explanations": {"に": "「変化に適応できず」の「に」で、適応する対象を示す。", "が": "「変化が適応できず」では、変化が主語になり文の流れが合わない。", "の": "「変化の適応できず」では、適応の対象がつながらず文が合わない。", "から": "「変化から適応できず」では、起点を示す「から」が合わない。"}, "error_tags": {"が": "主語の誤り", "の": "連体修飾の誤り", "から": "起点の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37474, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "新しいことにうまく合わせること。", "primary_collocate": null, "pronunciation": "てきおう", "ipa": "tekioː", "syllable_count": 4, "sentences": [{"text": "転校した妹は、新しい学校にすぐ適応した。", "target_word": "適応", "complexity_tier": "T3", "furigana": "転校[てんこう]した妹[いもうと]は、新[あたら]しい学校[がっこう]にすぐ適応[てきおう]した。", "sentence_source": "generated"}, {"text": "海外に引っ越した当初は、食べ物の違いに適応するのが大変だった。", "target_word": "適応", "complexity_tier": "T4", "furigana": "海外[かいがい]に引[ひ]っ越[こ]した当初[とうしょ]は、食[た]べ物[もの]の違[ちが]いに適応[てきおう]するのが大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "人間は環境の変化に適応して生きてきた。", "target_word": "適応", "complexity_tier": "T3", "furigana": "人間[にんげん]は環境[かんきょう]の変化[へんか]に適応[てきおう]して生[い]きてきた。", "sentence_source": "generated"}, {"text": "新入社員が職場に適応するまで、先輩が仕事を教える。", "target_word": "適応", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]が職場[しょくば]に適応[てきおう]するまで、先輩[せんぱい]が仕事[しごと]を教[おし]える。", "sentence_source": "generated"}, {"text": "寒い地域に住む動物は、寒さに適応した体をしている。", "target_word": "適応", "complexity_tier": "T3", "furigana": "寒[さむ]い地域[ちいき]に住[す]む動物[どうぶつ]は、寒[さむ]さに適応[てきおう]した体[からだ]をしている。", "sentence_source": "generated"}, {"text": "新しい制度への適応には、時間がかかる。", "target_word": "適応", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]への適応[てきおう]には、時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "留学生は、日本の生活に適応するために毎日日本語を話した。", "target_word": "適応", "complexity_tier": "T4", "furigana": "留学生[りゅうがくせい]は、日本[にほん]の生活[せいかつ]に適応[てきおう]するために毎日[まいにち]日本語[にほんご]を話[はな]した。", "sentence_source": "generated"}, {"text": "急な変化に適応できず、彼は仕事を辞めてしまった。", "target_word": "適応", "complexity_tier": "T3", "furigana": "急[きゅう]な変化[へんか]に適応[てきおう]できず、彼[かれ]は仕事[しごと]を辞[や]めてしまった。", "sentence_source": "generated"}, {"text": "子どもは大人よりも早く新しい環境に適応する。", "target_word": "適応", "complexity_tier": "T3", "furigana": "子[こ]どもは大人[おとな]よりも早[はや]く新[あたら]しい環境[かんきょう]に適応[てきおう]する。", "sentence_source": "generated"}, {"text": "暑さに適応するため、体が少しずつ汗をかきやすくなる。", "target_word": "適応", "complexity_tier": "T4", "furigana": "暑[あつ]さに適応[てきおう]するため、体[からだ]が少[すこ]しずつ汗[あせ]をかきやすくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "適応する", "label": "辞書形"}, {"form": "適応します", "label": "丁寧形"}, {"form": "適応した", "label": "過去形"}, {"form": "適応して", "label": "て形"}, {"form": "適応しない", "label": "否定形"}, {"form": "適応できる", "label": "可能形"}], "register": "中立（普通体）", "sense_fingerprint": "新しい環境・変化・生活にうまくなじんで合わせること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18652b11-0c76-4c07-b9a2-da1d1612a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37474, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "適応", "is_correct": true, "explanation": "「新しい学校にすぐ適応した」で、環境になじんだ意味に合う。"}, {"text": "解体", "is_correct": false, "explanation": "分解する意味で、学校には使わないので合わない。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつける意味で、学校になじむ意味とは合わない。"}, {"text": "点検", "is_correct": false, "explanation": "調べて確かめる意味で、ここに入ると意味が通らない。"}], "explanations": {"適応": "「新しい学校にすぐ適応した」で、環境になじんだ意味に合う。", "解体": "分解する意味で、学校には使わないので合わない。", "採点": "点数をつける意味で、学校になじむ意味とは合わない。", "点検": "調べて確かめる意味で、ここに入ると意味が通らない。"}, "sentence_index": 0, "correct_answer": "適応"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テストの問題に適応に答えた。", "explanation": "ここは〈適当〉の意味。いい加減に、または程よく答えることは適応ではなく適当と言うので合わない。"}, {"text": "新しいコンテストに適応した。", "explanation": "ここは〈応募〉の意味。申し込んで加わることは適応ではなく応募と言うので合わない。"}, {"text": "先生の質問に適応した。", "explanation": "ここは〈応答〉の意味。質問に返事をすることは適応ではなく応答と言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37474, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "適応", "is_correct": true, "explanation": "「日本の生活に適応するために」で、新しい環境になじむ意味に合う。"}, {"text": "反省", "is_correct": false, "explanation": "自分の行いを振り返る意味で、生活になじむ意味とは合わない。"}, {"text": "修理", "is_correct": false, "explanation": "壊れたものを直す意味で、生活には使わないので合わない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを終える意味で、生活の空欄には入らない。"}], "explanations": {"適応": "「日本の生活に適応するために」で、新しい環境になじむ意味に合う。", "反省": "自分の行いを振り返る意味で、生活になじむ意味とは合わない。", "修理": "壊れたものを直す意味で、生活には使わないので合わない。", "解散": "集まりを終える意味で、生活の空欄には入らない。"}, "sentence_index": 6, "correct_answer": "適応"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この服のサイズは、体にぴったり適応している。", "explanation": "ここは〈適合〉の意味。物や服が体に合うことは適応ではなく適合と言うので合わない。"}, {"text": "毎朝のランニングを、三か月間適応した。", "explanation": "ここは〈継続〉の意味。続けることは適応ではなく継続と言うので合わない。"}, {"text": "作品をコンクールに適応した。", "explanation": "ここは〈出品〉の意味。作品を出して見てもらうことは適応ではなく出品と言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37474, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい職場に適応られる人は、少しずつ増えている。", "corrected_sentence": "新しい職場に適応できる人は、少しずつ増えている。", "error_description": "活用の誤り。「適応する」の可能形は「適応できる」で、「適応られる」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37474, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい環境を適応するのは、時間がかかる。", "corrected_sentence": "新しい環境に適応するのは、時間がかかる。", "error_description": "助詞の誤り。「適応する」は「環境に適応する」のように「に」を取るので、「を」は誤り。正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37477, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「リーダーとして」で、役割・立場を表す。"}, {"text": "が", "is_correct": false, "explanation": "「リーダーが」と続けると主語になり、「して練習を始める」につながらない。"}, {"text": "を", "is_correct": false, "explanation": "「リーダーをして」は役割を表す言い方として不自然で、文の流れに合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「リーダーへして」は成立せず、方向を表す用法にもならない。"}], "correct_answer": "と", "explanations": {"と": "「リーダーとして」で、役割・立場を表す。", "が": "「リーダーが」と続けると主語になり、「して練習を始める」につながらない。", "を": "「リーダーをして」は役割を表す言い方として不自然で、文の流れに合わない。", "へ": "「リーダーへして」は成立せず、方向を表す用法にもならない。"}, "error_tags": {"と": "役割・資格", "が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37477, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37477, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "集団や組織の先頭に立って、他の人を導く役割の人。", "primary_collocate": null, "pronunciation": "りーだー", "ipa": "ɾiːdaː", "syllable_count": 4, "sentences": [{"text": "この組織のリーダーは、先頭に立って仕事を進めている。", "target_word": "リーダー", "complexity_tier": "T3", "furigana": "この組織[そしき]のリーダーは、先頭[せんとう]に立[た]って仕事[しごと]を進[すす]めている。", "sentence_source": "generated"}, {"text": "サッカー部のリーダーとして、彼は毎朝だれよりも早く練習を始める。", "target_word": "リーダー", "complexity_tier": "T3", "furigana": "サッカー部[ぶ]のリーダーとして、彼[かれ]は毎朝[まいあさ]だれよりも早[はや]く練習[れんしゅう]を始[はじ]める。", "sentence_source": "generated"}, {"text": "リーダーの話し方ひとつで、チームの雰囲気は変わる。", "target_word": "リーダー", "complexity_tier": "T3", "furigana": "リーダーの話[はな]し方[かた]ひとつで、チームの雰囲気[ふんいき]は変[か]わる。", "sentence_source": "generated"}, {"text": "若いリーダーが、古い習慣を変えようとしている。", "target_word": "リーダー", "complexity_tier": "T3", "furigana": "若[わか]いリーダーが、古[ふる]い習慣[しゅうかん]を変[か]えようとしている。", "sentence_source": "generated"}, {"text": "災害のとき、地域のリーダーが住民を避難所へ導いた。", "target_word": "リーダー", "complexity_tier": "T3", "furigana": "災害[さいがい]のとき、地域[ちいき]のリーダーが住民[じゅうみん]を避難所[ひなんじょ]へ導[みちび]いた。", "sentence_source": "generated"}, {"text": "グループのリーダーは、メンバー全員の名前を覚えている。", "target_word": "リーダー", "complexity_tier": "T3", "furigana": "グループのリーダーは、メンバー全員[ぜんいん]の名前[なまえ]を覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "先生は私をクラスのリーダーに選んでくれた。", "target_word": "リーダー", "complexity_tier": "T3", "furigana": "先生[せんせい]は私[わたし]をクラスのリーダーに選[えら]んでくれた。", "sentence_source": "generated"}, {"text": "リーダーには、責任を取る覚悟が必要だ。", "target_word": "リーダー", "complexity_tier": "T3", "furigana": "リーダーには、責任[せきにん]を取[と]る覚悟[かくご]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "私は人を導くリーダーより、支える側の仕事が向いている。", "target_word": "リーダー", "complexity_tier": "T3", "furigana": "私[わたし]は人[ひと]を導[みちび]くリーダーより、支[ささ]える側[がわ]の仕事[しごと]が向[む]いている。", "sentence_source": "generated"}, {"text": "登山隊のリーダーが、天気を見て出発を延ばした。", "target_word": "リーダー", "complexity_tier": "T3", "furigana": "登山隊[とざんたい]のリーダーが、天気[てんき]を見[み]て出発[しゅっぱつ]を延[の]ばした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "リーダー", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "組織や集団の先頭に立って人を導く役割の人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c94323-d2a7-4136-9285-064b10d13ae7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37477, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "リーダー", "is_correct": true, "explanation": "組織の先頭に立って進める人を指すので、主語として文に合う。"}, {"text": "ラベル", "is_correct": false, "explanation": "貼り紙の一種で、先頭に立って仕事を進めることはできない。"}, {"text": "ポスター", "is_correct": false, "explanation": "掲示物で、先頭に立つ主体にはならない。"}, {"text": "ファイル", "is_correct": false, "explanation": "書類を綴る道具で、仕事を進める主体にはならない。"}], "explanations": {"リーダー": "組織の先頭に立って進める人を指すので、主語として文に合う。", "ラベル": "貼り紙の一種で、先頭に立って仕事を進めることはできない。", "ポスター": "掲示物で、先頭に立つ主体にはならない。", "ファイル": "書類を綴る道具で、仕事を進める主体にはならない。"}, "sentence_index": 0, "correct_answer": "リーダー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜の海で、リーダーが近づく船の位置を映し出した。", "explanation": "ここは〈レーダー〉（電波で物体を探る装置）の意味。リーダーは人を指すので、船の位置を映す装置にはならない。"}, {"text": "屋根に掛けたリーダーを登って、雨どいを直した。", "explanation": "ここは〈ラダー〉（はしご）の意味。リーダーは人を導く役割で、登る道具ではない。"}, {"text": "後半、三点のリーダーを奪われて負けた。", "explanation": "ここは〈リード〉（得点の差）の意味。リーダーは人を指すので、点差は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37477, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "リーダー", "is_correct": true, "explanation": "「クラスのリーダーに選ぶ」で、役割を担う人を表し文に合う。"}, {"text": "グラウンド", "is_correct": false, "explanation": "運動場で、クラスの役割に選ばれることはない。"}, {"text": "プリント", "is_correct": false, "explanation": "配布物で、クラスの役割に選ばれることはない。"}, {"text": "ロッカー", "is_correct": false, "explanation": "収納設備で、クラスの役割に選ばれることはない。"}], "explanations": {"リーダー": "「クラスのリーダーに選ぶ」で、役割を担う人を表し文に合う。", "グラウンド": "運動場で、クラスの役割に選ばれることはない。", "プリント": "配布物で、クラスの役割に選ばれることはない。", "ロッカー": "収納設備で、クラスの役割に選ばれることはない。"}, "sentence_index": 6, "correct_answer": "リーダー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この作家のリーダーは、新聞に連載された長編小説だ。", "explanation": "ここは〈代表〉（代表作）の意味。リーダーは人を指すので、作品を指す語にはならない。"}, {"text": "荷物の箱に、リーダーを貼って宛先を書いた。", "explanation": "ここは〈ラベル〉（貼り札）の意味。リーダーは人を導く役割で、貼る札ではない。"}, {"text": "リーダー柄のシャツを着て、街を歩いた。", "explanation": "ここは〈ボーダー〉（横じまの柄）の意味。リーダーは人を導く役割で、柄の名前にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37477, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は班のリーダーに務めている。", "corrected_sentence": "彼は班のリーダーを務めている。", "error_description": "「務める」は「〜を務める」と目的語を取るので「を」が正しい。「に」にすると文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37477, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は私をクラスのリーダーが指名してくれた。", "corrected_sentence": "先生は私をクラスのリーダーに指名してくれた。", "error_description": "「リーダーに指名」の「に」は、指名された役割を表す。「リーダーが」にすると主語になり、文の構造が壊れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37478, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「権威が弱まる」の「が」。弱まるという変化の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「権威を弱まり」は目的語の形だが、弱まるは自動詞なので目的語を取れず合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着点や相手を示すが、「権威に弱まり」は文として続かない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「権威で弱まり」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「権威が弱まる」の「が」。弱まるという変化の主語を示す。", "を": "「権威を弱まり」は目的語の形だが、弱まるは自動詞なので目的語を取れず合わない。", "に": "「に」は着点や相手を示すが、「権威に弱まり」は文として続かない。", "で": "「で」は手段や場所を示すが、「権威で弱まり」は意味が通らない。"}, "error_tags": {"を": "目的語", "に": "着点・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37478, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「権威がある」の「が」。存在する対象を示す形で、この文の述語に合う。"}, {"text": "と", "is_correct": false, "explanation": "「権威と」は並列や相手を示すが、「権威とある」は文として続かない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すが、「権威よりある」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「権威へある」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「権威がある」の「が」。存在する対象を示す形で、この文の述語に合う。", "と": "「権威と」は並列や相手を示すが、「権威とある」は文として続かない。", "より": "「より」は比較の基準を示すが、「権威よりある」は意味が通らない。", "へ": "「へ」は方向を示すが、「権威へある」は成り立たない。"}, "error_tags": {"と": "並列・相手", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37478, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他の人に「すごい」と思われて、言うことを聞いてもらえる力のこと。", "primary_collocate": null, "pronunciation": "けんい", "ipa": "keŋi", "syllable_count": 3, "sentences": [{"text": "その教授は、医学の世界で大きな権威を持っている。", "target_word": "権威", "complexity_tier": "T3", "furigana": "その教授[きょうじゅ]は、医学[いがく]の世界[せかい]で大[おお]きな権威[けんい]を持[も]っている。", "sentence_source": "generated"}, {"text": "校長の権威が弱まり、生徒は話を聞かなくなった。", "target_word": "権威", "complexity_tier": "T3", "furigana": "校長[こうちょう]の権威[けんい]が弱[よわ]まり、生徒[せいと]は話[はなし]を聞[き]かなくなった。", "sentence_source": "generated"}, {"text": "彼は権威があるので、彼の意見には誰も反対しない。", "target_word": "権威", "complexity_tier": "T3", "furigana": "彼[かれ]は権威[けんい]があるので、彼[かれ]の意見[いけん]には誰[だれ]も反対[はんたい]しない。", "sentence_source": "generated"}, {"text": "親は権威を使って、子どもを無理に従わせてはいけない。", "target_word": "権威", "complexity_tier": "T3", "furigana": "親[おや]は権威[けんい]を使[つか]って、子[こ]どもを無理[むり]に従[したが]わせてはいけない。", "sentence_source": "generated"}, {"text": "その研究者は長年の成果によって、この分野で確かな権威を築いた。", "target_word": "権威", "complexity_tier": "T3", "furigana": "その研究者[けんきゅうしゃ]は長年[ながねん]の成果[せいか]によって、この分野[ぶんや]で確[たし]かな権威[けんい]を築[きず]いた。", "sentence_source": "generated"}, {"text": "権威だけに頼る先生は、生徒に尊敬されない。", "target_word": "権威", "complexity_tier": "T3", "furigana": "権威[けんい]だけに頼[たよ]る先生[せんせい]は、生徒[せいと]に尊敬[そんけい]されない。", "sentence_source": "generated"}, {"text": "優れた研究を続けて、彼は自分の権威を高めた。", "target_word": "権威", "complexity_tier": "T4", "furigana": "優[すぐ]れた研究[けんきゅう]を続[つづ]けて、彼[かれ]は自分[じぶん]の権威[けんい]を高[たか]めた。", "sentence_source": "generated"}, {"text": "彼の話し方には、人を従わせる権威がある。", "target_word": "権威", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はな]し方[かた]には、人[ひと]を従[したが]わせる権威[けんい]がある。", "sentence_source": "generated"}, {"text": "失敗が続き、監督の権威は失われた。", "target_word": "権威", "complexity_tier": "T3", "furigana": "失敗[しっぱい]が続[つづ]き、監督[かんとく]の権威[けんい]は失[うしな]われた。", "sentence_source": "generated"}, {"text": "子どもは、権威のある人の言葉を素直に信じやすい。", "target_word": "権威", "complexity_tier": "T4", "furigana": "子[こ]どもは、権威[けんい]のある人[ひと]の言葉[ことば]を素直[すなお]に信[しん]じやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "権威", "label": "基本形"}, {"form": "権威の", "label": "連体形（の）"}, {"form": "権威を", "label": "目的語形（を）"}, {"form": "権威がある", "label": "存在表現"}], "register": "やや硬い（普通体）", "sense_fingerprint": "人から尊敬され、その言葉に従ってもらえる力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18652b11-0c76-4c07-b9a2-da1d1612a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37478, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "権威", "is_correct": true, "explanation": "「権威」は人が従い尊敬する力のこと。医学界で教授が大きな影響力を持つ、という文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は持つものではないので、「大きな天気を持っている」は成り立たない。"}, {"text": "段差", "is_correct": false, "explanation": "「段差」は床や道の高低差を指し、人の影響力を表せない。「大きな段差を持つ」とは言えない。"}, {"text": "季節", "is_correct": false, "explanation": "「季節」は時期を指し、人が持つ力や地位を表さない。「大きな季節を持つ」は不自然。"}], "explanations": {"権威": "「権威」は人が従い尊敬する力のこと。医学界で教授が大きな影響力を持つ、という文脈に合う。", "天気": "「天気」は持つものではないので、「大きな天気を持っている」は成り立たない。", "段差": "「段差」は床や道の高低差を指し、人の影響力を表せない。「大きな段差を持つ」とは言えない。", "季節": "「季節」は時期を指し、人が持つ力や地位を表さない。「大きな季節を持つ」は不自然。"}, "sentence_index": 0, "correct_answer": "権威"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風の権威で、今日は電車が全部止まった。", "explanation": "〈影響〉の意味。台風が原因なら「影響」が自然で、権威は人が従う力や尊敬を指すので合わない。"}, {"text": "この薬は権威が強く、飲むと眠くなる。", "explanation": "〈作用〉の意味。薬が体に及ぼす働きには「作用」を使う。権威は人を従わせる力なので合わない。"}, {"text": "この料理は権威が薄く、味がぼやけている。", "explanation": "〈風味〉の意味。料理の香りや味わいには「風味」を使う。権威は人への影響力を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37478, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "権威", "is_correct": true, "explanation": "「自分の権威」は人から尊敬され従ってもらえる力。研究を重ねて高めた、という文に合う。"}, {"text": "名残", "is_correct": false, "explanation": "「名残」は残った気配や余韻を指し、高めるものではないので合わない。"}, {"text": "出費", "is_correct": false, "explanation": "「出費」は支払うお金のことで、人の評価を高める対象ではない。"}, {"text": "寝息", "is_correct": false, "explanation": "「寝息」は眠っている人の呼吸音で、高めるという動詞とは結びつかない。"}], "explanations": {"権威": "「自分の権威」は人から尊敬され従ってもらえる力。研究を重ねて高めた、という文に合う。", "名残": "「名残」は残った気配や余韻を指し、高めるものではないので合わない。", "出費": "「出費」は支払うお金のことで、人の評価を高める対象ではない。", "寝息": "「寝息」は眠っている人の呼吸音で、高めるという動詞とは結びつかない。"}, "sentence_index": 6, "correct_answer": "権威"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "口座の権威が十万円を下回った。", "explanation": "〈残高〉の意味。口座の金額には「残高」を使う。権威は人の社会的な影響力なので合わない。"}, {"text": "熱のせいで、子どもの権威が三十九度まで上がった。", "explanation": "〈体温〉の意味。熱の数値には「体温」を使う。権威は数値で表せないので合わない。"}, {"text": "列車の権威が時速百キロを超えた。", "explanation": "〈速度〉の意味。乗り物の速さには「速度」を使う。権威は速さの単位で測れないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37478, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その先生は、生徒を従わせる権威が持っている。", "corrected_sentence": "その先生は、生徒を従わせる権威を持っている。", "error_description": "「権威」は「持つ」の目的語なので、助詞は「を」が正しい。「が」にすると権威が主語になり、先生が持つという文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37478, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は権威を振り込まず、生徒と話し合った。", "corrected_sentence": "先生は権威を振りかざさず、生徒と話し合った。", "error_description": "「権威」と自然に結びつく動詞は「振りかざす」（力や地位を見せつけて使う）。「振り込む」は金銭を送る意味なので、権威とは組み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37479, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「王の権威は」の「は」。権威を文の主題として示す。"}, {"text": "を", "is_correct": false, "explanation": "「権威を」は目的語。受身の文で権威が主題なので、目的語の形は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「権威へ、国民の信頼によって支えられていた」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を続ける助詞だが、この位置では「権威の、」と文が途切れてしまい成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「王の権威は」の「は」。権威を文の主題として示す。", "を": "「権威を」は目的語。受身の文で権威が主題なので、目的語の形は合わない。", "へ": "「へ」は方向を示すが、「権威へ、国民の信頼によって支えられていた」は意味が通らない。", "の": "「の」は名詞を続ける助詞だが、この位置では「権威の、」と文が途切れてしまい成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37479, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「権威のある団体」の「の」。権威を「ある」にかかる連体修飾として示す。"}, {"text": "を", "is_correct": false, "explanation": "「権威を」は目的語の形だが、「ある」は目的語を取らないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「権威とある」は並列を示すが、続きの「ある団体」と結びつかない。"}, {"text": "より", "is_correct": false, "explanation": "「権威よりある」は比較を示すが、「ある団体」を修飾できず合わない。"}], "correct_answer": "の", "explanations": {"の": "「権威のある団体」の「の」。権威を「ある」にかかる連体修飾として示す。", "を": "「権威を」は目的語の形だが、「ある」は目的語を取らないので合わない。", "と": "「権威とある」は並列を示すが、続きの「ある団体」と結びつかない。", "より": "「権威よりある」は比較を示すが、「ある団体」を修飾できず合わない。"}, "error_tags": {"を": "目的語", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37479, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会や集団の中で、人の行動や考えに影響を与えることのできる力や地位。", "primary_collocate": null, "pronunciation": "けんい", "ipa": "keŋi", "syllable_count": 3, "sentences": [{"text": "古い組織では、年上の人の権威が強い。", "target_word": "権威", "complexity_tier": "T3", "furigana": "古[ふる]い組織[そしき]では、年上[としうえ]の人[ひと]の権威[けんい]が強[つよ]い。", "sentence_source": "generated"}, {"text": "王の権威は、国民の信頼によって支えられていた。", "target_word": "権威", "complexity_tier": "T3", "furigana": "王[おう]の権威[けんい]は、国民[こくみん]の信頼[しんらい]によって支[ささ]えられていた。", "sentence_source": "generated"}, {"text": "裁判所は、法律に基づく権威を持っている。", "target_word": "権威", "complexity_tier": "T4", "furigana": "裁判所[さいばんしょ]は、法律[ほうりつ]に基[もと]づく権威[けんい]を持[も]っている。", "sentence_source": "generated"}, {"text": "宗教の権威が強かった時代、人々は教会の教えに従った。", "target_word": "権威", "complexity_tier": "T4", "furigana": "宗教[しゅうきょう]の権威[けんい]が強[つよ]かった時代[じだい]、人々[ひとびと]は教会[きょうかい]の教[おし]えに従[したが]った。", "sentence_source": "generated"}, {"text": "不正が見つかり、社長は会社の中での権威を失った。", "target_word": "権威", "complexity_tier": "T4", "furigana": "不正[ふせい]が見[み]つかり、社長[しゃちょう]は会社[かいしゃ]の中[なか]での権威[けんい]を失[うしな]った。", "sentence_source": "generated"}, {"text": "政府の権威を守るため、役人は規則を厳しく守った。", "target_word": "権威", "complexity_tier": "T4", "furigana": "政府[せいふ]の権威[けんい]を守[まも]るため、役人[やくにん]は規則[きそく]を厳[きび]しく守[まも]った。", "sentence_source": "generated"}, {"text": "村の長老は、地位に伴う権威で争いをおさめた。", "target_word": "権威", "complexity_tier": "T4", "furigana": "村[むら]の長老[ちょうろう]は、地位[ちい]に伴[ともな]う権威[けんい]で争[あらそ]いをおさめた。", "sentence_source": "generated"}, {"text": "権威のある団体が発表した調査なので、多くの人が信じた。", "target_word": "権威", "complexity_tier": "T4", "furigana": "権威[けんい]のある団体[だんたい]が発表[はっぴょう]した調査[ちょうさ]なので、多[おお]くの人[ひと]が信[しん]じた。", "sentence_source": "generated"}, {"text": "若者の中には、権威に反発する人も少なくない。", "target_word": "権威", "complexity_tier": "T3", "furigana": "若者[わかもの]の中[なか]には、権威[けんい]に反発[はんぱつ]する人[ひと]も少[すく]なくない。", "sentence_source": "generated"}, {"text": "大学の権威が高まるにつれて、入学を希望する学生が増えた。", "target_word": "権威", "complexity_tier": "T4", "furigana": "大学[だいがく]の権威[けんい]が高[たか]まるにつれて、入学[にゅうがく]を希望[きぼう]する学生[がくせい]が増[ふ]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "権威", "label": "基本形"}, {"form": "権威の", "label": "連体形（の）"}, {"form": "権威に", "label": "に格形"}, {"form": "権威がある", "label": "存在表現"}], "register": "硬い（普通体）", "sense_fingerprint": "社会・組織の中の地位に基づいて人々の行動や考えを左右する力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18652b11-0c76-4c07-b9a2-da1d1612a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37479, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "権威", "is_correct": true, "explanation": "「年上の人の権威」は社会の中の地位に基づく影響力。強いと言えるので文に合う。"}, {"text": "季節", "is_correct": false, "explanation": "「季節が強い」とは言えず、人の地位や影響力を表せない。"}, {"text": "段差", "is_correct": false, "explanation": "「段差が強い」は不自然で、人の立場を指すことはできない。"}, {"text": "日程", "is_correct": false, "explanation": "「日程が強い」は成り立たず、人の影響力を表さない。"}], "explanations": {"権威": "「年上の人の権威」は社会の中の地位に基づく影響力。強いと言えるので文に合う。", "季節": "「季節が強い」とは言えず、人の地位や影響力を表せない。", "段差": "「段差が強い」は不自然で、人の立場を指すことはできない。", "日程": "「日程が強い」は成り立たず、人の影響力を表さない。"}, "sentence_index": 0, "correct_answer": "権威"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "通帳の権威が十万円を下回った。", "explanation": "〈残高〉の意味。通帳の金額には「残高」を使う。権威は社会的地位による影響力を指すので合わない。"}, {"text": "この薬は権威が多すぎると危険だ。", "explanation": "〈用量〉の意味。薬の決まった量には「用量」を使う。権威は量で数えられないので合わない。"}, {"text": "テレビの権威を最大にすると、隣の部屋まで聞こえる。", "explanation": "〈音量〉の意味。テレビの音の大きさには「音量」を使う。権威は人の地位による影響力なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37479, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "権威", "is_correct": true, "explanation": "「地位に伴う権威」は社会的な地位から生まれる影響力。それで争いをおさめる、という文に合う。"}, {"text": "寝具", "is_correct": false, "explanation": "「寝具で争いをおさめる」は成り立たず、人の立場や影響力を表さない。"}, {"text": "温度", "is_correct": false, "explanation": "「温度で争いをおさめる」は不自然で、対人の調停には使えない。"}, {"text": "歯磨き", "is_correct": false, "explanation": "「歯磨きで争いをおさめる」は意味が通らない。"}], "explanations": {"権威": "「地位に伴う権威」は社会的な地位から生まれる影響力。それで争いをおさめる、という文に合う。", "寝具": "「寝具で争いをおさめる」は成り立たず、人の立場や影響力を表さない。", "温度": "「温度で争いをおさめる」は不自然で、対人の調停には使えない。", "歯磨き": "「歯磨きで争いをおさめる」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "権威"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その子の権威が三十キロを超えた。", "explanation": "〈体重〉の意味。人の重さには「体重」を使う。権威は社会的な影響力なので合わない。"}, {"text": "車の権威が時速百キロを超えた。", "explanation": "〈速度〉の意味。車の速さには「速度」を使う。権威は速さを測る対象ではないので合わない。"}, {"text": "この花は権威が強く、部屋中に広がった。", "explanation": "〈香り〉の意味。花の匂いには「香り」を使う。権威は人の影響力を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37479, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校の権威を、生徒からの信頼によって保たれている。", "corrected_sentence": "学校の権威が、生徒からの信頼によって保たれている。", "error_description": "「保たれる」は受身で、「権威」が主語になる。主語を示す「が」が正しく、「を」にすると目的語となり、受身の文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37479, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会長の権威を、長年の実績によって築かれた。", "corrected_sentence": "会長の権威は、長年の実績によって築かれた。", "error_description": "「築かれた」は受身で、権威が主語になる。「を」は目的語を示すので誤りで、主語・主題を示す「は」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
