INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37480, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「実力がついて」の「が」。能力が身につく主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「実力と」は並列を示すが、「実力とついて」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「実力へついて」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、「実力よりついて」は「ついた」の意味に合わない。"}], "correct_answer": "が", "explanations": {"が": "「実力がついて」の「が」。能力が身につく主語を示す。", "と": "「実力と」は並列を示すが、「実力とついて」は文が成り立たない。", "へ": "「へ」は方向を示すが、「実力へついて」は意味が通らない。", "より": "「より」は比較を示すが、「実力よりついて」は「ついた」の意味に合わない。"}, "error_tags": {"と": "並列", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37480, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ほんとうのちから。じぶんの力でできること。", "primary_collocate": null, "pronunciation": "じつりょく", "ipa": "dʑitsɯɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "運ではなく、実力で勝ったと思う。", "target_word": "実力", "complexity_tier": "T3", "furigana": "運[うん]ではなく、実力[じつりょく]で勝[か]ったと思[おも]う。", "sentence_source": "generated"}, {"text": "試合が終わって、やっと彼の実力がわかった。", "target_word": "実力", "complexity_tier": "T3", "furigana": "試合[しあい]が終[お]わって、やっと彼[かれ]の実力[じつりょく]がわかった。", "sentence_source": "generated"}, {"text": "実力があれば、年齢は関係ない。", "target_word": "実力", "complexity_tier": "T3", "furigana": "実力[じつりょく]があれば、年齢[ねんれい]は関係[かんけい]ない。", "sentence_source": "generated"}, {"text": "彼女は緊張して、実力を出せなかった。", "target_word": "実力", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は緊張[きんちょう]して、実力[じつりょく]を出[だ]せなかった。", "sentence_source": "generated"}, {"text": "相手が強くて、自分の実力のなさを知った。", "target_word": "実力", "complexity_tier": "T3", "furigana": "相手[あいて]が強[つよ]くて、自分[じぶん]の実力[じつりょく]のなさを知[し]った。", "sentence_source": "generated"}, {"text": "実力で選ばれたのだから、自信を持っていい。", "target_word": "実力", "complexity_tier": "T3", "furigana": "実力[じつりょく]で選[えら]ばれたのだから、自信[じしん]を持[も]っていい。", "sentence_source": "generated"}, {"text": "本番では、ふだんの実力が出るものだ。", "target_word": "実力", "complexity_tier": "T3", "furigana": "本番[ほんばん]では、ふだんの実力[じつりょく]が出[で]るものだ。", "sentence_source": "generated"}, {"text": "弟は実力がついて、大会に出られるようになった。", "target_word": "実力", "complexity_tier": "T3", "furigana": "弟[おとうと]は実力[じつりょく]がついて、大会[たいかい]に出[で]られるようになった。", "sentence_source": "generated"}, {"text": "親の力ではなく、自分の実力で会社に入った。", "target_word": "実力", "complexity_tier": "T3", "furigana": "親[おや]の力[ちから]ではなく、自分[じぶん]の実力[じつりょく]で会社[かいしゃ]に入[はい]った。", "sentence_source": "generated"}, {"text": "実力を認められて、彼はチームの代表になった。", "target_word": "実力", "complexity_tier": "T3", "furigana": "実力[じつりょく]を認[みと]められて、彼[かれ]はチームの代表[だいひょう]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実力", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "運や助けではなく、その人が本当に持っている力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18652b11-0c76-4c07-b9a2-da1d1612a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37480, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実力", "is_correct": true, "explanation": "「運ではなく実力で」は偶然ではなく本人が持つ力で勝ったという意味で、文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気で勝った」は勝因として成り立たず、運との対比にもならない。"}, {"text": "郵便", "is_correct": false, "explanation": "「郵便で勝った」は意味が通らない。"}, {"text": "写真", "is_correct": false, "explanation": "「写真で勝った」は勝因として不自然で、運と対比させる文脈に合わない。"}], "explanations": {"実力": "「運ではなく実力で」は偶然ではなく本人が持つ力で勝ったという意味で、文に合う。", "天気": "「天気で勝った」は勝因として成り立たず、運との対比にもならない。", "郵便": "「郵便で勝った」は意味が通らない。", "写真": "「写真で勝った」は勝因として不自然で、運と対比させる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "実力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "マラソンの後半で実力が切れ、ついに歩き出した。", "explanation": "〈体力〉の意味。走り続ける体の余力には「体力」を使う。実力は身につけた能力を指すので合わない。"}, {"text": "ご飯がおいしくて、実力が止まらない。", "explanation": "〈食欲〉の意味。食べたい気持ちには「食欲」を使う。実力は能力なので合わない。"}, {"text": "スマホの実力が少なくなったので、充電した。", "explanation": "〈電池〉の意味。機器に残る電気には「電池」を使う。実力は人の能力なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37480, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実力", "is_correct": true, "explanation": "「ふだんの実力」は普段から持っている力。本番で出るという文に合う。"}, {"text": "天井", "is_correct": false, "explanation": "「天井が出る」は意味が通らず、力を表さない。"}, {"text": "照明", "is_correct": false, "explanation": "「照明が出る」は力の発揮を表さず、不自然。"}, {"text": "歯磨き", "is_correct": false, "explanation": "「歯磨きが出る」は意味が通らない。"}], "explanations": {"実力": "「ふだんの実力」は普段から持っている力。本番で出るという文に合う。", "天井": "「天井が出る」は意味が通らず、力を表さない。", "照明": "「照明が出る」は力の発揮を表さず、不自然。", "歯磨き": "「歯磨きが出る」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "実力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "貯金の実力が少なくなったので、今月は買い物を控えた。", "explanation": "〈貯金〉の意味。預けたお金の残りには「貯金」を使う。実力は人の能力を指すので合わない。"}, {"text": "雨の実力が強まり、川の水かさが増えた。", "explanation": "〈雨脚〉の意味。雨の降り方の勢いには「雨脚」を使う。実力は人が身につけた能力なので合わない。"}, {"text": "夜になると実力が増して、コートを着た。", "explanation": "〈寒さ〉の意味。気温の低さが増すことには「寒さ」を使う。実力は人の能力なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37480, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は本番で実力を消費した。", "corrected_sentence": "彼は本番で実力を発揮した。", "error_description": "「実力」と結びつく動詞は「発揮する」。「消費する」は資源や金銭に使う語で、実力とは組み合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37480, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は実力を自信を持ち、試合に臨んだ。", "corrected_sentence": "彼は実力に自信を持ち、試合に臨んだ。", "error_description": "「自信を持つ」の根拠は「実力に」で示す。「実力を」にすると目的語となり、「自信を持つ」の構文が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37481, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「実力をためしたい」の「を」。ためす対象を示す目的語。"}, {"text": "と", "is_correct": false, "explanation": "「実力とためしたい」は並列を示すが、「ためす」と続かず成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「ためす」には目的語が必要なので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「実力がためしたい」は実力を主語にするが、「ためす」は目的語を取るので合わない。"}], "correct_answer": "を", "explanations": {"を": "「実力をためしたい」の「を」。ためす対象を示す目的語。", "と": "「実力とためしたい」は並列を示すが、「ためす」と続かず成り立たない。", "へ": "「へ」は方向を示すが、「ためす」には目的語が必要なので合わない。", "が": "「実力がためしたい」は実力を主語にするが、「ためす」は目的語を取るので合わない。"}, "error_tags": {"と": "並列", "へ": "方向", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37481, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「実力に合った」の「に」。合う対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「実力を合った」は目的語の形だが、「合う」は「に」を取るので不自然。"}, {"text": "で", "is_correct": false, "explanation": "「実力で合った」は手段を示すが、「合う」の対象にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、「実力より合った」は「合う」の意味に合わない。"}], "correct_answer": "に", "explanations": {"に": "「実力に合った」の「に」。合う対象を示す。", "を": "「実力を合った」は目的語の形だが、「合う」は「に」を取るので不自然。", "で": "「実力で合った」は手段を示すが、「合う」の対象にはならない。", "より": "「より」は比較を示すが、「実力より合った」は「合う」の意味に合わない。"}, "error_tags": {"を": "目的語", "で": "手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37481, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実際に持っている能力や技能。勉強や練習で身につけた、自分の力。", "primary_collocate": null, "pronunciation": "じつりょく", "ipa": "dʑitsɯɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "毎日練習したので、英語の実力が上がった。", "target_word": "実力", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]したので、英語[えいご]の実力[じつりょく]が上[あ]がった。", "sentence_source": "generated"}, {"text": "試験で自分の実力をためしたい。", "target_word": "実力", "complexity_tier": "T3", "furigana": "試験[しけん]で自分[じぶん]の実力[じつりょく]をためしたい。", "sentence_source": "generated"}, {"text": "実力をつけるには、基本をくり返すしかない。", "target_word": "実力", "complexity_tier": "T3", "furigana": "実力[じつりょく]をつけるには、基本[きほん]をくり返[かえ]すしかない。", "sentence_source": "generated"}, {"text": "彼のピアノの実力は、プロと同じぐらいだ。", "target_word": "実力", "complexity_tier": "T3", "furigana": "彼[かれ]のピアノの実力[じつりょく]は、プロと同[おな]じぐらいだ。", "sentence_source": "generated"}, {"text": "模擬試験の結果は、今の実力を表している。", "target_word": "実力", "complexity_tier": "T3", "furigana": "模擬[もぎ]試験[しけん]の結果[けっか]は、今[いま]の実力[じつりょく]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "実力が足りなくて、第一志望の学校に落ちた。", "target_word": "実力", "complexity_tier": "T3", "furigana": "実力[じつりょく]が足[た]りなくて、第一[だいいち]志望[しぼう]の学校[がっこう]に落[お]ちた。", "sentence_source": "generated"}, {"text": "勉強を続けて、数学の実力がだいぶ伸びた。", "target_word": "実力", "complexity_tier": "T3", "furigana": "勉強[べんきょう]を続[つづ]けて、数学[すうがく]の実力[じつりょく]がだいぶ伸[の]びた。", "sentence_source": "generated"}, {"text": "先生は生徒の実力に合った問題を選んでくれた。", "target_word": "実力", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の実力[じつりょく]に合[あ]った問題[もんだい]を選[えら]んでくれた。", "sentence_source": "generated"}, {"text": "実力のある選手でも、毎日の練習を休まない。", "target_word": "実力", "complexity_tier": "T3", "furigana": "実力[じつりょく]のある選手[せんしゅ]でも、毎日[まいにち]の練習[れんしゅう]を休[やす]まない。", "sentence_source": "generated"}, {"text": "漢字の実力を高めるために、毎晩二十個ずつ覚えている。", "target_word": "実力", "complexity_tier": "T3", "furigana": "漢字[かんじ]の実力[じつりょく]を高[たか]めるために、毎晩[まいばん]二十個[にじゅっこ]ずつ覚[おぼ]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実力", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "勉強や練習で身につけた、実際に使える能力や技能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18652b11-0c76-4c07-b9a2-da1d1612a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37481, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実力", "is_correct": true, "explanation": "「英語の実力が上がった」は勉強や練習で身につけた英語の力が伸びたという意味で、文に合う。"}, {"text": "天井", "is_correct": false, "explanation": "「英語の天井が上がった」は意味が通らず、力の伸びを表さない。"}, {"text": "季節", "is_correct": false, "explanation": "「英語の季節」は成り立たず、力の伸びを表さない。"}, {"text": "郵便", "is_correct": false, "explanation": "「英語の郵便」は意味が通らない。"}], "explanations": {"実力": "「英語の実力が上がった」は勉強や練習で身につけた英語の力が伸びたという意味で、文に合う。", "天井": "「英語の天井が上がった」は意味が通らず、力の伸びを表さない。", "季節": "「英語の季節」は成り立たず、力の伸びを表さない。", "郵便": "「英語の郵便」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "実力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ピアノの練習で、彼の実力は三十八度まで上がった。", "explanation": "〈体温〉の意味。温度の数値には「体温」を使う。実力は身につけた能力で数値では表せないので合わない。"}, {"text": "倉庫の実力が少なくなったので、注文した。", "explanation": "〈在庫〉の意味。保管している品物の数には「在庫」を使う。実力は人の能力を指すので合わない。"}, {"text": "仕事の実力が多くて、毎晩帰りが遅くなった。", "explanation": "〈残業〉の意味。勤務時間を超えた仕事には「残業」を使う。実力は能力なので量が多いとは言えず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37481, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実力", "is_correct": true, "explanation": "「数学の実力が伸びた」は学習で身につけた力が伸びたという意味で、文に合う。"}, {"text": "温度", "is_correct": false, "explanation": "「数学の温度が伸びた」は意味が通らず、力の伸びを表さない。"}, {"text": "寝具", "is_correct": false, "explanation": "「数学の寝具」は成り立たず、力の伸びを表さない。"}, {"text": "冷房", "is_correct": false, "explanation": "「数学の冷房」は意味が通らない。"}], "explanations": {"実力": "「数学の実力が伸びた」は学習で身につけた力が伸びたという意味で、文に合う。", "温度": "「数学の温度が伸びた」は意味が通らず、力の伸びを表さない。", "寝具": "「数学の寝具」は成り立たず、力の伸びを表さない。", "冷房": "「数学の冷房」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "実力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先月の実力が百万円を超えた。", "explanation": "〈売上〉の意味。店や会社の売上金額には「売上」を使う。実力は能力を指すので合わない。"}, {"text": "弟の実力が十歳になった。", "explanation": "〈年齢〉の意味。人の年数には「年齢」を使う。実力は身につけた能力なので年数で表せず合わない。"}, {"text": "今日は実力が高いので、洗濯物が乾かない。", "explanation": "〈湿度〉の意味。空気中の水分の多さには「湿度」を使う。実力は人の能力で、洗濯物の乾きとは結びつかないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37481, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は毎日練習して、実力を伸びた。", "corrected_sentence": "彼は毎日練習して、実力を伸ばした。", "error_description": "「実力を」の後には他動詞「伸ばす」が続く。自動詞「伸びる」は目的語の「を」と合わないので、「伸ばした」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37481, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は英語の実力に磨いて、留学試験に受かった。", "corrected_sentence": "彼女は英語の実力を磨いて、留学試験に受かった。", "error_description": "「磨く」は「実力を」と結びつく他動詞。「に」にすると目的語が示されず、動詞の構文が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
