INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37482, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「もう」は、あることの上に、さらに何かがあることをあらわす言葉です。", "primary_collocate": null, "pronunciation": "もう", "ipa": "moː", "syllable_count": 2, "sentences": [{"text": "ケーキを食べましたが、もう一つ食べたいです。", "target_word": "もう", "complexity_tier": "T3", "furigana": "ケーキを食[た]べましたが、もう一[ひと]つ食[た]べたいです。", "sentence_source": "generated"}, {"text": "駅で友だちを待っています。もう一人来る予定です。", "target_word": "もう", "complexity_tier": "T3", "furigana": "駅[えき]で友[とも]だちを待[ま]っています。もう一人[ひとり]来[く]る予定[よてい]です。", "sentence_source": "generated"}, {"text": "今日は宿題がたくさんあるのに、もう一つ増えました。", "target_word": "もう", "complexity_tier": "T3", "furigana": "今日[きょう]は宿題[しゅくだい]がたくさんあるのに、もう一[ひと]つ増[ふ]えました。", "sentence_source": "generated"}, {"text": "この本はおもしろいので、もう一冊買いました。", "target_word": "もう", "complexity_tier": "T3", "furigana": "この本[ほん]はおもしろいので、もう一冊[いっさつ]買[か]いました。", "sentence_source": "generated"}, {"text": "先生、もう一つ質問があります。", "target_word": "もう", "complexity_tier": "T3", "furigana": "先生[せんせい]、もう一[ひと]つ質問[しつもん]があります。", "sentence_source": "generated"}, {"text": "お茶をもう一杯いかがですか。", "target_word": "もう", "complexity_tier": "T3", "furigana": "お茶[ちゃ]をもう一杯[いっぱい]いかがですか。", "sentence_source": "generated"}, {"text": "書類にもう一枚、名前を書いてください。", "target_word": "もう", "complexity_tier": "T3", "furigana": "書類[しょるい]にもう一枚[いちまい]、名前[なまえ]を書[か]いてください。", "sentence_source": "generated"}, {"text": "荷物が多いので、かばんをもう一つ持っていきます。", "target_word": "もう", "complexity_tier": "T3", "furigana": "荷物[にもつ]が多[おお]いので、かばんをもう一[ひと]つ持[も]っていきます。", "sentence_source": "generated"}, {"text": "弟が来たので、いすをもう一つ出しました。", "target_word": "もう", "complexity_tier": "T3", "furigana": "弟[おとうと]が来[き]たので、いすをもう一[ひと]つ出[だ]しました。", "sentence_source": "generated"}, {"text": "水が足りないので、もう一本買いました。", "target_word": "もう", "complexity_tier": "T3", "furigana": "水[みず]が足[た]りないので、もう一本[いっぽん]買[か]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "もう", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "すでにある数や量にさらに加える意味の「もう」（もう一つ・もう一杯）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18652b11-0c76-4c07-b9a2-da1d1612a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37482, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "もう", "is_correct": true, "explanation": "既にある数に一つ加える「もう」。「もう一つ食べたい」として文意に合う。"}, {"text": "ずっと", "is_correct": false, "explanation": "継続を表す副詞で、数を加える意味にならない。「ずっと一つ食べたい」は不自然。"}, {"text": "やっと", "is_correct": false, "explanation": "「ようやく」の意味で、追加の数量を表さない。「やっと一つ食べたい」は文として合わない。"}, {"text": "かなり", "is_correct": false, "explanation": "程度を表す副詞。「かなり一つ食べたい」は数を加える意味にならない。"}], "explanations": {"もう": "既にある数に一つ加える「もう」。「もう一つ食べたい」として文意に合う。", "ずっと": "継続を表す副詞で、数を加える意味にならない。「ずっと一つ食べたい」は不自然。", "やっと": "「ようやく」の意味で、追加の数量を表さない。「やっと一つ食べたい」は文として合わない。", "かなり": "程度を表す副詞。「かなり一つ食べたい」は数を加える意味にならない。"}, "sentence_index": 0, "correct_answer": "もう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "もう、いい加減にしてよ。", "explanation": "感情を表す「もう」で、数や量を一つ足す意味ではない。「もう一冊」の形に言い換えられない。"}, {"text": "あの店には、もう行かないと決めた。", "explanation": "「もう〜ない」で「二度と〜ない」の意味。既にある物に追加する「もう一〜」の用法ではない。"}, {"text": "値段がもう上がった。", "explanation": "「さらに」の代わりに「もう」を入れた文。ここは既に起きたことを表し、追加の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37482, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "もう", "is_correct": true, "explanation": "書類に一枚加えることを表す「もう」。「もう一枚、名前を書く」として文意に合う。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "熟睡の様子を表す副詞。書類に名前を書く動作とは結びつかない。"}, {"text": "のんびり", "is_correct": false, "explanation": "ゆったり過ごす様子を表す。「のんびり一枚、名前を書く」は数を加える意味にならない。"}, {"text": "ふらっと", "is_correct": false, "explanation": "何気なく立ち寄る様子を表す。ここでは数量を加える意味にならず、文が成り立たない。"}], "explanations": {"もう": "書類に一枚加えることを表す「もう」。「もう一枚、名前を書く」として文意に合う。", "ぐっすり": "熟睡の様子を表す副詞。書類に名前を書く動作とは結びつかない。", "のんびり": "ゆったり過ごす様子を表す。「のんびり一枚、名前を書く」は数を加える意味にならない。", "ふらっと": "何気なく立ち寄る様子を表す。ここでは数量を加える意味にならず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "もう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "バスはもう出発しました。", "explanation": "「すでに」の意味で使われている。既にある数に一つ加える「もう一本」の用法ではない。"}, {"text": "あの店のパンは、もう好きじゃない。", "explanation": "「もう〜ない」で好みが変わったことを表す。追加の意味ではない。"}, {"text": "もう、ずるいよ。", "explanation": "感情を表す「もう」で、数を加える意味ではない。ここでは「もう一本」の形にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37482, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "門の前で姉を待っています。もう一つ来る予定です。", "corrected_sentence": "門の前で姉を待っています。もう一人来る予定です。", "error_description": "人を数えるには「一人」を使う。「一つ」は物に使う数え方で、人には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37482, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨が強いので、かさをもう一枚買いました。", "corrected_sentence": "雨が強いので、かさをもう一本買いました。", "error_description": "傘は「本」で数える。「一枚」は紙や薄い物を数える語で、傘には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
