INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37483, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "既にある事柄に加えて、さらに別の事柄が存在することを示す副詞。", "primary_collocate": null, "pronunciation": "もう", "ipa": "moː", "syllable_count": 2, "sentences": [{"text": "朝ごはんを食べたけれど、もう一つパンを食べた。", "target_word": "もう", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんを食[た]べたけれど、もう一[ひと]つパンを食[た]べた。", "sentence_source": "generated"}, {"text": "犬を飼っているが、来月もう一匹ふえる予定だ。", "target_word": "もう", "complexity_tier": "T3", "furigana": "犬[いぬ]を飼[か]っているが、来月[らいげつ]もう一匹[いっぴき]ふえる予定[よてい]だ。", "sentence_source": "generated"}, {"text": "会議の前に、もう一人呼ばなければならない。", "target_word": "もう", "complexity_tier": "T3", "furigana": "会議[かいぎ]の前[まえ]に、もう一人[ひとり]呼[よ]ばなければならない。", "sentence_source": "generated"}, {"text": "一回では覚えられないので、もう二回書いた。", "target_word": "もう", "complexity_tier": "T3", "furigana": "一回[いっかい]では覚[おぼ]えられないので、もう二回[にかい]書[か]いた。", "sentence_source": "generated"}, {"text": "試合に勝ったので、もう一試合出られる。", "target_word": "もう", "complexity_tier": "T3", "furigana": "試合[しあい]に勝[か]ったので、もう一試合[ひとしあい]出[で]られる。", "sentence_source": "generated"}, {"text": "この町には公園があるが、もう一つ作る計画だ。", "target_word": "もう", "complexity_tier": "T3", "furigana": "この町[まち]には公園[こうえん]があるが、もう一[ひと]つ作[つく]る計画[けいかく]だ。", "sentence_source": "generated"}, {"text": "切符を買ったあとで、もう一枚必要だと気づいた。", "target_word": "もう", "complexity_tier": "T3", "furigana": "切符[きっぷ]を買[か]ったあとで、もう一枚[いちまい]必要[ひつよう]だと気[き]づいた。", "sentence_source": "generated"}, {"text": "熱があったので、薬をもう一包飲んだ。", "target_word": "もう", "complexity_tier": "T3", "furigana": "熱[ねつ]があったので、薬[くすり]をもう一包[ひとつつみ]飲[の]んだ。", "sentence_source": "generated"}, {"text": "部屋が暗いので、電気をもう一つ付けた。", "target_word": "もう", "complexity_tier": "T3", "furigana": "部屋[へや]が暗[くら]いので、電気[でんき]をもう一[ひと]つ付[つ]けた。", "sentence_source": "generated"}, {"text": "兄はケーキを二つ食べて、もう一つ頼んだ。", "target_word": "もう", "complexity_tier": "T3", "furigana": "兄[あに]はケーキを二[ふた]つ食[た]べて、もう一[ひと]つ頼[たの]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "もう", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "既存の物事に追加する意味の副詞「もう」（もう二回・もう一人）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18652b11-0c76-4c07-b9a2-da1d1612a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37483, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "もう", "is_correct": true, "explanation": "既にあるパンに一つ加える「もう」。「もう一つパンを食べた」として文意に合う。"}, {"text": "たびたび", "is_correct": false, "explanation": "回数が多いことを表す。「たびたび一つパンを食べた」は追加の意味にならない。"}, {"text": "すっかり", "is_correct": false, "explanation": "すべてそうなった様子を表す。数を加える意味にならず、文が成り立たない。"}, {"text": "とっくに", "is_correct": false, "explanation": "ずっと前に既に、の意味。「とっくに一つパンを食べた」は追加の数量を表さない。"}], "explanations": {"もう": "既にあるパンに一つ加える「もう」。「もう一つパンを食べた」として文意に合う。", "たびたび": "回数が多いことを表す。「たびたび一つパンを食べた」は追加の意味にならない。", "すっかり": "すべてそうなった様子を表す。数を加える意味にならず、文が成り立たない。", "とっくに": "ずっと前に既に、の意味。「とっくに一つパンを食べた」は追加の数量を表さない。"}, "sentence_index": 0, "correct_answer": "もう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "もう、何度言ったら分かるの。", "explanation": "感情を表す「もう」で、回数を足す意味ではない。ここは「もう二回」の形にならない。"}, {"text": "その会社には、もう勤めないことにした。", "explanation": "「もう〜ない」で「やめる」の意味。回数を足す「もう二回」の用法ではない。"}, {"text": "書類がもう完成した。", "explanation": "「やっと」の代わりに「もう」を入れた文。既に完了したことを表し、回数の追加にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37483, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "もう", "is_correct": true, "explanation": "切符に一枚加えることを表す「もう」。「もう一枚必要だ」として文意に合う。"}, {"text": "さっそく", "is_correct": false, "explanation": "すぐに、の意味。「さっそく一枚必要だ」は数を加える意味にならない。"}, {"text": "なかなか", "is_correct": false, "explanation": "なかなか〜ない、の形で使う。「なかなか一枚必要だ」は文として合わない。"}, {"text": "しばらく", "is_correct": false, "explanation": "時間の長さを表す。「しばらく一枚必要だ」は数量を加える意味にならない。"}], "explanations": {"もう": "切符に一枚加えることを表す「もう」。「もう一枚必要だ」として文意に合う。", "さっそく": "すぐに、の意味。「さっそく一枚必要だ」は数を加える意味にならない。", "なかなか": "なかなか〜ない、の形で使う。「なかなか一枚必要だ」は文として合わない。", "しばらく": "時間の長さを表す。「しばらく一枚必要だ」は数量を加える意味にならない。"}, "sentence_index": 6, "correct_answer": "もう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車はもう着いた。", "explanation": "「すでに」の意味で使われている。既にある物に一つ加える「もう一つ」の用法ではない。"}, {"text": "兄とはもう話さないことにした。", "explanation": "「もう〜ない」で関係をやめる意味。物を追加する用法ではない。"}, {"text": "もう、ケーキの食べすぎだよ。", "explanation": "感情を表す「もう」で、数を足す意味ではない。「もう一つ頼んだ」の形にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37483, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お客さんが来たので、いすをもう一人出した。", "corrected_sentence": "お客さんが来たので、いすをもう一脚出した。", "error_description": "いすの数え方は「脚」を使う。「一人」は人を数える語なので、いすには合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37483, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "頭痛がするので、薬をもう一枚飲んだ。", "corrected_sentence": "頭痛がするので、薬をもう一包飲んだ。", "error_description": "粉薬の一回分は「包」で数える。「一枚」は紙や薄い物を数える語で、薬には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37484, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「基軸に考える」の「に」。判断の基準を表し、文意に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す「が」。「安さを基軸が考えられている」と並ぶと主語が重なり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「基軸へ考えられている」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」。「基軸より考えられている」は比較の文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「基軸に考える」の「に」。判断の基準を表し、文意に合う。", "が": "主語を表す「が」。「安さを基軸が考えられている」と並ぶと主語が重なり、文が成り立たない。", "へ": "方向を表す「へ」。「基軸へ考えられている」は意味が通らない。", "より": "比較を表す「より」。「基軸より考えられている」は比較の文として成り立たない。"}, "error_tags": {"が": "subject", "へ": "direction", "より": "comparison"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37484, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「基軸がぶれる」の「が」。基軸を主語にする文で、文意に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す「を」。「基軸をぶれる」は自動詞の「ぶれる」と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「基軸へぶれると」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」。「基軸よりぶれると」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「基軸がぶれる」の「が」。基軸を主語にする文で、文意に合う。", "を": "目的語を表す「を」。「基軸をぶれる」は自動詞の「ぶれる」と合わない。", "へ": "方向を表す「へ」。「基軸へぶれると」は意味が通らない。", "より": "比較を表す「より」。「基軸よりぶれると」は文として成り立たない。"}, "error_tags": {"を": "object", "へ": "direction", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37484, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときの、たいせつな、もとになること。", "primary_collocate": null, "pronunciation": "きじく", "ipa": "kidʑikɯ", "syllable_count": 3, "sentences": [{"text": "この計画は、住民の意見を基軸にして進める。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "この計画[けいかく]は、住民[じゅうみん]の意見[いけん]を基軸[きじく]にして進[すす]める。", "sentence_source": "generated"}, {"text": "新しい店は、安さを基軸に考えられている。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]は、安[やす]さを基軸[きじく]に考[かんが]えられている。", "sentence_source": "generated"}, {"text": "先生は、生徒の理解度を基軸にして授業を組み立てた。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]の理解度[りかいど]を基軸[きじく]にして授業[じゅぎょう]を組[く]み立[た]てた。", "sentence_source": "generated"}, {"text": "仕事を選ぶとき、何を基軸にするかが大切だ。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "仕事[しごと]を選[えら]ぶとき、何[なに]を基軸[きじく]にするかが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "今回の旅行は、家族の希望が基軸になっている。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "今回[こんかい]の旅行[りょこう]は、家族[かぞく]の希望[きぼう]が基軸[きじく]になっている。", "sentence_source": "generated"}, {"text": "彼の考えは、いつも健康を基軸にしている。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "彼[かれ]の考[かんが]えは、いつも健康[けんこう]を基軸[きじく]にしている。", "sentence_source": "generated"}, {"text": "チームは守りを基軸に戦い方を決めた。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "チームは守[まも]りを基軸[きじく]に戦[たたか]い方[かた]を決[き]めた。", "sentence_source": "generated"}, {"text": "基軸がぶれると、方針が何度も変わってしまう。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "基軸[きじく]がぶれると、方針[ほうしん]が何度[なんど]も変[か]わってしまう。", "sentence_source": "generated"}, {"text": "会社は、お客様の声を基軸として商品を作る。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、お客様[きゃくさま]の声[こえ]を基軸[きじく]として商品[しょうひん]を作[つく]る。", "sentence_source": "generated"}, {"text": "練習メニューは、体力づくりを基軸に作られた。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "練習[れんしゅう]メニューは、体力[たいりょく]づくりを基軸[きじく]に作[つく]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "基軸", "label": "基本形"}], "register": "formal", "sense_fingerprint": "計画や行動を進めるときの、中心になる大切なもと（〜を基軸にする）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18652b11-0c76-4c07-b9a2-da1d1612a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37484, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基軸", "is_correct": true, "explanation": "計画の中心となる、もとになるものの意味。「住民の意見を基軸にして進める」として文意に合う。"}, {"text": "期限", "is_correct": false, "explanation": "締め切りの日の意味。「住民の意見を期限にして進める」は計画の中心になる意味にならない。"}, {"text": "予算", "is_correct": false, "explanation": "使える金額の意味。「住民の意見を予算にして進める」は不自然で、文が成り立たない。"}, {"text": "会場", "is_correct": false, "explanation": "催しを行う場所の意味。「住民の意見を会場にして進める」は文として合わない。"}], "explanations": {"基軸": "計画の中心となる、もとになるものの意味。「住民の意見を基軸にして進める」として文意に合う。", "期限": "締め切りの日の意味。「住民の意見を期限にして進める」は計画の中心になる意味にならない。", "予算": "使える金額の意味。「住民の意見を予算にして進める」は不自然で、文が成り立たない。", "会場": "催しを行う場所の意味。「住民の意見を会場にして進める」は文として合わない。"}, "sentence_index": 0, "correct_answer": "基軸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "時計の基軸に油をさした。", "explanation": "時計の回転軸の意味。判断の拠りどころという抽象的な用法とは違う。"}, {"text": "この家は基軸がしっかりしているので、地震に強い。", "explanation": "「土台」の代わりに「基軸」を入れた文。土台は建物の下の支えで、基軸は計画や判断の中心なので、建物には使わない。"}, {"text": "扇風機の基軸が折れたので、修理に出した。", "explanation": "機械の回転軸の意味。ここは判断の拠りどころという抽象的な意味で、合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37484, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基軸", "is_correct": true, "explanation": "戦い方を決めるもとになるもの、の意味。「守りを基軸に戦い方を決めた」として文意に合う。"}, {"text": "選手", "is_correct": false, "explanation": "競技をする人の意味。「守りを選手に戦い方を決めた」は文として合わない。"}, {"text": "得点", "is_correct": false, "explanation": "点を取ることの意味。「守りを得点に戦い方を決めた」は意味が通らない。"}, {"text": "試合", "is_correct": false, "explanation": "競技を行うことの意味。「守りを試合に戦い方を決めた」は不自然で、文が成り立たない。"}], "explanations": {"基軸": "戦い方を決めるもとになるもの、の意味。「守りを基軸に戦い方を決めた」として文意に合う。", "選手": "競技をする人の意味。「守りを選手に戦い方を決めた」は文として合わない。", "得点": "点を取ることの意味。「守りを得点に戦い方を決めた」は意味が通らない。", "試合": "競技を行うことの意味。「守りを試合に戦い方を決めた」は不自然で、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "基軸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "基軸がまっすぐな人は、姿勢がいい。", "explanation": "「基軸がまっすぐな人は」と置き換えた文。背骨は体の部位で、基軸は抽象的な中心なので、体には使わない。"}, {"text": "基軸がしっかりした土地に家を建てた。", "explanation": "「地盤」の代わりに「基軸」を入れた文。地盤は土地の強さを指し、基軸は計画や方針の中心なので、土地には使わない。"}, {"text": "ドリルの基軸がぶれて、穴があいた。", "explanation": "機械の回転軸の意味。ここは体力づくりを中心にするという抽象的な用法とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
