INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37485, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「基軸となる」の「と」。何かになる、という意味を表し、文意に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す「が」。「基軸がなるもの」は文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す「を」。「基軸をなるもの」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「基軸へなるもの」は文として合わない。"}], "correct_answer": "と", "explanations": {"と": "「基軸となる」の「と」。何かになる、という意味を表し、文意に合う。", "が": "主語を表す「が」。「基軸がなるもの」は文として成り立たない。", "を": "目的語を表す「を」。「基軸をなるもの」は意味が通らない。", "へ": "方向を表す「へ」。「基軸へなるもの」は文として合わない。"}, "error_tags": {"が": "subject", "を": "object", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37485, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「基軸は変わらない」の「は」。基軸を話題にして、それが変わらないと述べる文に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す「を」。「基軸を変わらない」は自動詞「変わる」と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「基軸へ変わらない」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」。「基軸より変わらない」は比較の文として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「基軸は変わらない」の「は」。基軸を話題にして、それが変わらないと述べる文に合う。", "を": "目的語を表す「を」。「基軸を変わらない」は自動詞「変わる」と合わない。", "へ": "方向を表す「へ」。「基軸へ変わらない」は意味が通らない。", "より": "比較を表す「より」。「基軸より変わらない」は比較の文として成り立たない。"}, "error_tags": {"を": "object", "へ": "direction", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37485, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の根幹となる、重要なよりどころ。基準。", "primary_collocate": null, "pronunciation": "きじく", "ipa": "kidʑikɯ", "syllable_count": 3, "sentences": [{"text": "判断の基軸がないと、人は迷ってしまう。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "判断[はんだん]の基軸[きじく]がないと、人[ひと]は迷[まよ]ってしまう。", "sentence_source": "generated"}, {"text": "憲法は、国の法律の基軸となるものだ。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "憲法[けんぽう]は、国[くに]の法律[ほうりつ]の基軸[きじく]となるものだ。", "sentence_source": "generated"}, {"text": "彼は自分の信念を基軸にして生きてきた。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の信念[しんねん]を基軸[きじく]にして生[い]きてきた。", "sentence_source": "generated"}, {"text": "評価の基軸をはっきりさせてから、点数をつけた。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "評価[ひょうか]の基軸[きじく]をはっきりさせてから、点数[てんすう]をつけた。", "sentence_source": "generated"}, {"text": "この学校の教育は、思いやりの心を基軸としている。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "この学校[がっこう]の教育[きょういく]は、思[おも]いやりの心[こころ]を基軸[きじく]としている。", "sentence_source": "generated"}, {"text": "組織の基軸が弱いと、意見がまとまらない。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "組織[そしき]の基軸[きじく]が弱[よわ]いと、意見[いけん]がまとまらない。", "sentence_source": "generated"}, {"text": "昔の価値観を基軸に、新しい規則が決められた。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "昔[むかし]の価値観[かちかん]を基軸[きじく]に、新[あたら]しい規則[きそく]が決[き]められた。", "sentence_source": "generated"}, {"text": "事業を広げても、会社の基軸は変わらない。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "事業[じぎょう]を広[ひろ]げても、会社[かいしゃ]の基軸[きじく]は変[か]わらない。", "sentence_source": "generated"}, {"text": "議論の基軸になる考えを、最初に示すべきだ。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "議論[ぎろん]の基軸[きじく]になる考[かんが]えを、最初[さいしょ]に示[しめ]すべきだ。", "sentence_source": "generated"}, {"text": "基軸となる原則を守れば、大きな間違いはしない。", "target_word": "基軸", "complexity_tier": "T3", "furigana": "基軸[きじく]となる原則[げんそく]を守[まも]れば、大[おお]きな間違[まちが]いはしない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "基軸", "label": "基本形"}], "register": "formal", "sense_fingerprint": "判断や組織の根幹となるよりどころ・基準（基軸となる）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18652b11-0c76-4c07-b9a2-da1d1612a51a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37485, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基軸", "is_correct": true, "explanation": "判断の拠りどころになるもの、の意味。「判断の基軸がないと迷う」として文意に合う。"}, {"text": "電池", "is_correct": false, "explanation": "乾電池の意味。「判断の電池がないと」は文として合わない。"}, {"text": "書類", "is_correct": false, "explanation": "文字で書かれた文書の意味。「判断の書類がないと」は判断の拠りどころの意味にならない。"}, {"text": "予定", "is_correct": false, "explanation": "これから行う計画の意味。「判断の予定がないと」は文として合わない。"}], "explanations": {"基軸": "判断の拠りどころになるもの、の意味。「判断の基軸がないと迷う」として文意に合う。", "電池": "乾電池の意味。「判断の電池がないと」は文として合わない。", "書類": "文字で書かれた文書の意味。「判断の書類がないと」は判断の拠りどころの意味にならない。", "予定": "これから行う計画の意味。「判断の予定がないと」は文として合わない。"}, "sentence_index": 0, "correct_answer": "基軸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "エンジンの基軸が折れたので、修理に出した。", "explanation": "機械の回転軸の意味。評価の基準という用法とは違うので、ここでは使えない。"}, {"text": "この土地は基軸が弱いので、家を建てられない。", "explanation": "地盤の代わりに「基軸」を入れた文。地盤は土地の強さを指し、基軸は判断の拠りどころなので、土地には使わない。"}, {"text": "旋盤の基軸を交換した。", "explanation": "工作機械の回転軸の意味。判断の基準という抽象的な用法とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37485, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基軸", "is_correct": true, "explanation": "規則を決める際のよりどころ、の意味。「昔の価値観を基軸に規則が決められた」として文意に合う。"}, {"text": "印刷", "is_correct": false, "explanation": "文字や絵を紙に写す意味。「昔の価値観を印刷に」は文として成り立たない。"}, {"text": "看板", "is_correct": false, "explanation": "店などの目印となる板の意味。「昔の価値観を看板に」は不自然で、意味が通らない。"}, {"text": "調査", "is_correct": false, "explanation": "事実を調べることの意味。「昔の価値観を調査に規則が決められた」は文として合わない。"}], "explanations": {"基軸": "規則を決める際のよりどころ、の意味。「昔の価値観を基軸に規則が決められた」として文意に合う。", "印刷": "文字や絵を紙に写す意味。「昔の価値観を印刷に」は文として成り立たない。", "看板": "店などの目印となる板の意味。「昔の価値観を看板に」は不自然で、意味が通らない。", "調査": "事実を調べることの意味。「昔の価値観を調査に規則が決められた」は文として合わない。"}, "sentence_index": 6, "correct_answer": "基軸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ロボットの基軸が回らなくなった。", "explanation": "機械の軸の意味。判断の拠りどころを表す用法ではないので、ここでは使えない。"}, {"text": "この家は基軸がしっかりしているので、地震に強い。", "explanation": "「柱」の代わりに「基軸」を入れた文。柱は建物を支える部材で、基軸は抽象的な中心なので、建物の部材には使わない。"}, {"text": "てこの基軸を少し動かすと、重さが変わった。", "explanation": "物理的な支点の意味。判断の基準という抽象的な用法とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37485, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい規則は、昔の価値観を基軸に決めらた。", "corrected_sentence": "新しい規則は、昔の価値観を基軸に決められた。", "error_description": "「決められた」の「れ」が抜けている。「決めらた」は動詞の形が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37485, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社の基軸を見直ると、方向が定まる。", "corrected_sentence": "会社の基軸を見直すと、方向が定まる。", "error_description": "「見直す」の辞書形が正しい。「見直ると」は動詞の形が誤っていて、文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b69ac3-2ce0-4cfb-8528-d477106a2d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37486, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ランキングを見ると」で、見る対象の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「ランキングが見ると」は主語になり、見る主体として文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ランキングに見ると」は見る対象を示せず、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "「ランキングへ見ると」は方向を表し、見る対象の意味にならない。"}], "correct_answer": "を", "explanations": {"を": "「ランキングを見ると」で、見る対象の目的語を示す。", "が": "「ランキングが見ると」は主語になり、見る主体として文が成り立たない。", "に": "「ランキングに見ると」は見る対象を示せず、不自然になる。", "へ": "「ランキングへ見ると」は方向を表し、見る対象の意味にならない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "相手・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37486, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ランキングが出る」で、表示される主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「ランキングを出る」は目的語にしても「出る」と合わず、不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "「ランキングと出る」は並列の意味になり、表示される主語として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「ランキングへ出る」は行き先の意味になり、画面に表示される意味にならない。"}], "correct_answer": "が", "explanations": {"が": "「ランキングが出る」で、表示される主語を示す。", "を": "「ランキングを出る」は目的語にしても「出る」と合わず、不自然になる。", "と": "「ランキングと出る」は並列の意味になり、表示される主語として成り立たない。", "へ": "「ランキングへ出る」は行き先の意味になり、画面に表示される意味にならない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37486, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなが遊ぶゲームで、じょうずな人がどれくらいのじゅんいかをおしえてくれるものです。", "primary_collocate": null, "pronunciation": "らんきんぐ", "ipa": "ɾaŋkiŋɡɯ", "syllable_count": 5, "sentences": [{"text": "このゲームのランキングで、ぼくは今週三位になった。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "このゲームのランキングで、ぼくは今週[こんしゅう]三位[さんい]になった。", "sentence_source": "generated"}, {"text": "ランキングを見ると、上手な人の順位がすぐにわかる。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "ランキングを見[み]ると、上手[じょうず]な人[ひと]の順位[じゅんい]がすぐにわかる。", "sentence_source": "generated"}, {"text": "毎日練習したので、ランキングが少しずつ上がってきた。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]したので、ランキングが少[すこ]しずつ上[あ]がってきた。", "sentence_source": "generated"}, {"text": "友だちはランキングの一位を何か月も守っている。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "友[とも]だちはランキングの一位[いちい]を何[なん]か月[げつ]も守[まも]っている。", "sentence_source": "generated"}, {"text": "オンラインゲームのランキングには、世界中の人の名前がのる。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "オンラインゲームのランキングには、世界中[せかいじゅう]の人[ひと]の名前[なまえ]がのる。", "sentence_source": "generated"}, {"text": "ランキングが発表されて、私は百位に入っていて驚いた。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "ランキングが発表[はっぴょう]されて、私[わたし]は百位[ひゃくい]に入[はい]っていて驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "弟はランキングが下がったので、くやしがっている。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "弟[おとうと]はランキングが下[さ]がったので、くやしがっている。", "sentence_source": "generated"}, {"text": "ゲームを終えると、画面にランキングが出る。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "ゲームを終[お]えると、画面[がめん]にランキングが出[で]る。", "sentence_source": "generated"}, {"text": "ランキングを上げたくて、夜おそくまで遊んでしまった。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "ランキングを上[あ]げたくて、夜[よる]おそくまで遊[あそ]んでしまった。", "sentence_source": "generated"}, {"text": "このランキングは、一週間ごとに新しくなります。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "このランキングは、一週間[いっしゅうかん]ごとに新[あたら]しくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ランキング", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ゲームで上手な人の順位を示す表", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: くやし (Zipf 2.35)','sentence 8 above tier T2: contains vocabulary far above tier T2: おそく (Zipf 2.34)']::text[], '07c94323-d2a7-4136-9285-064b10d13ae7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37486, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ランキング", "is_correct": true, "explanation": "ゲームの順位の一覧を指すので、「ランキングで三位」と文に合う。"}, {"text": "コーチ", "is_correct": false, "explanation": "指導者を指すので、順位の一覧として「三位」にはならない。"}, {"text": "アイテム", "is_correct": false, "explanation": "ゲーム内の道具で、順位を示す場所にはならない。"}, {"text": "セーブデータ", "is_correct": false, "explanation": "ゲームの保存情報で、順位を示す一覧にはならない。"}], "explanations": {"ランキング": "ゲームの順位の一覧を指すので、「ランキングで三位」と文に合う。", "コーチ": "指導者を指すので、順位の一覧として「三位」にはならない。", "アイテム": "ゲーム内の道具で、順位を示す場所にはならない。", "セーブデータ": "ゲームの保存情報で、順位を示す一覧にはならない。"}, "sentence_index": 0, "correct_answer": "ランキング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、公園でランキングをしてから学校へ行く。", "explanation": "ここは〈ランニング〉（走ること）の意味。ランキングは順位の一覧なので「する」の対象にならない。"}, {"text": "窓辺のランキングが、夜じゅう灯っていた。", "explanation": "ここは〈ランプ〉（灯り）の意味。ランキングは順位の一覧なので、灯る物にはならない。"}, {"text": "マラソン大会で、友だちは三十位のランキングをとった。", "explanation": "ここは〈順位〉（個別の位置）の意味。ランキングは一覧そのものを指すので「とる」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37486, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ランキング", "is_correct": true, "explanation": "「ランキングが下がった」で、順位の一覧が変わったことを表し文に合う。"}, {"text": "ボタン", "is_correct": false, "explanation": "押すための部品で、下がるという変化の主語にはならない。"}, {"text": "テント", "is_correct": false, "explanation": "野外の布製の施設で、順位のように下がる主語にはならない。"}, {"text": "階段", "is_correct": false, "explanation": "建物の段差で、順位が下がったという文の主語にはならない。"}], "explanations": {"ランキング": "「ランキングが下がった」で、順位の一覧が変わったことを表し文に合う。", "ボタン": "押すための部品で、下がるという変化の主語にはならない。", "テント": "野外の布製の施設で、順位のように下がる主語にはならない。", "階段": "建物の段差で、順位が下がったという文の主語にはならない。"}, "sentence_index": 6, "correct_answer": "ランキング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日、昼休みにはランキングを食べに行く。", "explanation": "ここは〈ランチ〉（昼食）の意味。ランキングは順位の一覧なので、食べ物として扱えない。"}, {"text": "マラソンでは、ランキングが一キロごとに水を飲む。", "explanation": "ここは〈ランナー〉（走る人）の意味。ランキングは一覧なので、水を飲む主体にはならない。"}, {"text": "お金の出し入れは、ネットランキングで毎日確かめる。", "explanation": "ここは〈ネットバンキング〉の意味。ランキングは順位表なので、お金の確認には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37486, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このランキングを名前がのると、うれしい。", "corrected_sentence": "このランキングに名前がのると、うれしい。", "error_description": "「〜に載る」の「に」が正しい。「ランキングを」にすると目的語になり、「のる」の文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37486, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このランキングを入るには、毎日練習が必要だ。", "corrected_sentence": "このランキングに入るには、毎日練習が必要だ。", "error_description": "「〜に入る」の「に」が正しい。「ランキングを」にすると目的語になり、「入る」の文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37487, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「テニスの世界ランキングで五位に入った」で、順位が決まる範囲や場面を表す。"}, {"text": "を", "is_correct": false, "explanation": "「ランキングを、五位に入った」は目的語となり、順位の範囲として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「ランキングが、五位に入った」は主語になり、彼女が入った場所の説明として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「ランキングと、五位に入った」は並列になり、場所を表せない。"}], "correct_answer": "で", "explanations": {"で": "「テニスの世界ランキングで五位に入った」で、順位が決まる範囲や場面を表す。", "を": "「ランキングを、五位に入った」は目的語となり、順位の範囲として成り立たない。", "が": "「ランキングが、五位に入った」は主語になり、彼女が入った場所の説明として不自然。", "と": "「ランキングと、五位に入った」は並列になり、場所を表せない。"}, "error_tags": {"で": "場面・範囲", "を": "目的語", "が": "主語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37487, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ランキングが一位でも」で、ランキングを主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "「ランキングを一位でも」は目的語となり、順位の状態を表す文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ランキングに一位でも」は場所や対象を示すが、順位の状態の説明にならない。"}, {"text": "と", "is_correct": false, "explanation": "「ランキングと一位でも」は並列になり、順位の状態として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「ランキングが一位でも」で、ランキングを主語として示す。", "を": "「ランキングを一位でも」は目的語となり、順位の状態を表す文として成り立たない。", "に": "「ランキングに一位でも」は場所や対象を示すが、順位の状態の説明にならない。", "と": "「ランキングと一位でも」は並列になり、順位の状態として成り立たない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "相手・対象", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37487, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ゲームや競技などで、実力や成績に基づいて順位をつけた一覧。", "primary_collocate": null, "pronunciation": "らんきんぐ", "ipa": "ɾaŋkiŋɡɯ", "syllable_count": 5, "sentences": [{"text": "大会が終わり、成績にもとづいたランキングが発表された。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "大会[たいかい]が終[お]わり、成績[せいせき]にもとづいたランキングが発表[はっぴょう]された。", "sentence_source": "generated"}, {"text": "テニスの世界ランキングで、彼女は五位に入った。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "テニスの世界[せかい]ランキングで、彼女[かのじょ]は五位[ごい]に入[はい]った。", "sentence_source": "generated"}, {"text": "ランキングの上位には、有名な選手が並んでいる。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "ランキングの上位[じょうい]には、有名[ゆうめい]な選手[せんしゅ]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "実力だけで決まるランキングなので、ごまかしはできない。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "実力[じつりょく]だけで決[き]まるランキングなので、ごまかしはできない。", "sentence_source": "generated"}, {"text": "去年のランキングと比べると、チームの順位が大きく上がった。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "去年[きょねん]のランキングと比[くら]べると、チームの順位[じゅんい]が大[おお]きく上[あ]がった。", "sentence_source": "generated"}, {"text": "ランキング表を見て、自分の位置を確かめた。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "ランキング表[ひょう]を見[み]て、自分[じぶん]の位置[いち]を確[たし]かめた。", "sentence_source": "generated"}, {"text": "将棋のランキングは、勝った数で変わる。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "将棋[しょうぎ]のランキングは、勝[か]った数[かず]で変[か]わる。", "sentence_source": "generated"}, {"text": "ランキングが一位でも、油断すれば次の試合で落ちる。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "ランキングが一位[いちい]でも、油断[ゆだん]すれば次[つぎ]の試合[しあい]で落[お]ちる。", "sentence_source": "generated"}, {"text": "ゲーム大会のランキングは、ホームページで見られます。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "ゲーム大会[たいかい]のランキングは、ホームページで見[み]られます。", "sentence_source": "generated"}, {"text": "新人の彼がランキングに入ったことは、大きなニュースになった。", "target_word": "ランキング", "complexity_tier": "T3", "furigana": "新人[しんじん]の彼[かれ]がランキングに入[はい]ったことは、大[おお]きなニュースになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ランキング", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "実力や成績で順位をつけた一覧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c94323-d2a7-4136-9285-064b10d13ae7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37487, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ランキング", "is_correct": true, "explanation": "成績にもとづいて順位をつけた一覧で、「発表された」の主語として合う。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "布製品で、成績にもとづいて発表されるものではない。"}, {"text": "ブーツ", "is_correct": false, "explanation": "履物で、成績にもとづいて発表されるものではない。"}, {"text": "スリッパ", "is_correct": false, "explanation": "室内履きで、成績にもとづいて発表されるものではない。"}], "explanations": {"ランキング": "成績にもとづいて順位をつけた一覧で、「発表された」の主語として合う。", "ハンカチ": "布製品で、成績にもとづいて発表されるものではない。", "ブーツ": "履物で、成績にもとづいて発表されるものではない。", "スリッパ": "室内履きで、成績にもとづいて発表されるものではない。"}, "sentence_index": 0, "correct_answer": "ランキング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "給料の振り込みは、ネットランキングで毎日確認する。", "explanation": "ここは〈ネットバンキング〉の意味。ランキングは成績の順位表なので、振り込みの確認には使えない。"}, {"text": "昼はいつも、近くの店でランキングを食べている。", "explanation": "ここは〈ランチ〉（昼食）の意味。ランキングは一覧なので、食べ物として扱えない。"}, {"text": "試合の終盤、彼らはランキングを一点守り切った。", "explanation": "ここは〈リード〉（得点の差）の意味。ランキングは順位の一覧なので、点差は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37487, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ランキング", "is_correct": true, "explanation": "「将棋のランキングは、勝った数で変わる」で、順位の一覧が変わることを表し文に合う。"}, {"text": "ペンキ", "is_correct": false, "explanation": "塗料で、勝った数によって変わる主語にはならない。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓の布で、勝った数によって変わる主語にはならない。"}, {"text": "ホース", "is_correct": false, "explanation": "水を運ぶ管で、勝った数によって変わる主語にはならない。"}], "explanations": {"ランキング": "「将棋のランキングは、勝った数で変わる」で、順位の一覧が変わることを表し文に合う。", "ペンキ": "塗料で、勝った数によって変わる主語にはならない。", "カーテン": "窓の布で、勝った数によって変わる主語にはならない。", "ホース": "水を運ぶ管で、勝った数によって変わる主語にはならない。"}, "sentence_index": 6, "correct_answer": "ランキング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "マラソンでは、ランキングが最後まで先頭を走っていた。", "explanation": "ここは〈ランナー〉（走る人）の意味。ランキングは一覧なので、走る主体にはならない。"}, {"text": "毎朝、ランキングを背負って学校へ行く。", "explanation": "ここは〈ランドセル〉（背負う通学かばん）の意味。ランキングは順位の一覧なので、背負えない。"}, {"text": "この雑誌のランキングは、主に二十代の女性だ。", "explanation": "ここは〈読者〉の意味。ランキングは順位の一覧なので、雑誌を読む人は指せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37487, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ランキングを一位は、毎年変わることがある。", "corrected_sentence": "ランキングの一位は、毎年変わることがある。", "error_description": "「ランキングの一位」の「の」が正しい。「ランキングを一位」と「を」にすると、「一位は」とつながらず文が壊れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37487, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "将棋のランキングを、勝った数で決まる。", "corrected_sentence": "将棋のランキングは、勝った数で決まる。", "error_description": "「決まる」は主語を取る自動詞なので、主題の「は」が正しい。「を」だと目的語になり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b20a62-fa0f-4f1a-a0e1-e4277de745d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37488, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「出る」の先となる場所・大会を示すので「に」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「出る」の主語にはならないので、ここでは合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手を表し、出る先にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を表し、出る先を示せない。"}], "correct_answer": "に", "explanations": {"に": "「出る」の先となる場所・大会を示すので「に」が入る。", "が": "「出る」の主語にはならないので、ここでは合わない。", "と": "「と」は相手を表し、出る先にはならない。", "より": "「より」は比較の基準を表し、出る先を示せない。"}, "error_tags": {"が": "主語", "と": "相手・並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37488, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「出る」の先となる大会を示すので「に」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「出る」を目的語で使うと移動の意味になり、参加先を表せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を表し、出る先は示せないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するだけで、出る先を示せない。"}], "correct_answer": "に", "explanations": {"に": "「出る」の先となる大会を示すので「に」が入る。", "を": "「出る」を目的語で使うと移動の意味になり、参加先を表せないので合わない。", "より": "「より」は比較の基準を表し、出る先は示せないので合わない。", "の": "「の」は名詞を修飾するだけで、出る先を示せない。"}, "error_tags": {"を": "移動の起点", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37488, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一番を決めるために人が集まって行う大会。", "primary_collocate": null, "pronunciation": "とーなめんと", "ipa": "toːnameɴto", "syllable_count": 6, "sentences": [{"text": "来月、町の体育館で卓球のトーナメントが開かれる。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "来月[らいげつ]、町[まち]の体育館[たいいくかん]で卓球[たっきゅう]のトーナメントが開[ひら]かれる。", "sentence_source": "generated"}, {"text": "弟はトーナメントに出るために、毎朝走っている。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "弟[おとうと]はトーナメントに出[で]るために、毎朝[まいあさ]走[はし]っている。", "sentence_source": "generated"}, {"text": "このトーナメントで勝てば、全国大会に行ける。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "このトーナメントで勝[か]てば、全国大会[ぜんこくたいかい]に行[い]ける。", "sentence_source": "generated"}, {"text": "小学生のトーナメントなので、会場は子どもでいっぱいだ。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "小学生[しょうがくせい]のトーナメントなので、会場[かいじょう]は子[こ]どもでいっぱいだ。", "sentence_source": "generated"}, {"text": "彼はトーナメントで一番になるのが夢だ。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "彼[かれ]はトーナメントで一番[いちばん]になるのが夢[ゆめ]だ。", "sentence_source": "generated"}, {"text": "去年のトーナメントでは、残念ながら二回戦で負けた。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "去年[きょねん]のトーナメントでは、残念[ざんねん]ながら二回戦[にかいせん]で負[ま]けた。", "sentence_source": "generated"}, {"text": "トーナメントの前の日は、早く寝ることにしている。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "トーナメントの前[まえ]の日[ひ]は、早[はや]く寝[ね]ることにしている。", "sentence_source": "generated"}, {"text": "学校のトーナメントに、クラスから四人が出る。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "学校[がっこう]のトーナメントに、クラスから四人[よにん]が出[で]る。", "sentence_source": "generated"}, {"text": "強い人が集まるトーナメントなので、とても緊張する。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "強[つよ]い人[ひと]が集[あつ]まるトーナメントなので、とても緊張[きんちょう]する。", "sentence_source": "generated"}, {"text": "トーナメントが終わったあと、みんなで食事に行った。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "トーナメントが終[お]わったあと、みんなで食事[しょくじ]に行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "トーナメント", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "一番を決めるために人が集まって行う大会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0625842b-0888-44c2-8a00-218ebf20c50e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37488, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "トーナメント", "is_correct": true, "explanation": "体育館で開かれる卓球の大会を指すので、「開かれる」と合う。"}, {"text": "ラケット", "is_correct": false, "explanation": "卓球で使う道具のことで、開かれるものではない。"}, {"text": "ネット", "is_correct": false, "explanation": "台の中央に張る網のことで、開かれるものではない。"}, {"text": "ユニフォーム", "is_correct": false, "explanation": "選手が着る服のことで、開かれるものではない。"}], "explanations": {"トーナメント": "体育館で開かれる卓球の大会を指すので、「開かれる」と合う。", "ラケット": "卓球で使う道具のことで、開かれるものではない。", "ネット": "台の中央に張る網のことで、開かれるものではない。", "ユニフォーム": "選手が着る服のことで、開かれるものではない。"}, "sentence_index": 0, "correct_answer": "トーナメント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "トーナメントでは、一度負けるともう次の試合に進めない。", "explanation": "ここは〈勝ち抜き方式〉の意味。大会そのものを指す語義ではないので、この文では合わない。"}, {"text": "大事な約束を、トーナメントに書いておいた。", "explanation": "ここは〈ノート〉の意味。トーナメントは書き込むものではなく試合なので、この文では使えない。"}, {"text": "月曜のトーナメントで、英語を習った。", "explanation": "ここは〈授業〉の意味。トーナメントは習うものではなく試合なので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37488, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "トーナメント", "is_correct": true, "explanation": "試合の前の日という文脈で自然に合う。"}, {"text": "カレー", "is_correct": false, "explanation": "料理の名前で、「前の日」に早く寝る話とは結びつかない。"}, {"text": "天ぷら", "is_correct": false, "explanation": "料理の名前で、この文の話題には入らない。"}, {"text": "ホッチキス", "is_correct": false, "explanation": "文房具のことで、「前の日」と結びつかない。"}], "explanations": {"トーナメント": "試合の前の日という文脈で自然に合う。", "カレー": "料理の名前で、「前の日」に早く寝る話とは結びつかない。", "天ぷら": "料理の名前で、この文の話題には入らない。", "ホッチキス": "文房具のことで、「前の日」と結びつかない。"}, "sentence_index": 6, "correct_answer": "トーナメント"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の朝、トーナメントで熱を計った。", "explanation": "ここは〈体温計〉の意味。トーナメントは熱を測る道具ではなく試合なので、この文では合わない。"}, {"text": "うちのトーナメントは、毎朝散歩に行く。", "explanation": "ここは〈ペット〉の意味。トーナメントは散歩する生き物ではないので合わない。"}, {"text": "トーナメントで駅まで行った。", "explanation": "ここは〈乗り物〉の意味。トーナメントは移動の手段ではないので、この文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37488, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週、学校の体育館で卓球のトーナメントを開かれる。", "corrected_sentence": "来週、学校の体育館で卓球のトーナメントが開かれる。", "error_description": "「開かれる」の主語はトーナメントなので「が」を付ける。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37488, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来年のトーナメントを参加することにした。", "corrected_sentence": "来年のトーナメントに参加することにした。", "error_description": "「参加する」は「〜に参加する」の形で使うので、「を」は誤り。「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37489, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「対戦表」を修飾するので「の」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「見る」の主語になると、対戦表を見る文に合わない。"}, {"text": "を", "is_correct": false, "explanation": "「見る」の目的語は対戦表なので、トーナメントを目的語にはできない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準で、対戦表を見る文の流れに合わない。"}], "correct_answer": "の", "explanations": {"の": "「対戦表」を修飾するので「の」が入る。", "が": "「見る」の主語になると、対戦表を見る文に合わない。", "を": "「見る」の目的語は対戦表なので、トーナメントを目的語にはできない。", "より": "「より」は比較の基準で、対戦表を見る文の流れに合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37489, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「勝ち抜く」の目的語になるので「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「勝ち抜く」は場所を表す「に」を取らないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表し、勝ち抜く対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を表すので、勝ち抜く対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「勝ち抜く」の目的語になるので「を」が入る。", "に": "「勝ち抜く」は場所を表す「に」を取らないので合わない。", "と": "「と」は相手や並列を表し、勝ち抜く対象にはならない。", "へ": "「へ」は向かう先を表すので、勝ち抜く対象にはならない。"}, "error_tags": {"に": "場所", "と": "相手・並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37489, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "競技者が勝ち進み、最終的な優勝者を決めるための試合方式。参加者は勝ち抜き戦などで順位を競う。", "primary_collocate": null, "pronunciation": "とーなめんと", "ipa": "toːnameɴto", "syllable_count": 6, "sentences": [{"text": "このトーナメントは、負けた人がそこで終わる方式だ。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "このトーナメントは、負[ま]けた人[ひと]がそこで終[お]わる方式[ほうしき]だ。", "sentence_source": "generated"}, {"text": "トーナメントの対戦表を見ると、決勝まで友達と当たらないとわかった。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "トーナメントの対戦表[たいせんひょう]を見[み]ると、決勝[けっしょう]まで友達[ともだち]と当[あ]たらないとわかった。", "sentence_source": "generated"}, {"text": "十六人が参加するトーナメントでは、四回勝てば優勝だ。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "十六人[じゅうろくにん]が参加[さんか]するトーナメントでは、四回[よんかい]勝[か]てば優勝[ゆうしょう]だ。", "sentence_source": "generated"}, {"text": "トーナメントを勝ち進むうちに、彼はどんどん自信をつけた。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "トーナメントを勝[か]ち進[すす]むうちに、彼[かれ]はどんどん自信[じしん]をつけた。", "sentence_source": "generated"}, {"text": "総当たり戦ではなく、トーナメントで順位を決める。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "総当[そうあ]たり戦[せん]ではなく、トーナメントで順位[じゅんい]を決[き]める。", "sentence_source": "generated"}, {"text": "トーナメントの一回戦で、強い相手と当たってしまった。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "トーナメントの一回戦[いっかいせん]で、強[つよ]い相手[あいて]と当[あ]たってしまった。", "sentence_source": "generated"}, {"text": "準決勝まで進んだが、トーナメントではそこで負けてしまった。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "準決勝[じゅんけっしょう]まで進[すす]んだが、トーナメント[とーなめんと]ではそこで負[ま]けてしまった。", "sentence_source": "generated"}, {"text": "彼女はトーナメントを一度も負けずに勝ち抜いた。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はトーナメントを一度[いちど]も負[ま]けずに勝[か]ち抜[ぬ]いた。", "sentence_source": "generated"}, {"text": "トーナメントでは、一回負けると次の試合に出られない。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "トーナメントでは、一回[いっかい]負[ま]けると次[つぎ]の試合[しあい]に出[で]られない。", "sentence_source": "generated"}, {"text": "今年のトーナメントには、全国から三十二人の選手が集まった。", "target_word": "トーナメント", "complexity_tier": "T3", "furigana": "今年[ことし]のトーナメントには、全国[ぜんこく]から三十二人[さんじゅうににん]の選手[せんしゅ]が集[あつ]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "トーナメント", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "負けたら退場する勝ち抜き式の試合方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0625842b-0888-44c2-8a00-218ebf20c50e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37489, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "トーナメント", "is_correct": true, "explanation": "負けた人がそこで終わる方式の名前なので、主語として合う。"}, {"text": "ユニフォーム", "is_correct": false, "explanation": "試合で着る服のことで、方式の名前にはならない。"}, {"text": "ゴール", "is_correct": false, "explanation": "得点を決める場所のことで、試合の方式ではない。"}, {"text": "キャプテン", "is_correct": false, "explanation": "チームの主将のことで、方式の名前ではない。"}], "explanations": {"トーナメント": "負けた人がそこで終わる方式の名前なので、主語として合う。", "ユニフォーム": "試合で着る服のことで、方式の名前にはならない。", "ゴール": "得点を決める場所のことで、試合の方式ではない。", "キャプテン": "チームの主将のことで、方式の名前ではない。"}, "sentence_index": 0, "correct_answer": "トーナメント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週のトーナメントを、家族みんなで応援に行くことにした。", "explanation": "ここは〈大会〉の意味。勝ち抜きの方式ではなく大会そのものを指すので、この文では使えない。"}, {"text": "去年のトーナメントは、市民体育館で開かれた。", "explanation": "ここは〈大会〉の意味。試合の進め方を表すのではないので、この文では合わない。"}, {"text": "トーナメントで、長い割り算を計算した。", "explanation": "ここは〈計算する〉の意味。トーナメントは計算の方法ではなく試合の方式なので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37489, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "トーナメント", "is_correct": true, "explanation": "準決勝まで進んで負けた試合形式を指すので、文の流れに合う。"}, {"text": "タオル", "is_correct": false, "explanation": "汗を拭く布のことで、負けて終わる試合形式ではない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで、試合の結果とは関係しない。"}, {"text": "ゼッケン", "is_correct": false, "explanation": "選手の番号札のことで、負けた場面の説明にはならない。"}], "explanations": {"トーナメント": "準決勝まで進んで負けた試合形式を指すので、文の流れに合う。", "タオル": "汗を拭く布のことで、負けて終わる試合形式ではない。", "天気": "空模様のことで、試合の結果とは関係しない。", "ゼッケン": "選手の番号札のことで、負けた場面の説明にはならない。"}, "sentence_index": 6, "correct_answer": "トーナメント"}, "level_6": {"correct_sentence_index": 8, "wrong_sentences": [{"text": "売り上げの変化を、トーナメントを見て読み取った。", "explanation": "ここは〈グラフ〉の意味。トーナメントは数字の推移を示す図ではなく試合方式なので、この文では使えない。"}, {"text": "トーナメントに、今日の出来事を書いた。", "explanation": "ここは〈日記〉の意味。トーナメントは書き込む帳面ではなく試合の方式なので、この文には合わない。"}, {"text": "トーナメントで、明日の天気を予報した。", "explanation": "ここは〈天気予報〉の意味。トーナメントは天気を予測するものではなく試合方式なので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
