INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37490, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「形式に合わせる」と言い、合わせる基準を表す「に」。"}, {"text": "が", "is_correct": false, "explanation": "「形式が合わせて書いた」は主語が合わず、文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「形式で合わせる」は手段としても不自然で、合わせる基準を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「形式の合わせて」と続かず、文が成立しない。"}], "correct_answer": "に", "explanations": {"に": "「形式に合わせる」と言い、合わせる基準を表す「に」。", "が": "「形式が合わせて書いた」は主語が合わず、文として成り立たない。", "で": "「形式で合わせる」は手段としても不自然で、合わせる基準を表せない。", "の": "「形式の合わせて」と続かず、文が成立しない。"}, "error_tags": {"が": "主語の誤用", "で": "手段の誤用", "の": "連体修飾の誤用"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内容", "is_correct": true, "explanation": "形式（外側の決まった型）に対して中身を表す語。「決まったやり方」と対になる。"}, {"text": "手順", "is_correct": false, "explanation": "手順は作業の順序を指し、形式の反対語ではない。"}, {"text": "方法", "is_correct": false, "explanation": "方法はやり方そのもので、形式と対になる関係ではない。"}, {"text": "規則", "is_correct": false, "explanation": "規則は守るべき決まりを指し、形式の対義語にはならない。"}], "correct_answer": "内容", "explanations": {"内容": "形式（外側の決まった型）に対して中身を表す語。「決まったやり方」と対になる。", "手順": "手順は作業の順序を指し、形式の反対語ではない。", "方法": "方法はやり方そのもので、形式と対になる関係ではない。", "規則": "規則は守るべき決まりを指し、形式の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
