INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37490, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものが決まった形ややり方のこと。", "primary_collocate": null, "pronunciation": "けいしき", "ipa": "keːɕiki", "syllable_count": 4, "sentences": [{"text": "申し込みの書類は決まった形式で出さなければならない。", "target_word": "形式", "complexity_tier": "T3", "furigana": "申[もう]し込[こ]みの書類[しょるい]は決[き]まった形式[けいしき]で出[だ]さなければならない。", "sentence_source": "generated"}, {"text": "この手紙は、会社用の形式に合わせて書いた。", "target_word": "形式", "complexity_tier": "T3", "furigana": "この手紙[てがみ]は、会社用[かいしゃよう]の形式[けいしき]に合[あ]わせて書[か]いた。", "sentence_source": "generated"}, {"text": "発表の形式が変わって、質問は最後にまとめて受けることになった。", "target_word": "形式", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の形式[けいしき]が変[か]わって、質問[しつもん]は最後[さいご]にまとめて受[う]けることになった。", "sentence_source": "generated"}, {"text": "先生は、レポートの形式を細かく教えてくれた。", "target_word": "形式", "complexity_tier": "T3", "furigana": "先生[せんせい]は、レポートの形式[けいしき]を細[こま]かく教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "履歴書は形式が決まっているので、見本を見ながら書いた。", "target_word": "形式", "complexity_tier": "T3", "furigana": "履歴書[りれきしょ]は形式[けいしき]が決[き]まっているので、見本[みほん]を見[み]ながら書[か]いた。", "sentence_source": "generated"}, {"text": "古い形式の申込用紙は、もう使えない。", "target_word": "形式", "complexity_tier": "T3", "furigana": "古[ふる]い形式[けいしき]の申込用紙[もうしこみようし]は、もう使[つか]えない。", "sentence_source": "generated"}, {"text": "試験の形式が去年と違うので、練習問題をやり直した。", "target_word": "形式", "complexity_tier": "T3", "furigana": "試験[しけん]の形式[けいしき]が去年[きょねん]と違[ちが]うので、練習問題[れんしゅうもんだい]をやり直[なお]した。", "sentence_source": "generated"}, {"text": "このアンケートは、選択肢から選ぶ形式になっている。", "target_word": "形式", "complexity_tier": "T3", "furigana": "このアンケートは、選択肢[せんたくし]から選[えら]ぶ形式[けいしき]になっている。", "sentence_source": "generated"}, {"text": "結婚式は昔の形式にそって行われた。", "target_word": "形式", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]は昔[むかし]の形式[けいしき]にそって行[おこな]われた。", "sentence_source": "generated"}, {"text": "会議の議事録は、会社で決めた形式で作る。", "target_word": "形式", "complexity_tier": "T3", "furigana": "会議[かいぎ]の議事録[ぎじろく]は、会社[かいしゃ]で決[き]めた形式[けいしき]で作[つく]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "形式", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "決まった書き方・やり方としての形式（書類・試験などの定まった様式）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b56525-d686-4f42-9de7-3cd4f31105fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37490, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形式", "is_correct": true, "explanation": "「決まった書き方・やり方」を表し、書類の定まった様式に合う。"}, {"text": "悩み", "is_correct": false, "explanation": "「決まった悩みで出す」は意味が通らず、書類の様式を表さない。"}, {"text": "季節", "is_correct": false, "explanation": "書類を季節で決めて出すという内容にはならない。"}, {"text": "味", "is_correct": false, "explanation": "書類に味という属性はなく、「決まった味で出す」は不自然。"}], "explanations": {"形式": "「決まった書き方・やり方」を表し、書類の定まった様式に合う。", "悩み": "「決まった悩みで出す」は意味が通らず、書類の様式を表さない。", "季節": "書類を季節で決めて出すという内容にはならない。", "味": "書類に味という属性はなく、「決まった味で出す」は不自然。"}, "sentence_index": 0, "correct_answer": "形式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このカフェは形式がおしゃれで、落ち着く。", "explanation": "ここは〈雰囲気〉の意味。形式は決まったやり方を指し、店の空気や感じは表さないので、「おしゃれで落ち着く」とは合わない。"}, {"text": "このクッキーは、星の形式で抜いた。", "explanation": "ここは〈型〉の意味。型は物を抜く道具の形を指すが、形式は書き方・やり方の決まりなので、物の形には使えない。"}, {"text": "このお皿は、丸い形式をしている。", "explanation": "ここは〈形〉の意味。形式は目に見える形ではなく、決まったやり方を指すので、物の形の説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37490, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形式", "is_correct": true, "explanation": "試験の決まった様式（出し方や書き方）を指し、去年と違うという内容に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「試験の天気が去年と違う」とは言えない。"}, {"text": "年齢", "is_correct": false, "explanation": "試験の年齢が変わるという意味にはならない。"}, {"text": "体重", "is_correct": false, "explanation": "「試験の体重」という言い方は成り立たない。"}], "explanations": {"形式": "試験の決まった様式（出し方や書き方）を指し、去年と違うという内容に合う。", "天気": "「試験の天気が去年と違う」とは言えない。", "年齢": "試験の年齢が変わるという意味にはならない。", "体重": "「試験の体重」という言い方は成り立たない。"}, "sentence_index": 6, "correct_answer": "形式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の形式を一週間早めた。", "explanation": "ここは〈日程〉の意味。形式は決まったやり方を指し、いつ行うかという日程は表さないので、「早める」とは合わない。"}, {"text": "この建物は、遠くから見ても形式が美しい。", "explanation": "ここは〈姿・見た目〉の意味。形式は決まったやり方の枠組みを指し、見た目の美しさは表さない。"}, {"text": "この果物は、形式が甘くておいしい。", "explanation": "ここは〈味〉の意味。形式は決まったやり方を指し、味は表さないので、「甘くておいしい」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37490, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "申込書は決まった形式を従って書く。", "corrected_sentence": "申込書は決まった形式に従って書く。", "error_description": "「従う」は「〜に従う」と言うため、「形式を」は誤り。正しくは「形式に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37490, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "書類の形式を、昨年から変わった。", "corrected_sentence": "書類の形式が、昨年から変わった。", "error_description": "「変わる」は主語に「が」を取る自動詞なので、「形式を」は誤り。正しくは「形式が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37491, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「形式で建てる」と言い、建て方の型を表す「で」。"}, {"text": "へ", "is_correct": false, "explanation": "「形式へ建てられている」は方向を表す「へ」が形式に合わず、文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「形式を建てる」は目的語として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「形式が建てられている」は主語として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「形式で建てる」と言い、建て方の型を表す「で」。", "へ": "「形式へ建てられている」は方向を表す「へ」が形式に合わず、文として成り立たない。", "を": "「形式を建てる」は目的語として成り立たない。", "が": "「形式が建てられている」は主語として成り立たない。"}, "error_tags": {"を": "目的語の誤用", "が": "主語の誤用", "へ": "方向の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37491, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「形式を守る」と言い、守る対象を表す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「形式が守って」は主語が合わず、文として不自然。"}, {"text": "の", "is_correct": false, "explanation": "「能の形式の守って」と続かず、文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「形式で守る」は手段の意味になり、守る対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「形式を守る」と言い、守る対象を表す「を」。", "が": "「形式が守って」は主語が合わず、文として不自然。", "の": "「能の形式の守って」と続かず、文が成立しない。", "で": "「形式で守る」は手段の意味になり、守る対象を表せない。"}, "error_tags": {"が": "主語の誤用", "の": "連体修飾の誤用", "で": "手段の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37491, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の決まった形や方法。種類を分けるときの型。", "primary_collocate": null, "pronunciation": "けいしき", "ipa": "keːɕiki", "syllable_count": 4, "sentences": [{"text": "詩にはいろいろな形式があり、俳句もその一つだ。", "target_word": "形式", "complexity_tier": "T3", "furigana": "詩[し]にはいろいろな形式[けいしき]があり、俳句[はいく]もその一[ひと]つだ。", "sentence_source": "generated"}, {"text": "この建物は、古い寺院の形式で建てられている。", "target_word": "形式", "complexity_tier": "T3", "furigana": "この建物[たてもの]は、古[ふる]い寺院[じいん]の形式[けいしき]で建[た]てられている。", "sentence_source": "generated"}, {"text": "音楽には、ソナタや協奏曲など、さまざまな形式がある。", "target_word": "形式", "complexity_tier": "T3", "furigana": "音楽[おんがく]には、ソナタや協奏曲[きょうそうきょく]など、さまざまな形式[けいしき]がある。", "sentence_source": "generated"}, {"text": "授業の形式は、講義とグループ討論の二つに分けられる。", "target_word": "形式", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の形式[けいしき]は、講義[こうぎ]とグループ討論[とうろん]の二[ふた]つに分[わ]けられる。", "sentence_source": "generated"}, {"text": "賃貸物件には、ワンルームや一戸建てなど、いくつかの形式がある。", "target_word": "形式", "complexity_tier": "T3", "furigana": "賃貸物件[ちんたいぶっけん]には、ワンルームや一戸建[いっこだ]てなど、いくつかの形式[けいしき]がある。", "sentence_source": "generated"}, {"text": "この小説は、日記の形式で書かれている。", "target_word": "形式", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、日記[にっき]の形式[けいしき]で書[か]かれている。", "sentence_source": "generated"}, {"text": "映画には、実写とアニメーションという二つの形式がある。", "target_word": "形式", "complexity_tier": "T3", "furigana": "映画[えいが]には、実写[じっしゃ]とアニメーションという二[ふた]つの形式[けいしき]がある。", "sentence_source": "generated"}, {"text": "この劇は、昔ながらの能の形式を守って上演された。", "target_word": "形式", "complexity_tier": "T3", "furigana": "この劇[げき]は、昔[むかし]ながらの能[のう]の形式[けいしき]を守[まも]って上演[じょうえん]された。", "sentence_source": "generated"}, {"text": "この曲は、三つの部分に分かれた形式で作られている。", "target_word": "形式", "complexity_tier": "T3", "furigana": "この曲[きょく]は、三[みっ]つの部分[ぶぶん]に分[わ]かれた形式[けいしき]で作[つく]られている。", "sentence_source": "generated"}, {"text": "ニュースの伝え方には、文章や映像などいくつかの形式がある。", "target_word": "形式", "complexity_tier": "T3", "furigana": "ニュースの伝[つた]え方[かた]には、文章[ぶんしょう]や映像[えいぞう]などいくつかの形式[けいしき]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "形式", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事を種類分けするときの型・タイプとしての形式（詩・音楽・建築などの様式）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b56525-d686-4f42-9de7-3cd4f31105fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37491, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形式", "is_correct": true, "explanation": "詩の様式・型（五言・七言など）を指し、「いろいろな形式がある」に合う。"}, {"text": "天気", "is_correct": false, "explanation": "詩を天気で分類するという言い方は成り立たない。"}, {"text": "年齢", "is_correct": false, "explanation": "詩の年齢で種類を分けるという内容にはならない。"}, {"text": "味", "is_correct": false, "explanation": "詩の味で分けるという言い方は不自然。"}], "explanations": {"形式": "詩の様式・型（五言・七言など）を指し、「いろいろな形式がある」に合う。", "天気": "詩を天気で分類するという言い方は成り立たない。", "年齢": "詩の年齢で種類を分けるという内容にはならない。", "味": "詩の味で分けるという言い方は不自然。"}, "sentence_index": 0, "correct_answer": "形式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この絵は、青い形式で描かれている。", "explanation": "ここは〈色〉の意味。形式は種類や型を指し、色合いは表さないので、「青い」とは合わない。"}, {"text": "この花は、形式がとても良い香りがする。", "explanation": "ここは〈香り〉の意味。形式は型や種類を指し、香りは表さないので、「良い香りがする」とは合わない。"}, {"text": "この箱は、形式が大きくて入らない。", "explanation": "ここは〈大きさ〉の意味。形式は型や種類を指し、寸法は表さないので、「大きくて入らない」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37491, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形式", "is_correct": true, "explanation": "映画の作り方の型（実写とアニメーション）を指し、「二つの形式がある」に合う。"}, {"text": "機嫌", "is_correct": false, "explanation": "映画に機嫌という属性はなく、「二つの機嫌がある」は成り立たない。"}, {"text": "季節", "is_correct": false, "explanation": "映画を季節で分けるという内容にはならない。"}, {"text": "体重", "is_correct": false, "explanation": "映画の体重という言い方は成り立たない。"}], "explanations": {"形式": "映画の作り方の型（実写とアニメーション）を指し、「二つの形式がある」に合う。", "機嫌": "映画に機嫌という属性はなく、「二つの機嫌がある」は成り立たない。", "季節": "映画を季節で分けるという内容にはならない。", "体重": "映画の体重という言い方は成り立たない。"}, "sentence_index": 6, "correct_answer": "形式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープは形式がおいしい。", "explanation": "ここは〈味〉の意味。形式は型や種類を指し、味は表さないので、「おいしい」とは合わない。"}, {"text": "この地域は、形式が一年中暖かい。", "explanation": "ここは〈気候〉の意味。形式は様式・型を指し、気温は表さないので、「暖かい」とは合わない。"}, {"text": "このケーキは、形式に流して冷やし固める。", "explanation": "ここは〈型〉の意味。型は物を入れて形を作る容器を指すが、形式は物理的な型ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37491, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この詩は、五七調の形式に書かれている。", "corrected_sentence": "この詩は、五七調の形式で書かれている。", "error_description": "「書く」の手段・方法を表すのは「で」。「形式に」は誤りで、正しくは「形式で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37491, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この小説は、手紙の形式を語られている。", "corrected_sentence": "この小説は、手紙の形式で語られている。", "error_description": "「語る」の手段を表すのは「で」。「形式を」は誤りで、正しくは「形式で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37492, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「イベントをします」で、行事を行う対象を表す。"}, {"text": "へ", "is_correct": false, "explanation": "「イベントへします」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「イベントのします」は文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「イベントがします」では、何をするかの対象が示せず文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「イベントをします」で、行事を行う対象を表す。", "へ": "「イベントへします」は文として成り立たない。", "の": "「イベントのします」は文として成り立たない。", "が": "「イベントがします」では、何をするかの対象が示せず文として成り立たない。"}, "error_tags": {"へ": "direction", "の": "ungrammatical", "が": "subject_marker"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
