INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37492, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなで集まって、楽しいことをするための計画や行事のことだよ。", "primary_collocate": null, "pronunciation": "いべんと", "ipa": "ibeɴto", "syllable_count": 4, "sentences": [{"text": "イベントは明日だ。", "target_word": "イベント", "complexity_tier": "T1", "furigana": "いべんとはあしただ。", "sentence_source": "generated"}, {"text": "イベントが好き。", "target_word": "イベント", "complexity_tier": "T1", "furigana": "いべんとがすき。", "sentence_source": "generated"}, {"text": "学校でイベントをします。", "target_word": "イベント", "complexity_tier": "T2", "furigana": "がっこうでいべんとをします。", "sentence_source": "generated"}, {"text": "友だちとイベントに行きました。", "target_word": "イベント", "complexity_tier": "T2", "furigana": "ともだちといべんとにいきました。", "sentence_source": "generated"}, {"text": "夏休みに、公園で楽しいイベントがある。", "target_word": "イベント", "complexity_tier": "T3", "furigana": "なつやすみに、こうえんでたのしいいべんとがある。", "sentence_source": "generated"}, {"text": "みんなでイベントの計画を立てている。", "target_word": "イベント", "complexity_tier": "T3", "furigana": "みんなでいべんとのけいかくをたてている。", "sentence_source": "generated"}, {"text": "イベントでは、歌やゲームをして遊ぶことができる。", "target_word": "イベント", "complexity_tier": "T4", "furigana": "いべんとでは、うたやげーむをしてあそぶことができる。", "sentence_source": "generated"}, {"text": "子ども向けのイベントを手伝ったら、とても喜ばれた。", "target_word": "イベント", "complexity_tier": "T4", "furigana": "こどもむけのいべんとをてつだったら、とてもよろこばれた。", "sentence_source": "generated"}, {"text": "クラスで考えたイベントが大成功して、先生にもほめてもらうことができた。", "target_word": "イベント", "complexity_tier": "T5", "furigana": "くらすでかんがえたいべんとがだいせいこうして、せんせいにもほめてもらうことができた。", "sentence_source": "generated"}, {"text": "毎月開かれるイベントを楽しみにしている家族が、この町にはたくさんいる。", "target_word": "イベント", "complexity_tier": "T5", "furigana": "まいつきひらかれるいべんとをたのしみにしているかぞくが、このまちにはたくさんいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "イベント会場", "label": "派生"}, {"form": "イベント名", "label": "派生"}, {"form": "イベント開催", "label": "派生"}], "register": "casual", "sense_fingerprint": "名詞 | みんなで楽しむ計画や行事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8930a259-a7dd-4914-8e14-2078091f2b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37492, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "イベント", "is_correct": true, "explanation": "「イベントは明日だ」で、行事の日を言う意味に合う。"}, {"text": "帽子", "is_correct": false, "explanation": "形は合うが、「帽子は明日だ」では意味が合わない。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、「机は明日だ」では意味が合わない。"}, {"text": "空", "is_correct": false, "explanation": "形は合うが、「空は明日だ」では意味が合わない。"}], "explanations": {"イベント": "「イベントは明日だ」で、行事の日を言う意味に合う。", "帽子": "形は合うが、「帽子は明日だ」では意味が合わない。", "机": "形は合うが、「机は明日だ」では意味が合わない。", "空": "形は合うが、「空は明日だ」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "イベント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "イベントが痛くて、病院へ行きました。", "explanation": "「イベント」は行事で、体の痛みを感じる物ではない。"}, {"text": "イベントを髪にかけて、きれいにした。", "explanation": "「イベント」は行事で、髪にかける物ではない。"}, {"text": "このイベントは大きくて、とても足が速い。", "explanation": "「イベント」は行事で、足が速いという性質はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37492, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "イベント", "is_correct": true, "explanation": "「イベントでは歌やゲームをして遊べる」で、楽しい催しの意味に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "形は合うが、冷蔵庫で歌やゲームをして遊ぶのは意味が合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、辞書で歌やゲームをして遊ぶのは意味が合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "形は合うが、鉛筆で歌やゲームをして遊ぶのは意味が合わない。"}], "explanations": {"イベント": "「イベントでは歌やゲームをして遊べる」で、楽しい催しの意味に合う。", "冷蔵庫": "形は合うが、冷蔵庫で歌やゲームをして遊ぶのは意味が合わない。", "辞書": "形は合うが、辞書で歌やゲームをして遊ぶのは意味が合わない。", "鉛筆": "形は合うが、鉛筆で歌やゲームをして遊ぶのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "イベント"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟は新しいイベントをはいて、外へ出かけた。", "explanation": "「イベント」は行事で、靴のようにはく物ではない。"}, {"text": "うちではイベントを三匹飼っている。", "explanation": "「イベント」は行事で、動物のように飼えない。"}, {"text": "このイベントは甘くて、コップに注いで飲んだ。", "explanation": "「イベント」は行事で、飲み物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37492, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちとイベントが行きました。", "corrected_sentence": "友だちとイベントに行きました。", "error_description": "「イベント」の後の助詞が誤り。行き先を表す「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
