INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37493, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特定の目的のために企画・開催される、集まりや催し物。", "primary_collocate": null, "pronunciation": "いべんと", "ipa": "ibeɴto", "syllable_count": 4, "sentences": [{"text": "学校イベントという儀礼的空間において、Tシャツデザインは単なる装飾を超え、集団内の微細な階層や個性の顕現として機能し得る。", "target_word": "イベント", "complexity_tier": "T6", "furigana": "がっこういべんとというぎれいてきくうかんにおいて、Tしゃつでざいんはたんなるそうしょくをこえ、しゅうだんないのびさいなかいそうやこせいのけんげんとしてきのうしえる。", "sentence_source": "mined"}, {"text": "イベントに行く。", "target_word": "イベント", "complexity_tier": "T1", "furigana": "いべんとにいく。", "sentence_source": "generated"}, {"text": "今日のイベントは楽しかったです。", "target_word": "イベント", "complexity_tier": "T2", "furigana": "きょうのいべんとはたのしかったです。", "sentence_source": "generated"}, {"text": "駅の前でイベントがあります。", "target_word": "イベント", "complexity_tier": "T2", "furigana": "えきのまえでいべんとがあります。", "sentence_source": "generated"}, {"text": "来月、町で大きなイベントが開かれる。", "target_word": "イベント", "complexity_tier": "T3", "furigana": "らいげつ、まちでおおきないべんとがひらかれる。", "sentence_source": "generated"}, {"text": "イベントの準備のために、みんなで集まった。", "target_word": "イベント", "complexity_tier": "T3", "furigana": "いべんとのじゅんびのために、みんなであつまった。", "sentence_source": "generated"}, {"text": "このイベントに参加すれば、新しい友だちができるかもしれない。", "target_word": "イベント", "complexity_tier": "T4", "furigana": "このいべんとにさんかすれば、あたらしいともだちができるかもしれない。", "sentence_source": "generated"}, {"text": "雨のため、屋外のイベントは中止になってしまった。", "target_word": "イベント", "complexity_tier": "T4", "furigana": "あめのため、おくがいのいべんとはちゅうしになってしまった。", "sentence_source": "generated"}, {"text": "地域の人々が協力して企画したイベントには、毎年たくさんの観光客が訪れる。", "target_word": "イベント", "complexity_tier": "T5", "furigana": "ちいきのひとびとがきょうりょくしてきかくしたいべんとには、まいとしたくさんのかんこうきゃくがおとずれる。", "sentence_source": "generated"}, {"text": "イベントの目的がはっきりしていないと、参加者に魅力が伝わりにくい。", "target_word": "イベント", "complexity_tier": "T5", "furigana": "いべんとのもくてきがはっきりしていないと、さんかしゃにみりょくがつたわりにくい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "イベント会場", "label": "派生"}, {"form": "イベント名", "label": "派生"}, {"form": "イベント開催", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 目的を持って開く催し物や集まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 4 words above tier T1 (max 2): 儀礼 (Zipf 3.28), 微細 (Zipf 3.24), 階層 (Zipf 3.74), 顕現 (Zipf 2.9)']::text[], '8930a259-a7dd-4914-8e14-2078091f2b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37493, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "イベント", "is_correct": true, "explanation": "「学校イベント」は学校の催し物で、文脈に意味が合う。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、「学校地図という儀礼的空間」では意味が合わない。"}, {"text": "靴下", "is_correct": false, "explanation": "形は合うが、「学校靴下」では儀礼的空間の意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「学校天気」では意味が合わない。"}], "explanations": {"イベント": "「学校イベント」は学校の催し物で、文脈に意味が合う。", "地図": "形は合うが、「学校地図という儀礼的空間」では意味が合わない。", "靴下": "形は合うが、「学校靴下」では儀礼的空間の意味が合わない。", "天気": "形は合うが、「学校天気」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "イベント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんにイベントを食べた。", "explanation": "「イベント」は催し物で、食べ物ではない。"}, {"text": "このイベントは長さが三メートルある。", "explanation": "「イベント」は催しで、長さを測れる物ではない。"}, {"text": "コンビニでイベントを一つ買ってきた。", "explanation": "「イベント」は催し物で、店で買える物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37493, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "イベント", "is_correct": true, "explanation": "「イベントに参加する」で友だちができるという流れに合う。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが、「財布に参加する」では意味が合わない。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、「机に参加する」では意味が合わない。"}, {"text": "電池", "is_correct": false, "explanation": "形は合うが、「電池に参加する」では意味が合わない。"}], "explanations": {"イベント": "「イベントに参加する」で友だちができるという流れに合う。", "財布": "形は合うが、「財布に参加する」では意味が合わない。", "机": "形は合うが、「机に参加する」では意味が合わない。", "電池": "形は合うが、「電池に参加する」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "イベント"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "イベントを着ると、体が温かくなる。", "explanation": "「イベント」は催し物で、服のように着る物ではない。"}, {"text": "犬のイベントが庭で吠えている。", "explanation": "「イベント」は催し物で、吠える動物ではない。"}, {"text": "彼はイベントに乗って、海を渡った。", "explanation": "「イベント」は乗り物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37493, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町でイベントを食べました。", "corrected_sentence": "町でイベントを開きました。", "error_description": "「イベント」と組み合わせる動詞が不自然。「食べる」ではなく「開く」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
