INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37494, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "到着点を表す「に」で「駅に入る」となる。"}, {"text": "の", "is_correct": false, "explanation": "「駅の入ってきた」は文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "すでに主語「集団が」があり、「駅が」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「駅で入ってくる」は不自然で、到着点にならない。"}], "correct_answer": "に", "explanations": {"に": "到着点を表す「に」で「駅に入る」となる。", "の": "「駅の入ってきた」は文として成り立たない。", "が": "すでに主語「集団が」があり、「駅が」では文が成り立たない。", "で": "「駅で入ってくる」は不自然で、到着点にならない。"}, "error_tags": {"の": "ungrammatical", "が": "subject_marker", "で": "location_of_action"}, "sentence_index": 2}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "個人", "is_correct": true, "explanation": "集団に対して、一人の人を表す反意語。"}, {"text": "仲間", "is_correct": false, "explanation": "仲間は集団を作る人で、反意語ではない。"}, {"text": "団体", "is_correct": false, "explanation": "団体は集団の類義語である。"}, {"text": "群れ", "is_correct": false, "explanation": "群れは集団の類義語である。"}], "correct_answer": "個人", "explanations": {"個人": "集団に対して、一人の人を表す反意語。", "仲間": "仲間は集団を作る人で、反意語ではない。", "団体": "団体は集団の類義語である。", "群れ": "群れは集団の類義語である。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37494, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「作る」の対象を表す「を」が自然。"}, {"text": "に", "is_correct": false, "explanation": "「集団に作る」とは言えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では「作る」につながらない。"}, {"text": "ほど", "is_correct": false, "explanation": "「集団ほど作って」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「作る」の対象を表す「を」が自然。", "に": "「集団に作る」とは言えない。", "へ": "方向を表す「へ」では「作る」につながらない。", "ほど": "「集団ほど作って」では文が成り立たない。"}, "error_tags": {"に": "target_or_location", "へ": "direction", "ほど": "ungrammatical"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "個人", "is_correct": true, "explanation": "集団に対する、一人の人を表す反意語。"}, {"text": "大勢", "is_correct": false, "explanation": "大勢は人数の多さを表し、集団に近い語である。"}, {"text": "家族", "is_correct": false, "explanation": "家族は小さな集団の一種で、反意語ではない。"}, {"text": "地域", "is_correct": false, "explanation": "地域は場所を表す語で、反意語ではない。"}], "correct_answer": "個人", "explanations": {"個人": "集団に対する、一人の人を表す反意語。", "大勢": "大勢は人数の多さを表し、集団に近い語である。", "家族": "家族は小さな集団の一種で、反意語ではない。", "地域": "地域は場所を表す語で、反意語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37494, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんの人が集まっているグループのことです。", "primary_collocate": null, "pronunciation": "しゅうだん", "ipa": "ɕɯːdaɴ", "syllable_count": 4, "sentences": [{"text": "集団で歩く。", "target_word": "集団", "complexity_tier": "T1", "furigana": "しゅうだんであるく。", "sentence_source": "generated"}, {"text": "集団が来た。", "target_word": "集団", "complexity_tier": "T1", "furigana": "しゅうだんがきた。", "sentence_source": "generated"}, {"text": "大きな集団が駅に入ってきた。", "target_word": "集団", "complexity_tier": "T2", "furigana": "おおきなしゅうだんがえきにはいってきた。", "sentence_source": "generated"}, {"text": "集団の中に友だちがいます。", "target_word": "集団", "complexity_tier": "T2", "furigana": "しゅうだんのなかにともだちがいます。", "sentence_source": "generated"}, {"text": "観光客の集団が、写真を撮っている。", "target_word": "集団", "complexity_tier": "T3", "furigana": "かんこうきゃくのしゅうだんが、しゃしんをとっている。", "sentence_source": "generated"}, {"text": "山で、大きな集団からはぐれてしまった。", "target_word": "集団", "complexity_tier": "T3", "furigana": "やまで、おおきなしゅうだんからはぐれてしまった。", "sentence_source": "generated"}, {"text": "昔の人々は集団で生活することで、敵から身を守っていた。", "target_word": "集団", "complexity_tier": "T4", "furigana": "むかしのひとびとはしゅうだんでせいかつすることで、てきからみをまもっていた。", "sentence_source": "generated"}, {"text": "集団を作って遊ぶ子どもたちの声が、公園に響いていた。", "target_word": "集団", "complexity_tier": "T4", "furigana": "しゅうだんをつくってあそぶこどもたちのこえが、こうえんにひびいていた。", "sentence_source": "generated"}, {"text": "先頭の集団が坂を登り切ったとき、観客から大きな拍手が起こった。", "target_word": "集団", "complexity_tier": "T5", "furigana": "せんとうのしゅうだんがさかをのぼりきったとき、かんきゃくからおおきなはくしゅがおこった。", "sentence_source": "generated"}, {"text": "彼はどんな集団の中にいても、自分のペースを崩さない人だ。", "target_word": "集団", "complexity_tier": "T5", "furigana": "かれはどんなしゅうだんのなかにいても、じぶんのぺーすをくずさないひとだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集団的", "label": "派生"}, {"form": "集団化", "label": "派生"}, {"form": "集団生活", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 多くの人が集まったグループ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8930a259-a7dd-4914-8e14-2078091f2b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37494, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集団", "is_correct": true, "explanation": "人のグループで歩くという意味になり、自然。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが意味が合わない。辞書で歩くという意味にならない。"}, {"text": "空気", "is_correct": false, "explanation": "形は合うが意味が合わない。空気で歩くとは言えない。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが意味が合わない。机で歩くとは言えない。"}], "explanations": {"集団": "人のグループで歩くという意味になり、自然。", "辞書": "形は合うが意味が合わない。辞書で歩くという意味にならない。", "空気": "形は合うが意味が合わない。空気で歩くとは言えない。", "机": "形は合うが意味が合わない。机で歩くとは言えない。"}, "sentence_index": 0, "correct_answer": "集団"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "集団を昨日の夜に食べました。", "explanation": "集団は人のグループで、食べるものではない。"}, {"text": "集団は一人で駅に着きました。", "explanation": "集団は多くの人の集まりなので、「一人で」と矛盾する。"}, {"text": "かばんの中に集団が入っています。", "explanation": "集団は人のグループなので、かばんの中に入る物としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37494, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集団", "is_correct": true, "explanation": "人々が集まって生活し、敵から身を守るという意味に合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが意味が合わない。机で生活して敵から身を守るとは言えない。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが意味が合わない。辞書で生活するという意味にならない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。季節で生活して身を守るとは言えない。"}], "explanations": {"集団": "人々が集まって生活し、敵から身を守るという意味に合う。", "机": "形は合うが意味が合わない。机で生活して敵から身を守るとは言えない。", "辞書": "形は合うが意味が合わない。辞書で生活するという意味にならない。", "季節": "形は合うが意味が合わない。季節で生活して身を守るとは言えない。"}, "sentence_index": 6, "correct_answer": "集団"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "集団を食べながら、駅まで歩いた。", "explanation": "集団は人のグループで、食べる対象ではない。"}, {"text": "教室には集団が一人だけいた。", "explanation": "集団は多くの人の集まりなので、「一人だけ」とは言えない。"}, {"text": "机の上に大きな集団を置いた。", "explanation": "集団は人のグループで、机の上に置く物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37494, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "集団を来た。", "corrected_sentence": "集団が来た。", "error_description": "「集団」の後の助詞が誤り。「来る」の主語には「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37494, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔の人々は集団を生活することで、敵から身を守っていた。", "corrected_sentence": "昔の人々は集団で生活することで、敵から身を守っていた。", "error_description": "集団は「生活する」の手段・形態を表すので「で」が正しい。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37495, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「必要です」の対象を示す「が」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「必要です」の前に「を」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「必要です」とつながらない。"}, {"text": "の", "is_correct": false, "explanation": "「決まりの必要です」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「必要です」の対象を示す「が」が自然。", "を": "「必要です」の前に「を」は使えない。", "へ": "方向を表す「へ」は「必要です」とつながらない。", "の": "「決まりの必要です」は文として成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "の": "ungrammatical"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "個人", "is_correct": true, "explanation": "集団に対して、一人の人を表す反意語。"}, {"text": "団体", "is_correct": false, "explanation": "団体は集団に近い類義語で、反意語ではない。"}, {"text": "仲間", "is_correct": false, "explanation": "仲間は集団の構成員を表し、反意語ではない。"}, {"text": "組織", "is_correct": false, "explanation": "組織は集団に近い語で、反意語ではない。"}], "correct_answer": "個人", "explanations": {"個人": "集団に対して、一人の人を表す反意語。", "団体": "団体は集団に近い類義語で、反意語ではない。", "仲間": "仲間は集団の構成員を表し、反意語ではない。", "組織": "組織は集団に近い語で、反意語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37495, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「集団」が主語として「研究している」にかかる。"}, {"text": "を", "is_correct": false, "explanation": "すでに「技術を」があり、集団に「を」は付けられない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では主語にならず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「専門家の集団に、新しい技術を研究している」では主語がなく文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「集団」が主語として「研究している」にかかる。", "を": "すでに「技術を」があり、集団に「を」は付けられない。", "へ": "方向を表す「へ」では主語にならず文が成り立たない。", "に": "「専門家の集団に、新しい技術を研究している」では主語がなく文が成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "に": "ungrammatical"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "個人", "is_correct": true, "explanation": "集団に対する、一人の人を表す反意語。"}, {"text": "全員", "is_correct": false, "explanation": "全員は集団の全体を指し、反意語ではない。"}, {"text": "集会", "is_correct": false, "explanation": "集会は人が集まる催しで、反意語ではない。"}, {"text": "社会", "is_correct": false, "explanation": "社会は大きな集まりで、反意語ではない。"}], "correct_answer": "個人", "explanations": {"個人": "集団に対する、一人の人を表す反意語。", "全員": "全員は集団の全体を指し、反意語ではない。", "集会": "集会は人が集まる催しで、反意語ではない。", "社会": "社会は大きな集まりで、反意語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37495, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の人が集まってできた、まとまりのあるグループ。", "primary_collocate": null, "pronunciation": "しゅうだん", "ipa": "ɕɯːdaɴ", "syllable_count": 4, "sentences": [{"text": "学校イベントという儀礼的空間において、Tシャツデザインは単なる装飾を超え、集団内の微細な階層や個性の顕現として機能し得る。", "target_word": "集団", "complexity_tier": "T6", "furigana": "がっこういべんとというぎれいてきくうかんにおいて、Tしゃつでざいんはたんなるそうしょくをこえ、しゅうだんないのびさいなかいそうやこせいのけんげんとしてきのうしえる。", "sentence_source": "mined"}, {"text": "集団には、決まりが必要です。", "target_word": "集団", "complexity_tier": "T2", "furigana": "しゅうだんには、きまりがひつようです。", "sentence_source": "generated"}, {"text": "この集団は十人のメンバーでできている。", "target_word": "集団", "complexity_tier": "T2", "furigana": "このしゅうだんはじゅうにんのめんばーでできている。", "sentence_source": "generated"}, {"text": "集団の目標をみんなで話し合った。", "target_word": "集団", "complexity_tier": "T3", "furigana": "しゅうだんのもくひょうをみんなではなしあった。", "sentence_source": "generated"}, {"text": "彼は集団に入るのが苦手だ。", "target_word": "集団", "complexity_tier": "T3", "furigana": "かれはしゅうだんにはいるのがにがてだ。", "sentence_source": "generated"}, {"text": "集団の一員として、責任を持って行動してください。", "target_word": "集団", "complexity_tier": "T4", "furigana": "しゅうだんのいちいんとして、せきにんをもってこうどうしてください。", "sentence_source": "generated"}, {"text": "同じ集団の中でも、考え方は人によって違う。", "target_word": "集団", "complexity_tier": "T4", "furigana": "おなじしゅうだんのなかでも、かんがえかたはひとによってちがう。", "sentence_source": "generated"}, {"text": "専門家の集団が、新しい技術を研究している。", "target_word": "集団", "complexity_tier": "T4", "furigana": "せんもんかのしゅうだんが、あたらしいぎじゅつをけんきゅうしている。", "sentence_source": "generated"}, {"text": "集団で決めたことは、たとえ自分が反対でも守る必要がある。", "target_word": "集団", "complexity_tier": "T5", "furigana": "しゅうだんできめたことは、たとえじぶんがはんたいでもまもるひつようがある。", "sentence_source": "generated"}, {"text": "小さな集団ほど、一人ひとりの意見が全体に大きく影響するものだ。", "target_word": "集団", "complexity_tier": "T5", "furigana": "ちいさなしゅうだんほど、ひとりひとりのいけんがぜんたいにおおきくえいきょうするものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集団的", "label": "派生"}, {"form": "集団化", "label": "派生"}, {"form": "集団生活", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人が集まってできたまとまり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8930a259-a7dd-4914-8e14-2078091f2b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37495, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集団", "is_correct": true, "explanation": "人の集まりを表し、「集団内の階層や個性」という文脈に合う。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが意味が合わない。野菜の内部に階層や個性の顕現という文脈は成り立たない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。Tシャツデザインが季節内の階層を示すとは言えない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気に階層や個性があるとは言えない。"}], "explanations": {"集団": "人の集まりを表し、「集団内の階層や個性」という文脈に合う。", "野菜": "形は合うが意味が合わない。野菜の内部に階層や個性の顕現という文脈は成り立たない。", "季節": "形は合うが意味が合わない。Tシャツデザインが季節内の階層を示すとは言えない。", "天気": "形は合うが意味が合わない。天気に階層や個性があるとは言えない。"}, "sentence_index": 0, "correct_answer": "集団"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "集団を一人で食べたら、とてもおいしかった。", "explanation": "集団は人のまとまりなので、食べるものとして使うのは誤り。"}, {"text": "彼は集団という一人きりの部屋で本を読んだ。", "explanation": "集団は複数の人のまとまりで、「一人きり」とは矛盾する。"}, {"text": "私は集団を右手で持って、かばんに入れた。", "explanation": "集団は人のまとまりを指す語で、手で持てる物としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37495, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集団", "is_correct": true, "explanation": "「同じ集団の中でも考え方は違う」と、人のまとまりを表す文脈に合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが意味が合わない。机の中で人の考え方が違うとは言えない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気の中で考え方が人によって違うとは言えない。"}, {"text": "時計", "is_correct": false, "explanation": "形は合うが意味が合わない。時計の中に人の考え方の違いは出てこない。"}], "explanations": {"集団": "「同じ集団の中でも考え方は違う」と、人のまとまりを表す文脈に合う。", "机": "形は合うが意味が合わない。机の中で人の考え方が違うとは言えない。", "天気": "形は合うが意味が合わない。天気の中で考え方が人によって違うとは言えない。", "時計": "形は合うが意味が合わない。時計の中に人の考え方の違いは出てこない。"}, "sentence_index": 6, "correct_answer": "集団"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は集団を二つ飲みました。", "explanation": "集団は人のまとまりで、飲み物のように「飲む」ことはできない。"}, {"text": "集団を冷蔵庫に入れて冷やした。", "explanation": "集団は人のまとまりで、冷蔵庫に入れて冷やす物ではない。"}, {"text": "この集団は、たった一人の人だ。", "explanation": "集団は複数の人のまとまりで、一人の人を指すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37495, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この集団を十人のメンバーでできている。", "corrected_sentence": "この集団は十人のメンバーでできている。", "error_description": "「集団」の後の助詞が誤り。「できている」の主題には「は」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37495, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "集団が一員として、責任を持って行動してください。", "corrected_sentence": "集団の一員として、責任を持って行動してください。", "error_description": "「集団」の後の助詞が誤り。「一員」につなぐには「の」を使う。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4fab62d-0a4e-45e4-a502-4510257a1863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37496, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不可視", "is_correct": true, "explanation": "「可視」の対義語。見えない状態を表し、文中の「見えない部分」と反対の関係になる。"}, {"text": "煙", "is_correct": false, "explanation": "名詞だが「可視」の対義語ではない。見えるものの一つで、見える・見えないの対にはならない。"}, {"text": "波", "is_correct": false, "explanation": "名詞だが「可視」の対義語ではない。光の性質を表す語だが、可視の反対語とはされない。"}, {"text": "雲", "is_correct": false, "explanation": "名詞だが「可視」の対義語ではない。空に見えるものの一つで、見える・見えないの対とは別。"}], "correct_answer": "不可視", "explanations": {"不可視": "「可視」の対義語。見えない状態を表し、文中の「見えない部分」と反対の関係になる。", "煙": "名詞だが「可視」の対義語ではない。見えるものの一つで、見える・見えないの対にはならない。", "波": "名詞だが「可視」の対義語ではない。光の性質を表す語だが、可視の反対語とはされない。", "雲": "名詞だが「可視」の対義語ではない。空に見えるものの一つで、見える・見えないの対とは別。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37496, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不可視", "is_correct": true, "explanation": "「可視」の対義語。見えない状態を表し、この文の「見えない」と同じ内容になる。"}, {"text": "熱", "is_correct": false, "explanation": "名詞だが「可視」の対義語ではない。感じるものの一つで、見える・見えないの対にはならない。"}, {"text": "地図", "is_correct": false, "explanation": "名詞だが「可視」の対義語ではない。見るための資料で、見える・見えないの対とは別。"}, {"text": "足音", "is_correct": false, "explanation": "名詞だが「可視」の対義語ではない。耳で聞くもので、見える・見えないの対にはならない。"}], "correct_answer": "不可視", "explanations": {"不可視": "「可視」の対義語。見えない状態を表し、この文の「見えない」と同じ内容になる。", "熱": "名詞だが「可視」の対義語ではない。感じるものの一つで、見える・見えないの対にはならない。", "地図": "名詞だが「可視」の対義語ではない。見るための資料で、見える・見えないの対とは別。", "足音": "名詞だが「可視」の対義語ではない。耳で聞くもので、見える・見えないの対にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37496, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "目に見えること。", "primary_collocate": null, "pronunciation": "かし", "ipa": "kaɕi", "syllable_count": 2, "sentences": [{"text": "太陽の光には、可視の部分と不可視の部分がある。", "target_word": "可視", "complexity_tier": "T4", "furigana": "太陽[たいよう]の光[ひかり]には、可視[かし]の部分[ぶぶん]と不可視[ふかし]の部分[ぶぶん]がある。", "sentence_source": "generated"}, {"text": "可視の距離が短い霧の日は、運転に注意が必要だ。", "target_word": "可視", "complexity_tier": "T4", "furigana": "可視[かし]の距離[きょり]が短[みじか]い霧[きり]の日[ひ]は、運転[うんてん]に注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "星が可視かどうかは、空の明るさに左右される。", "target_word": "可視", "complexity_tier": "T4", "furigana": "星[ほし]が可視[かし]かどうかは、空[そら]の明[あか]るさに左右[さゆう]される。", "sentence_source": "generated"}, {"text": "紫外線は波長が短く、人間の目には可視ではない。", "target_word": "可視", "complexity_tier": "T3", "furigana": "紫外線[しがいせん]は波長[はちょう]が短[みじか]く、人間[にんげん]の目[め]には可視[かし]ではない。", "sentence_source": "generated"}, {"text": "実験で使う粒が小さすぎて、肉眼では可視ではなかった。", "target_word": "可視", "complexity_tier": "T4", "furigana": "実験[じっけん]で使[つか]う粒[つぶ]が小[ちい]さすぎて、肉眼[にくがん]では可視[かし]ではなかった。", "sentence_source": "generated"}, {"text": "地図の上で、可視の範囲を青い線で示した。", "target_word": "可視", "complexity_tier": "T4", "furigana": "地図[ちず]の上[うえ]で、可視[かし]の範囲[はんい]を青[あお]い線[せん]で示[しめ]した。", "sentence_source": "generated"}, {"text": "窓から可視の範囲にある建物は、すべて百年以上前に建てられた。", "target_word": "可視", "complexity_tier": "T4", "furigana": "窓[まど]から可視[かし]の範囲[はんい]にある建物[たてもの]は、すべて百年[ひゃくねん]以上前[いじょうまえ]に建[た]てられた。", "sentence_source": "generated"}, {"text": "霧で視界が悪く、可視の距離は十メートルほどしかなかった。", "target_word": "可視", "complexity_tier": "T3", "furigana": "霧[きり]で視界[しかい]が悪[わる]く、可視[かし]の距離[きょり]は十[じゅう]メートルほどしかなかった。", "sentence_source": "generated"}, {"text": "暗い部屋でも、スイッチの光だけは可視だった。", "target_word": "可視", "complexity_tier": "T4", "furigana": "暗[くら]い部屋[へや]でも、スイッチの光[ひかり]だけは可視[かし]だった。", "sentence_source": "generated"}, {"text": "夜明け前の空はまだ暗く、東の山の稜線だけがかろうじて可視だった。", "target_word": "可視", "complexity_tier": "T3", "furigana": "夜明[よあ]け前[まえ]の空[そら]はまだ暗[くら]く、東[ひがし]の山[やま]の稜線[りょうせん]だけがかろうじて可視[かし]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "可視", "label": "基本形"}, {"form": "可視の", "label": "連体形"}], "register": "formal", "sense_fingerprint": "肉眼で見えるという性質（不可視の対義。可視の範囲・可視ではない）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdaeb0f0-0ec9-497f-897c-c8ed7f9c59cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37496, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可視", "is_correct": true, "explanation": "ここは〈目に見える〉の意味。光の見える部分と見えない部分（不可視）を対比している。"}, {"text": "音", "is_correct": false, "explanation": "「音の部分と不可視の部分」は意味が合わない。光は目で見えるかどうかで分けられる。"}, {"text": "味", "is_correct": false, "explanation": "「味の部分」は太陽の光の説明として成り立たない。味覚の話になってしまう。"}, {"text": "重さ", "is_correct": false, "explanation": "「重さの部分」は太陽の光の説明として成り立たない。見えるかどうかの対比にならない。"}], "explanations": {"可視": "ここは〈目に見える〉の意味。光の見える部分と見えない部分（不可視）を対比している。", "音": "「音の部分と不可視の部分」は意味が合わない。光は目で見えるかどうかで分けられる。", "味": "「味の部分」は太陽の光の説明として成り立たない。味覚の話になってしまう。", "重さ": "「重さの部分」は太陽の光の説明として成り立たない。見えるかどうかの対比にならない。"}, "sentence_index": 0, "correct_answer": "可視"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "遠くの鳥の声は、人間の耳には可視ではない。", "explanation": "ここは〈可聴〉（聞き取れる）の意味。鳥の声は耳で聞くもので、目に見えるかどうかとは関係ないので可視は合わない。"}, {"text": "この川は雨が降ると、渡ることが可視ではない。", "explanation": "ここは〈可能〉（できる）の意味。可視は見えることなので、行動ができるかどうかには使わない。"}, {"text": "けがの痛みが可視だ。", "explanation": "ここは〈ひどい〉（程度が強い）の意味。痛みは目に見えないので、可視とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37496, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可視", "is_correct": true, "explanation": "ここは〈目で見える〉の意味。窓から見える範囲を表すので「可視の範囲」に入る。"}, {"text": "香り", "is_correct": false, "explanation": "「香りの範囲にある建物」は意味が通らない。建物の位置は見える範囲で示す。"}, {"text": "時間", "is_correct": false, "explanation": "「時間の範囲にある建物」とは言わない。場所の範囲を表す語ではない。"}, {"text": "面積", "is_correct": false, "explanation": "「面積の範囲にある建物」は不自然。窓から見える建物の範囲を表す語ではない。"}], "explanations": {"可視": "ここは〈目で見える〉の意味。窓から見える範囲を表すので「可視の範囲」に入る。", "香り": "「香りの範囲にある建物」は意味が通らない。建物の位置は見える範囲で示す。", "時間": "「時間の範囲にある建物」とは言わない。場所の範囲を表す語ではない。", "面積": "「面積の範囲にある建物」は不自然。窓から見える建物の範囲を表す語ではない。"}, "sentence_index": 6, "correct_answer": "可視"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その犯人が彼だったことは、可視だ。", "explanation": "ここは〈明らか〉（はっきりしている）の意味。推理の結果は目に見えるものではないので、可視は合わない。"}, {"text": "その判断は、状況を考えれば可視だ。", "explanation": "ここは〈妥当〉（適切だ）の意味。判断は目で見えないので、可視とは言えない。"}, {"text": "夜の寒さが可視になって、体が震えた。", "explanation": "ここは〈感じられる〉の意味。寒さは肌で感じるもので、目に見えるものではないので可視は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37496, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "霧の夜は、道路の白線が可視で範囲から外れやすい。", "corrected_sentence": "霧の夜は、道路の白線が可視の範囲から外れやすい。", "error_description": "「可視の範囲」の「の」が正しい。「で」は手段や場所を表すので、名詞を修飾できず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37496, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "煙の多い日は、遠くの山がほとんど可視がならない。", "corrected_sentence": "煙の多い日は、遠くの山がほとんど可視にならない。", "error_description": "「なる」は「に」を取る。「可視が」は誤りで、正しくは「可視に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f85c42-a8ad-4a51-880f-093957973213') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
