INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37498, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「必ず」は、かならずという意味で、絶対にそうなると言うときに使う言葉です。", "primary_collocate": null, "pronunciation": "かならず", "ipa": "kanaɾazɯ", "syllable_count": 4, "sentences": [{"text": "約束した時間には必ず行く。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "約束[やくそく]した時間[じかん]には必[かなら]ず行[い]く。", "sentence_source": "generated"}, {"text": "宿題は毎日、必ず出さなければならない。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]は毎日[まいにち]、必[かなら]ず出[だ]さなければならない。", "sentence_source": "generated"}, {"text": "薬は食後に必ず飲むように言われた。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "薬[くすり]は食後[しょくご]に必[かなら]ず飲[の]むように言[い]われた。", "sentence_source": "generated"}, {"text": "練習を続ければ、必ず上手になる。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "練習[れんしゅう]を続[つづ]ければ、必[かなら]ず上手[じょうず]になる。", "sentence_source": "generated"}, {"text": "家を出る前に、必ず鍵をかける。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "家[いえ]を出[で]る前[まえ]に、必[かなら]ず鍵[かぎ]をかける。", "sentence_source": "generated"}, {"text": "彼は一度言ったことは必ず守る人だ。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "彼[かれ]は一度[いちど]言[い]ったことは必[かなら]ず守[まも]る人[ひと]だ。", "sentence_source": "generated"}, {"text": "この道を行けば、必ず駅に着く。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "この道[みち]を行[い]けば、必[かなら]ず駅[えき]に着[つ]く。", "sentence_source": "generated"}, {"text": "日本に来たときは、必ず私に連絡すること。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "日本[にほん]に来[き]たときは、必[かなら]ず私[わたし]に連絡[れんらく]すること。", "sentence_source": "generated"}, {"text": "夜が終われば、必ず朝が来る。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "夜[よる]が終[お]われば、必[かなら]ず朝[あさ]が来[く]る。", "sentence_source": "generated"}, {"text": "試合に勝ったら、必ずお礼を言いに行く。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "試合[しあい]に勝[か]ったら、必[かなら]ずお礼[れい]を言[い]いに行[い]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "必ず", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "例外なくそうなる・必ずそうするという確かさを表す副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b56525-d686-4f42-9de7-3cd4f31105fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37498, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必ず", "is_correct": true, "explanation": "「絶対にそうなる」の意味で、「約束の時間には行く」と確実に言うのに合う。"}, {"text": "決して", "is_correct": false, "explanation": "「決して」は打ち消しと呼応するので、「決して行く」とは言えない。"}, {"text": "全然", "is_correct": false, "explanation": "「全然」は打ち消しと呼応するので、肯定の文には入らない。"}, {"text": "少しも", "is_correct": false, "explanation": "「少しも」は打ち消しと呼応するので、「少しも行く」は成り立たない。"}], "explanations": {"必ず": "「絶対にそうなる」の意味で、「約束の時間には行く」と確実に言うのに合う。", "決して": "「決して」は打ち消しと呼応するので、「決して行く」とは言えない。", "全然": "「全然」は打ち消しと呼応するので、肯定の文には入らない。", "少しも": "「少しも」は打ち消しと呼応するので、「少しも行く」は成り立たない。"}, "sentence_index": 0, "correct_answer": "必ず"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "必ず、明日は雨が降るかもしれない。", "explanation": "ここは〈確実に〉の意味。「かもしれない」（不確か）と矛盾するので、もしかしたらの代わりには使えない。"}, {"text": "偶然、必ず駅で昔の友達に会った。", "explanation": "ここは〈確実に〉の意味。「偶然」は予想外の出来事を表すので、必ずとは逆の意味になり合わない。"}, {"text": "彼は、必ず一度だけ来た。", "explanation": "「一度だけ」は回数が限られることを表し、例外なく確実に起こる「必ず」とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37498, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必ず", "is_correct": true, "explanation": "「この道を行けば、確実に駅に着く」の意味で、条件から確実な結果を表すのに合う。"}, {"text": "一度も", "is_correct": false, "explanation": "「一度も」は打ち消しと呼応するので、「一度も着く」は成り立たない。"}, {"text": "二度と", "is_correct": false, "explanation": "「二度と」は打ち消しと呼応するので、肯定の文には入らない。"}, {"text": "ちっとも", "is_correct": false, "explanation": "「ちっとも」は打ち消しと呼応するので、「ちっとも着く」は不自然。"}], "explanations": {"必ず": "「この道を行けば、確実に駅に着く」の意味で、条件から確実な結果を表すのに合う。", "一度も": "「一度も」は打ち消しと呼応するので、「一度も着く」は成り立たない。", "二度と": "「二度と」は打ち消しと呼応するので、肯定の文には入らない。", "ちっとも": "「ちっとも」は打ち消しと呼応するので、「ちっとも着く」は不自然。"}, "sentence_index": 6, "correct_answer": "必ず"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は、たまに必ず電話をくれる。", "explanation": "ここは〈時々〉の意味。必ずは例外なく確実にそうなることを表すので、たまにとは矛盾する。"}, {"text": "彼は、適当に必ず宿題を出す。", "explanation": "ここは〈いい加減に〉の意味。必ずは確実を表すので、いい加減さとは矛盾する。"}, {"text": "ふと必ずお礼を言いに行った。", "explanation": "ここは〈不意に〉の意味。必ずは確実に決まっていることを表すので、思いつきのようなふとと矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37498, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この電車は必ずしも時間どおりに来る。", "corrected_sentence": "この電車は必ず時間どおりに来る。", "error_description": "「必ずしも」は否定と呼応するので、肯定の文では「必ず」にする必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37498, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は、どんな時も必ずを家族に連絡する。", "corrected_sentence": "彼女は、どんな時も必ず家族に連絡する。", "error_description": "「必ず」は副詞なので、格助詞「を」は付かない。「必ずを」は誤りで、「必ず」だけで正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
