INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37499, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「必ず」は、確実にそれをする、またはそうなるということを表す副詞です。どんな状況でも例外なく実現することを強調します。", "primary_collocate": null, "pronunciation": "かならず", "ipa": "kanaɾazɯ", "syllable_count": 4, "sentences": [{"text": "規則なので、入る前に必ず名前を書く。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "規則[きそく]なので、入[はい]る前[まえ]に必[かなら]ず名前[なまえ]を書[か]く。", "sentence_source": "generated"}, {"text": "毎朝、彼は必ず同じ時間に起きる。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、彼[かれ]は必[かなら]ず同[おな]じ時間[じかん]に起[お]きる。", "sentence_source": "generated"}, {"text": "注文のあとには必ず確認のメールが届く。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "注文[ちゅうもん]のあとには必[かなら]ず確認[かくにん]のメールが届[とど]く。", "sentence_source": "generated"}, {"text": "私は寝る前に必ず日記をつける。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "私[わたし]は寝[ね]る前[まえ]に必[かなら]ず日記[にっき]をつける。", "sentence_source": "generated"}, {"text": "毎年、夏休みには必ず祖父の家へ行く。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "毎年[まいとし]、夏休[なつやす]みには必[かなら]ず祖父[そふ]の家[いえ]へ行[い]く。", "sentence_source": "generated"}, {"text": "火を使ったあとは、必ず元栓を閉める。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "火[ひ]を使[つか]ったあとは、必[かなら]ず元栓[もとせん]を閉[し]める。", "sentence_source": "generated"}, {"text": "道路を渡るときは、必ず左右を見る。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "道路[どうろ]を渡[わた]るときは、必[かなら]ず左右[さゆう]を見[み]る。", "sentence_source": "generated"}, {"text": "彼は忙しくても、必ず返事をくれる。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "彼[かれ]は忙[いそが]しくても、必[かなら]ず返事[へんじ]をくれる。", "sentence_source": "generated"}, {"text": "借りた本は必ず期限までに返す。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "借[か]りた本[ほん]は必[かなら]ず期限[きげん]までに返[かえ]す。", "sentence_source": "generated"}, {"text": "この店は、行けば必ず誰かが歌っている。", "target_word": "必ず", "complexity_tier": "T3", "furigana": "この店[みせ]は、行[い]けば必[かなら]ず誰[だれ]かが歌[うた]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "必ず", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "どんな場合も例外なく行う・起こる習慣や決まりを強調する副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 元栓 (Zipf 2.2)']::text[], '69b56525-d686-4f42-9de7-3cd4f31105fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37499, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必ず", "is_correct": true, "explanation": "例外なく毎回行う決まりを表し、「入る前に名前を書く」という規則に合う。"}, {"text": "決して", "is_correct": false, "explanation": "「決して」は打ち消しと呼応するので、「決して名前を書く」とは言えない。"}, {"text": "全然", "is_correct": false, "explanation": "「全然」は打ち消しと呼応するので、肯定の決まりには入らない。"}, {"text": "少しも", "is_correct": false, "explanation": "「少しも」は打ち消しと呼応するので、「少しも書く」は成り立たない。"}], "explanations": {"必ず": "例外なく毎回行う決まりを表し、「入る前に名前を書く」という規則に合う。", "決して": "「決して」は打ち消しと呼応するので、「決して名前を書く」とは言えない。", "全然": "「全然」は打ち消しと呼応するので、肯定の決まりには入らない。", "少しも": "「少しも」は打ち消しと呼応するので、「少しも書く」は成り立たない。"}, "sentence_index": 0, "correct_answer": "必ず"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、気まぐれに必ず同じ電車に乗る。", "explanation": "ここは〈気まぐれに〉の意味。必ずは例外なく続く習慣を表すので、気まぐれとは矛盾する。"}, {"text": "偶然、毎朝必ず同じ電車に乗る。", "explanation": "「偶然」は予想外の出来事を表し、毎朝の習慣を例外なく続ける必ずとは逆の意味になる。"}, {"text": "その店には、必ず誰もいないことがある。", "explanation": "「〜ことがある」は時々を表すので、例外なく続ける必ずとは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37499, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必ず", "is_correct": true, "explanation": "道路を渡るたびに例外なく行う決まりを表し、「左右を見る」という習慣に合う。"}, {"text": "一度も", "is_correct": false, "explanation": "「一度も」は打ち消しと呼応するので、「一度も見る」は成り立たない。"}, {"text": "二度と", "is_correct": false, "explanation": "「二度と」は打ち消しと呼応するので、肯定の習慣には入らない。"}, {"text": "ちっとも", "is_correct": false, "explanation": "「ちっとも」は打ち消しと呼応するので、「ちっとも見る」は不自然。"}], "explanations": {"必ず": "道路を渡るたびに例外なく行う決まりを表し、「左右を見る」という習慣に合う。", "一度も": "「一度も」は打ち消しと呼応するので、「一度も見る」は成り立たない。", "二度と": "「二度と」は打ち消しと呼応するので、肯定の習慣には入らない。", "ちっとも": "「ちっとも」は打ち消しと呼応するので、「ちっとも見る」は不自然。"}, "sentence_index": 6, "correct_answer": "必ず"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店では、ついうっかり必ず誰かが歌っている。", "explanation": "ここは〈うっかり〉の意味。必ずは例外なく続くことを表すので、うっかりとは矛盾する。"}, {"text": "この店では、ほどほどに必ず誰かが歌っている。", "explanation": "ここは〈ほどほど〉の意味。必ずは例外なく続くことを表すので、ほどほどに抑えるという意味とは矛盾する。"}, {"text": "この店では、一度だけ必ず誰かが歌った。", "explanation": "「一度だけ」は限られた回数を表し、例外なく続く必ずとは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37499, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は毎日、必ずしも掃除をしてから開く。", "corrected_sentence": "この店は毎日、必ず掃除をしてから開く。", "error_description": "「必ずしも」は否定と呼応するので、例外なく続ける習慣を表す肯定の文では「必ず」にする必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37499, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は、毎朝必ずで窓を開ける。", "corrected_sentence": "私は、毎朝必ず窓を開ける。", "error_description": "「必ず」は副詞なので、格助詞「で」は付かない。「必ずで」は誤りで、「必ず」だけで正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37500, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「国境の問題で対立した」の「で」は、対立が起きた場面・原因を示し、文が自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「対立」は目的語を取らず、問題の所在を示す「で」が必要。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示すが、「問題」が動詞を修飾する形にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、原因や場面を表す文脈には合わない。"}], "correct_answer": "で", "explanations": {"で": "「国境の問題で対立した」の「で」は、対立が起きた場面・原因を示し、文が自然に成り立つ。", "を": "目的語を示すが、「対立」は目的語を取らず、問題の所在を示す「で」が必要。", "の": "連体修飾を示すが、「問題」が動詞を修飾する形にならない。", "へ": "方向を示す助詞で、原因や場面を表す文脈には合わない。"}, "error_tags": {"を": "目的語を示すが、「対立」は目的語を取らず、問題の所在を示す「で」が必要", "の": "連体修飾を示すが、「問題」が動詞を修飾する形にならない", "へ": "方向を示す助詞で、原因や場面を表す文脈には合わない"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "協調", "is_correct": true, "explanation": "「対立」の対義語で、互いに力を合わせて同じ方向に進むこと。"}, {"text": "出発", "is_correct": false, "explanation": "旅立つ意味で、「対立」の対義語ではない。"}, {"text": "計画", "is_correct": false, "explanation": "前もって決めておく意味で、「対立」の対義語ではない。"}, {"text": "保存", "is_correct": false, "explanation": "そのまま残しておく意味で、「対立」の対義語ではない。"}], "correct_answer": "協調", "explanations": {"協調": "「対立」の対義語で、互いに力を合わせて同じ方向に進むこと。", "出発": "旅立つ意味で、「対立」の対義語ではない。", "計画": "前もって決めておく意味で、「対立」の対義語ではない。", "保存": "そのまま残しておく意味で、「対立」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37500, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "協調", "is_correct": true, "explanation": "「対立」の対義語で、互いに力を合わせて同じ方向に進むこと。"}, {"text": "観察", "is_correct": false, "explanation": "よく見て調べる意味で、「対立」の対義語ではない。"}, {"text": "運搬", "is_correct": false, "explanation": "物を別の場所へ運ぶ意味で、「対立」の対義語ではない。"}, {"text": "解説", "is_correct": false, "explanation": "わかりやすく説明する意味で、「対立」の対義語ではない。"}], "correct_answer": "協調", "explanations": {"協調": "「対立」の対義語で、互いに力を合わせて同じ方向に進むこと。", "観察": "よく見て調べる意味で、「対立」の対義語ではない。", "運搬": "物を別の場所へ運ぶ意味で、「対立」の対義語ではない。", "解説": "わかりやすく説明する意味で、「対立」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37500, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人やものが、反対の立場になること。", "primary_collocate": null, "pronunciation": "たいりつ", "ipa": "taiɾitsɯ", "syllable_count": 4, "sentences": [{"text": "兄と弟は進路のことで対立している。", "target_word": "対立", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]は進路[しんろ]のことで対立[たいりつ]している。", "sentence_source": "generated"}, {"text": "二つの国は国境の問題で対立した。", "target_word": "対立", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]は国境[こっきょう]の問題[もんだい]で対立[たいりつ]した。", "sentence_source": "generated"}, {"text": "社長と社員が給料をめぐって対立している。", "target_word": "対立", "complexity_tier": "T3", "furigana": "社長[しゃちょう]と社員[しゃいん]が給料[きゅうりょう]をめぐって対立[たいりつ]している。", "sentence_source": "generated"}, {"text": "会議では、賛成の人と反対の人が真っ向から対立した。", "target_word": "対立", "complexity_tier": "T4", "furigana": "会議[かいぎ]では、賛成[さんせい]の人[ひと]と反対[はんたい]の人[ひと]が真[ま]っ向[こう]から対立[たいりつ]した。", "sentence_source": "generated"}, {"text": "二つのチームは長い間、対立してきた。", "target_word": "対立", "complexity_tier": "T3", "furigana": "二[ふた]つのチームは長[なが]い間[あいだ]、対立[たいりつ]してきた。", "sentence_source": "generated"}, {"text": "父と母の意見が対立して、家の中が静かになった。", "target_word": "対立", "complexity_tier": "T3", "furigana": "父[ちち]と母[はは]の意見[いけん]が対立[たいりつ]して、家[いえ]の中[なか]が静[しず]かになった。", "sentence_source": "generated"}, {"text": "先生と生徒が対立しないように、まず話し合った。", "target_word": "対立", "complexity_tier": "T3", "furigana": "先生[せんせい]と生徒[せいと]が対立[たいりつ]しないように、まず話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "村の人たちは二つのグループに分かれて対立した。", "target_word": "対立", "complexity_tier": "T3", "furigana": "村[むら]の人[ひと]たちは二[ふた]つのグループに分[わ]かれて対立[たいりつ]した。", "sentence_source": "generated"}, {"text": "友だちと対立したくないので、私は黙っていた。", "target_word": "対立", "complexity_tier": "T3", "furigana": "友[とも]だちと対立[たいりつ]したくないので、私[わたし]は黙[だま]っていた。", "sentence_source": "generated"}, {"text": "両党は新しい法律をめぐって激しく対立している。", "target_word": "対立", "complexity_tier": "T4", "furigana": "両党[りょうとう]は新[あたら]しい法律[ほうりつ]をめぐって激[はげ]しく対立[たいりつ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "対立", "label": "基本形"}, {"form": "対立する", "label": "サ変動詞・終止形"}, {"form": "対立した", "label": "過去形"}, {"form": "対立している", "label": "継続形"}], "register": "formal", "sense_fingerprint": "人や集団が互いに反対の立場に立つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6ee224-92d2-4127-abed-56d8891d40e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37500, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "対立", "is_correct": true, "explanation": "「対立」は人が反対の立場に立つことで、進路をめぐる兄弟の食い違いに合う。"}, {"text": "点火", "is_correct": false, "explanation": "「点火」は火をつけることで、進路をめぐる食い違いには使えない。"}, {"text": "収穫", "is_correct": false, "explanation": "「収穫」は作物を取り入れることで、立場の食い違いには合わない。"}, {"text": "膨張", "is_correct": false, "explanation": "「膨張」は体積や規模が広がることで、進路の話では意味が通らない。"}], "explanations": {"対立": "「対立」は人が反対の立場に立つことで、進路をめぐる兄弟の食い違いに合う。", "点火": "「点火」は火をつけることで、進路をめぐる食い違いには使えない。", "収穫": "「収穫」は作物を取り入れることで、立場の食い違いには合わない。", "膨張": "「膨張」は体積や規模が広がることで、進路の話では意味が通らない。"}, "sentence_index": 0, "correct_answer": "対立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先月の大会で強豪校と対立して、三位になった。", "explanation": "ここは〈対戦〉の意味。対立は立場の食い違いを指し、試合で戦う場合には使わない。"}, {"text": "交差点で、トラックと乗用車が対立して、大きな音を立てた。", "explanation": "ここは〈衝突〉の意味。対立は立場や意見の食い違いで、物がぶつかる場合には使わない。"}, {"text": "赤と青の絵の具が対立して、紫色になった。", "explanation": "ここは〈混合〉の意味。対立は反対の立場になることで、色が混ざり合う場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37500, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "対立", "is_correct": true, "explanation": "「対立」は反対の立場に立つ意味で、先生と生徒が避けたい状態に合う。"}, {"text": "採掘", "is_correct": false, "explanation": "「採掘」は地下から資源を掘り出すことで、人間関係の話には合わない。"}, {"text": "焙煎", "is_correct": false, "explanation": "「焙煎」は豆などを炒ることで、先生と生徒には使えない。"}, {"text": "浸水", "is_correct": false, "explanation": "「浸水」は水が入り込むことで、先生と生徒の文には意味が通らない。"}], "explanations": {"対立": "「対立」は反対の立場に立つ意味で、先生と生徒が避けたい状態に合う。", "採掘": "「採掘」は地下から資源を掘り出すことで、人間関係の話には合わない。", "焙煎": "「焙煎」は豆などを炒ることで、先生と生徒には使えない。", "浸水": "「浸水」は水が入り込むことで、先生と生徒の文には意味が通らない。"}, "sentence_index": 6, "correct_answer": "対立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "強い磁石同士が対立して、なかなか近づけなかった。", "explanation": "ここは〈反発〉の意味。対立は立場の食い違いを指し、磁石がはね返し合う場合には使わない。"}, {"text": "この森では、動物と植物が平和に対立している。", "explanation": "ここは〈共存〉の意味。対立は反対の立場に立つことで、平和に並んで暮らす場合には使わない。"}, {"text": "二つの橋は並んで対立している。", "explanation": "ここは〈並ぶ〉の意味。対立は立場の食い違いを指し、物が並んでいる場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37500, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は妹を服の好みをめぐって対立している。", "corrected_sentence": "姉は妹と服の好みをめぐって対立している。", "error_description": "「対立」は「〜と対立する」の形で使うので、助詞は「と」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37500, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父と母は家計の使い方をめぐって対立していだ。", "corrected_sentence": "父と母は家計の使い方をめぐって対立していた。", "error_description": "過去の語尾は「た」が正しい。「だ」は濁音になった誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37501, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「両者の対立が少しずつ解けた」の「が」は、解けた対立を主語として示し、文の主語を表す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「解けた」の主語の位置には入らない。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示すが、「対立」が解けるという主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、ここでは文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「両者の対立が少しずつ解けた」の「が」は、解けた対立を主語として示し、文の主語を表す。", "の": "連体修飾の助詞で、「解けた」の主語の位置には入らない。", "に": "位置や相手を示すが、「対立」が解けるという主語にはならない。", "へ": "方向を示す助詞で、ここでは文が成り立たない。"}, "error_tags": {"の": "連体修飾の助詞で、「解けた」の主語の位置には入らない", "に": "位置や相手を示すが、「対立」が解けるという主語にはならない", "へ": "方向を示す助詞で、ここでは文が成り立たない"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致", "is_correct": true, "explanation": "「意見の対立」の対義語で、意見が同じになること。"}, {"text": "出発", "is_correct": false, "explanation": "旅立つ意味で、意見の食い違いの対義語ではない。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像を撮る意味で、意見の対立とは関係がない。"}, {"text": "計量", "is_correct": false, "explanation": "分量をはかる意味で、意見の対立の対義語ではない。"}], "correct_answer": "一致", "explanations": {"一致": "「意見の対立」の対義語で、意見が同じになること。", "出発": "旅立つ意味で、意見の食い違いの対義語ではない。", "撮影": "写真や映像を撮る意味で、意見の対立とは関係がない。", "計量": "分量をはかる意味で、意見の対立の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
