INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37501, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "意見や立場が互いに反対であること。また、そのような関係。", "primary_collocate": null, "pronunciation": "たいりつ", "ipa": "taiɾitsɯ", "syllable_count": 4, "sentences": [{"text": "二人の間には意見の対立がある。", "target_word": "対立", "complexity_tier": "T3", "furigana": "二人[ふたり]の間[あいだ]には意見[いけん]の対立[たいりつ]がある。", "sentence_source": "generated"}, {"text": "話し合いで、両者の対立が少しずつ解けた。", "target_word": "対立", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いで、両者[りょうしゃ]の対立[たいりつ]が少[すこ]しずつ解[と]けた。", "sentence_source": "generated"}, {"text": "環境を守るか、工場を作るかという対立が続いている。", "target_word": "対立", "complexity_tier": "T4", "furigana": "環境[かんきょう]を守[まも]るか、工場[こうじょう]を作[つく]るかという対立[たいりつ]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "対立を避けるために、彼は何も言わなかった。", "target_word": "対立", "complexity_tier": "T3", "furigana": "対立[たいりつ]を避[さ]けるために、彼[かれ]は何[なに]も言[い]わなかった。", "sentence_source": "generated"}, {"text": "親子の対立が深まり、ほとんど話さなくなった。", "target_word": "対立", "complexity_tier": "T3", "furigana": "親子[おやこ]の対立[たいりつ]が深[ふか]まり、ほとんど話[はな]さなくなった。", "sentence_source": "generated"}, {"text": "労働者と会社の対立は、まだ解決していない。", "target_word": "対立", "complexity_tier": "T4", "furigana": "労働者[ろうどうしゃ]と会社[かいしゃ]の対立[たいりつ]は、まだ解決[かいけつ]していない。", "sentence_source": "generated"}, {"text": "この問題では、与党と野党の対立が目立つ。", "target_word": "対立", "complexity_tier": "T4", "furigana": "この問題[もんだい]では、与党[よとう]と野党[やとう]の対立[たいりつ]が目立[めだ]つ。", "sentence_source": "generated"}, {"text": "対立する意見を聞いてから、私は決めたい。", "target_word": "対立", "complexity_tier": "T3", "furigana": "対立[たいりつ]する意見[いけん]を聞[き]いてから、私[わたし]は決[き]めたい。", "sentence_source": "generated"}, {"text": "二つの案は考え方が対立していて、まとまらない。", "target_word": "対立", "complexity_tier": "T3", "furigana": "二[ふた]つの案[あん]は考[かんが]え方[かた]が対立[たいりつ]していて、まとまらない。", "sentence_source": "generated"}, {"text": "兄弟の対立は、母の一言でおさまった。", "target_word": "対立", "complexity_tier": "T3", "furigana": "兄弟[きょうだい]の対立[たいりつ]は、母[はは]の一言[ひとこと]でおさまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "対立", "label": "基本形"}, {"form": "対立する", "label": "サ変動詞・終止形"}, {"form": "対立している", "label": "継続形"}, {"form": "対立した", "label": "過去形"}], "register": "formal", "sense_fingerprint": "意見や立場が食い違っている状態・関係", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6ee224-92d2-4127-abed-56d8891d40e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37501, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "対立", "is_correct": true, "explanation": "意見の食い違いを指すので、「意見の対立がある」は自然な表現。"}, {"text": "乾燥", "is_correct": false, "explanation": "「乾燥」は水分がなくなることで、意見には使わない。"}, {"text": "落雷", "is_correct": false, "explanation": "「落雷」は雷が落ちることで、意見の話では意味が通らない。"}, {"text": "配送", "is_correct": false, "explanation": "「配送」は荷物を届けることで、意見には合わない。"}], "explanations": {"対立": "意見の食い違いを指すので、「意見の対立がある」は自然な表現。", "乾燥": "「乾燥」は水分がなくなることで、意見には使わない。", "落雷": "「落雷」は雷が落ちることで、意見の話では意味が通らない。", "配送": "「配送」は荷物を届けることで、意見には合わない。"}, "sentence_index": 0, "correct_answer": "対立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "交差点で二台の車が対立して、ぶつかりそうになった。", "explanation": "ここは〈衝突〉の意味。対立は意見や立場の食い違いで、車がぶつかる場合には使わない。"}, {"text": "強い磁石の同じ極どうしが対立して、離れた。", "explanation": "ここは〈反発〉の意味。対立は立場の食い違いで、磁石がはね返し合う場合には使わない。"}, {"text": "二人の声が対立して、歌がきれいに響いた。", "explanation": "ここは〈調和〉の意味。対立は意見や立場の食い違いで、声が溶け合う場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37501, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "対立", "is_correct": true, "explanation": "与党と野党の食い違いを指すので、文の意味に合う。"}, {"text": "点検", "is_correct": false, "explanation": "「点検」は機械や設備を調べることで、政党の関係には合わない。"}, {"text": "漂白", "is_correct": false, "explanation": "「漂白」は色を抜くことで、政党の関係には使えない。"}, {"text": "寒冷", "is_correct": false, "explanation": "「寒冷」は気候が冷たいことで、政党の話には意味が通らない。"}], "explanations": {"対立": "与党と野党の食い違いを指すので、文の意味に合う。", "点検": "「点検」は機械や設備を調べることで、政党の関係には合わない。", "漂白": "「漂白」は色を抜くことで、政党の関係には使えない。", "寒冷": "「寒冷」は気候が冷たいことで、政党の話には意味が通らない。"}, "sentence_index": 6, "correct_answer": "対立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この絵では、二つの色が対立して、一つの明るい色になっている。", "explanation": "ここは〈融合〉の意味。対立は反対の立場になることで、色が混ざり合う場合には使わない。"}, {"text": "二つの図形は辺が重なり合って、きれいな四角形になった。", "explanation": "ここは〈重なり〉の意味。対立は立場や意見の食い違いを指し、辺が重なる場合には使わない。"}, {"text": "チームは対立して、髪の色を揃えた。", "explanation": "ここは〈統一〉の意味。対立は反対の立場になることで、足並みを揃える場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
