INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37502, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "りゆうの こと。", "primary_collocate": null, "pronunciation": "わけ", "ipa": "wake", "syllable_count": 2, "sentences": [{"text": "遅れた訳を、先生にきちんと説明した。", "target_word": "訳", "complexity_tier": "T3", "furigana": "遅[おく]れた訳[わけ]を、先生[せんせい]にきちんと説明[せつめい]した。", "sentence_source": "generated"}, {"text": "彼が怒っている訳が、私にはわからない。", "target_word": "訳", "complexity_tier": "T3", "furigana": "彼[かれ]が怒[おこ]っている訳[わけ]が、私[わたし]にはわからない。", "sentence_source": "generated"}, {"text": "何も言わずに帰った訳を、あとで友達に聞いた。", "target_word": "訳", "complexity_tier": "T3", "furigana": "何[なに]も言[い]わずに帰[かえ]った訳[わけ]を、あとで友達[ともだち]に聞[き]いた。", "sentence_source": "generated"}, {"text": "彼女が泣いていた訳は、手紙を読んで初めてわかった。", "target_word": "訳", "complexity_tier": "T3", "furigana": "彼女[かのじょ]が泣[な]いていた訳[わけ]は、手紙[てがみ]を読[よ]んで初[はじ]めてわかった。", "sentence_source": "generated"}, {"text": "仕事をやめた訳を、父に話した。", "target_word": "訳", "complexity_tier": "T3", "furigana": "仕事[しごと]をやめた訳[わけ]を、父[ちち]に話[はな]した。", "sentence_source": "generated"}, {"text": "母は、私が引っ越す訳を知りたがった。", "target_word": "訳", "complexity_tier": "T3", "furigana": "母[はは]は、私[わたし]が引[ひ]っ越[こ]す訳[わけ]を知[し]りたがった。", "sentence_source": "generated"}, {"text": "試合に負けた訳を、みんなで考えた。", "target_word": "訳", "complexity_tier": "T3", "furigana": "試合[しあい]に負[ま]けた訳[わけ]を、みんなで考[かんが]えた。", "sentence_source": "generated"}, {"text": "彼が来なかった訳は、病気だったからだ。", "target_word": "訳", "complexity_tier": "T3", "furigana": "彼[かれ]が来[こ]なかった訳[わけ]は、病気[びょうき]だったからだ。", "sentence_source": "generated"}, {"text": "二人が別れた訳は、誰も知らない。", "target_word": "訳", "complexity_tier": "T3", "furigana": "二人[ふたり]が別[わか]れた訳[わけ]は、誰[だれ]も知[し]らない。", "sentence_source": "generated"}, {"text": "彼が急に笑い出した訳が、誰にもわからなかった。", "target_word": "訳", "complexity_tier": "T3", "furigana": "彼[かれ]が急[きゅう]に笑[わら]い出[だ]した訳[わけ]が、誰[だれ]にもわからなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "訳", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ある出来事や行動の理由・わけ（訳を聞く・訳を話す）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b56525-d686-4f42-9de7-3cd4f31105fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37502, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "訳", "is_correct": true, "explanation": "「遅れた理由」の意味で、先生に説明する内容として文が成り立つ。"}, {"text": "季節", "is_correct": false, "explanation": "季節は説明の対象にならず、「遅れた季節を説明した」は意味が通らない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は説明する内容ではなく、「遅れた音量」は文脈に合わない。"}, {"text": "期待", "is_correct": false, "explanation": "期待は「遅れた」と結びつかず、「遅れた期待を説明した」は不自然。"}], "explanations": {"訳": "「遅れた理由」の意味で、先生に説明する内容として文が成り立つ。", "季節": "季節は説明の対象にならず、「遅れた季節を説明した」は意味が通らない。", "音量": "音量は説明する内容ではなく、「遅れた音量」は文脈に合わない。", "期待": "期待は「遅れた」と結びつかず、「遅れた期待を説明した」は不自然。"}, "sentence_index": 0, "correct_answer": "訳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は庭の訳をきれいに剪定した。", "explanation": "ここは〈理由〉ではなく、物の名として誤用している。庭木を剪定する文では『訳』は指せず、『枝』と言うべき。"}, {"text": "会計の訳を表にまとめた。", "explanation": "ここは〈内訳〉の意味。『訳』だけでは内訳（内容の割り振り）を表さず、『内訳』と言うべき。"}, {"text": "鍋の訳を、火にかけて温め直した。", "explanation": "ここは〈理由〉ではなく、物の名として誤用している。鍋を火にかける文脈では『訳』は指せず、『鍋』と言うべき。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37502, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "訳", "is_correct": true, "explanation": "「負けた理由」の意味で、考える対象として文が成り立つ。"}, {"text": "速度", "is_correct": false, "explanation": "速度は考察の対象として「負けた」と結びつかず、文脈に合わない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は「試合に負けた」の対象にならず、「色彩を考えた」は不自然。"}, {"text": "体温", "is_correct": false, "explanation": "体温は「試合に負けた」と結びつかず、考える内容として成り立たない。"}], "explanations": {"訳": "「負けた理由」の意味で、考える対象として文が成り立つ。", "速度": "速度は考察の対象として「負けた」と結びつかず、文脈に合わない。", "色彩": "色彩は「試合に負けた」の対象にならず、「色彩を考えた」は不自然。", "体温": "体温は「試合に負けた」と結びつかず、考える内容として成り立たない。"}, "sentence_index": 6, "correct_answer": "訳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店では、訳を一つずつ丁寧に磨いて売っている。", "explanation": "ここは〈理由〉ではなく、物の名として誤用している。理由や事情を磨いて売るとは言えず、商品を指すなら『品物』と言うべき。"}, {"text": "彼は窓ガラスの訳を一枚ずつ磨いた。", "explanation": "ここは〈理由〉ではなく、物の名として誤用している。窓ガラスを磨く文では『訳』は指せず、『窓』と言うべき。"}, {"text": "新しい訳ソフトを入れて、英文を調べた。", "explanation": "ここは〈翻訳〉の語。『訳ソフト』とは言わず、『翻訳ソフト』を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
