INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37503, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の理由や事情。また、言葉の意味。", "primary_collocate": null, "pronunciation": "わけ", "ipa": "wake", "syllable_count": 2, "sentences": [{"text": "彼には、学校を休まなければならない訳がある。", "target_word": "訳", "complexity_tier": "T3", "furigana": "彼[かれ]には、学校[がっこう]を休[やす]まなければならない訳[わけ]がある。", "sentence_source": "generated"}, {"text": "訳があって、今日は早く帰らせてもらう。", "target_word": "訳", "complexity_tier": "T3", "furigana": "訳[わけ]があって、今日[きょう]は早[はや]く帰[かえ]らせてもらう。", "sentence_source": "generated"}, {"text": "彼の話は難しくて、何を言っているのか訳がわからない。", "target_word": "訳", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は難[むずか]しくて、何[なに]を言[い]っているのか訳[わけ]がわからない。", "sentence_source": "generated"}, {"text": "事情を知らない人は、訳もわからず困ってしまう。", "target_word": "訳", "complexity_tier": "T3", "furigana": "事情[じじょう]を知[し]らない人[ひと]は、訳[わけ]もわからず困[こま]ってしまう。", "sentence_source": "generated"}, {"text": "子どもは訳のわからないことを言って泣いていた。", "target_word": "訳", "complexity_tier": "T3", "furigana": "子[こ]どもは訳[わけ]のわからないことを言[い]って泣[な]いていた。", "sentence_source": "generated"}, {"text": "彼が会社をやめた訳を、同僚から聞いた。", "target_word": "訳", "complexity_tier": "T3", "furigana": "彼[かれ]が会社[かいしゃ]をやめた訳[わけ]を、同僚[どうりょう]から聞[き]いた。", "sentence_source": "generated"}, {"text": "突然の知らせに、訳がわからなくなって立ち尽くした。", "target_word": "訳", "complexity_tier": "T3", "furigana": "突然[とつぜん]の知[し]らせに、訳[わけ]がわからなくなって立[た]ち尽[つ]くした。", "sentence_source": "generated"}, {"text": "大事な訳があるらしく、彼は何も言わずに席を立った。", "target_word": "訳", "complexity_tier": "T3", "furigana": "大事[だいじ]な訳[わけ]があるらしく、彼[かれ]は何[なに]も言[い]わずに席[せき]を立[た]った。", "sentence_source": "generated"}, {"text": "彼が黙っている訳を、私は何となく察している。", "target_word": "訳", "complexity_tier": "T3", "furigana": "彼[かれ]が黙[だま]っている訳[わけ]を、私[わたし]は何[なん]となく察[さっ]している。", "sentence_source": "generated"}, {"text": "訳を話せば長くなるので、今日はやめておく。", "target_word": "訳", "complexity_tier": "T3", "furigana": "訳[わけ]を話[はな]せば長[なが]くなるので、今日[きょう]はやめておく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "訳", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事の事情やいきさつ、また話の筋道・意味（訳がある・訳がわからない）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: contains vocabulary far above tier T1: 立ち尽くし (Zipf 2.34)']::text[], '69b56525-d686-4f42-9de7-3cd4f31105fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37503, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "訳", "is_correct": true, "explanation": "「休まなければならない理由」の意味で、文が成り立つ。"}, {"text": "天気", "is_correct": false, "explanation": "天気は「休まなければならない」の理由にならず、文が成り立たない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は説明や理由の対象にならず、「花瓶がある」は意味が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は学校を休む理由として成り立たず、「体重がある」は不自然。"}], "explanations": {"訳": "「休まなければならない理由」の意味で、文が成り立つ。", "天気": "天気は「休まなければならない」の理由にならず、文が成り立たない。", "花瓶": "花瓶は説明や理由の対象にならず、「花瓶がある」は意味が通らない。", "体重": "体重は学校を休む理由として成り立たず、「体重がある」は不自然。"}, "sentence_index": 0, "correct_answer": "訳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会計の訳を表にまとめた。", "explanation": "ここは〈内訳〉の意味。『訳』単独では内訳（内容の割り振り）を表さず、『内訳』と言うべき。"}, {"text": "彼は机の訳を、雑巾でふいてから座った。", "explanation": "ここは〈理由〉ではなく、物の名として誤用している。机をふく文脈では『訳』は指せず、『机』と言うべき。"}, {"text": "玄関の訳を、毎朝きれいにはいた。", "explanation": "ここは〈理由〉ではなく、物の名として誤用している。玄関をはく文脈では『訳』は指せず、『玄関』と言うべき。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37503, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "訳", "is_correct": true, "explanation": "「わからなくなった理由・事情」の意味で、文が成り立つ。"}, {"text": "湯気", "is_correct": false, "explanation": "湯気は「わからなくなる」対象として意味が通らない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は「わからなくなる」の対象として不自然で、文脈に合わない。"}, {"text": "速度", "is_correct": false, "explanation": "速度は知らせの内容と結びつかず、「速度がわからなくなる」は文脈に合わない。"}], "explanations": {"訳": "「わからなくなった理由・事情」の意味で、文が成り立つ。", "湯気": "湯気は「わからなくなる」対象として意味が通らない。", "色彩": "色彩は「わからなくなる」の対象として不自然で、文脈に合わない。", "速度": "速度は知らせの内容と結びつかず、「速度がわからなくなる」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "訳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この道の訳を、地図で一つずつ確かめた。", "explanation": "ここは〈理由〉ではなく、物の名として誤用している。道を地図で確かめる文では『訳』は指せず、『道順』と言うべき。"}, {"text": "新しい訳ソフトを入れた。", "explanation": "ここは〈翻訳〉の語。『訳ソフト』とは言わず、『翻訳ソフト』を使う。"}, {"text": "この皿の訳を、棚にそっと置いた。", "explanation": "ここは〈理由〉ではなく、物の名として誤用している。皿を棚に置く文では『訳』は指せず、『皿』と言うべき。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37503, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼が来ない訳に、私にはわからない。", "corrected_sentence": "彼が来ない訳が、私にはわからない。", "error_description": "「わからない」は「〜が」で主語を取るため、「訳」には「が」が付く。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37503, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼が黙っていた訳を、私は納得した。", "corrected_sentence": "彼が黙っていた訳に、私は納得した。", "error_description": "「納得する」は「〜に」で対象を示すため、「訳」には「に」が付く。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
