INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37504, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「会う」の相手を示す格助詞で、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「会う」は相手を「と」で示すので、「を」は合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「会う」の相手を示す形にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、会う相手を示す用法ではないので合わない。"}], "correct_answer": "と", "explanations": {"と": "「会う」の相手を示す格助詞で、ここに入る。", "を": "「会う」は相手を「と」で示すので、「を」は合わない。", "から": "「から」は起点を示すので、「会う」の相手を示す形にはならない。", "へ": "方向を示す「へ」は、会う相手を示す用法ではないので合わない。"}, "error_tags": {"を": "目的語", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37504, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分と同じことをしようとする人。", "primary_collocate": null, "pronunciation": "らいばる", "ipa": "ɾaibaɾɯ", "syllable_count": 4, "sentences": [{"text": "私と同じ大学を受ける友達は、いちばんのライバルです。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "私[わたし]と同[おな]じ大学[だいがく]を受[う]ける友達[ともだち]は、いちばんのライバルです。", "sentence_source": "generated"}, {"text": "同じ仕事を目指しているので、彼はライバルだ。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "同[おな]じ仕事[しごと]を目指[めざ]しているので、彼[かれ]はライバルだ。", "sentence_source": "generated"}, {"text": "弟も同じコンクールに出るので、ライバルになった。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "弟[おとうと]も同[おな]じコンクールに出[で]るので、ライバルになった。", "sentence_source": "generated"}, {"text": "クラスに同じ夢を持つライバルがいて、毎日がんばっている。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "クラスに同[おな]じ夢[ゆめ]を持[も]つライバルがいて、毎日[まいにち]がんばっている。", "sentence_source": "generated"}, {"text": "同じ大学の同じ学部を目指す人は、みんなライバルだ。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "同[おな]じ大学[だいがく]の同[おな]じ学部[がくぶ]を目指[めざ]す人[ひと]は、みんなライバルだ。", "sentence_source": "generated"}, {"text": "彼女は同じ役をねらうライバルに、台本を見せなかった。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は同[おな]じ役[やく]をねらうライバルに、台本[だいほん]を見[み]せなかった。", "sentence_source": "generated"}, {"text": "ライバルがいるから、私も負けずに練習を続けられる。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "ライバルがいるから、私[わたし]も負[ま]けずに練習[れんしゅう]を続[つづ]けられる。", "sentence_source": "generated"}, {"text": "昔のライバルと駅で会って、少し話した。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "昔[むかし]のライバルと駅[えき]で会[あ]って、少[すこ]し話[はな]した。", "sentence_source": "generated"}, {"text": "同じ会社の同期は、仲間でもありライバルでもある。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "同[おな]じ会社[かいしゃ]の同期[どうき]は、仲間[なかま]でもありライバルでもある。", "sentence_source": "generated"}, {"text": "兄と私は同じ大会の代表の座をねらっていて、おたがいがライバルだ。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]は同[おな]じ大会[たいかい]の代表[だいひょう]の座[ざ]をねらっていて、おたがいがライバルだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ライバル", "label": "base"}], "register": "中立", "sense_fingerprint": "自分と同じことを目指す人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54f5b9e3-f2d6-4f8e-8908-7999cfe0d07d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37504, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ライバル", "is_correct": true, "explanation": "同じ大学を受けて競い合う相手を指すので、ここに入る。"}, {"text": "先生", "is_correct": false, "explanation": "教える立場の人で、同じ大学を受験する相手ではないので合わない。"}, {"text": "店員", "is_correct": false, "explanation": "店で働く人で、同じ大学を受ける友達の説明には合わない。"}, {"text": "医者", "is_correct": false, "explanation": "病気を診る人で、受験する相手ではないので文に合わない。"}], "explanations": {"ライバル": "同じ大学を受けて競い合う相手を指すので、ここに入る。", "先生": "教える立場の人で、同じ大学を受験する相手ではないので合わない。", "店員": "店で働く人で、同じ大学を受ける友達の説明には合わない。", "医者": "病気を診る人で、受験する相手ではないので文に合わない。"}, "sentence_index": 0, "correct_answer": "ライバル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合中、ライバルの選手がパスを回してくれた。", "explanation": "ここは〈味方〉の意味。ライバルは競う相手で、パスを回して助ける味方の意味にはならない。"}, {"text": "彼は私のライバルで、毎日手をつないで一緒に帰る。", "explanation": "ここは〈恋人〉の意味。ライバルは競い合う相手で、手をつないで帰る恋人の関係とは合わないので使わない。"}, {"text": "保育園で、ライバルが子どもの面倒をていねいに見ている。", "explanation": "ここは〈保育士〉の意味。ライバルは子どもを世話する立場ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37504, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ライバル", "is_correct": true, "explanation": "負けまいと張り合う相手を指すので、「負けずに練習を続けられる」の理由に合う。"}, {"text": "大工", "is_correct": false, "explanation": "家を建てる職人で、負けずに練習する理由にはならない。"}, {"text": "運転手", "is_correct": false, "explanation": "車を運転する人で、練習を続ける理由として文に合わない。"}, {"text": "看護師", "is_correct": false, "explanation": "患者を世話する人で、張り合って練習する相手ではない。"}], "explanations": {"ライバル": "負けまいと張り合う相手を指すので、「負けずに練習を続けられる」の理由に合う。", "大工": "家を建てる職人で、負けずに練習する理由にはならない。", "運転手": "車を運転する人で、練習を続ける理由として文に合わない。", "看護師": "患者を世話する人で、張り合って練習する相手ではない。"}, "sentence_index": 6, "correct_answer": "ライバル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はライバルとして、私の練習メニューを組んで毎日指導してくれる。", "explanation": "ここは〈指導者〉の意味。ライバルは競う相手で、練習メニューを組んで指導する立場の言葉ではないので合わない。"}, {"text": "ライバルは、お客さんの注文を受けて料理を運んでいる。", "explanation": "ここは〈店員〉の意味。ライバルは競う相手で、注文を受けて料理を運ぶ接客の立場の言葉ではないので合わない。"}, {"text": "ライバルは、部下の報告書に目を通して承認した。", "explanation": "ここは〈上司〉の意味。ライバルは同じことを競う相手で、部下の報告を承認する立場の言葉ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37504, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は、私のライバルを同じ大会で競っている。", "corrected_sentence": "妹は、私のライバルと同じ大会で競っている。", "error_description": "「競う」は相手を「と」で示すので、「ライバルを」ではなく「ライバルと」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37504, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は、ライバルを一度も負けなかった。", "corrected_sentence": "私は、ライバルに一度も負けなかった。", "error_description": "「負ける」は相手を「に」で示すので、「ライバルを」ではなく「ライバルに」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
