INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37505, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「なる」の変化先を示す格助詞で、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「なる」は「に」で結果を示すので、「が」は合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「なる」の結果には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、変化の結果にはならない。"}], "correct_answer": "に", "explanations": {"に": "「なる」の変化先を示す格助詞で、ここに入る。", "が": "「なる」は「に」で結果を示すので、「が」は合わない。", "を": "「を」は目的語を示すので、「なる」の結果には合わない。", "で": "「で」は場所や手段を示すので、変化の結果にはならない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37505, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "同じ目標や立場にあって、競い合う相手。", "primary_collocate": null, "pronunciation": "らいばる", "ipa": "ɾaibaɾɯ", "syllable_count": 4, "sentences": [{"text": "二人は同じ試合で優勝を争う、強いライバルだ。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "二人[ふたり]は同[おな]じ試合[しあい]で優勝[ゆうしょう]を争[あらそ]う、強[つよ]いライバルだ。", "sentence_source": "generated"}, {"text": "彼は試合のたびに競い合うライバルで、いちばんの親友でもある。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "彼[かれ]は試合[しあい]のたびに競[きそ]い合[あ]うライバルで、いちばんの親友[しんゆう]でもある。", "sentence_source": "generated"}, {"text": "来月の大会で、長年のライバルと決勝で戦う。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "来月[らいげつ]の大会[たいかい]で、長年[ながねん]のライバルと決勝[けっしょう]で戦[たたか]う。", "sentence_source": "generated"}, {"text": "成績を競うライバルがいると、勉強にも力が入る。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "成績[せいせき]を競[きそ]うライバルがいると、勉強[べんきょう]にも力[ちから]が入[はい]る。", "sentence_source": "generated"}, {"text": "彼女は同じ新人賞をねらうライバルを、心の中で意識していた。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は同[おな]じ新人賞[しんじんしょう]をねらうライバルを、心[こころ]の中[なか]で意識[いしき]していた。", "sentence_source": "generated"}, {"text": "二つの会社は、売り上げを争うライバルとして知られている。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]は、売[う]り上[あ]げを争[あらそ]うライバルとして知[し]られている。", "sentence_source": "generated"}, {"text": "決勝戦の相手は、去年負けたライバルだった。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "決勝戦[けっしょうせん]の相手[あいて]は、去年[きょねん]負[ま]けたライバルだった。", "sentence_source": "generated"}, {"text": "同じ部の二人は、エースの座を争うライバルになった。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "同[おな]じ部[ぶ]の二人[ふたり]は、エースの座[ざ]を争[あらそ]うライバルになった。", "sentence_source": "generated"}, {"text": "よきライバルがいたから、彼は世界一の選手になれた。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "よきライバルがいたから、彼[かれ]は世界一[せかいいち]の選手[せんしゅ]になれた。", "sentence_source": "generated"}, {"text": "姉と私は、ピアノの発表会で順位を競うライバルだ。", "target_word": "ライバル", "complexity_tier": "T3", "furigana": "姉[あね]と私[わたし]は、ピアノの発表会[はっぴょうかい]で順位[じゅんい]を競[きそ]うライバルだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ライバル", "label": "base"}], "register": "中立", "sense_fingerprint": "勝ち負けを競い合う相手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54f5b9e3-f2d6-4f8e-8908-7999cfe0d07d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37505, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ライバル", "is_correct": true, "explanation": "勝ち負けを争う相手を指すので、「優勝を争う」に合う。"}, {"text": "審判", "is_correct": false, "explanation": "試合を裁く人で、選手として優勝を争う相手ではない。"}, {"text": "観客", "is_correct": false, "explanation": "試合を見る人で、優勝を争う相手ではない。"}, {"text": "応援団", "is_correct": false, "explanation": "応援する側の人で、優勝を争う相手ではない。"}], "explanations": {"ライバル": "勝ち負けを争う相手を指すので、「優勝を争う」に合う。", "審判": "試合を裁く人で、選手として優勝を争う相手ではない。", "観客": "試合を見る人で、優勝を争う相手ではない。", "応援団": "応援する側の人で、優勝を争う相手ではない。"}, "sentence_index": 0, "correct_answer": "ライバル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "実験にはライバルがいて、データを集めてくれた。", "explanation": "ここは〈協力者〉の意味。ライバルは競う相手で、データ集めを手伝う相手ではない。"}, {"text": "ライバルは弟子の作品を一つずつ評価して、技を指導した。", "explanation": "ここは〈師匠〉の意味。ライバルは競う相手で、弟子に技を指導する立場の言葉ではないので合わない。"}, {"text": "ライバルは試合の流れをわかりやすく解説して、視聴者を楽しませた。", "explanation": "ここは〈解説者〉の意味。ライバルは競う相手で、試合を解説する立場の言葉ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37505, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ライバル", "is_correct": true, "explanation": "勝ち負けを争って負けた相手を指すので、「去年負けた」に合う。"}, {"text": "相棒", "is_correct": false, "explanation": "一緒に組む味方で、負けた相手を指す語ではない。"}, {"text": "指導者", "is_correct": false, "explanation": "教える立場の人で、決勝戦で戦った相手ではない。"}, {"text": "案内係", "is_correct": false, "explanation": "道案内をする人で、決勝戦の相手ではないので合わない。"}], "explanations": {"ライバル": "勝ち負けを争って負けた相手を指すので、「去年負けた」に合う。", "相棒": "一緒に組む味方で、負けた相手を指す語ではない。", "指導者": "教える立場の人で、決勝戦で戦った相手ではない。", "案内係": "道案内をする人で、決勝戦の相手ではないので合わない。"}, "sentence_index": 6, "correct_answer": "ライバル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ライバルが二人の縁をつないで、結婚式まで世話をした。", "explanation": "ここは〈仲人〉の意味。ライバルは競い合う相手で、縁組みの世話をする立場の言葉ではないので合わない。"}, {"text": "ライバルは会議の内容をていねいに訳して、みんなに伝えた。", "explanation": "ここは〈通訳〉の意味。ライバルは競い合う相手で、言葉を訳して伝える立場の言葉ではないので合わない。"}, {"text": "ライバルが、お客さんを商品の棚からレジまで案内した。", "explanation": "ここは〈店員〉の意味。ライバルは競い合う相手で、客を案内する接客の立場の言葉ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37505, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二人は、長年のライバルを決勝で戦った。", "corrected_sentence": "二人は、長年のライバルと決勝で戦った。", "error_description": "「戦う」は相手を「と」で示すので、「ライバルを」ではなく「ライバルと」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37505, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は、よきライバルを競い合って成長した。", "corrected_sentence": "私は、よきライバルと競い合って成長した。", "error_description": "「競い合う」は相手を「と」で示すので、「ライバルを」ではなく「ライバルと」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33cacc52-1f04-4931-b665-a81d12f7965e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37506, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「戦い」の後に「なりました」と続き、「〜になる」の「に」が付く。"}, {"text": "を", "is_correct": false, "explanation": "「戦いを なりました」は成り立たず、「なる」は「に」で結果を示す。"}, {"text": "で", "is_correct": false, "explanation": "「戦いで なりました」は文が成り立たず、「で」は結果の意味にならない。"}, {"text": "から", "is_correct": false, "explanation": "「戦いから なりました」は文が成り立たず、起点の意味にもならない。"}], "correct_answer": "に", "explanations": {"に": "「戦い」の後に「なりました」と続き、「〜になる」の「に」が付く。", "を": "「戦いを なりました」は成り立たず、「なる」は「に」で結果を示す。", "で": "「戦いで なりました」は文が成り立たず、「で」は結果の意味にならない。", "から": "「戦いから なりました」は文が成り立たず、起点の意味にもならない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "から": "起点・理由"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
