INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37506, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "相手とぶつかって、どちらが強いか決めることです。", "primary_collocate": null, "pronunciation": "たたかい", "ipa": "tatakai", "syllable_count": 4, "sentences": [{"text": "二匹のオスのシカが、角をぶつけ合って激しい戦いをしました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "二(に)匹(ひき)のオスのシカが、角(つの)をぶつけ合(あ)って激(はげ)しい戦(たたか)いをしました。", "sentence_source": "generated"}, {"text": "強いチームが勝つと思っていましたが、最後まで分からない戦いになりました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "強(つよ)いチームが勝(か)つと思(おも)っていましたが、最後(さいご)まで分(わ)からない戦(たたか)いになりました。", "sentence_source": "generated"}, {"text": "この戦いに勝った人が、今年のチャンピオンになります。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "この戦(たたか)いに勝(か)った人(ひと)が、今年(ことし)のチャンピオンになります。", "sentence_source": "generated"}, {"text": "リングの上では、二人の選手の戦いが始まりました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "リングの上(うえ)では、二人(ふたり)の選手(せんしゅ)の戦(たたか)いが始(はじ)まりました。", "sentence_source": "generated"}, {"text": "ライオンの子どもたちは、遊びの中で仲間との小さな戦いを何度も繰り返します。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "ライオンの子[こ]どもたちは、遊[あそ]びの中[なか]で仲間[なかま]との小[ちい]さな戦[たたか]いを何度[なんど]も繰[く]り返[かえ]します。", "sentence_source": "generated"}, {"text": "試合は一点を争う苦しい戦いでしたが、私たちは最後に勝ちました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "試合(しあい)は一点(いってん)を争(あらそ)う苦(くる)しい戦(たたか)いでしたが、私(わたし)たちは最後(さいご)に勝(か)ちました。", "sentence_source": "generated"}, {"text": "強い相手との戦いに負けて、彼は悔しそうに下を向きました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "強(つよ)い相手(あいて)との戦(たたか)いに負(ま)けて、彼(かれ)は悔(くや)しそうに下(した)を向(む)きました。", "sentence_source": "generated"}, {"text": "初めての戦いで緊張しましたが、先生の言葉を思い出して落ち着きました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "初(はじ)めての戦(たたか)いで緊張(きんちょう)しましたが、先生(せんせい)の言葉(ことば)を思(おも)い出(だ)して落(お)ち着(つ)きました。", "sentence_source": "generated"}, {"text": "夜遅くまで続いた戦いのあと、ふたりの力士は握手をしました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "夜(よる)遅(おそ)くまで続(つづ)いた戦(たたか)いのあと、ふたりの力士(りきし)は握手(あくしゅ)をしました。", "sentence_source": "generated"}, {"text": "戦いが終わると、観客は大きな拍手を送りました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "戦(たたか)いが終(お)わると、観客(かんきゃく)は大(おお)きな拍手(はくしゅ)を送(おく)りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戦い", "label": "基本形"}, {"form": "戦いを", "label": "を格"}, {"form": "戦いに", "label": "に格"}, {"form": "戦いの", "label": "の格"}], "register": "丁寧語", "sense_fingerprint": "戦い:相手とぶつかり合い、強さを決める勝負", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b56525-d686-4f42-9de7-3cd4f31105fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37506, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戦い", "is_correct": true, "explanation": "角をぶつけ合う勝負の意味で、「激しい戦いをした」と文が成り立つ。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は「激しい」ことをして行うものではなく、「激しい眠気をした」は不自然。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は「激しく」行う行為の対象にならず、「激しい手紙をした」は成り立たない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は「激しい」と結びつかず、「激しい料理をした」は意味が通らない。"}], "explanations": {"戦い": "角をぶつけ合う勝負の意味で、「激しい戦いをした」と文が成り立つ。", "眠気": "眠気は「激しい」ことをして行うものではなく、「激しい眠気をした」は不自然。", "手紙": "手紙は「激しく」行う行為の対象にならず、「激しい手紙をした」は成り立たない。", "料理": "料理は「激しい」と結びつかず、「激しい料理をした」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "戦い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店のケーキは、戦いのように甘くておいしい。", "explanation": "ここは〈甘さ〉を述べる文。戦いは勝ち負けを競う意味で、味の説明には合わない。『甘い』と言うべき。"}, {"text": "私は毎朝、戦いの量を数えてから食事をする。", "explanation": "ここは〈食事〉の文。戦いは勝ち負けを競う意味で、食事の量には合わない。『量』と言うべき。"}, {"text": "この時計は、戦いのように正確に時を刻む。", "explanation": "ここは〈正確さ〉を述べる文。戦いは勝ち負けを競う意味で、時計の正確さには合わない。『正確』と言うべき。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37506, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戦い", "is_correct": true, "explanation": "強い相手との勝負に「負けた」と結びつき、文が成り立つ。"}, {"text": "相談", "is_correct": false, "explanation": "相談は「負けた」の対象にならず、「相談に負けた」は不自然。"}, {"text": "天気", "is_correct": false, "explanation": "天気は勝負の相手や対象にならず、「天気に負けた」は文脈に合わない。"}, {"text": "雑誌", "is_correct": false, "explanation": "雑誌は勝負の対象にならず、「雑誌に負けた」は成り立たない。"}], "explanations": {"戦い": "強い相手との勝負に「負けた」と結びつき、文が成り立つ。", "相談": "相談は「負けた」の対象にならず、「相談に負けた」は不自然。", "天気": "天気は勝負の相手や対象にならず、「天気に負けた」は文脈に合わない。", "雑誌": "雑誌は勝負の対象にならず、「雑誌に負けた」は成り立たない。"}, "sentence_index": 6, "correct_answer": "戦い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は、ケーキの戦いを毎朝一時間ずつ楽しんだ。", "explanation": "ここは〈楽しむ〉の文。戦いは勝ち負けを競う意味で、食べる時間には合わない。『楽しみ』と言うべき。"}, {"text": "この机の戦いは、とても古くて丈夫だ。", "explanation": "ここは〈机〉の状態を述べる文。戦いは勝ち負けを競う意味で、家具の状態には合わない。『机』の状態を言うべき。"}, {"text": "この花瓶の戦いは、とても美しい。", "explanation": "ここは〈花瓶〉の美しさを述べる文。戦いは勝ち負けを競う意味で、花瓶の美しさには合わない。『美しさ』と言うべき。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37506, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日の戦いを負けて、ふたりは悔しそうにした。", "corrected_sentence": "雨の日の戦いに負けて、ふたりは悔しそうにした。", "error_description": "「負ける」は「〜に負ける」で相手や勝負を示すため、「戦い」には「に」が付く。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37506, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "初めての戦いが、少し緊張した。", "corrected_sentence": "初めての戦いで、少し緊張した。", "error_description": "「緊張する」は場面を「で」で示すため、「戦い」には「で」が付く。「が」では主語になり不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37507, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「終わって」の主語になる「戦い」には「が」が付く。"}, {"text": "を", "is_correct": false, "explanation": "「戦いを 終わって」は文が成り立たず、「終わる」は目的語を取らない。"}, {"text": "に", "is_correct": false, "explanation": "「戦いに 終わって」は結びつかず、主語の位置に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「戦いへ 終わって」は方向の意味にならず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「終わって」の主語になる「戦い」には「が」が付く。", "を": "「戦いを 終わって」は文が成り立たず、「終わる」は目的語を取らない。", "に": "「戦いに 終わって」は結びつかず、主語の位置に合わない。", "へ": "「戦いへ 終わって」は方向の意味にならず、文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "方向・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37507, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「せいで」に続く名詞句を作る「の」で、「長い戦いのせいで」と文が成り立つ。"}, {"text": "で", "is_correct": false, "explanation": "「戦いで せいで」は文が成り立たず、「で」は原因を示すこの形に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「戦いと せいで」は結びつかず、名詞の修飾にならない。"}, {"text": "より", "is_correct": false, "explanation": "「戦いより せいで」は比較の意味にならず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「せいで」に続く名詞句を作る「の」で、「長い戦いのせいで」と文が成り立つ。", "で": "「戦いで せいで」は文が成り立たず、「で」は原因を示すこの形に合わない。", "と": "「戦いと せいで」は結びつかず、名詞の修飾にならない。", "より": "「戦いより せいで」は比較の意味にならず、文が成り立たない。"}, "error_tags": {"で": "手段・場所", "と": "並列・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37507, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "互いに勝ち負けを競うこと。特に、武力や競技などで相手と争うこと。", "primary_collocate": null, "pronunciation": "たたかい", "ipa": "tatakai", "syllable_count": 4, "sentences": [{"text": "昔、この土地では二つの国が長い戦いを続けました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "昔(むかし)、この土地(とち)では二(ふた)つの国(くに)が長(なが)い戦(たたか)いを続(つづ)けました。", "sentence_source": "generated"}, {"text": "戦いが終わって、人々はようやく静かな生活に戻りました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "戦(たたか)いが終(お)わって、人々(ひとびと)はようやく静(しず)かな生活(せいかつ)に戻(もど)りました。", "sentence_source": "generated"}, {"text": "オリンピックでは、世界中の選手が金メダルをかけて戦いに挑みます。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "オリンピックでは、世界中(せかいじゅう)の選手(せんしゅ)が金(きん)メダルをかけて戦(たたか)いに挑(いど)みます。", "sentence_source": "generated"}, {"text": "決勝の戦いは延長戦までもつれ、最後は一点差で決まりました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "決勝(けっしょう)の戦(たたか)いは延長戦(えんちょうせん)までもつれ、最後(さいご)は一点差(いってんさ)で決(き)まりました。", "sentence_source": "generated"}, {"text": "歴史の授業で、有名な戦いが起きた場所を地図で調べました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "歴史[れきし]の授業[じゅぎょう]で、有名[ゆうめい]な戦[たたか]いが起[お]きた場所[ばしょ]を地図[ちず]で調[しら]べました。", "sentence_source": "generated"}, {"text": "戦いに勝った王様は、新しい城を建てることにしました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "戦(たたか)いに勝(か)った王様(おうさま)は、新(あたら)しい城(しろ)を建(た)てることにしました。", "sentence_source": "generated"}, {"text": "剣道の大会では、一回戦から厳しい戦いが続きました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "剣道(けんどう)の大会(たいかい)では、一回戦(いっかいせん)から厳(きび)しい戦(たたか)いが続(つづ)きました。", "sentence_source": "generated"}, {"text": "長い戦いのせいで、村の畑は荒れてしまいました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "長(なが)い戦(たたか)いのせいで、村(むら)の畑(はたけ)は荒(あ)れてしまいました。", "sentence_source": "generated"}, {"text": "相撲の戦いは短いですが、土俵の上では一瞬も気を抜けません。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "相撲(すもう)の戦(たたか)いは短(みじか)いですが、土俵(どひょう)の上(うえ)では一瞬(いっしゅん)も気(き)を抜(ぬ)けません。", "sentence_source": "generated"}, {"text": "私は兵士たちの戦いを描いた映画を見て、平和の大切さを考えました。", "target_word": "戦い", "complexity_tier": "T3", "furigana": "私(わたし)は兵士(へいし)たちの戦(たたか)いを描(えが)いた映画(えいが)を見(み)て、平和(へいわ)の大切(たいせつ)さを考(かんが)えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戦い", "label": "基本形"}, {"form": "戦いを", "label": "を格"}, {"form": "戦いに", "label": "に格"}, {"form": "戦いの", "label": "の格"}], "register": "丁寧語", "sense_fingerprint": "戦い:武力や競技で勝ち負けを争う戦争・試合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b56525-d686-4f42-9de7-3cd4f31105fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37507, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戦い", "is_correct": true, "explanation": "国同士が長く争った意味で、「長い戦いを続けた」と文が成り立つ。"}, {"text": "天井", "is_correct": false, "explanation": "天井は争いの対象にならず、「長い天井を続けた」は意味が通らない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は続けて行う行為の対象にならず、「長い色彩を続けた」は不自然。"}, {"text": "味覚", "is_correct": false, "explanation": "味覚は続ける行為の対象にならず、「長い味覚を続けた」は成り立たない。"}], "explanations": {"戦い": "国同士が長く争った意味で、「長い戦いを続けた」と文が成り立つ。", "天井": "天井は争いの対象にならず、「長い天井を続けた」は意味が通らない。", "色彩": "色彩は続けて行う行為の対象にならず、「長い色彩を続けた」は不自然。", "味覚": "味覚は続ける行為の対象にならず、「長い味覚を続けた」は成り立たない。"}, "sentence_index": 0, "correct_answer": "戦い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は毎朝、散歩を戦いのように楽しんでいる。", "explanation": "ここは〈散歩〉を楽しむ文。戦いは武力や競技で相手と争う意味で、散歩には合わない。『散歩』と言うべき。"}, {"text": "妹は、おやつを戦いの量だけ食べた。", "explanation": "ここは〈食べる〉の文。戦いは勝ち負けを競う意味で、おやつの量には合わない。『量』と言うべき。"}, {"text": "庭の戦いを、ふたりで手入れした。", "explanation": "ここは〈庭の手入れ〉の文。戦いは争う意味で、庭の作業には合わない。『庭』と言うべき。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37507, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戦い", "is_correct": true, "explanation": "大会で続いた厳しい勝負の意味で、「厳しい戦いが続いた」と文が成り立つ。"}, {"text": "寝具", "is_correct": false, "explanation": "寝具は続く対象にならず、「厳しい寝具が続いた」は意味が通らない。"}, {"text": "水深", "is_correct": false, "explanation": "水深は大会の流れとして続くものではなく、文脈に合わない。"}, {"text": "香料", "is_correct": false, "explanation": "香料は大会の展開に結びつかず、「厳しい香料が続いた」は成り立たない。"}], "explanations": {"戦い": "大会で続いた厳しい勝負の意味で、「厳しい戦いが続いた」と文が成り立つ。", "寝具": "寝具は続く対象にならず、「厳しい寝具が続いた」は意味が通らない。", "水深": "水深は大会の流れとして続くものではなく、文脈に合わない。", "香料": "香料は大会の展開に結びつかず、「厳しい香料が続いた」は成り立たない。"}, "sentence_index": 6, "correct_answer": "戦い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ふたりは昼ごはんの戦いで、ぬれてしまった。", "explanation": "ここは〈昼ごはん〉の文。戦いは争う意味で、食事の場面にはつながらない。『食事』と言うべき。"}, {"text": "今日は、ふとん干しの戦いを終えた。", "explanation": "ここは〈干す〉という作業の文。戦いは争う意味で、ふとん干しには合わない。『作業』と言うべき。"}, {"text": "この店は、味噌汁の戦いで客を増やした。", "explanation": "ここは〈味〉の評判の文。戦いは争う意味で、味の評判には合わない。『評判』と言うべき。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37507, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "敵との戦いを勝った。", "corrected_sentence": "敵との戦いに勝った。", "error_description": "「勝つ」は「〜に勝つ」で相手や勝負を示すため、「戦い」には「に」が付く。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37507, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の大会では、準決勝まで厳しい戦いを続きました。", "corrected_sentence": "夏の大会では、準決勝まで厳しい戦いが続きました。", "error_description": "「続く」は主語を「が」で示す自動詞のため、「戦い」には「が」が付く。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37508, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「協調がなければ」で、「ない」の主語を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「ない」は目的語を取らず主語を取るので、「協調をなければ」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「協調になければ」は場所・帰着の「に」が「ない」と続かず、不自然で成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「協調となければ」は引用・結果の「と」の形で、「なければ」と続かない。"}], "correct_answer": "が", "explanations": {"が": "「協調がなければ」で、「ない」の主語を示す格助詞。", "を": "「ない」は目的語を取らず主語を取るので、「協調をなければ」は成り立たない。", "に": "「協調になければ」は場所・帰着の「に」が「ない」と続かず、不自然で成り立たない。", "と": "「協調となければ」は引用・結果の「と」の形で、「なければ」と続かない。"}, "error_tags": {"を": "目的語（「ない」の主語と合わない）", "に": "場所・帰着（不自然）", "と": "引用・結果（続かない）"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "対立", "is_correct": true, "explanation": "協調の対義語。互いに譲らず張り合う関係で、協調と反対の意味を持つ。"}, {"text": "延期", "is_correct": false, "explanation": "予定を先に延ばすこと。協調の対義語ではない。"}, {"text": "放任", "is_correct": false, "explanation": "干渉せずに任せること。協調の対義語として辞書に並ばない。"}, {"text": "自立", "is_correct": false, "explanation": "他に頼らず自分で立つこと。協調の対義語ではない。"}], "correct_answer": "対立", "explanations": {"対立": "協調の対義語。互いに譲らず張り合う関係で、協調と反対の意味を持つ。", "延期": "予定を先に延ばすこと。協調の対義語ではない。", "放任": "干渉せずに任せること。協調の対義語として辞書に並ばない。", "自立": "他に頼らず自分で立つこと。協調の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37508, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「協調が必要です」で、「必要です」の主語を示す格助詞。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を示すが、「必要です」の主語にならず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「必要です」の主語にならず、「協調へ必要です」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点・理由の「から」は「協調から必要です」と続かず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「協調が必要です」で、「必要です」の主語を示す格助詞。", "で": "「で」は手段・場所を示すが、「必要です」の主語にならず文が成り立たない。", "へ": "方向の「へ」は「必要です」の主語にならず、「協調へ必要です」は成り立たない。", "から": "起点・理由の「から」は「協調から必要です」と続かず、文が成り立たない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "から": "起点・理由"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "対立", "is_correct": true, "explanation": "協調の対義語。互いに譲らず張り合う関係で、協調と反対の意味を持つ。"}, {"text": "延期", "is_correct": false, "explanation": "予定を先に延ばすこと。協調の対義語ではない。"}, {"text": "分業", "is_correct": false, "explanation": "仕事を分け持つこと。協調と対になる関係ではない。"}, {"text": "交換", "is_correct": false, "explanation": "互いに物を取り替えること。協調の対義語ではない。"}], "correct_answer": "対立", "explanations": {"対立": "協調の対義語。互いに譲らず張り合う関係で、協調と反対の意味を持つ。", "延期": "予定を先に延ばすこと。協調の対義語ではない。", "分業": "仕事を分け持つこと。協調と対になる関係ではない。", "交換": "互いに物を取り替えること。協調の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37508, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなで力を合わせて、同じ目標に向かって動くこと。", "primary_collocate": null, "pronunciation": "きょうちょう", "ipa": "kʲoːtɕoː", "syllable_count": 4, "sentences": [{"text": "この仕事はチームの協調が大切です。", "target_word": "協調", "complexity_tier": "T3", "furigana": "この仕事(しごと)はチームの協調(きょうちょう)が大切(たいせつ)です。", "sentence_source": "generated"}, {"text": "みんなの協調がなければ、文化祭は成功しません。", "target_word": "協調", "complexity_tier": "T3", "furigana": "みんなの協調(きょうちょう)がなければ、文化祭(ぶんかさい)は成功(せいこう)しません。", "sentence_source": "generated"}, {"text": "協調して動いたので、荷物を早く運べました。", "target_word": "協調", "complexity_tier": "T3", "furigana": "協調(きょうちょう)して動(うご)いたので、荷物(にもつ)を早(はや)く運(はこ)べました。", "sentence_source": "generated"}, {"text": "三年生が協調して準備を進め、劇は大成功でした。", "target_word": "協調", "complexity_tier": "T3", "furigana": "三年生(さんねんせい)が協調(きょうちょう)して準備(じゅんび)を進(すす)め、劇(げき)は大成功(だいせいこう)でした。", "sentence_source": "generated"}, {"text": "意見が違っても、協調を忘れずに話し合いましょう。", "target_word": "協調", "complexity_tier": "T3", "furigana": "意見(いけん)が違(ちが)っても、協調(きょうちょう)を忘(わす)れずに話(はな)し合(あ)いましょう。", "sentence_source": "generated"}, {"text": "クラス全員の協調のおかげで、合唱コンクールで一位になりました。", "target_word": "協調", "complexity_tier": "T3", "furigana": "クラス全員(ぜんいん)の協調(きょうちょう)のおかげで、合唱(がっしょう)コンクールで一位(いちい)になりました。", "sentence_source": "generated"}, {"text": "協調を大切にする山田さんは、チームでよく信頼されています。", "target_word": "協調", "complexity_tier": "T3", "furigana": "協調(きょうちょう)を大切(たいせつ)にする山田(やまだ)さんは、チームでよく信頼(しんらい)されています。", "sentence_source": "generated"}, {"text": "野球は一人では勝てないので、仲間との協調が必要です。", "target_word": "協調", "complexity_tier": "T3", "furigana": "野球(やきゅう)は一人(ひとり)では勝(か)てないので、仲間(なかま)との協調(きょうちょう)が必要(ひつよう)です。", "sentence_source": "generated"}, {"text": "全員の協調がうまくいかず、リレーでバトンを落としてしまいました。", "target_word": "協調", "complexity_tier": "T3", "furigana": "全員(ぜんいん)の協調(きょうちょう)がうまくいかず、リレーでバトンを落(お)としてしまいました。", "sentence_source": "generated"}, {"text": "目標が同じでも、協調しなければ力は一つになりません。", "target_word": "協調", "complexity_tier": "T3", "furigana": "目標(もくひょう)が同(おな)じでも、協調(きょうちょう)しなければ力(ちから)は一(ひと)つになりません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "協調", "label": "基本形"}, {"form": "協調する", "label": "する動詞・辞書形"}, {"form": "協調して", "label": "て形"}, {"form": "協調した", "label": "過去形"}], "register": "丁寧語", "sense_fingerprint": "協調:全員が力を合わせて同じ目標へ進むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b56525-d686-4f42-9de7-3cd4f31105fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37508, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "協調", "is_correct": true, "explanation": "名詞。「チームの〜が大切」の位置に入り、文として成り立つ。"}, {"text": "協調して", "is_correct": false, "explanation": "て形は後ろに動詞が続く形で、「チームの〜が」の名詞の位置には入らない。"}, {"text": "協調する", "is_correct": false, "explanation": "辞書形の動詞。「チームの協調する大切」となり、名詞の位置に入らない。"}, {"text": "協調した", "is_correct": false, "explanation": "過去の動詞形。「チームの協調した大切」となり、名詞の位置には入らない。"}], "explanations": {"協調": "名詞。「チームの〜が大切」の位置に入り、文として成り立つ。", "協調して": "て形は後ろに動詞が続く形で、「チームの〜が」の名詞の位置には入らない。", "協調する": "辞書形の動詞。「チームの協調する大切」となり、名詞の位置に入らない。", "協調した": "過去の動詞形。「チームの協調した大切」となり、名詞の位置には入らない。"}, "sentence_index": 0, "correct_answer": "協調"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議では、安全の大切さを協調しました。", "explanation": "ここは〈強調〉の意味。協調は人と力を合わせることで、大事な点を強く言い表す意味では使わない。"}, {"text": "来週の会議で、新しい予算の案を協調する予定です。", "explanation": "ここは〈協議〉の意味。協調は同じ目標へ力を合わせることで、話し合って決めることは協議という。"}, {"text": "大雪で困っていたおばあさんの買い物を、協調して手伝いました。", "explanation": "ここは〈協力〉の意味。協調は互いに調整し合って目標に向かうことで、一方が相手を手伝う場面では協力を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37508, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "協調", "is_correct": true, "explanation": "名詞。「〜を大切にする」の目的語になり、文が成り立つ。"}, {"text": "協調的", "is_correct": false, "explanation": "形容動詞型の語幹。「協調的を大切にする」とは続かない。"}, {"text": "協調しない", "is_correct": false, "explanation": "否定の動詞形。名詞の位置に入らず、「協調しないを大切にする」は成り立たない。"}, {"text": "協調させる", "is_correct": false, "explanation": "使役の動詞形。「協調させるを大切にする」と続かない。"}], "explanations": {"協調": "名詞。「〜を大切にする」の目的語になり、文が成り立つ。", "協調的": "形容動詞型の語幹。「協調的を大切にする」とは続かない。", "協調しない": "否定の動詞形。名詞の位置に入らず、「協調しないを大切にする」は成り立たない。", "協調させる": "使役の動詞形。「協調させるを大切にする」と続かない。"}, "sentence_index": 6, "correct_answer": "協調"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周りの意見に協調して、自分の考えをすぐ変えてしまいました。", "explanation": "ここは〈同調〉の意味。協調は同じ目標へ力を合わせることで、周りに流されて考えを合わせることは同調という。"}, {"text": "両国は長い話し合いの末、新しい貿易の協調を結びました。", "explanation": "ここは〈協定〉の意味。協調は力を合わせる態度で、取り決めを結ぶことは協定という。"}, {"text": "取引先と製品の値段を協調し続けています。", "explanation": "ここは〈交渉〉の意味。協調は目標に向かって力を合わせることで、条件を話し合って詰めることは交渉という。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37508, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班のみんなが協調を、作業を分担しました。", "corrected_sentence": "班のみんなが協調して、作業を分担しました。", "error_description": "「協調を」は誤り。協調は「協調して」の形で動作を続けるので、目的語の「を」ではなく動詞のて形「して」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37508, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仲間と協調するて練習すると、上達が早くなります。", "corrected_sentence": "仲間と協調して練習すると、上達が早くなります。", "error_description": "「協調するて」は誤り。する動詞のて形は「して」で、辞書形に「て」を付けた形は使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37509, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「協調がよくなり」で、「よくなる」の主語を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「よくなる」は目的語を取らないので、「協調をよくなり」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「協調とよくなり」は相手や引用の「と」で、「よくなり」と続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「協調へよくなり」は方向の「へ」で、「よくなり」の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「協調がよくなり」で、「よくなる」の主語を示す格助詞。", "を": "「よくなる」は目的語を取らないので、「協調をよくなり」は成り立たない。", "と": "「協調とよくなり」は相手や引用の「と」で、「よくなり」と続かない。", "へ": "「協調へよくなり」は方向の「へ」で、「よくなり」の主語にならない。"}, "error_tags": {"を": "目的語（よくなると合わない）", "と": "相手・引用", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "対立", "is_correct": true, "explanation": "協調の対義語。互いに譲らず張り合う関係で、協調と反対の意味を持つ。"}, {"text": "延期", "is_correct": false, "explanation": "予定を先に延ばすこと。協調の対義語ではない。"}, {"text": "放任", "is_correct": false, "explanation": "干渉せずに任せること。協調の対義語として辞書に並ばない。"}, {"text": "自立", "is_correct": false, "explanation": "他に頼らず自分で立つこと。協調の対義語ではない。"}], "correct_answer": "対立", "explanations": {"対立": "協調の対義語。互いに譲らず張り合う関係で、協調と反対の意味を持つ。", "延期": "予定を先に延ばすこと。協調の対義語ではない。", "放任": "干渉せずに任せること。協調の対義語として辞書に並ばない。", "自立": "他に頼らず自分で立つこと。協調の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37509, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「協調が欠かせません」で、「欠かせません」の主語を示す格助詞。"}, {"text": "で", "is_correct": false, "explanation": "「協調で欠かせません」は手段・場所の「で」が「欠かせない」と続かず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「協調より欠かせません」と続かず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」は「協調の欠かせません」と続かず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「協調が欠かせません」で、「欠かせません」の主語を示す格助詞。", "で": "「協調で欠かせません」は手段・場所の「で」が「欠かせない」と続かず、不自然。", "より": "比較の「より」は「協調より欠かせません」と続かず、文が成り立たない。", "の": "連体の「の」は「協調の欠かせません」と続かず、文が成り立たない。"}, "error_tags": {"で": "手段・場所", "より": "比較", "の": "連体（名詞修飾）"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "対立", "is_correct": true, "explanation": "協調の対義語。互いに譲らず張り合う関係で、協調と反対の意味を持つ。"}, {"text": "延期", "is_correct": false, "explanation": "予定を先に延ばすこと。協調の対義語ではない。"}, {"text": "分業", "is_correct": false, "explanation": "仕事を分け持つこと。協調と対になる関係ではない。"}, {"text": "交換", "is_correct": false, "explanation": "互いに物を取り替えること。協調の対義語ではない。"}], "correct_answer": "対立", "explanations": {"対立": "協調の対義語。互いに譲らず張り合う関係で、協調と反対の意味を持つ。", "延期": "予定を先に延ばすこと。協調の対義語ではない。", "分業": "仕事を分け持つこと。協調と対になる関係ではない。", "交換": "互いに物を取り替えること。協調の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37509, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の人が互いに助け合い、調整しながら行動すること。", "primary_collocate": null, "pronunciation": "きょうちょう", "ipa": "kʲoːtɕoː", "syllable_count": 4, "sentences": [{"text": "医者と看護師が協調して、患者さんを助けました。", "target_word": "協調", "complexity_tier": "T3", "furigana": "医者(いしゃ)と看護師(かんごし)が協調(きょうちょう)して、患者(かんじゃ)さんを助(たす)けました。", "sentence_source": "generated"}, {"text": "二つの部署の協調がよくなり、仕事が早く終わるようになりました。", "target_word": "協調", "complexity_tier": "T3", "furigana": "二(ふた)つの部署(ぶしょ)の協調(きょうちょう)がよくなり、仕事(しごと)が早(はや)く終(お)わるようになりました。", "sentence_source": "generated"}, {"text": "協調して動くには、まず相手の予定を聞くことが大切です。", "target_word": "協調", "complexity_tier": "T3", "furigana": "協調(きょうちょう)して動(うご)くには、まず相手(あいて)の予定(よてい)を聞(き)くことが大切(たいせつ)です。", "sentence_source": "generated"}, {"text": "ダンスでは、パートナーとの協調が特に大切です。", "target_word": "協調", "complexity_tier": "T3", "furigana": "ダンスでは、パートナーとの協調(きょうちょう)が特に大切(たいせつ)です。", "sentence_source": "generated"}, {"text": "町の人々は協調して、川の掃除を毎週続けています。", "target_word": "協調", "complexity_tier": "T3", "furigana": "町(まち)の人々(ひとびと)は協調(きょうちょう)して、川(かわ)の掃除(そうじ)を毎週(まいしゅう)続(つづ)けています。", "sentence_source": "generated"}, {"text": "毎朝の短い話し合いが、二つの班の協調を助けています。", "target_word": "協調", "complexity_tier": "T3", "furigana": "毎朝(まいあさ)の短(みじか)い話(はな)し合(あ)いが、二(ふた)つの班(はん)の協調(きょうちょう)を助(たす)けています。", "sentence_source": "generated"}, {"text": "隊員たちは協調しながら、山で迷った人を探しました。", "target_word": "協調", "complexity_tier": "T3", "furigana": "隊員(たいいん)たちは協調(きょうちょう)しながら、山(やま)で迷(まよ)った人(ひと)を探(さが)しました。", "sentence_source": "generated"}, {"text": "工事は、大工と電気屋の協調が欠かせません。", "target_word": "協調", "complexity_tier": "T3", "furigana": "工事(こうじ)は、大工(だいく)と電気屋(でんきや)の協調(きょうちょう)が欠(か)かせません。", "sentence_source": "generated"}, {"text": "仲間と協調できず、ひとりで進めた計画は失敗しました。", "target_word": "協調", "complexity_tier": "T3", "furigana": "仲間(なかま)と協調(きょうちょう)できず、ひとりで進(すす)めた計画(けいかく)は失敗(しっぱい)しました。", "sentence_source": "generated"}, {"text": "兄弟が協調して家事を分けると、母はとても助かります。", "target_word": "協調", "complexity_tier": "T3", "furigana": "兄弟(きょうだい)が協調(きょうちょう)して家事(かじ)を分(わ)けると、母(はは)はとても助(たす)かります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "協調", "label": "基本形"}, {"form": "協調する", "label": "する動詞・辞書形"}, {"form": "協調して", "label": "て形"}, {"form": "協調しながら", "label": "ながら形"}], "register": "丁寧語", "sense_fingerprint": "協調:複数の人が助け合い、調整しながら行動すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b56525-d686-4f42-9de7-3cd4f31105fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37509, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "協調", "is_correct": true, "explanation": "名詞。「医者と看護師が協調して」の形で、動作の主体の協力を表す。"}, {"text": "協調性", "is_correct": false, "explanation": "人の性質を表す名詞。「医者と看護師が協調性して」とは続かない。"}, {"text": "協調的", "is_correct": false, "explanation": "形容動詞型の語。「協調的して」とは続かず、文が成り立たない。"}, {"text": "協調中", "is_correct": false, "explanation": "進行中の状態を表す名詞。「協調中して」は文として成り立たない。"}], "explanations": {"協調": "名詞。「医者と看護師が協調して」の形で、動作の主体の協力を表す。", "協調性": "人の性質を表す名詞。「医者と看護師が協調性して」とは続かない。", "協調的": "形容動詞型の語。「協調的して」とは続かず、文が成り立たない。", "協調中": "進行中の状態を表す名詞。「協調中して」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "協調"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この点は必ず協調して伝えてください。", "explanation": "ここは〈強調〉の意味。協調は人と力を合わせることで、大事な点を強く示す意味では使わない。"}, {"text": "次回の打ち合わせで、報告の内容を協調する予定です。", "explanation": "ここは〈協議〉の意味。協調は互いに助け合って行動することで、内容を話し合って決めることは協議という。"}, {"text": "契約書の内容に協調しました。", "explanation": "ここは〈同意〉の意味。協調は互いに助け合い調整しながら行動することで、内容を認めて納得する意味は持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37509, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "協調", "is_correct": true, "explanation": "名詞。「隊員たちは協調しながら」の形で、共同で行動する意味を表す。"}, {"text": "協調後", "is_correct": false, "explanation": "時点を表す名詞。「協調後しながら」とは続かない。"}, {"text": "協調時", "is_correct": false, "explanation": "場面を表す名詞。「協調時しながら」は文として成り立たない。"}, {"text": "協調前", "is_correct": false, "explanation": "時点を表す名詞。「協調前しながら」は続かない。"}], "explanations": {"協調": "名詞。「隊員たちは協調しながら」の形で、共同で行動する意味を表す。", "協調後": "時点を表す名詞。「協調後しながら」とは続かない。", "協調時": "場面を表す名詞。「協調時しながら」は文として成り立たない。", "協調前": "時点を表す名詞。「協調前しながら」は続かない。"}, "sentence_index": 6, "correct_answer": "協調"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "流行の髪型に協調して、みんなと同じ髪にしました。", "explanation": "ここは〈同調〉の意味。協調は同じ目標へ力を合わせることで、周りに合わせて自分も同じにする意味は持たない。"}, {"text": "二つの町は、ごみ処理について協調を結びました。", "explanation": "ここは〈協定〉の意味。協調は力を合わせる態度で、取り決めを結ぶことは協定という。"}, {"text": "地元の会社が大会の費用を協調してくれました。", "explanation": "ここは〈協賛〉の意味。協調は人どうしが力を合わせることで、費用を出して支えることは協賛という。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37509, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの班が協調に、川の掃除を進めました。", "corrected_sentence": "二つの班が協調して、川の掃除を進めました。", "error_description": "「協調に」は誤り。協調は「協調して」の形で動作を続けるので、格助詞の「に」ではなく動詞のて形「して」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37509, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救助隊は協調しなら、山の斜面を調べました。", "corrected_sentence": "救助隊は協調しながら、山の斜面を調べました。", "error_description": "「協調しなら」は誤り。同時に行う意味の「しながら」の形が崩れている。「しながら」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37510, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「こんな機会」について二度とないと述べる話題を導く。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す助詞で、「ない」の主題の位置には入らない。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表す助詞で、ここでは「二度とない」の主題にならない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す助詞で、ここでは「二度とない」の主題にはならない。"}], "correct_answer": "は", "explanations": {"は": "「こんな機会」について二度とないと述べる話題を導く。", "を": "目的語を表す助詞で、「ない」の主題の位置には入らない。", "に": "位置や相手を表す助詞で、ここでは「二度とない」の主題にならない。", "で": "場所や手段を表す助詞で、ここでは「二度とない」の主題にはならない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37510, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「少ない」の主語を表し、運動する機会が少ないという意味になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す助詞だが、「少ない」は主語を取るので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す助詞で、ここでは「少ない」の主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表す助詞で、ここでは主語の役割を担えない。"}], "correct_answer": "が", "explanations": {"が": "「少ない」の主語を表し、運動する機会が少ないという意味になる。", "を": "目的語を表す助詞だが、「少ない」は主語を取るので合わない。", "で": "場所や手段を表す助詞で、ここでは「少ない」の主語にならない。", "と": "共同や引用を表す助詞で、ここでは主語の役割を担えない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "共同・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37510, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするのにちょうどいいとき。", "primary_collocate": null, "pronunciation": "きかい", "ipa": "kikai", "syllable_count": 3, "sentences": [{"text": "外国の人と話す機会があれば、日本語を使いたい。", "target_word": "機会", "complexity_tier": "T3", "furigana": "外国[がいこく]の人[ひと]と話[はな]す機会[きかい]があれば、日本語[にほんご]を使[つか]いたい。", "sentence_source": "generated"}, {"text": "こんな機会は二度とないから、やってみよう。", "target_word": "機会", "complexity_tier": "T3", "furigana": "こんな機会[きかい]は二度[にど]とないから、やってみよう。", "sentence_source": "generated"}, {"text": "彼に会う機会がなくて、お礼を言えないままだ。", "target_word": "機会", "complexity_tier": "T3", "furigana": "彼[かれ]に会[あ]う機会[きかい]がなくて、お礼[れい]を言[い]えないままだ。", "sentence_source": "generated"}, {"text": "友だちが旅行に来る機会に、いっしょに京都を回った。", "target_word": "機会", "complexity_tier": "T3", "furigana": "友[とも]だちが旅行[りょこう]に来[く]る機会[きかい]に、いっしょに京都[きょうと]を回[まわ]った。", "sentence_source": "generated"}, {"text": "先生は、みんなが発表する機会を作ってくれた。", "target_word": "機会", "complexity_tier": "T3", "furigana": "先生[せんせい]は、みんなが発表[はっぴょう]する機会[きかい]を作[つく]ってくれた。", "sentence_source": "generated"}, {"text": "せっかくの機会なので、その店で食事をしてみた。", "target_word": "機会", "complexity_tier": "T3", "furigana": "せっかくの機会[きかい]なので、その店[みせ]で食事[しょくじ]をしてみた。", "sentence_source": "generated"}, {"text": "仕事をやめる機会を、ずっと待っていた。", "target_word": "機会", "complexity_tier": "T3", "furigana": "仕事[しごと]をやめる機会[きかい]を、ずっと待[ま]っていた。", "sentence_source": "generated"}, {"text": "運動する機会が少ないので、毎朝歩くことにした。", "target_word": "機会", "complexity_tier": "T3", "furigana": "運動[うんどう]する機会[きかい]が少[すく]ないので、毎朝[まいあさ]歩[ある]くことにした。", "sentence_source": "generated"}, {"text": "留学する機会に恵まれて、世界が広がった。", "target_word": "機会", "complexity_tier": "T3", "furigana": "留学[りゅうがく]する機会[きかい]に恵[めぐ]まれて、世界[せかい]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "機会があれば、いつかこの町にまた来たい。", "target_word": "機会", "complexity_tier": "T3", "furigana": "機会[きかい]があれば、いつかこの町[まち]にまた来[き]たい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "機会", "label": "基本形"}, {"form": "機会が", "label": "主格（が）"}, {"form": "機会に", "label": "位格（に）"}, {"form": "機会を", "label": "目的格（を）"}], "register": "neutral", "sense_fingerprint": "何かをするのにちょうどよい、めぐってきた時", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8da5f40a-19ae-49fd-abf3-80abdb2562f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37510, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "機会", "is_correct": true, "explanation": "話すことができるよい時を表し、「話す機会があれば」という文に合う。"}, {"text": "性格", "is_correct": false, "explanation": "人の性質を表す語で、「話す」の対象として文に入らないので合わない。"}, {"text": "季節", "is_correct": false, "explanation": "一年の時期を表す語で、話す相手に会う場面には合わない。"}, {"text": "料金", "is_correct": false, "explanation": "支払う金額を表す語で、話す場面の意味には合わない。"}], "explanations": {"機会": "話すことができるよい時を表し、「話す機会があれば」という文に合う。", "性格": "人の性質を表す語で、「話す」の対象として文に入らないので合わない。", "季節": "一年の時期を表す語で、話す相手に会う場面には合わない。", "料金": "支払う金額を表す語で、話す場面の意味には合わない。"}, "sentence_index": 0, "correct_answer": "機会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場の機会が、朝から止まっている。", "explanation": "ここは〈機械〉の意味。機会は「よい時」の意味で、止まる物ではないので合わない。"}, {"text": "遅れた機会を先生に説明した。", "explanation": "ここは〈理由〉の意味。機会は「よい時」で、遅れた事情を説明する対象にはならないので合わない。"}, {"text": "映画の機会が印象に残った。", "explanation": "ここは〈場面〉の意味。機会は「よい時」で、映画の一場面は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37510, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "機会", "is_correct": true, "explanation": "仕事を辞めるのに適したよい時を表し、待っていたという文に合う。"}, {"text": "予算", "is_correct": false, "explanation": "使えるお金の額で、仕事を辞める時として待つ対象にはならない。"}, {"text": "音量", "is_correct": false, "explanation": "音の大きさを表す語で、仕事を辞める場面の意味には合わない。"}, {"text": "温度", "is_correct": false, "explanation": "温かさの度合いを表す語で、待つ対象として文に入らない。"}], "explanations": {"機会": "仕事を辞めるのに適したよい時を表し、待っていたという文に合う。", "予算": "使えるお金の額で、仕事を辞める時として待つ対象にはならない。", "音量": "音の大きさを表す語で、仕事を辞める場面の意味には合わない。", "温度": "温かさの度合いを表す語で、待つ対象として文に入らない。"}, "sentence_index": 6, "correct_answer": "機会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "機会の中身を確かめたら、お金が足りなかった。", "explanation": "ここは〈財布〉の意味。機会は「よい時」で、中身を入れる入れ物ではないので合わない。"}, {"text": "その機会は親切で、みんなに好かれている。", "explanation": "ここは〈人〉の意味。機会は時や状況で、親切な人柄を持つものではないので合わない。"}, {"text": "父は今日は機会がいい。", "explanation": "ここは〈機嫌〉の意味。機会はよい時で、人の気分の良さは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37510, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "長い準備のすえ、ついに大きな機会が得た。", "corrected_sentence": "長い準備のすえ、ついに大きな機会を得た。", "error_description": "「得る」は他動詞で目的語に「を」を取る。「機会が」の「が」は誤りで、「機会を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
