INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37511, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「来た」の主語を表し、機会が来たという意味になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す助詞だが、「来た」は主語を取るので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す助詞で、ここでは「来た」の主語にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を表す助詞で、主語の役割は果たさないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「来た」の主語を表し、機会が来たという意味になる。", "を": "目的語を表す助詞だが、「来た」は主語を取るので合わない。", "で": "場所や手段を表す助詞で、ここでは「来た」の主語にならない。", "の": "連体修飾を表す助詞で、主語の役割は果たさないので合わない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37511, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある行動をとったり、何かが起こったりするのに適した状況や時。", "primary_collocate": null, "pronunciation": "きかい", "ipa": "kikai", "syllable_count": 3, "sentences": [{"text": "試合に出る機会を、彼は逃さなかった。", "target_word": "機会", "complexity_tier": "T3", "furigana": "試合[しあい]に出[で]る機会[きかい]を、彼[かれ]は逃[のが]さなかった。", "sentence_source": "generated"}, {"text": "景気が上がった今は、店を広げる機会だ。", "target_word": "機会", "complexity_tier": "T3", "furigana": "景気[けいき]が上[あ]がった今[いま]は、店[みせ]を広[ひろ]げる機会[きかい]だ。", "sentence_source": "generated"}, {"text": "失敗は、新しいことを学ぶ機会にもなる。", "target_word": "機会", "complexity_tier": "T3", "furigana": "失敗[しっぱい]は、新[あたら]しいことを学[まな]ぶ機会[きかい]にもなる。", "sentence_source": "generated"}, {"text": "その会議は、考えを伝える大切な機会になった。", "target_word": "機会", "complexity_tier": "T3", "furigana": "その会議[かいぎ]は、考[かんが]えを伝[つた]える大切[たいせつ]な機会[きかい]になった。", "sentence_source": "generated"}, {"text": "面接は、自分の経験を話す機会だ。", "target_word": "機会", "complexity_tier": "T3", "furigana": "面接[めんせつ]は、自分[じぶん]の経験[けいけん]を話[はな]す機会[きかい]だ。", "sentence_source": "generated"}, {"text": "雨が続いて、外で遊ぶ機会が少なかった。", "target_word": "機会", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]いて、外[そと]で遊[あそ]ぶ機会[きかい]が少[すく]なかった。", "sentence_source": "generated"}, {"text": "引っ越しは、古い物を整理する良い機会だ。", "target_word": "機会", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しは、古[ふる]い物[もの]を整理[せいり]する良[よ]い機会[きかい]だ。", "sentence_source": "generated"}, {"text": "社長に意見を伝える機会が、やっと来た。", "target_word": "機会", "complexity_tier": "T3", "furigana": "社長[しゃちょう]に意見[いけん]を伝[つた]える機会[きかい]が、やっと来[き]た。", "sentence_source": "generated"}, {"text": "同じ機会は二度と来ないので、よく考えて決めた。", "target_word": "機会", "complexity_tier": "T3", "furigana": "同[おな]じ機会[きかい]は二度[にど]と来[こ]ないので、よく考[かんが]えて決[き]めた。", "sentence_source": "generated"}, {"text": "この祭りは、町の人が集まる貴重な機会だ。", "target_word": "機会", "complexity_tier": "T3", "furigana": "この祭[まつ]りは、町[まち]の人[ひと]が集[あつ]まる貴重[きちょう]な機会[きかい]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "機会", "label": "基本形"}, {"form": "機会が", "label": "主格（が）"}, {"form": "機会に", "label": "位格（に）"}, {"form": "機会だ", "label": "断定形"}], "register": "neutral", "sense_fingerprint": "ある行動をとるのに適した状況や時、何かが起こる場面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8da5f40a-19ae-49fd-abf3-80abdb2562f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37511, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "機会", "is_correct": true, "explanation": "試合に出るのにちょうどよい時を表し、逃さなかったという文に合う。"}, {"text": "費用", "is_correct": false, "explanation": "お金の額を表す語で、試合に出る対象として逃すとは言わないので合わない。"}, {"text": "天候", "is_correct": false, "explanation": "その日の空模様を表す語で、逃すという動作の対象にはならない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表す語で、試合に出る場面の対象としては合わない。"}], "explanations": {"機会": "試合に出るのにちょうどよい時を表し、逃さなかったという文に合う。", "費用": "お金の額を表す語で、試合に出る対象として逃すとは言わないので合わない。", "天候": "その日の空模様を表す語で、逃すという動作の対象にはならない。", "体重": "体の重さを表す語で、試合に出る場面の対象としては合わない。"}, "sentence_index": 0, "correct_answer": "機会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作業の機会を一つずつ確かめた。", "explanation": "ここは〈手順〉の意味。機会は「よい時」で、作業の順序を確かめる対象にはならないので合わない。"}, {"text": "彼は話す機会が高い。", "explanation": "ここは〈能力〉の意味。機会は時や状況で、力の高さは表さないので合わない。"}, {"text": "この店には、いろいろな機会のパンがある。", "explanation": "ここは〈種類〉の意味。機会は「よい時」で、パンの分類は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37511, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "機会", "is_correct": true, "explanation": "整理するのにちょうどよい時を表し、「良い機会だ」という文に合う。"}, {"text": "身長", "is_correct": false, "explanation": "体の高さを表す語で、「整理する良い」の対象にはならないので合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温かさを表す語で、物を整理する場面には合わない。"}, {"text": "香り", "is_correct": false, "explanation": "物から漂う匂いを表す語で、整理する対象として文に入らない。"}], "explanations": {"機会": "整理するのにちょうどよい時を表し、「良い機会だ」という文に合う。", "身長": "体の高さを表す語で、「整理する良い」の対象にはならないので合わない。", "体温": "体の温かさを表す語で、物を整理する場面には合わない。", "香り": "物から漂う匂いを表す語で、整理する対象として文に入らない。"}, "sentence_index": 6, "correct_answer": "機会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "料理に使う機会を、よく洗っておく。", "explanation": "ここは〈道具〉の意味。機会は「よい時」で、洗う物ではないので合わない。"}, {"text": "この店では、みんなが機会を分担している。", "explanation": "ここは〈役割〉の意味。機会は時や状況で、仕事を分ける対象にはならないので合わない。"}, {"text": "彼は味の機会が鋭い。", "explanation": "ここは〈感覚〉の意味。機会は「よい時」で、味を感じ取る力は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37511, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大きな機会を恵まれ、夢がかなった。", "corrected_sentence": "大きな機会に恵まれ、夢がかなった。", "error_description": "「恵まれる」は「～に恵まれる」の形で助詞「に」を取る。「機会を」の「を」は誤りで、「機会に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37511, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この旅で、貴重な機会を出会った。", "corrected_sentence": "この旅で、貴重な機会に出会った。", "error_description": "「出会う」は助詞「に」（または「と」）を取る。「機会を」の「を」は誤りで、「機会に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37512, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「敗北を認める」の「を」は、認める対象を示す目的語で、文の意味に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「認める」の目的語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "相手や方向を示すが、「認める」の目的語を示す形には使わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「認める」の対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "「敗北を認める」の「を」は、認める対象を示す目的語で、文の意味に合う。", "が": "主語を示すが、「認める」の目的語にはならない。", "に": "相手や方向を示すが、「認める」の目的語を示す形には使わない。", "で": "場所や手段を示すが、「認める」の対象には合わない。"}, "error_tags": {"が": "主語を示すが、「認める」の目的語にはならない", "に": "相手や方向を示すが、「認める」の目的語を示す形には使わない", "で": "場所や手段を示すが、「認める」の対象には合わない"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勝利", "is_correct": true, "explanation": "「敗北」の対義語で、戦いや競争に勝つこと。"}, {"text": "出場", "is_correct": false, "explanation": "試合に参加することで、「敗北」の対義語ではない。"}, {"text": "練習", "is_correct": false, "explanation": "技術を身につけるための反復で、「敗北」の対義語ではない。"}, {"text": "応援", "is_correct": false, "explanation": "味方を力づけることで、「敗北」の対義語ではない。"}], "correct_answer": "勝利", "explanations": {"勝利": "「敗北」の対義語で、戦いや競争に勝つこと。", "出場": "試合に参加することで、「敗北」の対義語ではない。", "練習": "技術を身につけるための反復で、「敗北」の対義語ではない。", "応援": "味方を力づけることで、「敗北」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37512, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「戦争に敗北して」の「に」は、負けた相手・場面を示し、「敗北する」の形に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「戦争を敗北する」は不自然で、「戦争に敗北する」が正しい。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、動詞の前に続けると文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、戦争を受ける形には合わない。"}], "correct_answer": "に", "explanations": {"に": "「戦争に敗北して」の「に」は、負けた相手・場面を示し、「敗北する」の形に合う。", "を": "目的語を示すが、「戦争を敗北する」は不自然で、「戦争に敗北する」が正しい。", "の": "連体修飾の助詞で、動詞の前に続けると文が成り立たない。", "へ": "方向を示す助詞で、戦争を受ける形には合わない。"}, "error_tags": {"を": "目的語を示すが、「戦争を敗北する」は不自然で、「戦争に敗北する」が正しい", "の": "連体修飾の助詞で、動詞の前に続けると文が成り立たない", "へ": "方向を示す助詞で、戦争を受ける形には合わない"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勝利", "is_correct": true, "explanation": "「敗北」の対義語で、戦いや競争に勝つこと。"}, {"text": "観戦", "is_correct": false, "explanation": "試合を見ることで、「敗北」の対義語ではない。"}, {"text": "合宿", "is_correct": false, "explanation": "集団で泊まり込んで練習することで、「敗北」の対義語ではない。"}, {"text": "欠場", "is_correct": false, "explanation": "試合に出ないことで、「敗北」の対義語ではない。"}], "correct_answer": "勝利", "explanations": {"勝利": "「敗北」の対義語で、戦いや競争に勝つこと。", "観戦": "試合を見ることで、「敗北」の対義語ではない。", "合宿": "集団で泊まり込んで練習することで、「敗北」の対義語ではない。", "欠場": "試合に出ないことで、「敗北」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37512, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "戦いや競争で、負けること。", "primary_collocate": null, "pronunciation": "はいぼく", "ipa": "haibokɯ", "syllable_count": 4, "sentences": [{"text": "彼のチームは決勝で敗北した。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "彼[かれ]のチームは決勝[けっしょう]で敗北[はいぼく]した。", "sentence_source": "generated"}, {"text": "敗北を認めるのは、とてもつらいことだ。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "敗北[はいぼく]を認[みと]めるのは、とてもつらいことだ。", "sentence_source": "generated"}, {"text": "何度も敗北を経験して、彼は強くなった。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "何度[なんど]も敗北[はいぼく]を経験[けいけん]して、彼[かれ]は強[つよ]くなった。", "sentence_source": "generated"}, {"text": "試合に敗北したあと、選手たちは泣いていた。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "試合[しあい]に敗北[はいぼく]したあと、選手[せんしゅ]たちは泣[な]いていた。", "sentence_source": "generated"}, {"text": "敗北の原因を、みんなで話し合った。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "敗北[はいぼく]の原因[げんいん]を、みんなで話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "我が軍は戦いに敗北し、城を失った。", "target_word": "敗北", "complexity_tier": "T4", "furigana": "我[わ]が軍[ぐん]は戦[たたか]いに敗北[はいぼく]し、城[しろ]を失[うしな]った。", "sentence_source": "generated"}, {"text": "一度の敗北であきらめてはいけない。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "一度[いちど]の敗北[はいぼく]であきらめてはいけない。", "sentence_source": "generated"}, {"text": "王は戦争に敗北して、国を去った。", "target_word": "敗北", "complexity_tier": "T4", "furigana": "王[おう]は戦争[せんそう]に敗北[はいぼく]して、国[くに]を去[さ]った。", "sentence_source": "generated"}, {"text": "開幕戦での敗北が、チームの自信を奪った。", "target_word": "敗北", "complexity_tier": "T4", "furigana": "開幕戦[かいまくせん]での敗北[はいぼく]が、チームの自信[じしん]を奪[うば]った。", "sentence_source": "generated"}, {"text": "敗北しても、彼は笑顔で相手と握手した。", "target_word": "敗北", "complexity_tier": "T4", "furigana": "敗北[はいぼく]しても、彼[かれ]は笑顔[えがお]で相手[あいて]と握手[あくしゅ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "敗北", "label": "基本形"}, {"form": "敗北する", "label": "サ変動詞・終止形"}, {"form": "敗北した", "label": "過去形"}, {"form": "敗北して", "label": "て形"}], "register": "formal", "sense_fingerprint": "戦いや競争に負けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6ee224-92d2-4127-abed-56d8891d40e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37512, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "敗北", "is_correct": true, "explanation": "「敗北」は決勝で負けたことを表し、文の意味に合う。"}, {"text": "献上", "is_correct": false, "explanation": "「献上」は目上の人に物を差し出すことで、試合の結果には合わない。"}, {"text": "点火", "is_correct": false, "explanation": "「点火」は火をつけることで、決勝の結果には使えない。"}, {"text": "乾燥", "is_correct": false, "explanation": "「乾燥」は水分がなくなることで、試合の話には意味が通らない。"}], "explanations": {"敗北": "「敗北」は決勝で負けたことを表し、文の意味に合う。", "献上": "「献上」は目上の人に物を差し出すことで、試合の結果には合わない。", "点火": "「点火」は火をつけることで、決勝の結果には使えない。", "乾燥": "「乾燥」は水分がなくなることで、試合の話には意味が通らない。"}, "sentence_index": 0, "correct_answer": "敗北"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "料理で塩を入れすぎる敗北をした。", "explanation": "ここは〈失敗〉の意味。敗北は戦いや競争で負けることで、料理のミスには使わない。"}, {"text": "前半の最後に敗北し、チームは一点を取られた。", "explanation": "ここは〈失点〉の意味。敗北は勝負に負けることで、点を取られる場面には使わない。"}, {"text": "エンジンの故障で飛行機が敗北し、急に落ちていった。", "explanation": "ここは〈失速〉の意味。敗北は競争で負けることで、飛行機の速さが落ちる場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37512, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "敗北", "is_correct": true, "explanation": "「一度の敗北であきらめない」は自然で、文の意味に合う。"}, {"text": "採掘", "is_correct": false, "explanation": "「採掘」は地下から資源を掘ることで、あきらめる話には合わない。"}, {"text": "解凍", "is_correct": false, "explanation": "「解凍」は凍ったものを溶かすことで、文の意味に合わない。"}, {"text": "浸水", "is_correct": false, "explanation": "「浸水」は水が入り込むことで、あきらめる話には使えない。"}], "explanations": {"敗北": "「一度の敗北であきらめない」は自然で、文の意味に合う。", "採掘": "「採掘」は地下から資源を掘ることで、あきらめる話には合わない。", "解凍": "「解凍」は凍ったものを溶かすことで、文の意味に合わない。", "浸水": "「浸水」は水が入り込むことで、あきらめる話には使えない。"}, "sentence_index": 6, "correct_answer": "敗北"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "傷口が敗北して、ばい菌が広がった。", "explanation": "ここは〈化膿〉の意味。敗北は勝負に負けることで、傷が膿む場合には使わない。"}, {"text": "ロスタイムに敗北して、試合をひっくり返した。", "explanation": "ここは〈逆転〉の意味。敗北は負けることで、負けの状況をひっくり返す場合には使わない。"}, {"text": "雨でぬれた坂道で敗北して、車はゆっくり止まった。", "explanation": "ここは〈減速〉の意味。敗北は勝負に負けることで、速さを落とす場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37512, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は決勝で相手を敗北した。", "corrected_sentence": "彼女は決勝で相手に敗北した。", "error_description": "「敗北」は「〜に敗北する」の形で使うので、助詞は「に」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37512, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その国は長い戦争の末に敗北しだ。", "corrected_sentence": "その国は長い戦争の末に敗北した。", "error_description": "過去の語尾は「た」が正しい。「だ」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37513, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「将棋の大会で敗北した」の「で」は、負けた場面を示し、文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「敗北」は目的語を取らず、場面を示す「で」が必要。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、大会が負けるという文にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、大会の場面を表す文脈には合わない。"}], "correct_answer": "で", "explanations": {"で": "「将棋の大会で敗北した」の「で」は、負けた場面を示し、文の意味に合う。", "を": "目的語を示すが、「敗北」は目的語を取らず、場面を示す「で」が必要。", "が": "主語を示すが、大会が負けるという文にはならない。", "へ": "方向を示す助詞で、大会の場面を表す文脈には合わない。"}, "error_tags": {"を": "目的語を示すが、「敗北」は目的語を取らず、場面を示す「で」が必要", "が": "主語を示すが、大会が負けるという文にはならない", "へ": "方向を示す助詞で、大会の場面を表す文脈には合わない"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勝利", "is_correct": true, "explanation": "「敗北」の対義語で、戦いや競争に勝つこと。"}, {"text": "解説", "is_correct": false, "explanation": "わかりやすく説明することで、「敗北」の対義語ではない。"}, {"text": "採用", "is_correct": false, "explanation": "選んで取り入れることで、「敗北」の対義語ではない。"}, {"text": "計画", "is_correct": false, "explanation": "前もって決めておくことで、「敗北」の対義語ではない。"}], "correct_answer": "勝利", "explanations": {"勝利": "「敗北」の対義語で、戦いや競争に勝つこと。", "解説": "わかりやすく説明することで、「敗北」の対義語ではない。", "採用": "選んで取り入れることで、「敗北」の対義語ではない。", "計画": "前もって決めておくことで、「敗北」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
