INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37513, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "試合や争いなどで、相手に負けること。", "primary_collocate": null, "pronunciation": "はいぼく", "ipa": "haibokɯ", "syllable_count": 4, "sentences": [{"text": "選挙で敗北した候補者は、短い挨拶をした。", "target_word": "敗北", "complexity_tier": "T4", "furigana": "選挙[せんきょ]で敗北[はいぼく]した候補者[こうほしゃ]は、短[みじか]い挨拶[あいさつ]をした。", "sentence_source": "generated"}, {"text": "彼は将棋の大会で敗北した。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "彼[かれ]は将棋[しょうぎ]の大会[たいかい]で敗北[はいぼく]した。", "sentence_source": "generated"}, {"text": "彼女は初めて敗北を味わった。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は初[はじ]めて敗北[はいぼく]を味[あじ]わった。", "sentence_source": "generated"}, {"text": "敗北が続いて、監督は選手を入れ替えた。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "敗北[はいぼく]が続[つづ]いて、監督[かんとく]は選手[せんしゅ]を入[い]れ替[か]えた。", "sentence_source": "generated"}, {"text": "訴えは認められず、会社は裁判で敗北した。", "target_word": "敗北", "complexity_tier": "T4", "furigana": "訴[うった]えは認[みと]められず、会社[かいしゃ]は裁判[さいばん]で敗北[はいぼく]した。", "sentence_source": "generated"}, {"text": "相手の強さを知り、敗北を覚悟した。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "相手[あいて]の強[つよ]さを知[し]り、敗北[はいぼく]を覚悟[かくご]した。", "sentence_source": "generated"}, {"text": "敗北の悔しさをバネにして、毎日練習した。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "敗北[はいぼく]の悔[くや]しさをバネにして、毎日[まいにち]練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "最後の一球で、私たちは敗北した。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "最後[さいご]の一球[いっきゅう]で、私[わたし]たちは敗北[はいぼく]した。", "sentence_source": "generated"}, {"text": "大会での敗北は、いい勉強になった。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "大会[たいかい]での敗北[はいぼく]は、いい勉強[べんきょう]になった。", "sentence_source": "generated"}, {"text": "この敗北を、次の成功につなげたい。", "target_word": "敗北", "complexity_tier": "T3", "furigana": "この敗北[はいぼく]を、次[つぎ]の成功[せいこう]につなげたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "敗北", "label": "基本形"}, {"form": "敗北する", "label": "サ変動詞・終止形"}, {"form": "敗北した", "label": "過去形"}, {"form": "敗北を", "label": "目的語形"}], "register": "formal", "sense_fingerprint": "試合や争いで相手に負けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6ee224-92d2-4127-abed-56d8891d40e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37513, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "敗北", "is_correct": true, "explanation": "「選挙で敗北した候補者」は自然で、文の意味に合う。"}, {"text": "焙煎", "is_correct": false, "explanation": "「焙煎」は豆などを炒ることで、選挙には使えない。"}, {"text": "漂白", "is_correct": false, "explanation": "「漂白」は色を抜くことで、選挙の話には合わない。"}, {"text": "解凍", "is_correct": false, "explanation": "「解凍」は凍ったものを溶かすことで、選挙には意味が通らない。"}], "explanations": {"敗北": "「選挙で敗北した候補者」は自然で、文の意味に合う。", "焙煎": "「焙煎」は豆などを炒ることで、選挙には使えない。", "漂白": "「漂白」は色を抜くことで、選挙の話には合わない。", "解凍": "「解凍」は凍ったものを溶かすことで、選挙には意味が通らない。"}, "sentence_index": 0, "correct_answer": "敗北"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このクラスの平均点は、前回より大きく敗北した。", "explanation": "ここは〈悪化〉の意味。敗北は勝負に負けることで、点数が下がる場合には使わない。"}, {"text": "前半の最後に敗北し、チームは一点を取られた。", "explanation": "ここは〈失点〉の意味。敗北は勝負に負けることで、点を取られる場面には使わない。"}, {"text": "雨で路面がぬれ、バスは交差点の手前で敗北した。", "explanation": "ここは〈減速〉の意味。敗北は勝負に負けることで、速さを落とす場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37513, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "敗北", "is_correct": true, "explanation": "「敗北の悔しさ」は自然で、文の意味に合う。"}, {"text": "採掘", "is_correct": false, "explanation": "「採掘」は地下から資源を掘ることで、悔しさの話には合わない。"}, {"text": "浸水", "is_correct": false, "explanation": "「浸水」は水が入り込むことで、悔しさの話には使えない。"}, {"text": "点火", "is_correct": false, "explanation": "「点火」は火をつけることで、悔しさとは結びつかない。"}], "explanations": {"敗北": "「敗北の悔しさ」は自然で、文の意味に合う。", "採掘": "「採掘」は地下から資源を掘ることで、悔しさの話には合わない。", "浸水": "「浸水」は水が入り込むことで、悔しさの話には使えない。", "点火": "「点火」は火をつけることで、悔しさとは結びつかない。"}, "sentence_index": 6, "correct_answer": "敗北"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テストで計算ミスの敗北をした。", "explanation": "ここは〈失敗〉の意味。敗北は競争で負けることで、ミスには使わない。"}, {"text": "古いエンジンのせいで、車の速さが敗北した。", "explanation": "ここは〈失速〉の意味。敗北は勝負に負けることで、速さが落ちる場合には使わない。"}, {"text": "最後の数分で敗北して、試合をひっくり返した。", "explanation": "ここは〈逆転〉の意味。敗北は負けることで、負けの状況をひっくり返す場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
