INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37514, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "て", "options": [{"text": "て", "is_correct": true, "explanation": "「結束して」と、動詞「する」の連用形に続く形になる。"}, {"text": "が", "is_correct": false, "explanation": "「結束しがいます」では文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「結束しをいます」では文が成り立たない。"}, {"text": "は", "is_correct": false, "explanation": "「結束しはいます」では文が成り立たない。"}], "correct_answer": "て", "explanations": {"て": "「結束して」と、動詞「する」の連用形に続く形になる。", "が": "「結束しがいます」では文が成り立たない。", "を": "「結束しをいます」では文が成り立たない。", "は": "「結束しはいます」では文が成り立たない。"}, "error_tags": {"が": "ungrammatical_after_verb_stem", "を": "ungrammatical_after_verb_stem", "は": "ungrammatical_after_verb_stem"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不和", "is_correct": true, "explanation": "仲良くまとまる「結束」に対し、仲が悪い状態を表す反対の意味。"}, {"text": "団結", "is_correct": false, "explanation": "結束と同じ意味の類義語で、反対ではない。"}, {"text": "友情", "is_correct": false, "explanation": "仲の良さを表し、結束の反対ではない。"}, {"text": "練習", "is_correct": false, "explanation": "くり返し行うことで、結束とは関係のない別の語。"}], "correct_answer": "不和", "explanations": {"不和": "仲良くまとまる「結束」に対し、仲が悪い状態を表す反対の意味。", "団結": "結束と同じ意味の類義語で、反対ではない。", "友情": "仲の良さを表し、結束の反対ではない。", "練習": "くり返し行うことで、結束とは関係のない別の語。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
