INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37514, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が心を一つにして、仲良くまとまること。", "primary_collocate": null, "pronunciation": "けっそく", "ipa": "kesːokɯ", "syllable_count": 4, "sentences": [{"text": "みんなの結束が強い。", "target_word": "結束", "complexity_tier": "T1", "furigana": "みんなの結束[けっそく]が強[つよ]い。", "sentence_source": "generated"}, {"text": "私たちのクラスは結束しています。", "target_word": "結束", "complexity_tier": "T2", "furigana": "私[わたし]たちのクラスは結束[けっそく]しています。", "sentence_source": "generated"}, {"text": "結束は大切だと思います。", "target_word": "結束", "complexity_tier": "T2", "furigana": "結束[けっそく]は大切[たいせつ]だと思[おも]います。", "sentence_source": "generated"}, {"text": "結束するために、みんなで歌を歌った。", "target_word": "結束", "complexity_tier": "T3", "furigana": "結束[けっそく]するために、みんなで歌[うた]を歌[うた]った。", "sentence_source": "generated"}, {"text": "全員で結束して、最後まで走りきった。", "target_word": "結束", "complexity_tier": "T3", "furigana": "全員[ぜんいん]で結束[けっそく]して、最後[さいご]まで走[はし]りきった。", "sentence_source": "generated"}, {"text": "この家族は結束が固いことで有名だ。", "target_word": "結束", "complexity_tier": "T3", "furigana": "この家族[かぞく]は結束[けっそく]が固[かた]いことで有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "運動会で、クラスの結束が深まった。", "target_word": "結束", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]で、クラスの結束[けっそく]が深[ふか]まった。", "sentence_source": "generated"}, {"text": "結束していなければ、優勝はできなかっただろう。", "target_word": "結束", "complexity_tier": "T4", "furigana": "結束[けっそく]していなければ、優勝[ゆうしょう]はできなかっただろう。", "sentence_source": "generated"}, {"text": "先生に結束の大切さを教えられた。", "target_word": "結束", "complexity_tier": "T4", "furigana": "先生[せんせい]に結束[けっそく]の大切[たいせつ]さを教[おし]えられた。", "sentence_source": "generated"}, {"text": "結束がなければ、チームは勝てない。", "target_word": "結束", "complexity_tier": "T4", "furigana": "結束[けっそく]がなければ、チームは勝[か]てない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結束する", "label": "活用"}, {"form": "結束した", "label": "活用"}, {"form": "結束力", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 心を一つに仲良くまとまること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a39150a-21a7-47ec-ad3d-64f57f18784e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37514, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "結束", "is_correct": true, "explanation": "見出し語「けっそく」そのもの。"}, {"text": "結核", "is_correct": false, "explanation": "「けっかく」で、「そ」が「か」に変わる別の語。"}, {"text": "傑作", "is_correct": false, "explanation": "「けっさく」で、「そ」が「さ」に変わる別の語。"}, {"text": "拙速", "is_correct": false, "explanation": "「せっそく」で、「け」が「せ」に変わる別の語。"}], "explanations": {"結束": "見出し語「けっそく」そのもの。", "結核": "「けっかく」で、「そ」が「か」に変わる別の語。", "傑作": "「けっさく」で、「そ」が「さ」に変わる別の語。", "拙速": "「せっそく」で、「け」が「せ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "結束"}, "level_3": {"options": [{"text": "結束", "is_correct": true, "explanation": "みんなの心がまとまっている強さを表し、意味が合う。"}, {"text": "身長", "is_correct": false, "explanation": "形は合うが意味が合わない。身長は「強い」とは言わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが意味が合わない。「みんなの値段が強い」とは言えない。"}, {"text": "天井", "is_correct": false, "explanation": "形は合うが意味が合わない。天井は「強い」とは言わない。"}], "explanations": {"結束": "みんなの心がまとまっている強さを表し、意味が合う。", "身長": "形は合うが意味が合わない。身長は「強い」とは言わない。", "値段": "形は合うが意味が合わない。「みんなの値段が強い」とは言えない。", "天井": "形は合うが意味が合わない。天井は「強い」とは言わない。"}, "sentence_index": 0, "correct_answer": "結束"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "結束をかぶって、日差しをよけた。", "explanation": "「結束」を帽子のようにかぶる物として使っており、心のまとまりの意味に合わない。"}, {"text": "この店では、結束が一つ百円で売られている。", "explanation": "「結束」を商品のように数えて売っており、意味が合わない。"}, {"text": "朝から結束が痛くて、病院に行った。", "explanation": "「結束」を体の部位のように使っており、抽象的なまとまりの意味に反する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37514, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "結束", "is_correct": true, "explanation": "見出し語「けっそく」そのもの。"}, {"text": "鉄則", "is_correct": false, "explanation": "「てっそく」で、「け」が「て」に変わる別の語。"}, {"text": "血相", "is_correct": false, "explanation": "「けっそう」で、「く」が「う」に変わる別の語。"}, {"text": "潔白", "is_correct": false, "explanation": "「けっぱく」で、「そ」が「ぱ」に変わる別の語。"}], "explanations": {"結束": "見出し語「けっそく」そのもの。", "鉄則": "「てっそく」で、「け」が「て」に変わる別の語。", "血相": "「けっそう」で、「く」が「う」に変わる別の語。", "潔白": "「けっぱく」で、「そ」が「ぱ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "結束"}, "level_3": {"options": [{"text": "結束", "is_correct": true, "explanation": "運動会でクラスの心のまとまりが深まったという意味に合う。"}, {"text": "身長", "is_correct": false, "explanation": "形は合うが意味が合わない。身長は「深まる」ものではない。"}, {"text": "屋根", "is_correct": false, "explanation": "形は合うが意味が合わない。屋根が深まるとは言えない。"}, {"text": "速度", "is_correct": false, "explanation": "形は合うが意味が合わない。速度は「深まる」とは言わない。"}], "explanations": {"結束": "運動会でクラスの心のまとまりが深まったという意味に合う。", "身長": "形は合うが意味が合わない。身長は「深まる」ものではない。", "屋根": "形は合うが意味が合わない。屋根が深まるとは言えない。", "速度": "形は合うが意味が合わない。速度は「深まる」とは言わない。"}, "sentence_index": 6, "correct_answer": "結束"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "結束は川の水がきれいで、魚がたくさんいる。", "explanation": "「結束」を川のある場所のように使っており、心のまとまりの意味に合わない。"}, {"text": "昨日、結束を拾ったので、交番に届けた。", "explanation": "「結束」を財布のような落とし物として使っており、意味が合わない。"}, {"text": "夜になると、結束が空にたくさん光っている。", "explanation": "「結束」を星のように空で光る物として使っており、抽象的な意味に反する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validatio