INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37515, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「社会的結束の醸成」と、醸成の対象を表す。"}, {"text": "を", "is_correct": false, "explanation": "「結束を醸成を」と「を」が重なり文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「結束へ醸成」では方向の意味が合わず文にならない。"}, {"text": "しか", "is_correct": false, "explanation": "「しか」は否定を伴うので、この文では使えない。"}], "correct_answer": "の", "explanations": {"の": "「社会的結束の醸成」と、醸成の対象を表す。", "を": "「結束を醸成を」と「を」が重なり文が成り立たない。", "へ": "「結束へ醸成」では方向の意味が合わず文にならない。", "しか": "「しか」は否定を伴うので、この文では使えない。"}, "error_tags": {"を": "object_marker_misuse", "へ": "direction", "しか": "requires_negation"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分裂", "is_correct": true, "explanation": "まとまる「結束」に対し、分かれてばらばらになる反対の意味。"}, {"text": "団結", "is_correct": false, "explanation": "結束と同じ意味の類義語で、反対ではない。"}, {"text": "協力", "is_correct": false, "explanation": "力を合わせることで、結束の反対ではない。"}, {"text": "努力", "is_correct": false, "explanation": "がんばることで、結束とは関係のない別の語。"}], "correct_answer": "分裂", "explanations": {"分裂": "まとまる「結束」に対し、分かれてばらばらになる反対の意味。", "団結": "結束と同じ意味の類義語で、反対ではない。", "協力": "力を合わせることで、結束の反対ではない。", "努力": "がんばることで、結束とは関係のない別の語。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37515, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「結束が乱れる」と、乱れるものを示す主語の助詞。"}, {"text": "を", "is_correct": false, "explanation": "「乱れる」は自動詞なので「結束を乱れる」とは言えない。"}, {"text": "へ", "is_correct": false, "explanation": "「結束へ乱れる」では方向の意味が合わず文にならない。"}, {"text": "しか", "is_correct": false, "explanation": "「しか」は否定を伴うので「乱れると」とは続かない。"}], "correct_answer": "が", "explanations": {"が": "「結束が乱れる」と、乱れるものを示す主語の助詞。", "を": "「乱れる」は自動詞なので「結束を乱れる」とは言えない。", "へ": "「結束へ乱れる」では方向の意味が合わず文にならない。", "しか": "「しか」は否定を伴うので「乱れると」とは続かない。"}, "error_tags": {"を": "intransitive_verb", "へ": "direction", "しか": "requires_negation"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分裂", "is_correct": true, "explanation": "まとまる「結束」に対し、分かれてばらばらになる反対の意味。"}, {"text": "連帯", "is_correct": false, "explanation": "結びつくことで、結束に近い意味。反対ではない。"}, {"text": "勝利", "is_correct": false, "explanation": "勝つことで、結束とは関係のない別の語。"}, {"text": "準備", "is_correct": false, "explanation": "前もって整えることで、結束の反対ではない。"}], "correct_answer": "分裂", "explanations": {"分裂": "まとまる「結束」に対し、分かれてばらばらになる反対の意味。", "連帯": "結びつくことで、結束に近い意味。反対ではない。", "勝利": "勝つことで、結束とは関係のない別の語。", "準備": "前もって整えることで、結束の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37515, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人々が共通の目的や感情によって強く結びつき、まとまること。", "primary_collocate": null, "pronunciation": "けっそく", "ipa": "kesːokɯ", "syllable_count": 4, "sentences": [{"text": "この取り組みは、単なる植物の栽培を超え、環境再生と社会的結束の醸成を同時に企図する点に特徴がある。", "target_word": "結束", "complexity_tier": "T6", "furigana": "この取[と]り組[く]みは、単[たん]なる植物[しょくぶつ]の栽培[さいばい]を超[こ]え、環境[かんきょう]再生[さいせい]と社会的[しゃかいてき]結束[けっそく]の醸成[じょうせい]を同時[どうじ]に企図[きと]する点[てん]に特徴[とくちょう]がある。", "sentence_source": "mined"}, {"text": "結束が強い。", "target_word": "結束", "complexity_tier": "T1", "furigana": "結束[けっそく]が強[つよ]い。", "sentence_source": "generated"}, {"text": "チームの結束は固いです。", "target_word": "結束", "complexity_tier": "T2", "furigana": "チームの結束[けっそく]は固[かた]いです。", "sentence_source": "generated"}, {"text": "みんなで結束を高めます。", "target_word": "結束", "complexity_tier": "T2", "furigana": "みんなで結束[けっそく]を高[たか]めます。", "sentence_source": "generated"}, {"text": "結束して、問題に立ち向かった。", "target_word": "結束", "complexity_tier": "T3", "furigana": "結束[けっそく]して、問題[もんだい]に立[た]ち向[む]かった。", "sentence_source": "generated"}, {"text": "祭りは地域の結束を強める役割を果たしている。", "target_word": "結束", "complexity_tier": "T3", "furigana": "祭[まつ]りは地域[ちいき]の結束[けっそく]を強[つよ]める役割[やくわり]を果[は]たしている。", "sentence_source": "generated"}, {"text": "負けたあと、チームの結束が強まった。", "target_word": "結束", "complexity_tier": "T3", "furigana": "負[ま]けたあと、チームの結束[けっそく]が強[つよ]まった。", "sentence_source": "generated"}, {"text": "結束が乱れると、組織はうまく動かなくなる。", "target_word": "結束", "complexity_tier": "T4", "furigana": "結束[けっそく]が乱[みだ]れると、組織[そしき]はうまく動[うご]かなくなる。", "sentence_source": "generated"}, {"text": "全員の結束があれば、どんな困難も乗り越えられるだろう。", "target_word": "結束", "complexity_tier": "T4", "furigana": "全員[ぜんいん]の結束[けっそく]があれば、どんな困難[こんなん]も乗[の]り越[こ]えられるだろう。", "sentence_source": "generated"}, {"text": "住民の結束によって、町は災害から守られた。", "target_word": "結束", "complexity_tier": "T4", "furigana": "住民[じゅうみん]の結束[けっそく]によって、町[まち]は災害[さいがい]から守[まも]られた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結束する", "label": "活用"}, {"form": "結束した", "label": "活用"}, {"form": "結束力", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 共通の目的で強くまとまること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a39150a-21a7-47ec-ad3d-64f57f18784e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37515, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "結束", "is_correct": true, "explanation": "見出し語「けっそく」そのもの。"}, {"text": "結核", "is_correct": false, "explanation": "「けっかく」で、「そ」が「か」に変わる別の語。"}, {"text": "傑作", "is_correct": false, "explanation": "「けっさく」で、「そ」が「さ」に変わる別の語。"}, {"text": "拙速", "is_correct": false, "explanation": "「せっそく」で、「け」が「せ」に変わる別の語。"}], "explanations": {"結束": "見出し語「けっそく」そのもの。", "結核": "「けっかく」で、「そ」が「か」に変わる別の語。", "傑作": "「けっさく」で、「そ」が「さ」に変わる別の語。", "拙速": "「せっそく」で、「け」が「せ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "結束"}, "level_3": {"options": [{"text": "結束", "is_correct": true, "explanation": "「社会的結束」は人々のまとまりを表し、醸成の対象として合う。"}, {"text": "速度", "is_correct": false, "explanation": "形は合うが意味が合わない。「社会的速度の醸成」とは言わない。"}, {"text": "材料", "is_correct": false, "explanation": "形は合うが意味が合わない。社会的な材料を醸成するとは言えない。"}, {"text": "体積", "is_correct": false, "explanation": "形は合うが意味が合わない。体積は醸成するものではない。"}], "explanations": {"結束": "「社会的結束」は人々のまとまりを表し、醸成の対象として合う。", "速度": "形は合うが意味が合わない。「社会的速度の醸成」とは言わない。", "材料": "形は合うが意味が合わない。社会的な材料を醸成するとは言えない。", "体積": "形は合うが意味が合わない。体積は醸成するものではない。"}, "sentence_index": 0, "correct_answer": "結束"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "結束を使って、友達に手紙を書きました。", "explanation": "「結束」を筆記用具のような道具として使っており、人のまとまりの意味に合わない。"}, {"text": "毎朝、結束を飲んでから学校へ行く。", "explanation": "「結束」を飲み物として使っており、抽象的なまとまりの意味に反する。"}, {"text": "この結束はとても長くて、五メートルもある。", "explanation": "「結束」を長さのある物体として使っており、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37515, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "結束", "is_correct": true, "explanation": "見出し語「けっそく」そのもの。"}, {"text": "鉄則", "is_correct": false, "explanation": "「てっそく」で、「け」が「て」に変わる別の語。"}, {"text": "血相", "is_correct": false, "explanation": "「けっそう」で、「く」が「う」に変わる別の語。"}, {"text": "潔白", "is_correct": false, "explanation": "「けっぱく」で、「そ」が「ぱ」に変わる別の語。"}], "explanations": {"結束": "見出し語「けっそく」そのもの。", "鉄則": "「てっそく」で、「け」が「て」に変わる別の語。", "血相": "「けっそう」で、「く」が「う」に変わる別の語。", "潔白": "「けっぱく」で、「そ」が「ぱ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "結束"}, "level_3": {"options": [{"text": "結束", "is_correct": true, "explanation": "負けた後にチームのまとまりが強まったという意味に合う。"}, {"text": "身長", "is_correct": false, "explanation": "形は合うが意味が合わない。身長は「強まる」ものではない。"}, {"text": "体重", "is_correct": false, "explanation": "形は合うが意味が合わない。体重は「強まる」とは言わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが意味が合わない。チームの値段が強まるとは言えない。"}], "explanations": {"結束": "負けた後にチームのまとまりが強まったという意味に合う。", "身長": "形は合うが意味が合わない。身長は「強まる」ものではない。", "体重": "形は合うが意味が合わない。体重は「強まる」とは言わない。", "値段": "形は合うが意味が合わない。チームの値段が強まるとは言えない。"}, "sentence_index": 6, "correct_answer": "結束"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の雨で、結束がぬれてしまった。", "explanation": "「結束」を傘や服のような物としてぬれるものにしており、意味が合わない。"}, {"text": "駅の近くに、大きな結束が建った。", "explanation": "「結束」を建物として使っており、抽象的なまとまりの意味に反する。"}, {"text": "彼は結束を食べて、とても元気になった。", "explanation": "「結束」を食べ物として使っており、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37515, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "クラスの結束を強いです。", "corrected_sentence": "クラスの結束は強いです。", "error_description": "形容詞「強い」の主題には「を」でなく「は」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37515, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "結束で乱れると、チームは弱くなる。", "corrected_sentence": "結束が乱れると、チームは弱くなる。", "error_description": "「乱れる」の主語を表す助詞は「で」でなく「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
