INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37516, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "季節・夜・霧・溝などの程度が進み、より深い状態になること。", "primary_collocate": null, "pronunciation": "ふかまる", "ipa": "ɸɯkamaɾɯ", "syllable_count": 4, "sentences": [{"text": "秋が深まって、山の木の葉が赤くなりました。", "target_word": "深まって", "complexity_tier": "T3", "furigana": "秋(あき)が深(ふか)まって、山(やま)の木(き)の葉(は)が赤(あか)くなりました。", "sentence_source": "generated"}, {"text": "紅葉が深まり、山全体が赤と黄色に染まりました。", "target_word": "深まり", "complexity_tier": "T3", "furigana": "紅葉(こうよう)が深(ふか)まり、山全体(やまぜんたい)が赤(あか)と黄色(きいろ)に染(そ)まりました。", "sentence_source": "generated"}, {"text": "山では夕方から霧が深まり、道が見えにくくなりました。", "target_word": "深まり", "complexity_tier": "T3", "furigana": "山(やま)では夕方(ゆうがた)から霧(きり)が深(ふか)まり、道(みち)が見(み)えにくくなりました。", "sentence_source": "generated"}, {"text": "冬が深まると、朝の空気はいっそう冷たくなります。", "target_word": "深まる", "complexity_tier": "T3", "furigana": "冬(ふゆ)が深(ふか)まると、朝(あさ)の空気(くうき)はいっそう冷(つめ)たくなります。", "sentence_source": "generated"}, {"text": "二人の間の溝が深まり、話し合いもできなくなりました。", "target_word": "深まり", "complexity_tier": "T3", "furigana": "二人(ふたり)の間(あいだ)の溝(みぞ)が深(ふか)まり、話(はな)し合(あ)いもできなくなりました。", "sentence_source": "generated"}, {"text": "事件の謎は、新しい手紙が見つかって、さらに深まりました。", "target_word": "深まり", "complexity_tier": "T3", "furigana": "事件(じけん)の謎(なぞ)は、新(あたら)しい手紙(てがみ)が見(み)つかって、さらに深(ふか)まりました。", "sentence_source": "generated"}, {"text": "夜が深まった頃、やっと研究室の電気が消えました。", "target_word": "深まった", "complexity_tier": "T3", "furigana": "夜(よる)が深(ふか)まった頃(ころ)、やっと研究室(けんきゅうしつ)の電気(でんき)が消(き)えました。", "sentence_source": "generated"}, {"text": "日がたつにつれて、森の緑は深まっていきます。", "target_word": "深まって", "complexity_tier": "T3", "furigana": "日(ひ)がたつにつれて、森(もり)の緑(みどり)は深(ふか)まっていきます。", "sentence_source": "generated"}, {"text": "雪がやむと、森の静けさがいっそう深まりました。", "target_word": "深まり", "complexity_tier": "T3", "furigana": "雪(ゆき)がやむと、森(もり)の静(しず)けさがいっそう深(ふか)まりました。", "sentence_source": "generated"}, {"text": "日が暮れるにつれて、谷の霧がいっそう深まりました。", "target_word": "深まり", "complexity_tier": "T3", "furigana": "日(ひ)が暮(く)れるにつれて、谷(たに)の霧(きり)がいっそう深(ふか)まりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "深まる", "label": "辞書形"}, {"form": "深まり", "label": "連用形"}, {"form": "深まって", "label": "て形"}, {"form": "深まった", "label": "過去形"}, {"form": "深まらない", "label": "否定形"}], "register": "丁寧語", "sense_fingerprint": "深まる:季節・夜・霧・溝などの程度がふかくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b56525-d686-4f42-9de7-3cd4f31105fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37516, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深まって", "is_correct": true, "explanation": "て形。「秋が深まって、」と自動詞の変化を述べ、後ろに文を続ける。"}, {"text": "深めて", "is_correct": false, "explanation": "他動詞のて形。「秋が深めて、」は主語と合わない。"}, {"text": "深まろう", "is_correct": false, "explanation": "意志を表す形。「秋が深まろう、」と続かず、文の流れに合わない。"}, {"text": "深めた", "is_correct": false, "explanation": "他動詞の過去形。「秋が深めた、」は成り立たない。"}], "explanations": {"深まって": "て形。「秋が深まって、」と自動詞の変化を述べ、後ろに文を続ける。", "深めて": "他動詞のて形。「秋が深めて、」は主語と合わない。", "深まろう": "意志を表す形。「秋が深まろう、」と続かず、文の流れに合わない。", "深めた": "他動詞の過去形。「秋が深めた、」は成り立たない。"}, "sentence_index": 0, "correct_answer": "深まって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風が深まると、朝の空気はいっそう冷たくなります。", "explanation": "ここは〈強まる〉の意味。深まるは程度が奥へ進むことで、風の勢いが増す場合は強まるを使う。"}, {"text": "読者の数が深まって、この本は人気になりました。", "explanation": "ここは〈増える〉の意味。深まるは内容や程度が奥深くなることで、人数が増える場合には使わない。"}, {"text": "売り上げが深まって、今月は三割も少なくなりました。", "explanation": "ここは〈減る〉の意味。深まるは程度が奥へ進む変化で、数量が下がる場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37516, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深まった", "is_correct": true, "explanation": "過去形。「夜が深まった頃」と名詞「頃」を修飾し、文として成り立つ。"}, {"text": "深まり", "is_correct": false, "explanation": "連用形。「夜が深まり頃」と名詞の前に続かず成り立たない。"}, {"text": "深めよう", "is_correct": false, "explanation": "意志形の他動詞。主語の「夜」と合わず、「頃」にも続かない。"}, {"text": "深めない", "is_correct": false, "explanation": "否定形の他動詞。「夜が深めない頃」は主語と合わない。"}], "explanations": {"深まった": "過去形。「夜が深まった頃」と名詞「頃」を修飾し、文として成り立つ。", "深まり": "連用形。「夜が深まり頃」と名詞の前に続かず成り立たない。", "深めよう": "意志形の他動詞。主語の「夜」と合わず、「頃」にも続かない。", "深めない": "否定形の他動詞。「夜が深めない頃」は主語と合わない。"}, "sentence_index": 6, "correct_answer": "深まった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの噂が深まって、町中の人が知っています。", "explanation": "ここは〈広がる〉の意味。深まるは内容や気持ちが奥深くなることで、噂が及ぶ範囲が広がる場合には使わない。"}, {"text": "人混みが深まって、身動きがとれなくなりました。", "explanation": "ここは〈混む〉の意味。深まるは程度が奥へ進む変化で、人が集まって混雑する場合には使わない。"}, {"text": "仕事のペースが深まって、計画より早く終わりました。", "explanation": "ここは〈速まる〉の意味。深まるは程度が奥へ進む変化で、動きの速さが増す場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37516, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋を深まるにつれて、朝晩の風が冷たくなりました。", "corrected_sentence": "秋が深まるにつれて、朝晩の風が冷たくなりました。", "error_description": "「秋を」は誤り。「深まる」は自動詞で、主語の「秋」に「が」を付ける。目的語の「を」ではない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "深まり", "is_correct": true, "explanation": "連用形。「紅葉が深まり、」と読点で続けて文をつなぐ形。"}, {"text": "深まる", "is_correct": false, "explanation": "辞書形。「深まる、」と続けると文が成り立たない。"}, {"text": "深まれ", "is_correct": false, "explanation": "命令形。「紅葉が深まれ、」は命令の形で、文の途中では成り立たない。"}, {"text": "深まろう", "is_correct": false, "explanation": "意志形。「紅葉が深まろう、」は主語と合わず、文の流れにも合わない。"}], "correct_form": "深まり", "base_form": "深まる", "form_label": "連用形", "sentence_index": 1, "explanations": {"深まり": "連用形。「紅葉が深まり、」と読点で続けて文をつなぐ形。", "深まる": "辞書形。「深まる、」と続けると文が成り立たない。", "深まれ": "命令形。「紅葉が深まれ、」は命令の形で、文の途中では成り立たない。", "深まろう": "意志形。「紅葉が深まろう、」は主語と合わず、文の流れにも合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37516, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜が深まて、街はすっかり静かになりました。", "corrected_sentence": "夜が深まって、街はすっかり静かになりました。", "error_description": "「深まて」は誤り。五段動詞「深まる」のて形は「深まって」で、促音「っ」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "深まって", "is_correct": true, "explanation": "て形。「深まっていきます」と続けて、変化の進行を表す形。"}, {"text": "深まり", "is_correct": false, "explanation": "連用形。「深まりいきます」とは続かない。"}, {"text": "深まらず", "is_correct": false, "explanation": "否定の「ず」形。「深まらずいきます」は成り立たない。"}, {"text": "深まれば", "is_correct": false, "explanation": "条件形。「深まればいきます」とは続かない。"}], "correct_form": "深まって", "base_form": "深まる", "form_label": "て形", "sentence_index": 7, "explanations": {"深まって": "て形。「深まっていきます」と続けて、変化の進行を表す形。", "深まり": "連用形。「深まりいきます」とは続かない。", "深まらず": "否定の「ず」形。「深まらずいきます」は成り立たない。", "深まれば": "条件形。「深まればいきます」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
