INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37517, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "感情や状態が、より強く、または深くなる。", "primary_collocate": null, "pronunciation": "ふかまる", "ipa": "ɸɯkamaɾɯ", "syllable_count": 4, "sentences": [{"text": "一緒に旅行して、二人の友情が深まりました。", "target_word": "深まり", "complexity_tier": "T3", "furigana": "一緒(いっしょ)に旅行(りょこう)して、二人(ふたり)の友情(ゆうじょう)が深(ふか)まりました。", "sentence_source": "generated"}, {"text": "先生の説明を聞いて、歴史への理解が深まりました。", "target_word": "深まり", "complexity_tier": "T3", "furigana": "先生(せんせい)の説明(せつめい)を聞(き)いて、歴史(れきし)への理解(りかい)が深(ふか)まりました。", "sentence_source": "generated"}, {"text": "結果が出ないまま日がたち、私の不安は深まる一方でした。", "target_word": "深まる", "complexity_tier": "T3", "furigana": "結果(けっか)が出(で)ないまま日(ひ)がたち、私(わたし)の不安(ふあん)は深(ふか)まる一方(いっぽう)でした。", "sentence_source": "generated"}, {"text": "何度も会ううちに、彼への信頼が深まっていきました。", "target_word": "深まって", "complexity_tier": "T3", "furigana": "何度(なんど)も会(あ)ううちに、彼(かれ)への信頼(しんらい)が深(ふか)まっていきました。", "sentence_source": "generated"}, {"text": "海外で働いた経験から、異文化への興味が深まりました。", "target_word": "深まり", "complexity_tier": "T3", "furigana": "海外(かいがい)で働(はたら)いた経験(けいけん)から、異文化(いぶんか)への興味(きょうみ)が深(ふか)まりました。", "sentence_source": "generated"}, {"text": "彼の話に矛盾があって、みんなの疑いが深まりました。", "target_word": "深まり", "complexity_tier": "T3", "furigana": "彼(かれ)の話(はなし)に矛盾(むじゅん)があって、みんなの疑(うたが)いが深(ふか)まりました。", "sentence_source": "generated"}, {"text": "毎日世話をするうちに、犬への愛情が深まりました。", "target_word": "深まり", "complexity_tier": "T3", "furigana": "毎日(まいにち)世話(せわ)をするうちに、犬(いぬ)への愛情(あいじょう)が深(ふか)まりました。", "sentence_source": "generated"}, {"text": "話し合いを重ねて、両国の関係が深まりました。", "target_word": "深まり", "complexity_tier": "T3", "furigana": "話(はな)し合(あ)いを重(かさ)ねて、両国(りょうこく)の関係(かんけい)が深(ふか)まりました。", "sentence_source": "generated"}, {"text": "本を読むほど、この問題への関心が深まります。", "target_word": "深まり", "complexity_tier": "T3", "furigana": "本(ほん)を読(よ)むほど、この問題(もんだい)への関心(かんしん)が深(ふか)まります。", "sentence_source": "generated"}, {"text": "雨が続いて、町の人々の心配はますます深まっています。", "target_word": "深まって", "complexity_tier": "T3", "furigana": "雨(あめ)が続(つづ)いて、町(まち)の人々(ひとびと)の心配(しんぱい)はますます深(ふか)まっています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "深まる", "label": "辞書形"}, {"form": "深まり", "label": "連用形"}, {"form": "深まって", "label": "て形"}, {"form": "深まった", "label": "過去形"}, {"form": "深まらない", "label": "否定形"}], "register": "丁寧語", "sense_fingerprint": "深まる:友情・理解・不安など感情や状態がより強くなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69b56525-d686-4f42-9de7-3cd4f31105fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37517, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深まり", "is_correct": true, "explanation": "連用形。「友情が深まりました」の形で、「ました」に続く。"}, {"text": "深め", "is_correct": false, "explanation": "他動詞の連用形。「友情が深めました」は主語と合わず、文が成り立たない。"}, {"text": "深まる", "is_correct": false, "explanation": "辞書形。「深まるました」となり成り立たない。"}, {"text": "深まらない", "is_correct": false, "explanation": "否定形。「深まらないました」となり成り立たない。"}], "explanations": {"深まり": "連用形。「友情が深まりました」の形で、「ました」に続く。", "深め": "他動詞の連用形。「友情が深めました」は主語と合わず、文が成り立たない。", "深まる": "辞書形。「深まるました」となり成り立たない。", "深まらない": "否定形。「深まらないました」となり成り立たない。"}, "sentence_index": 0, "correct_answer": "深まり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その噂は、ネットを通じて深まり、町じゅうに知れ渡りました。", "explanation": "ここは〈広がる〉の意味。深まるは気持ちや理解が奥深くなることで、噂が及ぶ範囲が広がる場合には使わない。"}, {"text": "仕事の量が深まって、残業が増えました。", "explanation": "ここは〈増す〉の意味。深まるは程度が奥深くなることで、量が多くなる場合には使わない。"}, {"text": "風邪で熱が深まって、今朝は四十度になりました。", "explanation": "ここは〈上がる〉の意味。深まるは気持ちや状態が奥深くなることで、体温が高くなる場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37517, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深まり", "is_correct": true, "explanation": "連用形。「愛情が深まりました」の形で、「ました」に続く。"}, {"text": "深まろう", "is_correct": false, "explanation": "意志形。「深まろうました」とは続かない。"}, {"text": "深めよう", "is_correct": false, "explanation": "意志形の他動詞。主語の「愛情」と合わず、「ました」にも続かない。"}, {"text": "深まれ", "is_correct": false, "explanation": "命令形。「深まれました」とは続かない。"}], "explanations": {"深まり": "連用形。「愛情が深まりました」の形で、「ました」に続く。", "深まろう": "意志形。「深まろうました」とは続かない。", "深めよう": "意志形の他動詞。主語の「愛情」と合わず、「ました」にも続かない。", "深まれ": "命令形。「深まれました」とは続かない。"}, "sentence_index": 6, "correct_answer": "深まり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洗濯したシャツの布地が深まって、すっかり小さくなりました。", "explanation": "ここは〈縮む〉の意味。深まるは奥へ進む変化で、布が縮んで小さくなる場合には使わない。"}, {"text": "庭の草が深まって、足の踏み場もありません。", "explanation": "ここは〈生い茂る〉の意味。深まるは気持ちや状態が奥深くなることで、草が伸びて茂る様子には使わない。"}, {"text": "鍋の湯が深まって、なかなか冷めません。", "explanation": "ここは〈温まる〉の意味。深まるは気持ちや状態が奥深くなることで、湯の温度が上がる場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37517, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父との会話で、家族の絆が深まるました。", "corrected_sentence": "祖父との会話で、家族の絆が深まりました。", "error_description": "「深まるました」は誤り。「ました」の前は連用形「深まり」で、辞書形「深まる」は続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "深まり", "is_correct": true, "explanation": "連用形。「理解が深まりました」の形で、「ました」に続く。"}, {"text": "深まる", "is_correct": false, "explanation": "辞書形。「理解が深まるました」となり、「ました」と続かない。"}, {"text": "深まった", "is_correct": false, "explanation": "過去形。「深まったました」となり、文が成り立たない。"}, {"text": "深まらない", "is_correct": false, "explanation": "否定形。理解が深まらなかったという意味になり、文の内容と合わない。"}], "correct_form": "深まり", "base_form": "深まる", "form_label": "連用形", "sentence_index": 1, "explanations": {"深まり": "連用形。「理解が深まりました」の形で、「ました」に続く。", "深まる": "辞書形。「理解が深まるました」となり、「ました」と続かない。", "深まった": "過去形。「深まったました」となり、文が成り立たない。", "深まらない": "否定形。理解が深まらなかったという意味になり、文の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37517, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "長い交流を通して、両国の信頼を深まりました。", "corrected_sentence": "長い交流を通して、両国の信頼が深まりました。", "error_description": "「信頼を」は誤り。自動詞「深まる」の主語には「が」を付けるので、目的語の「を」ではなく「が」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "深まり", "is_correct": true, "explanation": "連用形。「関係が深まりました」の形で、「ました」に続く。"}, {"text": "深まろう", "is_correct": false, "explanation": "意志形。「深まろうました」とは続かない。"}, {"text": "深まれば", "is_correct": false, "explanation": "条件形。「深まればました」とは続かない。"}, {"text": "深まらず", "is_correct": false, "explanation": "否定の「ず」形。「深まらずました」は成り立たない。"}], "correct_form": "深まり", "base_form": "深まる", "form_label": "連用形", "sentence_index": 7, "explanations": {"深まり": "連用形。「関係が深まりました」の形で、「ました」に続く。", "深まろう": "意志形。「深まろうました」とは続かない。", "深まれば": "条件形。「深まればました」とは続かない。", "深まらず": "否定の「ず」形。「深まらずました」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9acf6a9b-0f97-40bc-9a6c-f136c74f1012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
