INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37518, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「敵対」は、相手と反対の立場になって戦うことです。", "primary_collocate": null, "pronunciation": "てきたい", "ipa": "tekitai", "syllable_count": 4, "sentences": [{"text": "二つの国は長い間、敵対していた。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]は長[なが]い間[あいだ]、敵対[てきたい]していた。", "sentence_source": "generated"}, {"text": "彼は社長と敵対して、会社を辞めることになった。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "彼[かれ]は社長[しゃちょう]と敵対[てきたい]して、会社[かいしゃ]を辞[や]めることになった。", "sentence_source": "generated"}, {"text": "昔は敵対していた二人が、今では親友だ。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "昔[むかし]は敵対[てきたい]していた二人[ふたり]が、今[いま]では親友[しんゆう]だ。", "sentence_source": "generated"}, {"text": "敵対する国同士が話し合いの場についた。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "敵対[てきたい]する国同士[くにどうし]が話[はな]し合[あ]いの場[ば]についた。", "sentence_source": "generated"}, {"text": "私はあなたと敵対するつもりはありません。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "私[わたし]はあなたと敵対[てきたい]するつもりはありません。", "sentence_source": "generated"}, {"text": "敵対するチームの選手とも、試合のあとは握手をした。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "敵対[てきたい]するチームの選手[せんしゅ]とも、試合[しあい]のあとは握手[あくしゅ]をした。", "sentence_source": "generated"}, {"text": "利益をめぐって、二つの会社は敵対するようになった。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "利益[りえき]をめぐって、二[ふた]つの会社[かいしゃ]は敵対[てきたい]するようになった。", "sentence_source": "generated"}, {"text": "王様に敵対した者は、みな国から追い出された。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "王様[おうさま]に敵対[てきたい]した者[もの]は、みな国[くに]から追[お]い出[だ]された。", "sentence_source": "generated"}, {"text": "二人は敵対しているように見えて、実は仲がいい。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "二人[ふたり]は敵対[てきたい]しているように見[み]えて、実[じつ]は仲[なか]がいい。", "sentence_source": "generated"}, {"text": "村の人々は、隣の村と敵対して、橋を壊してしまった。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "村[むら]の人々[ひとびと]は、隣[となり]の村[むら]と敵対[てきたい]して、橋[はし]を壊[こわ]してしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "敵対する", "label": "終止形"}, {"form": "敵対した", "label": "過去形"}, {"form": "敵対している", "label": "進行・状態"}, {"form": "敵対しない", "label": "否定形"}], "register": "標準（やや硬い）", "sense_fingerprint": "相手と反対の立場に立って戦う、争う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d21cf5d-f729-4c5e-b9cd-2c0746b4a406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37518, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "敵対", "is_correct": true, "explanation": "文中の形。「〜していた」に続けて「相手と敵として争う関係だった」という意味になり、文脈に合う。"}, {"text": "敵対的", "is_correct": false, "explanation": "形容動詞の形。「敵対的していた」とは続かず、空欄に入らない。"}, {"text": "敵対者", "is_correct": false, "explanation": "人を指す名詞。「敵対者していた」と動詞として続かず、国同士の関係を表せない。"}, {"text": "敵対心", "is_correct": false, "explanation": "感情を表す名詞。「敵対心していた」と動詞として続かず、空欄に入らない。"}], "explanations": {"敵対": "文中の形。「〜していた」に続けて「相手と敵として争う関係だった」という意味になり、文脈に合う。", "敵対的": "形容動詞の形。「敵対的していた」とは続かず、空欄に入らない。", "敵対者": "人を指す名詞。「敵対者していた」と動詞として続かず、国同士の関係を表せない。", "敵対心": "感情を表す名詞。「敵対心していた」と動詞として続かず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "敵対"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人は意見が敵対して、なかなか結論が出なかった。", "explanation": "ここは〈対立〉の意味。意見の食い違いは「対立」と言い、「敵対」は敵として争う関係を指すので、意見どうしには使わない。"}, {"text": "彼は難しい山に敵対して、頂上を目指した。", "explanation": "ここは〈挑戦〉の意味。難しい山に立ち向かうのは「挑戦」で、「敵対」は相手を敵として争う関係を指すので、山には使わない。"}, {"text": "苦情に敵対して、丁寧に謝った。", "explanation": "ここは〈対応〉の意味。苦情に応じて丁寧に処理する場面は「対応」で、「敵対」は相手を敵として争う関係なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37518, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "敵対", "is_correct": true, "explanation": "文中の形。「〜するようになった」に続けて、利益をめぐる争いから対立関係に変わった流れに合う。"}, {"text": "敵意", "is_correct": false, "explanation": "感情を表す名詞。「敵意するようになった」とは続かず、「敵意を抱くようになった」の形になるので空欄に入らない。"}, {"text": "敵方", "is_correct": false, "explanation": "陣営を指す名詞。「敵方するようになった」と動詞として続かず、空欄に入らない。"}, {"text": "敵国", "is_correct": false, "explanation": "国を指す名詞。「敵国するようになった」と続かず、会社どうしの関係には当てはまらない。"}], "explanations": {"敵対": "文中の形。「〜するようになった」に続けて、利益をめぐる争いから対立関係に変わった流れに合う。", "敵意": "感情を表す名詞。「敵意するようになった」とは続かず、「敵意を抱くようになった」の形になるので空欄に入らない。", "敵方": "陣営を指す名詞。「敵方するようになった」と動詞として続かず、空欄に入らない。", "敵国": "国を指す名詞。「敵国するようになった」と続かず、会社どうしの関係には当てはまらない。"}, "sentence_index": 6, "correct_answer": "敵対"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの国は敵対して、新しい条約を作った。", "explanation": "ここは〈協調〉の意味。力を合わせて条約を作る場面は「協調」で、「敵対」は争う関係を指すので、共同の成果には合わない。"}, {"text": "救助隊と地元の人々は大雨のあとに敵対して、被害を抑えた。", "explanation": "ここは〈連携〉の意味。現場で力を合わせて被害を抑える場面は「連携」で、「敵対」は争う関係を指すので合わない。"}, {"text": "隣の村と敵対して、橋の修理を決めた。", "explanation": "ここは〈協議〉の意味。話し合って修理を決めるのは「協議」で、「敵対」は争う関係を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37518, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "両国は長い間、敵対せていた。", "corrected_sentence": "両国は長い間、敵対していた。", "error_description": "「する」の連用形の誤り。「して」を「せて」としたのが誤り。正しくは「敵対していた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37518, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "利益をめぐって、二社は敵対せるようになった。", "corrected_sentence": "利益をめぐって、二社は敵対するようになった。", "error_description": "「する」を使役形の「せる」にした誤り。「敵対するようになった」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
