INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37519, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "互いに敵として対立すること。相手に反抗したり、争ったりする関係。", "primary_collocate": null, "pronunciation": "てきたい", "ipa": "tekitai", "syllable_count": 4, "sentences": [{"text": "兄弟は遺産の問題で敵対し、十年も口をきかなかった。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "兄弟[きょうだい]は遺産[いさん]の問題[もんだい]で敵対[てきたい]し、十年[じゅうねん]も口[くち]をきかなかった。", "sentence_source": "generated"}, {"text": "敵対する勢力の間で、小さな争いが続いている。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "敵対[てきたい]する勢力[せいりょく]の間[あいだ]で、小[ちい]さな争[あらそ]いが続[つづ]いている。", "sentence_source": "generated"}, {"text": "彼女は新しい部長に敵対する態度をとらなかった。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は新[あたら]しい部長[ぶちょう]に敵対[てきたい]する態度[たいど]をとらなかった。", "sentence_source": "generated"}, {"text": "両国は国境をめぐって敵対している。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "両国[りょうこく]は国境[こっきょう]をめぐって敵対[てきたい]している。", "sentence_source": "generated"}, {"text": "敵対していた二つの家は、結婚をきっかけに仲直りした。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "敵対[てきたい]していた二[ふた]つの家[いえ]は、結婚[けっこん]をきっかけに仲直[なかなお]りした。", "sentence_source": "generated"}, {"text": "先生は、生徒同士が敵対しないように気をつけている。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒同士[せいとどうし]が敵対[てきたい]しないように気[き]をつけている。", "sentence_source": "generated"}, {"text": "物語では、主人公と敵対する魔法使いが現れる。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "物語[ものがたり]では、主人公[しゅじんこう]と敵対[てきたい]する魔法使[まほうつか]いが現[あらわ]れる。", "sentence_source": "generated"}, {"text": "彼とは意見が違うだけで、敵対しているわけではない。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "彼[かれ]とは意見[いけん]が違[ちが]うだけで、敵対[てきたい]しているわけではない。", "sentence_source": "generated"}, {"text": "会社どうしが敵対すると、客も困ってしまう。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "会社[かいしゃ]どうしが敵対[てきたい]すると、客[きゃく]も困[こま]ってしまう。", "sentence_source": "generated"}, {"text": "昔から敵対してきた町が、今年は合同で祭りを開く。", "target_word": "敵対", "complexity_tier": "T3", "furigana": "昔[むかし]から敵対[てきたい]してきた町[まち]が、今年[ことし]は合同[ごうどう]で祭[まつ]りを開[ひら]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "敵対する", "label": "終止形"}, {"form": "敵対した", "label": "過去形"}, {"form": "敵対している", "label": "進行・状態"}, {"form": "敵対しない", "label": "否定形"}], "register": "標準（やや硬い）", "sense_fingerprint": "互いに敵として対立し、反抗したり争ったりする関係", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d21cf5d-f729-4c5e-b9cd-2c0746b4a406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37519, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "敵対", "is_correct": true, "explanation": "文中の形。「〜し、」で続けて、遺産の問題で互いに対立した状態を表し、文に合う。"}, {"text": "敵対的", "is_correct": false, "explanation": "形容動詞の形。「敵対的し、」とは続かず、空欄に入らない。"}, {"text": "敵対者", "is_correct": false, "explanation": "人を指す名詞。「敵対者し、」では文が成り立たない。"}, {"text": "敵対心", "is_correct": false, "explanation": "感情を表す名詞。「敵対心し、」と動詞として続かず、空欄に入らない。"}], "explanations": {"敵対": "文中の形。「〜し、」で続けて、遺産の問題で互いに対立した状態を表し、文に合う。", "敵対的": "形容動詞の形。「敵対的し、」とは続かず、空欄に入らない。", "敵対者": "人を指す名詞。「敵対者し、」では文が成り立たない。", "敵対心": "感情を表す名詞。「敵対心し、」と動詞として続かず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "敵対"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "両国は国境の線引きをめぐって、三か月も仲良く敵対した。", "explanation": "ここは〈友好〉の意味。互いに親しく付き合う場面は「友好」で、「敵対」は争う関係を指すので「仲良く」とは合わない。"}, {"text": "村の祭りの準備を、両家が敵対して進めた。", "explanation": "ここは〈協力〉の意味。準備を分担して力を合わせる場面は「協力」で、「敵対」は争う関係を指すので合わない。"}, {"text": "新しい企画に敵対して、みなで支えることにした。", "explanation": "ここは〈支持〉の意味。企画を全員で支える場面は「支持」で、「敵対」は争う関係を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37519, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "敵対", "is_correct": true, "explanation": "文中の形。「主人公と〜する魔法使い」の形で、主人公に反する敵役を表し、文に合う。"}, {"text": "敵軍", "is_correct": false, "explanation": "軍隊を指す名詞。「主人公と敵軍する魔法使い」とは動詞として続かず、空欄に入らない。"}, {"text": "敵陣", "is_correct": false, "explanation": "陣地を指す名詞。「主人公と敵陣する魔法使い」とは続かず、空欄に入らない。"}, {"text": "敵国", "is_correct": false, "explanation": "国を指す名詞。「主人公と敵国する魔法使い」とは続かず、空欄に入らない。"}], "explanations": {"敵対": "文中の形。「主人公と〜する魔法使い」の形で、主人公に反する敵役を表し、文に合う。", "敵軍": "軍隊を指す名詞。「主人公と敵軍する魔法使い」とは動詞として続かず、空欄に入らない。", "敵陣": "陣地を指す名詞。「主人公と敵陣する魔法使い」とは続かず、空欄に入らない。", "敵国": "国を指す名詞。「主人公と敵国する魔法使い」とは続かず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "敵対"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの会社は新商品の開発を、敵対して進めた。", "explanation": "ここは〈提携〉の意味。共同で商品を作る場面は「提携」で、「敵対」は争う関係を指すので、共同の開発には合わない。"}, {"text": "消防と警察は火事の現場で敵対して、住民を避難させた。", "explanation": "ここは〈連携〉の意味。現場で互いに協力して住民を避難させる場面は「連携」で、「敵対」は争う関係を指すので合わない。"}, {"text": "大雨の日、隣の村と敵対して土のうを積んだ。", "explanation": "ここは〈助け合い〉の意味。土のうを一緒に積む場面は「助け合い」で、「敵対」は争う関係を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37519, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄弟は遺産の問題で敵対せて、長年口をきかなかった。", "corrected_sentence": "兄弟は遺産の問題で敵対し、長年口をきかなかった。", "error_description": "「する」の連用形の誤り。「敵対せて」は誤りで、「敵対し、」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37519, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔から敵対せてきた町々が、今年は合同で祭りを開く。", "corrected_sentence": "昔から敵対してきた町々が、今年は合同で祭りを開く。", "error_description": "「する」の連用形の誤り。「敵対せてきた」は誤りで、「敵対してきた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37520, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽蔑", "is_correct": true, "explanation": "相手を見下して敬わない気持ち。すごいと思う「尊敬」の対義語として辞書に載る。"}, {"text": "感謝", "is_correct": false, "explanation": "恩や親切への礼の気持ち。尊敬の反対ではない。"}, {"text": "信頼", "is_correct": false, "explanation": "頼れると信じる気持ち。尊敬と近い面はあるが、反対の意味ではない。"}, {"text": "同情", "is_correct": false, "explanation": "相手の苦しみを思いやる気持ち。尊敬の反対ではない。"}], "correct_answer": "軽蔑", "explanations": {"軽蔑": "相手を見下して敬わない気持ち。すごいと思う「尊敬」の対義語として辞書に載る。", "感謝": "恩や親切への礼の気持ち。尊敬の反対ではない。", "信頼": "頼れると信じる気持ち。尊敬と近い面はあるが、反対の意味ではない。", "同情": "相手の苦しみを思いやる気持ち。尊敬の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37520, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽蔑", "is_correct": true, "explanation": "相手を見下して敬わない気持ち。すごいと思う「尊敬」の対義語として辞書に載る。"}, {"text": "感動", "is_correct": false, "explanation": "心を強く動かされること。尊敬とは別の感情で、反対語ではない。"}, {"text": "親近", "is_correct": false, "explanation": "親しみを感じること。尊敬の反対ではない。"}, {"text": "好意", "is_correct": false, "explanation": "好ましく思う気持ち。尊敬の反対ではない。"}], "correct_answer": "軽蔑", "explanations": {"軽蔑": "相手を見下して敬わない気持ち。すごいと思う「尊敬」の対義語として辞書に載る。", "感動": "心を強く動かされること。尊敬とは別の感情で、反対語ではない。", "親近": "親しみを感じること。尊敬の反対ではない。", "好意": "好ましく思う気持ち。尊敬の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37520, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "すごいと思うこと。", "primary_collocate": null, "pronunciation": "そんけい", "ipa": "soŋkeː", "syllable_count": 4, "sentences": [{"text": "私は父を尊敬している。", "target_word": "尊敬", "complexity_tier": "T2", "furigana": "私[わたし]は父[ちち]を尊敬[そんけい]している。", "sentence_source": "generated"}, {"text": "努力を続ける彼女を尊敬する。", "target_word": "尊敬", "complexity_tier": "T3", "furigana": "努力[どりょく]を続[つづ]ける彼女[かのじょ]を尊敬[そんけい]する。", "sentence_source": "generated"}, {"text": "先生はみんなから尊敬されている。", "target_word": "尊敬", "complexity_tier": "T3", "furigana": "先生[せんせい]はみんなから尊敬[そんけい]されている。", "sentence_source": "generated"}, {"text": "彼の優しさに、尊敬の気持ちを持った。", "target_word": "尊敬", "complexity_tier": "T3", "furigana": "彼[かれ]の優[やさ]しさに、尊敬[そんけい]の気持[きも]ちを持[も]った。", "sentence_source": "generated"}, {"text": "尊敬する人は誰ですか。", "target_word": "尊敬", "complexity_tier": "T2", "furigana": "尊敬[そんけい]する人[ひと]は誰[だれ]ですか。", "sentence_source": "generated"}, {"text": "あの選手は、世界中の人に尊敬されている。", "target_word": "尊敬", "complexity_tier": "T3", "furigana": "あの選手[せんしゅ]は、世界中[せかいじゅう]の人[ひと]に尊敬[そんけい]されている。", "sentence_source": "generated"}, {"text": "母の強さは、尊敬に値する。", "target_word": "尊敬", "complexity_tier": "T4", "furigana": "母[はは]の強[つよ]さは、尊敬[そんけい]に値[あたい]する。", "sentence_source": "generated"}, {"text": "毎日早く起きる兄を、私は尊敬している。", "target_word": "尊敬", "complexity_tier": "T3", "furigana": "毎日[まいにち]早[はや]く起[お]きる兄[あに]を、私[わたし]は尊敬[そんけい]している。", "sentence_source": "generated"}, {"text": "自分の失敗を認める人を尊敬します。", "target_word": "尊敬", "complexity_tier": "T3", "furigana": "自分[じぶん]の失敗[しっぱい]を認[みと]める人[ひと]を尊敬[そんけい]します。", "sentence_source": "generated"}, {"text": "小さいころから、祖父を尊敬してきた。", "target_word": "尊敬", "complexity_tier": "T3", "furigana": "小[ちい]さいころから、祖父[そふ]を尊敬[そんけい]してきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "尊敬", "label": "基本形"}, {"form": "尊敬する", "label": "サ変動詞・終止形"}, {"form": "尊敬している", "label": "継続形"}, {"form": "尊敬される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "相手をすごいと思う気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6ee224-92d2-4127-abed-56d8891d40e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37520, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尊敬", "is_correct": true, "explanation": "「父を尊敬している」の形で、すごいと思う気持ちを表す。目的語の「父を」を取るので空所に入る。"}, {"text": "相談", "is_correct": false, "explanation": "「相談する」は「父に相談する」と相手を「に」で示すため、「父を相談している」とは続かない。"}, {"text": "結婚", "is_correct": false, "explanation": "「結婚する」は「父と結婚する」と「と」で相手を示す。「父を結婚している」は意味が成り立たない。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩する」は歩く道を「を」で示す。人を「を」で取るなら「散歩させる」になり、この空所には合わない。"}], "explanations": {"尊敬": "「父を尊敬している」の形で、すごいと思う気持ちを表す。目的語の「父を」を取るので空所に入る。", "相談": "「相談する」は「父に相談する」と相手を「に」で示すため、「父を相談している」とは続かない。", "結婚": "「結婚する」は「父と結婚する」と「と」で相手を示す。「父を結婚している」は意味が成り立たない。", "散歩": "「散歩する」は歩く道を「を」で示す。人を「を」で取るなら「散歩させる」になり、この空所には合わない。"}, "sentence_index": 0, "correct_answer": "尊敬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は私の意見を尊敬してくれた。", "explanation": "ここは〈尊重〉（大切に扱う）の意味。意見は人ではないので、すごいと思う対象にはならない。「意見を尊重する」が自然。"}, {"text": "彼は目上の人と話すとき、尊敬を使う。", "explanation": "ここは〈尊敬語〉（敬語の一種）の意味。言葉遣いは「尊敬語を使う」と言い、「尊敬」は人をすごいと思う気持ちなので言葉遣いの名前にはならない。"}, {"text": "夜の山道は暗く、尊敬を覚えて足がすくんだ。", "explanation": "ここは〈恐れ〉の意味。暗い山道で足がすくむ時は「怖い」「恐ろしい」と言い、「尊敬」は人の立派さを認める気持ちなので、場所の怖さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37520, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尊敬", "is_correct": true, "explanation": "「母の強さは尊敬に値する」の形で、認めるに足る立派さを表す。"}, {"text": "返信", "is_correct": false, "explanation": "「返信」は手紙などへの返事で、「返信に値する」とは言わない。"}, {"text": "出発", "is_correct": false, "explanation": "「出発」は場所を起点にする言葉で、「出発に値する」は不自然。"}, {"text": "注文", "is_correct": false, "explanation": "「注文」は品物を頼むことで、「注文に値する」とは言わない。"}], "explanations": {"尊敬": "「母の強さは尊敬に値する」の形で、認めるに足る立派さを表す。", "返信": "「返信」は手紙などへの返事で、「返信に値する」とは言わない。", "出発": "「出発」は場所を起点にする言葉で、「出発に値する」は不自然。", "注文": "「注文」は品物を頼むことで、「注文に値する」とは言わない。"}, "sentence_index": 6, "correct_answer": "尊敬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体調を崩した母を、尊敬して眠れなかった。", "explanation": "ここは〈心配〉の意味。母の体調を気にして眠れない時は「心配で眠れなかった」と言い、「尊敬」は人の立派な行いを認める言葉なので、体調への気遣いには使わない。"}, {"text": "その知らせに、尊敬して言葉を失った。", "explanation": "ここは〈驚き〉の意味。予想外の知らせに言葉を失う時は「驚いて言葉を失う」と言い、「尊敬」は人の立派さを認める気持ちなので、知らせへの反応には合わない。"}, {"text": "夢を、尊敬して毎晩眺めた。", "explanation": "ここは〈憧れ〉の意味。夢や理想に心を寄せる時は「憧れる」と言い、「尊敬」は人の立派な行いを認める言葉なので、夢の対象には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37520, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母に尊敬している。", "corrected_sentence": "祖母を尊敬している。", "error_description": "誤: 祖母に尊敬している → 正: 祖母を尊敬している。「尊敬する」は対象を「を」で取るため、目的語の助詞は「を」が正しい。「に」は相手を示すので、ここでは不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37520, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は村人に尊敬しられている。", "corrected_sentence": "祖父は村人に尊敬されている。", "error_description": "誤: 尊敬しられている → 正: 尊敬されている。「尊敬する」の受身は「尊敬される」。「しられ」は動詞の語形が誤りで、「さ」を入れた「されて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37521, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽蔑", "is_correct": true, "explanation": "相手を見下して敬わない気持ち。えらいと思う「尊敬」の対義語として辞書に載る。"}, {"text": "好感", "is_correct": false, "explanation": "好ましく感じること。尊敬の反対ではない。"}, {"text": "同情", "is_correct": false, "explanation": "相手の苦しみを思いやる気持ち。反対の意味ではない。"}, {"text": "信頼", "is_correct": false, "explanation": "頼れると信じる気持ち。尊敬と近いが、反対語ではない。"}], "correct_answer": "軽蔑", "explanations": {"軽蔑": "相手を見下して敬わない気持ち。えらいと思う「尊敬」の対義語として辞書に載る。", "好感": "好ましく感じること。尊敬の反対ではない。", "同情": "相手の苦しみを思いやる気持ち。反対の意味ではない。", "信頼": "頼れると信じる気持ち。尊敬と近いが、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37521, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「技術を尊敬していた」の目的語。尊敬の対象を示す。"}, {"text": "と", "is_correct": false, "explanation": "「技術と尊敬していた」は並列を示し、尊敬の対象を「を」で示す文型に合わない。"}, {"text": "から", "is_correct": false, "explanation": "「技術から尊敬していた」は起点を示し、尊敬の対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「技術の尊敬していた」は連体修飾になり、目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「技術を尊敬していた」の目的語。尊敬の対象を示す。", "と": "「技術と尊敬していた」は並列を示し、尊敬の対象を「を」で示す文型に合わない。", "から": "「技術から尊敬していた」は起点を示し、尊敬の対象にはならない。", "の": "「技術の尊敬していた」は連体修飾になり、目的語にはならない。"}, "error_tags": {"と": "相手・並列", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽蔑", "is_correct": true, "explanation": "相手を見下して敬わない気持ち。えらいと思う「尊敬」の対義語として辞書に載る。"}, {"text": "感謝", "is_correct": false, "explanation": "恩や親切への礼の気持ち。尊敬の反対ではない。"}, {"text": "親近", "is_correct": false, "explanation": "親しみを感じること。反対の意味ではない。"}, {"text": "感動", "is_correct": false, "explanation": "心を強く動かされること。尊敬とは別の感情で、反対語ではない。"}], "correct_answer": "軽蔑", "explanations": {"軽蔑": "相手を見下して敬わない気持ち。えらいと思う「尊敬」の対義語として辞書に載る。", "感謝": "恩や親切への礼の気持ち。尊敬の反対ではない。", "親近": "親しみを感じること。反対の意味ではない。", "感動": "心を強く動かされること。尊敬とは別の感情で、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37521, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "相手のすぐれた点や行いを認めて、その人をえらいと思うこと。", "primary_collocate": null, "pronunciation": "そんけい", "ipa": "soŋkeː", "syllable_count": 4, "sentences": [{"text": "彼の誠実な態度に、私は尊敬の念をいだいた。", "target_word": "尊敬", "complexity_tier": "T4", "furigana": "彼[かれ]の誠実[せいじつ]な態度[たいど]に、私[わたし]は尊敬[そんけい]の念[ねん]をいだいた。", "sentence_source": "generated"}, {"text": "医者として働く姉を、心から尊敬している。", "target_word": "尊敬", "complexity_tier": "T3", "furigana": "医者[いしゃ]として働[はたら]く姉[あね]を、心[こころ]から尊敬[そんけい]している。", "sentence_source": "generated"}, {"text": "部下は課長の公平さを尊敬している。", "target_word": "尊敬", "complexity_tier": "T4", "furigana": "部下[ぶか]は課長[かちょう]の公平[こうへい]さを尊敬[そんけい]している。", "sentence_source": "generated"}, {"text": "尊敬する先輩に、仕事のやり方を教わった。", "target_word": "尊敬", "complexity_tier": "T3", "furigana": "尊敬[そんけい]する先輩[せんぱい]に、仕事[しごと]のやり方[かた]を教[おそ]わった。", "sentence_source": "generated"}, {"text": "人を助ける行いは、尊敬されるべきだ。", "target_word": "尊敬", "complexity_tier": "T4", "furigana": "人[ひと]を助[たす]ける行[おこな]いは、尊敬[そんけい]されるべきだ。", "sentence_source": "generated"}, {"text": "彼女は年上の人にも年下の人にも尊敬の気持ちを忘れない。", "target_word": "尊敬", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は年上[としうえ]の人[ひと]にも年下[としした]の人[ひと]にも尊敬[そんけい]の気持[きも]ちを忘[わす]れない。", "sentence_source": "generated"}, {"text": "困っている人を放っておかない君を、尊敬している。", "target_word": "尊敬", "complexity_tier": "T3", "furigana": "困[こま]っている人[ひと]を放[ほう]っておかない君[きみ]を、尊敬[そんけい]している。", "sentence_source": "generated"}, {"text": "弟子は師匠の技術を尊敬していた。", "target_word": "尊敬", "complexity_tier": "T4", "furigana": "弟子[でし]は師匠[ししょう]の技術[ぎじゅつ]を尊敬[そんけい]していた。", "sentence_source": "generated"}, {"text": "約束を必ず守る彼は、周りから尊敬されている。", "target_word": "尊敬", "complexity_tier": "T3", "furigana": "約束[やくそく]を必[かなら]ず守[まも]る彼[かれ]は、周[まわ]りから尊敬[そんけい]されている。", "sentence_source": "generated"}, {"text": "村長は長年地域に尽くし、みんなの尊敬を集めた。", "target_word": "尊敬", "complexity_tier": "T4", "furigana": "村長[そんちょう]は長年[ながねん]地域[ちいき]に尽[つ]くし、みんなの尊敬[そんけい]を集[あつ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "尊敬", "label": "基本形"}, {"form": "尊敬する", "label": "サ変動詞・終止形"}, {"form": "尊敬される", "label": "受身形"}, {"form": "尊敬している", "label": "継続形"}], "register": "formal", "sense_fingerprint": "相手のすぐれた点や行いを認めてえらいと思うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6ee224-92d2-4127-abed-56d8891d40e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37521, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尊敬", "is_correct": true, "explanation": "「尊敬の念をいだく」の形で、相手のすぐれた点を認める気持ちを表す。"}, {"text": "返信", "is_correct": false, "explanation": "「返信の念」とは言わず、この空所には合わない。"}, {"text": "出発", "is_correct": false, "explanation": "「出発の念」は不自然で、この空所には合わない。"}, {"text": "注文", "is_correct": false, "explanation": "「注文の念」とは言わない。"}], "explanations": {"尊敬": "「尊敬の念をいだく」の形で、相手のすぐれた点を認める気持ちを表す。", "返信": "「返信の念」とは言わず、この空所には合わない。", "出発": "「出発の念」は不自然で、この空所には合わない。", "注文": "「注文の念」とは言わない。"}, "sentence_index": 0, "correct_answer": "尊敬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部長は部下の意見を尊敬して、提案を採用した。", "explanation": "ここは〈尊重〉の意味。意見は人ではないので、えらいと認める対象にはならない。「意見を尊重する」が自然。"}, {"text": "目上の人には、尊敬をつけて話す。", "explanation": "ここは〈敬語〉の意味。目上の人への話し方は「敬語を使う」と言い、「尊敬」は人を立派だと思う気持ちなので言葉遣いにはつけられない。"}, {"text": "夜の森の静けさに、尊敬を感じて足がすくんだ。", "explanation": "ここは〈恐れ〉の意味。静かで暗い森に怖さを覚える時は「怖い」「恐ろしい」と言い、「尊敬」は人の立派さを認める気持ちなので、場所への怖さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37521, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尊敬", "is_correct": true, "explanation": "「君を尊敬するよ」の形で、えらいと認める気持ちを表す。"}, {"text": "相談", "is_correct": false, "explanation": "「相談する」は「君に相談する」と相手を「に」で示すので、「君を相談するよ」は合わない。"}, {"text": "結婚", "is_correct": false, "explanation": "「結婚する」は「君と結婚する」と「と」で示すので、「君を結婚する」は不自然。"}, {"text": "登校", "is_correct": false, "explanation": "「登校する」は学校へ行くことで、人を「を」で取らないので合わない。"}], "explanations": {"尊敬": "「君を尊敬するよ」の形で、えらいと認める気持ちを表す。", "相談": "「相談する」は「君に相談する」と相手を「に」で示すので、「君を相談するよ」は合わない。", "結婚": "「結婚する」は「君と結婚する」と「と」で示すので、「君を結婚する」は不自然。", "登校": "「登校する」は学校へ行くことで、人を「を」で取らないので合わない。"}, "sentence_index": 6, "correct_answer": "尊敬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この古い机に、尊敬を感じている。", "explanation": "ここは〈愛着〉の意味。物に思い入れを持つ時は「愛着を感じる」と言い、「尊敬」は人の行いを立派だと認める言葉で、物には使わない。"}, {"text": "試験の結果を聞いて、尊敬して胸をなでおろした。", "explanation": "ここは〈安心〉の意味。ほっとした時は「胸をなでおろす」「安心する」を使い、「尊敬」は人の立派な行いを認める言葉なので、結果を聞いた安堵には使わない。"}, {"text": "道を聞かれて、尊敬して困った。", "explanation": "ここは〈困惑〉の意味。思いがけず対応に迷う時は「困った」「戸惑った」と言い、「尊敬」は人をえらいと認める気持ちなので、道を尋ねられた場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37521, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新人は課長の公平さに尊敬している。", "corrected_sentence": "新人は課長の公平さを尊敬している。", "error_description": "誤: 公平さに尊敬している → 正: 公平さを尊敬している。「尊敬する」は対象を「を」で取るので、目的語の助詞は「を」が正しい。「に」は相手を示すため不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37521, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の人は村長に尊敬しられている。", "corrected_sentence": "町の人は村長に尊敬されている。", "error_description": "誤: 尊敬しられている → 正: 尊敬されている。「尊敬する」の受身は「尊敬される」。「しられ」は動詞の語形が誤りで、「されて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62feac62-bb48-464b-8bda-242782882371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37522, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「感じる」の目的語を示す「を」。「ジレンマを感じた」が自然。"}, {"text": "が", "is_correct": false, "explanation": "「私はジレンマが感じた」は主語が二つ並び、不自然になる。"}, {"text": "に", "is_correct": false, "explanation": "「感じる」は「に」を取らないので、「ジレンマに感じた」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「ジレンマで感じた」は原因や手段の意味になり、「感じる」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「感じる」の目的語を示す「を」。「ジレンマを感じた」が自然。", "が": "「私はジレンマが感じた」は主語が二つ並び、不自然になる。", "に": "「感じる」は「に」を取らないので、「ジレンマに感じた」は成り立たない。", "で": "「ジレンマで感じた」は原因や手段の意味になり、「感じる」の目的語にならない。"}, "error_tags": {"が": "主格", "に": "相手・場所", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37522, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37522, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのことの間で、どちらを選ぶか迷うこと。", "primary_collocate": null, "pronunciation": "じれんま", "ipa": "dʑiɾeɴma", "syllable_count": 4, "sentences": [{"text": "仕事を続けるか、家族のそばに戻るか、彼はジレンマに悩んでいる。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "仕事[しごと]を続[つづ]けるか、家族[かぞく]のそばに戻[もど]るか、彼[かれ]はジレンマに悩[なや]んでいる。", "sentence_source": "generated"}, {"text": "行きたい大学と親が選んだ大学の間で、私はジレンマを感じた。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "行[い]きたい大学[だいがく]と親[おや]が選[えら]んだ大学[だいがく]の間[あいだ]で、私[わたし]はジレンマを感[かん]じた。", "sentence_source": "generated"}, {"text": "安い店に行くか近い店に行くかというジレンマで、昼休みが終わった。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "安[やす]い店[みせ]に行[い]くか近[ちか]い店[みせ]に行[い]くかというジレンマで、昼休[ひるやす]みが終[お]わった。", "sentence_source": "generated"}, {"text": "本当のことを言うか黙っているか、そのジレンマが彼女を苦しめた。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "本当[ほんとう]のことを言[い]うか黙[だま]っているか、そのジレンマが彼女[かのじょ]を苦[くる]しめた。", "sentence_source": "generated"}, {"text": "彼は長いジレンマの末に、ようやく転職を決めた。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "彼[かれ]は長[なが]いジレンマの末[すえ]に、ようやく転職[てんしょく]を決[き]めた。", "sentence_source": "generated"}, {"text": "夢をとるか安定をとるか、ジレンマで夜も眠れない。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "夢[ゆめ]をとるか安定[あんてい]をとるか、ジレンマで夜[よる]も眠[ねむ]れない。", "sentence_source": "generated"}, {"text": "母は、娘の味方をするか夫の味方をするかというジレンマに立たされた。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "母[はは]は、娘[むすめ]の味方[みかた]をするか夫[おっと]の味方[みかた]をするかというジレンマに立[た]たされた。", "sentence_source": "generated"}, {"text": "二つの会社から内定をもらったが、どちらを選ぶかでジレンマを感じている。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]から内定[ないてい]をもらったが、どちらを選[えら]ぶかでジレンマを感[かん]じている。", "sentence_source": "generated"}, {"text": "試合に出たい気持ちと足の痛みの間で、選手はジレンマに陥った。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "試合[しあい]に出[で]たい気持[きも]ちと足[あし]の痛[いた]みの間[あいだ]で、選手[せんしゅ]はジレンマに陥[おちい]った。", "sentence_source": "generated"}, {"text": "友達を助けたいが約束も守りたいというジレンマがある。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "友達[ともだち]を助[たす]けたいが約束[やくそく]も守[まも]りたいというジレンマがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ジレンマ", "label": "基本形"}, {"form": "ジレンマに", "label": "に格"}], "register": "neutral", "sense_fingerprint": "二つの選択肢のどちらを選ぶか迷う心の状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba24b57-71af-43be-bb65-9109da6c8bd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37522, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ジレンマ", "is_correct": true, "explanation": "「〜に悩んでいる」で、二つの選択肢の間で迷う状況を指す語。ここが正解。"}, {"text": "ユーモア", "is_correct": false, "explanation": "「ユーモアに悩んでいる」とは言わない。ユーモアは面白さを表し、進路の板ばさみには合わない。"}, {"text": "ハーモニー", "is_correct": false, "explanation": "ハーモニーは調和や和音の意味で、「〜に悩んでいる」と続けると不自然になる。"}, {"text": "リズム", "is_correct": false, "explanation": "リズムは拍子や調子の意味。「リズムに悩んでいる」は文脈に合わず、二択の迷いを表せない。"}], "explanations": {"ジレンマ": "「〜に悩んでいる」で、二つの選択肢の間で迷う状況を指す語。ここが正解。", "ユーモア": "「ユーモアに悩んでいる」とは言わない。ユーモアは面白さを表し、進路の板ばさみには合わない。", "ハーモニー": "ハーモニーは調和や和音の意味で、「〜に悩んでいる」と続けると不自然になる。", "リズム": "リズムは拍子や調子の意味。「リズムに悩んでいる」は文脈に合わず、二択の迷いを表せない。"}, "sentence_index": 0, "correct_answer": "ジレンマ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この二つの証言にはジレンマがある。", "explanation": "ここは〈矛盾〉の意味。食い違う証言の関係は矛盾と言う。ジレンマは二つの選択肢のどちらを選ぶかで迷う状況を指すので合わない。"}, {"text": "A店は安くて近いので迷う余地がない。これはまさにジレンマだ。", "explanation": "ここは〈どちらにするかすぐ決まる選択〉の意味。ジレンマは、どちらを選ぶか迷うことを指すので、迷う余地がない場面には合わない。"}, {"text": "この理論は一見矛盾するが、実は正しい。これはジレンマだ。", "explanation": "ここは〈パラドックス〉の意味。一見矛盾する命題を指す語で、ジレンマは二つの選択肢の板ばさみを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37522, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ジレンマ", "is_correct": true, "explanation": "「〜という〇〇に立たされた」で、板ばさみの状況を表す語。ここが正解。"}, {"text": "ドラマ", "is_correct": false, "explanation": "ドラマは劇や出来事のまとまりの意味。「ドラマに立たされた」とは言わず、二択の板ばさみには合わない。"}, {"text": "テンポ", "is_correct": false, "explanation": "テンポは速さや調子のこと。「テンポに立たされた」は意味が通らず、板ばさみの場面に入らない。"}, {"text": "ロマン", "is_correct": false, "explanation": "ロマンは夢や憧れの意味。「ロマンに立たされた」とは言わず、板ばさみの状況には合わない。"}], "explanations": {"ジレンマ": "「〜という〇〇に立たされた」で、板ばさみの状況を表す語。ここが正解。", "ドラマ": "ドラマは劇や出来事のまとまりの意味。「ドラマに立たされた」とは言わず、二択の板ばさみには合わない。", "テンポ": "テンポは速さや調子のこと。「テンポに立たされた」は意味が通らず、板ばさみの場面に入らない。", "ロマン": "ロマンは夢や憧れの意味。「ロマンに立たされた」とは言わず、板ばさみの状況には合わない。"}, "sentence_index": 6, "correct_answer": "ジレンマ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の面接がジレンマで、落ち着かない。", "explanation": "ここは〈不安〉の意味。ジレンマは二つの選択肢の板ばさみで、面接への心配には使わない。"}, {"text": "取引先とジレンマが成立し、契約が結ばれた。", "explanation": "ここは〈合意〉の意味。ジレンマは二つの選択の板ばさみを指し、取引が成立するという意味はないので、合意の場面には使わない。"}, {"text": "客が押し寄せ、店内はジレンマになった。", "explanation": "ここは〈混乱〉の意味。ジレンマは二つの選択の板ばさみで、人が集まって収拾がつかない状態は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37522, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は転職か残留かのジレンマを悩んでいる。", "corrected_sentence": "彼女は転職か残留かのジレンマに悩んでいる。", "error_description": "「悩む」は「に」を取るので、正しくは「ジレンマに悩んでいる」。「を」を付けると目的語のように見えて不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37522, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は値上げで客を失い、ジレンマに落ちた。", "corrected_sentence": "会社は値上げで客を失い、ジレンマに陥った。", "error_description": "「ジレンマ」に続く動詞は「陥る」。「落ちる」は穴や罠への落下に使う語なので、板ばさみの状態には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37523, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37523, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ジレンマの中」と名詞を続ける「の」。「ジレンマの中にいた」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「ジレンマを中にいた」は成り立たず、場所を示す語として不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」。「ジレンマで中にいた」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。「ジレンマと中にいた」は文の骨組みが合わない。"}], "correct_answer": "の", "explanations": {"の": "「ジレンマの中」と名詞を続ける「の」。「ジレンマの中にいた」が自然。", "を": "「ジレンマを中にいた」は成り立たず、場所を示す語として不自然になる。", "で": "手段や場所の「で」。「ジレンマで中にいた」は文が成り立たない。", "と": "並列の「と」。「ジレンマと中にいた」は文の骨組みが合わない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "並列・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37523, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つの選択肢の間で、どちらを選んでも良い結果にならない難しい状況。", "primary_collocate": null, "pronunciation": "じれんま", "ipa": "dʑiɾeɴma", "syllable_count": 4, "sentences": [{"text": "値上げをすれば客が減り、しなければ赤字になる。会社はジレンマに陥っている。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "値上[ねあ]げをすれば客[きゃく]が減[へ]り、しなければ赤字[あかじ]になる。会社[かいしゃ]はジレンマに陥[おちい]っている。", "sentence_source": "generated"}, {"text": "薬を飲むと眠くなり、飲まないと痛い。医者もジレンマを感じている。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]むと眠[ねむ]くなり、飲[の]まないと痛[いた]い。医者[いしゃ]もジレンマを感[かん]じている。", "sentence_source": "generated"}, {"text": "環境を守ると工場が止まり、工場を動かすと空気が汚れる。これは大きなジレンマだ。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "環境[かんきょう]を守[まも]ると工場[こうじょう]が止[と]まり、工場[こうじょう]を動[うご]かすと空気[くうき]が汚[よご]れる。これは大[おお]きなジレンマだ。", "sentence_source": "generated"}, {"text": "正直に話せば彼が傷つき、黙れば嘘になる。ジレンマだ。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "正直[しょうじき]に話[はな]せば彼[かれ]が傷[きず]つき、黙[だま]れば嘘[うそ]になる。ジレンマだ。", "sentence_source": "generated"}, {"text": "道を広げても古い家を残しても不満が出るというジレンマに、町は直面した。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "道[みち]を広[ひろ]げても古[ふる]い家[いえ]を残[のこ]しても不満[ふまん]が出[で]るというジレンマに、町[まち]は直面[ちょくめん]した。", "sentence_source": "generated"}, {"text": "先生は、厳しくすれば嫌われ、優しくすれば生徒が伸びないというジレンマを抱えている。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "先生[せんせい]は、厳[きび]しくすれば嫌[きら]われ、優[やさ]しくすれば生徒[せいと]が伸[の]びないというジレンマを抱[かか]えている。", "sentence_source": "generated"}, {"text": "人を増やせば費用がかかり、増やさなければ仕事が終わらない。このジレンマは解けない。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "人[ひと]を増[ふ]やせば費用[ひよう]がかかり、増[ふ]やさなければ仕事[しごと]が終[お]わらない。このジレンマは解[と]けない。", "sentence_source": "generated"}, {"text": "彼は、どちらを選んでも誰かが損をするジレンマの中にいた。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "彼[かれ]は、どちらを選[えら]んでも誰[だれ]かが損[そん]をするジレンマの中[なか]にいた。", "sentence_source": "generated"}, {"text": "経済を回すと感染が広がり、止めると生活が苦しくなる。政府はジレンマに苦しんだ。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "経済[けいざい]を回[まわ]すと感染[かんせん]が広[ひろ]がり、止[と]めると生活[せいかつ]が苦[くる]しくなる。政府[せいふ]はジレンマに苦[くる]しんだ。", "sentence_source": "generated"}, {"text": "親切にしても迷惑がられ、放っておくと冷たいと言われる。そんなジレンマが続く。", "target_word": "ジレンマ", "complexity_tier": "T3", "furigana": "親切[しんせつ]にしても迷惑[めいわく]がられ、放[ほう]っておくと冷[つめ]たいと言[い]われる。そんなジレンマが続[つづ]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ジレンマ", "label": "基本形"}, {"form": "ジレンマに", "label": "に格"}], "register": "neutral", "sense_fingerprint": "どちらを選んでも不利益が出る板ばさみの状況", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba24b57-71af-43be-bb65-9109da6c8bd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37523, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ジレンマ", "is_correct": true, "explanation": "「会社は〇〇に陥っている」で、どちらを選んでも損をする板ばさみを表す語。ここが正解。"}, {"text": "ボリューム", "is_correct": false, "explanation": "ボリュームは量や音量の意味で、「〇〇に陥っている」の対象にならない。"}, {"text": "メリハリ", "is_correct": false, "explanation": "メリハリは強弱や区別の意味で、「陥る」とは続かない。"}, {"text": "ニュアンス", "is_correct": false, "explanation": "ニュアンスは微妙な意味合いのことで、「陥っている」と組み合わせると不自然になる。"}], "explanations": {"ジレンマ": "「会社は〇〇に陥っている」で、どちらを選んでも損をする板ばさみを表す語。ここが正解。", "ボリューム": "ボリュームは量や音量の意味で、「〇〇に陥っている」の対象にならない。", "メリハリ": "メリハリは強弱や区別の意味で、「陥る」とは続かない。", "ニュアンス": "ニュアンスは微妙な意味合いのことで、「陥っている」と組み合わせると不自然になる。"}, "sentence_index": 0, "correct_answer": "ジレンマ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この商品はジレンマが高く、なかなか売れなかった。", "explanation": "ここは〈価格〉の意味。ジレンマは状況を指す語で、値段が高いとは言えない。"}, {"text": "機械のジレンマで、工場は三日間止まった。", "explanation": "ここは〈故障〉の意味。ジレンマは選択に迷う状況を表し、機械の不具合には使わない。"}, {"text": "転職先は給料も休みも申し分なく、迷う余地はなかった。まさにジレンマだ。", "explanation": "ここは〈決めやすい良い選択〉の意味。ジレンマは、どちらを選んでも良い結果にならない難しい状況を指すので、一方が明らかに良い場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37523, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ジレンマ", "is_correct": true, "explanation": "「このジレンマは解けない」の主語になり、解決しにくい板ばさみを表す語。ここが正解。"}, {"text": "ロマン", "is_correct": false, "explanation": "ロマンは夢や憧れの意味。「このロマンは解けない」とは言わず、文が成り立たない。"}, {"text": "リズム", "is_correct": false, "explanation": "リズムは拍子の意味。解けない対象にはならず、文脈に合わない。"}, {"text": "テンポ", "is_correct": false, "explanation": "テンポは速さの意味。「このテンポは解けない」は意味が通らない。"}], "explanations": {"ジレンマ": "「このジレンマは解けない」の主語になり、解決しにくい板ばさみを表す語。ここが正解。", "ロマン": "ロマンは夢や憧れの意味。「このロマンは解けない」とは言わず、文が成り立たない。", "リズム": "リズムは拍子の意味。解けない対象にはならず、文脈に合わない。", "テンポ": "テンポは速さの意味。「このテンポは解けない」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "ジレンマ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この事業はジレンマが大きく、会社は大いに潤った。", "explanation": "ここは〈利益〉の意味。ジレンマは選択の板ばさみで、もうけの大きさは表さない。「潤った」とも合わない。"}, {"text": "会場に客が押し寄せ、受付がジレンマになった。", "explanation": "ここは〈混乱〉の意味。ジレンマは二つの選択の板ばさみで、人が殺到して収拾がつかない状態は指さない。"}, {"text": "この作業にはジレンマがかかる。", "explanation": "ここは〈手間〉の意味。時間や労力がかかることを指す語で、板ばさみの状況には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37523, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "値上げも値下げもできず、会社はジレンマを陥っている。", "corrected_sentence": "値上げも値下げもできず、会社はジレンマに陥っている。", "error_description": "「陥る」は「に」を取る自動詞。「を」を付けると目的語のように見えて、文が成り立たなくなる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37523, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このジレンマを解散させる方法が見つからない。", "corrected_sentence": "このジレンマを解消する方法が見つからない。", "error_description": "「ジレンマ」は「解消する」で終わらせる。「解散」は議会や団体などの集団に使う語で、ジレンマには合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37524, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「働く」の主語を示す「が」。心理が働く、と主語になるので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語。「働く」は自動詞なので「心理を働いた」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「心理と働いた」は文として成り立たず、「と」は共同や引用を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「心理へ働いた」では主語が立たず、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「働く」の主語を示す「が」。心理が働く、と主語になるので正しい。", "を": "「を」は他動詞の目的語。「働く」は自動詞なので「心理を働いた」は不自然。", "と": "「心理と働いた」は文として成り立たず、「と」は共同や引用を示す。", "へ": "「へ」は方向を示す。「心理へ働いた」では主語が立たず、意味が通らない。"}, "error_tags": {"を": "目的語", "と": "相手・並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37524, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「考える」の対象を示す「を」。心理に直接付く助詞として正しい。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や引用を示す。「心理と考えれば」では対象にならず不自然。"}, {"text": "が", "is_correct": false, "explanation": "「心理が考えれば」は心理が考える主体にならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示す。「心理の考えれば」では動詞の目的語が立たない。"}], "correct_answer": "を", "explanations": {"を": "「考える」の対象を示す「を」。心理に直接付く助詞として正しい。", "と": "「と」は相手や引用を示す。「心理と考えれば」では対象にならず不自然。", "が": "「心理が考えれば」は心理が考える主体にならず不自然。", "の": "「の」は所属や修飾を示す。「心理の考えれば」では動詞の目的語が立たない。"}, "error_tags": {"と": "相手・引用", "が": "主格", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37524, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心の中で思ったり、感じたりすること。", "primary_collocate": null, "pronunciation": "しんり", "ipa": "ɕiɴɾi", "syllable_count": 3, "sentences": [{"text": "初めての発表の前は、どうしても心理が不安定になるものだ。", "target_word": "心理", "complexity_tier": "T3", "furigana": "初(はじ)めての発表(はっぴょう)の前(まえ)は、どうしても心理(しんり)が不安定(ふあんてい)になるものだ。", "sentence_source": "generated"}, {"text": "その場から逃げたいという心理が働いた。", "target_word": "心理", "complexity_tier": "T3", "furigana": "その場(ば)から逃(に)げたいという心理(しんり)が働(はたら)いた。", "sentence_source": "generated"}, {"text": "手紙を読んで、心理が複雑に揺れた。", "target_word": "心理", "complexity_tier": "T3", "furigana": "手紙(てがみ)を読(よ)んで、心理(しんり)が複雑(ふくざつ)に揺(ゆ)れた。", "sentence_source": "generated"}, {"text": "彼の心理は顔にすぐ出る。", "target_word": "心理", "complexity_tier": "T2", "furigana": "彼(かれ)の心理(しんり)は顔(かお)にすぐ出(で)る。", "sentence_source": "generated"}, {"text": "この小説は主人公の心理を丁寧に書いている。", "target_word": "心理", "complexity_tier": "T3", "furigana": "この小説(しょうせつ)は主人公(しゅじんこう)の心理(しんり)を丁寧(ていねい)に書(か)いている。", "sentence_source": "generated"}, {"text": "合格したと聞いて、心理の変化が顔に出てしまった。", "target_word": "心理", "complexity_tier": "T3", "furigana": "合格(ごうかく)したと聞(き)いて、心理(しんり)の変化(へんか)が顔(かお)に出(で)てしまった。", "sentence_source": "generated"}, {"text": "だれも見ていないと、ずるをしたいという心理が働きやすい。", "target_word": "心理", "complexity_tier": "T3", "furigana": "だれも見(み)ていないと、ずるをしたいという心理(しんり)が働(はたら)きやすい。", "sentence_source": "generated"}, {"text": "彼が黙った理由は、そのときの心理を考えれば分かる。", "target_word": "心理", "complexity_tier": "T4", "furigana": "彼(かれ)が黙(だま)った理由(りゆう)は、そのときの心理(しんり)を考(かんが)えれば分(わ)かる。", "sentence_source": "generated"}, {"text": "別れの前の心理を、そっと歌にした。", "target_word": "心理", "complexity_tier": "T3", "furigana": "わかれのまえのしんりを、そっとうたにした。", "sentence_source": "generated"}, {"text": "疑う心理が強くなって、友達の言葉を信じられなかった。", "target_word": "心理", "complexity_tier": "T4", "furigana": "疑(うたが)う心理(しんり)が強(つよ)くなって、友達(ともだち)の言葉(ことば)を信(しん)じられなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "心理", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ある場面で心の中に生まれる思いや気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '830f321e-9b60-438b-aad8-359bdfb0dd5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37524, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心理", "is_correct": true, "explanation": "「心理が不安定になる」で、発表の前に生まれる心の状態を指す。文の意味に合う。"}, {"text": "手順", "is_correct": false, "explanation": "手順は作業の順番で、不安定になるという主語にはならない。"}, {"text": "目的", "is_correct": false, "explanation": "目的は行動の狙いで、心が不安定になるという文の主語にはならない。"}, {"text": "順序", "is_correct": false, "explanation": "順序は並べる順番で、不安定になるという文の主語としては合わない。"}], "explanations": {"心理": "「心理が不安定になる」で、発表の前に生まれる心の状態を指す。文の意味に合う。", "手順": "手順は作業の順番で、不安定になるという主語にはならない。", "目的": "目的は行動の狙いで、心が不安定になるという文の主語にはならない。", "順序": "順序は並べる順番で、不安定になるという文の主語としては合わない。"}, "sentence_index": 0, "correct_answer": "心理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その心理は高すぎて、払えなかった。", "explanation": "ここは〈料金〉の意味。料金は高い・安いで言うが、心理には値段の概念がないので合わない。"}, {"text": "この心理は古いので、よく壊れる。", "explanation": "ここは〈機械〉の意味。古さや壊れやすさは物について言うもので、心の働きを指す心理には使わない。"}, {"text": "今夜は心理が降るそうなので、傘を持って出かけた。", "explanation": "ここは〈天気〉の意味。雨は降ると言うが、心理は降るものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37524, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心理", "is_correct": true, "explanation": "「心理が働く」で、ずるをしたいという心の動きを指す。文の意味に合う。"}, {"text": "期限", "is_correct": false, "explanation": "期限は締め切りの日時で、心が働くという文の主語にはならない。"}, {"text": "単位", "is_correct": false, "explanation": "単位は数量の基準で、心の働きを表す文には入らない。"}, {"text": "予算", "is_correct": false, "explanation": "予算は使えるお金の枠で、心が働くという文に合わない。"}], "explanations": {"心理": "「心理が働く」で、ずるをしたいという心の動きを指す。文の意味に合う。", "期限": "期限は締め切りの日時で、心が働くという文の主語にはならない。", "単位": "単位は数量の基準で、心の働きを表す文には入らない。", "予算": "予算は使えるお金の枠で、心が働くという文に合わない。"}, "sentence_index": 6, "correct_answer": "心理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は心理が豊かで、映画を見ると必ず泣く。", "explanation": "ここは〈感情〉の意味。感じ方が豊かだと言うのは感情で、「心理が豊か」とは言わないので誤り。"}, {"text": "彼は心理がはっきりしていて、名前も答えられる。", "explanation": "ここは〈意識〉の意味。目覚めている状態は「意識がはっきりする」と言うので、心理には合わない。"}, {"text": "彼は心理が強く、何でもすぐ試したくなる。", "explanation": "ここは〈好奇心〉の意味。知りたい気持ちの強さは「好奇心が強い」と言うので、心理の強さとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37524, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試合の直前、選手の心理を大きく揺れた。", "corrected_sentence": "試合の直前、選手の心理が大きく揺れた。", "error_description": "「揺れる」は自動詞で、動きの主体を「が」で示す。「を」は他動詞の目的語に使うので、「心理を揺れた」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37524, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "疑う心理が強いなって、人を信じにくくなった。", "corrected_sentence": "疑う心理が強くなって、人を信じにくくなった。", "error_description": "「強い」は形容詞なので、「なる」に続けるときは「強く」と連用形にする。「強いなって」は活用の誤りで、正しくは「強くなって」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37525, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
